-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras (Trasy) — 64 tras
-- Vygenerováno pro Velín → Trasy. NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy se vkládají jako is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže podle (name, branch_id), aby šlo migraci pustit opakovaně.
-- ════════════════════════════════════════════════════════════════════
-- Nový sloupec pro filtr podle států, kterými trasa projíždí (idempotentní).
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první pobočka.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Hrady a zámky jižní Vysočiny  (010_hrady.json)
  delete from public.routes where name = 'Hrady a zámky jižní Vysočiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Hrady a zámky jižní Vysočiny', 'Okruh po nejkrásnějších hradech a zámcích jižní Vysočiny vede převážně po klidných silnicích II. a III. třídy s příjemným střídáním lesních úseků, rybníků a rozhlédnutých plání Českomoravské vrchoviny. Trasa nabízí svižné zatáčky kolem Kamene a Roštejna i pohodovější přejezdy mezi historickými městečky Žirovnice, Kamenice nad Lipou a Telč. Vrcholem je zastávka v UNESCO městě Telč s renesančním zámkem a náměstím. Nejlepší je jaro až podzim; pozor na úzké a místy hrbolaté lesní silnice u Roštejna a na turistický provoz v Telči za slunečných víkendů.', 'loop', 175, 225, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.424, "lng": 15.015, "label": "Hrad Kámen"}, {"lat": 49.30264, "lng": 15.0793, "label": "Zámek Kamenice nad Lipou"}, {"lat": 49.254, "lng": 15.185, "label": "Zámek Žirovnice"}, {"lat": 49.183, "lng": 15.455, "label": "Zámek Telč"}, {"lat": 49.272, "lng": 15.484, "label": "Hrad Roštejn"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.424,15.015%7C49.30264,15.0793%7C49.254,15.185%7C49.183,15.455%7C49.272,15.484', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_K%C3%A1men.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_K%C3%A1men.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kamenice_nad_Lipou,_z%C3%A1mek_a_l%C3%ADpa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDirovnice%20z%C3%A1mek%20zdola.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn_hrad_03.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg"}'::text[], '{"Hrad Kámen","Zámek Kamenice nad Lipou","Zámek Žirovnice","Zámek Telč","Hrad Roštejn","Restaurace: Gril u Osla / El Grill de Burro (Telč)"}'::text[], '{"Česko"}'::text[], false, 10, 'approved');

  -- Za rozhlednami Vysočiny  (020_rozhledny.json)
  delete from public.routes where name = 'Za rozhlednami Vysočiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Za rozhlednami Vysočiny', 'Kompaktní vyhlídkový okruh po malebných silnicích druhé a třetí třídy kolem Pelhřimova a Pacova, který se ZÁMĚRNĚ vyhýbá dálnicím i rychlostním silnicím a drží se klidných okresek přes lesy a pahorkatinu Vysočiny. Trasa nabízí táhlé zatáčky, střídání stoupání a sjezdů a otevřené výhledy z hřebenů Křemešnické vrchoviny, nejlepší je od května do října, kdy jsou rozhledny přístupné a vozovka suchá. Pozor na úzké lesní úseky, občasný štěrk a listí v zatáčkách, v obcích na cyklisty a zemědělskou techniku. Povrch je vesměs slušný, ale místy hrbolatý, proto volte plynulou jízdu. Okruh začíná i končí v Mezné u Pelhřimova.', 'loop', 118, 195, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.431, "lng": 15.223, "label": "Pelhřimov – Masarykovo náměstí"}, {"lat": 49.4035, "lng": 15.32711, "label": "Rozhledna Pípalka na Křemešníku"}, {"lat": 49.376, "lng": 15.435, "label": "Čeřínek – Přední skála"}, {"lat": 49.53578, "lng": 15.00367, "label": "Strážiště u Pacova"}, {"lat": 49.42439, "lng": 15.01388, "label": "Hrad Kámen"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.431,15.223%7C49.4035,15.32711%7C49.376,15.435%7C49.53578,15.00367%7C49.42439,15.01388', 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C5%99eme%C5%A1n%C3%ADk%20-%20rozhledna%20obr01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C5%99eme%C5%A1n%C3%ADk%20-%20rozhledna%20obr01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pelh%C5%99imov%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pelh%C5%99imov%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/P%C5%99edn%C3%AD%20sk%C3%A1la%20(017).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kaple%20svat%C3%A9ho%20Jana%20K%C5%99titele%20pod%20Str%C3%A1%C5%BEi%C5%A1t%C4%9Bm%20(Q67180794)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20K%C3%A1men.jpg"}'::text[], '{"Rozhledna Pípalka na Křemešníku","Pelhřimov – Masarykovo náměstí","Restaurace: PATRO (Pelhřimov)","Čeřínek – Přední skála","Strážiště u Pacova","Hrad Kámen"}'::text[], '{"Česko"}'::text[], false, 20, 'approved');

  -- Přehrady a voda Vysočiny  (030_prehrady.json)
  delete from public.routes where name = 'Přehrady a voda Vysočiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Přehrady a voda Vysočiny', 'Pohodová okružní jízda po vodních dílech severně od Pelhřimova, vhodná i pro méně zkušené jezdce. Z domácí základny v Mezné vyrazíte přes Červenou Řečici k nádrži Trnávka a dál údolím řeky Želivky k premonstrátskému klášteru v Želivě. Trasa záměrně vede pouze po klidných silnicích druhé a třetí třídy a zcela se vyhýbá dálnicím, takže si užijete zvlněnou krajinu Vysočiny, lesy a hladiny přehrad. Vrcholem je monumentální hráz vodárenské nádrže Švihov (Želivka), odkud se vracíte přes Sedlickou přehradu zpět na jih. Ideální je počítat se zastávkami na koupání a fotky u vody.', 'loop', 118, 165, 'easy',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – základna Mezná"}, {"lat": 49.425, "lng": 15.18, "label": "Červená Řečice"}, {"lat": 49.518, "lng": 15.212, "label": "Vodní nádrž Trnávka"}, {"lat": 49.53, "lng": 15.215, "label": "Klášter Želiv"}, {"lat": 49.676, "lng": 15.151, "label": "Vodní nádrž Švihov (Želivka)"}, {"lat": 49.51377, "lng": 15.27026, "label": "Vodní nádrž Sedlice"}, {"lat": 49.43, "lng": 15.28, "label": "Humpolec – zpáteční směr"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – základna Mezná"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.425,15.18%7C49.518,15.212%7C49.53,15.215%7C49.676,15.151%7C49.51377,15.27026%7C49.43,15.28', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hr%C3%A1z%20VD%20Trn%C3%A1vka%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hr%C3%A1z%20VD%20Trn%C3%A1vka%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20the%20Nativity%20of%20the%20Virgin%20Mary%20(%C5%BDeliv)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Prehrada%20Svihov%20A.%20Hraz-Lavka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20elektr%C3%A1rna%20Sedlice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gustav%20Mahler%20birth%20house%20in%20Kali%C5%A1t%C4%9B%2C%20Pelh%C5%99imov%20District.JPG"}'::text[], '{"Vodní nádrž Trnávka","Klášter Želiv","Vodní nádrž Švihov (Želivka)","Vodní nádrž Sedlice","Restaurace: Mahler Penzion (Kaliště)"}'::text[], '{"Česko"}'::text[], false, 30, 'approved');

  -- UNESCO trojúhelník – Telč, Třebíč, Zelená hora  (040_unesco.json)
  delete from public.routes where name = 'UNESCO trojúhelník – Telč, Třebíč, Zelená hora' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'UNESCO trojúhelník – Telč, Třebíč, Zelená hora', 'Okružní vyjížďka po třech památkách UNESCO na Vysočině vede výhradně po scénických silnicích II. a III. třídy – dálnicím a rychlostním silnicím se zcela vyhýbá. Z Mezné u Pelhřimova zamíříte na jih k renesanční Telči, odtud východními údolími řek přes Jaroměřice a Třebíč do srdce Vysočiny. Trasa nabízí svižné zatáčky, lesní úseky kolem rybníků a mírné stoupání k Zelené hoře nad Žďárem. Cesta je středně náročná, s dostatkem zastávek na prohlídky historických center a možností občerstvení ve městech.', 'poi', 215, 270, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.184, "lng": 15.453, "label": "Telč – náměstí a zámek"}, {"lat": 49.093, "lng": 15.893, "label": "Jaroměřice nad Rokytnou"}, {"lat": 49.219, "lng": 15.877, "label": "Třebíč – bazilika a židovská čtvrť"}, {"lat": 49.35, "lng": 15.9, "label": "Náměšť nad Oslavou – průjezd"}, {"lat": 49.45, "lng": 15.94, "label": "Velké Meziříčí – průjezd"}, {"lat": 49.588, "lng": 15.942, "label": "Zelená hora, Žďár nad Sázavou"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.588,15.942&travelmode=driving&waypoints=49.184,15.453%7C49.093,15.893%7C49.219,15.877%7C49.35,15.9%7C49.45,15.94', 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jaromerice%20nad%20rokytnou%20barocco%20castle%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D,%20bazilika%20sv.%20Prokopa%20z%20bylinkov%C3%A9%20zahrady%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D,%20bazilika%20sv.%20Prokopa%20z%20bylinkov%C3%A9%20zahrady%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Interior%20of%20Jewish%20Synagogue.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20kostel%20sv.%20Jana%20Nepomuck%C3%A9ho%20na%20Zelen%C3%A9%20ho%C5%99e.jpg"}'::text[], '{"Zámek a náměstí Telč","Zámek Jaroměřice nad Rokytnou","Restaurace: Adam''s Bar & Bistro (Třebíč)","Bazilika sv. Prokopa v Třebíči","Židovská čtvrť Třebíč","Poutní kostel sv. Jana Nepomuckého na Zelené hoře"}'::text[], '{"Česko"}'::text[], false, 40, 'approved');

  -- Údolím řeky Sázavy  (050_sazava.json)
  delete from public.routes where name = 'Údolím řeky Sázavy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolím řeky Sázavy', 'Malebná trasa sleduje kroutící se údolí řeky Sázavy proti proudu od Lipnice nad Sázavou až po Sázavský klášter a záměrně se vyhýbá dálnicím. Silnice se vinou podél řeky, střídají stoupání k hradům nad údolím s klidnými úseky mezi lesy a skalami. Nejlepší je jezdit v květnu až září, kdy je asfalt suchý a údolí nejzelenější. Pozor na úzké a místy nekvalitní vozovky, kamení a listí v zatáčkách a na frekventované úseky u hradů v hlavní turistické sezóně. Jde o středně náročnou celodenní vyjížďku s pěti zastávkami u hradů a klášterů nad řekou.', 'poi', 98, 150, 'medium',
     '[{"lat": 49.614, "lng": 15.413, "label": "Hrad Lipnice nad Sázavou"}, {"lat": 49.669, "lng": 15.404, "label": "Zámek Světlá nad Sázavou"}, {"lat": 49.696, "lng": 15.278, "label": "Hrad Ledeč nad Sázavou"}, {"lat": 49.81, "lng": 14.928, "label": "Hrad Český Šternberk"}, {"lat": 49.876, "lng": 14.898, "label": "Sázavský klášter"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.614,15.413&destination=49.876,14.898&travelmode=driving&waypoints=49.669,15.404%7C49.696,15.278%7C49.81,14.928', 'https://commons.wikimedia.org/wiki/Special:FilePath/6.8.19%20Lipnice%20nad%20Sazavou%20134%20(48483743832).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/6.8.19%20Lipnice%20nad%20Sazavou%20134%20(48483743832).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sv%C4%9Btl%C3%A1%20nad%20S%C3%A1zavou%20-%20z%C3%A1mek2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lede%C4%8D%20nad%20S%C3%A1zavou%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20%C4%8Cesk%C3%BD%20%C5%A0ternberk%20z%20mostu%20p%C5%99es%20S%C3%A1zavu.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cesk%C3%BD%20%C5%A0ternberk-%2028.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A1zavsk%C3%BD%20kl%C3%A1%C5%A1ter.JPG"}'::text[], '{"Hrad Lipnice nad Sázavou","Zámek Světlá nad Sázavou","Hrad Ledeč nad Sázavou","Hrad Český Šternberk","Restaurace: Pod Hradem (Český Šternberk)","Sázavský klášter"}'::text[], '{"Česko"}'::text[], false, 50, 'approved');

  -- Žďárské vrchy – skály a serpentiny  (060_zdarske.json)
  delete from public.routes where name = 'Žďárské vrchy – skály a serpentiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Žďárské vrchy – skály a serpentiny', 'Okruh Žďárskými vrchy vede úzkými, klikatými silnicemi skalnatou vrchovinou plnou žulových skalních měst, hlubokých lesů a rašelinišť. Trasa se úmyslně vyhýbá dálnicím i rychlostním silnicím – jede se výhradně po zvlněných okreskách plných zatáček a stoupání kolem nejvyšších vrcholů oblasti. Nejlepší je jaro až podzim; v létě si užijete stinné lesní úseky, na podzim barvy a výhledy, ale pozor na vlhké listí a chladné údolní mlhy. Buďte opatrní na úzkých hřebenových cestách, na štěrk a písek v zatáčkách po lesních pracích a na cyklisty a chodce v okolí turistických skal. Vzhledem k převýšení, technickým serpentinám a proměnlivému povrchu jde o náročnější okruh pro zkušenější jezdce.', 'loop', 118, 175, 'hard',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.6636, "lng": 16.0533, "label": "Sněžné"}, {"lat": 49.66056, "lng": 16.07222, "label": "Drátník (Dráteník)"}, {"lat": 49.67079, "lng": 16.03238, "label": "Devět skal"}, {"lat": 49.68606, "lng": 16.09333, "label": "Čtyři palice"}, {"lat": 49.55497, "lng": 16.27954, "label": "Rozhledna Karasín"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.6636,16.0533%7C49.66056,16.07222%7C49.67079,16.03238%7C49.68606,16.09333%7C49.55497,16.27954', 'https://commons.wikimedia.org/wiki/Special:FilePath/29%20devetskal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/29%20devetskal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cty%C5%99i%20palice%20-%20Pali%C4%8Dat%C3%A1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dr%C3%A1tn%C3%ADk%20-%20v%C4%9B%C5%BE%20Sokol1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20svat%C3%A9ho%20K%C5%99%C3%AD%C5%BEe%20(Sn%C4%9B%C5%BEn%C3%A9)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Karas%C3%ADn.jpg"}'::text[], '{"Skalní útvar Devět skal","Skály Čtyři palice","Skalní útvar Drátník","Restaurace: Hotel Sněžné – Restaurace (Sněžné)","Městys Sněžné (Milovy)","Rozhledna Karasín"}'::text[], '{"Česko"}'::text[], false, 60, 'approved');

  -- Rybníky a zámky Třeboňska  (070_trebonsko.json)
  delete from public.routes where name = 'Rybníky a zámky Třeboňska' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rybníky a zámky Třeboňska', 'Pohodová okružní jízda malebnou rybniční krajinou Třeboňska po rovinatých silnicích druhé a třetí třídy, zcela bez dálnic a rychlostních silnic. Trasa vede od renesančního zámku v Jindřichově Hradci přes pohádkový vodní zámek Červená Lhota k historickému městu Třeboň s rybníkem Svět. Cesta pokračuje po hrázi největšího rybníka v Česku – Rožmberka – lemované mohutnými duby a končí u novogotické Schwarzenberské hrobky. Silnice jsou převážně klidné, s minimem stoupání, ideální pro nenáročnou vyjížďku a focení. Počítejte s tempem odpovídajícím poznávání památek a časem na zastávky u vody.', 'poi', 118, 180, 'easy',
     '[{"lat": 49.144, "lng": 15.003, "label": "Jindřichův Hradec – zámek"}, {"lat": 49.198, "lng": 15.077, "label": "Zámek Červená Lhota"}, {"lat": 49.061, "lng": 14.804, "label": "Rybník Rožmberk – hráz"}, {"lat": 49.02, "lng": 14.783, "label": "Schwarzenberská hrobka"}, {"lat": 49.003, "lng": 14.771, "label": "Třeboň – zámek a rybník Svět"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.144,15.003&destination=49.003,14.771&travelmode=driving&waypoints=49.198,15.077%7C49.061,14.804%7C49.02,14.783', 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Jind%C5%99ich%C5%AFv_Hradec,_Mal%C3%A9_ark%C3%A1dy.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Jind%C5%99ich%C5%AFv_Hradec,_Mal%C3%A9_ark%C3%A1dy.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek-cervena-lhota.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BEmberk,_V%C3%BDtopa_Ro%C5%BEmberka.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schwarzenbersk%C3%A1_hrobka.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_u_T%C5%99ebon%C4%9B.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rybn%C3%ADk_Sv%C4%9Bt_v_T%C5%99eboni,_pohled_z_hr%C3%A1ze.JPG"}'::text[], '{"Zámek Jindřichův Hradec","Zámek Červená Lhota","Rybník Rožmberk – hráz","Schwarzenberská hrobka","Restaurace: Šupina a Šupinka (Třeboň)","Třeboň – zámek a rybník Svět"}'::text[], '{"Česko"}'::text[], false, 70, 'approved');

  -- Vltava, Orlík a Zvíkov  (080_orlik.json)
  delete from public.routes where name = 'Vltava, Orlík a Zvíkov' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Vltava, Orlík a Zvíkov', 'Malebný okruh podél Orlické přehrady a řeky Vltavy, který propojuje čtyři romantické zastávky nad rozlehlou vodní hladinou. Trasa vede výhradně po klidných silnicích druhé a třetí třídy, dálnicím a rychlostním silnicím se zcela vyhýbá. Užijete si zatáčky nad zálivy přehrady, hluboké lesy a nádherné výhledy z vysokých mostů. Ideální je zastavit na zámku Orlík, přejet Podolský most a zamířit k hradu Zvíkov nad soutokem Vltavy a Otavy. Kombinace svižných úseků a poklidných partií u vody dělá z okruhu příjemnou celodenní vyjížďku.', 'poi', 68, 110, 'medium',
     '[{"lat": 49.539, "lng": 14.164, "label": "Hráz vodní nádrže Orlík"}, {"lat": 49.5175, "lng": 14.16972, "label": "Zámek Orlík nad Vltavou"}, {"lat": 49.4, "lng": 14.29, "label": "Kostel Červená nad Vltavou"}, {"lat": 49.35645, "lng": 14.26352, "label": "Podolský most"}, {"lat": 49.437, "lng": 14.1885, "label": "Hrad Zvíkov"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.539,14.164&destination=49.437,14.1885&travelmode=driving&waypoints=49.5175,14.16972%7C49.4,14.29%7C49.35645,14.26352', 'https://commons.wikimedia.org/wiki/Special:FilePath/Orlik-prehradni%20hraz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orlik-prehradni%20hraz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20n%20Vltavou%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%20n%20Vltavou%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerven%C3%A1%20014.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Podolsk%C3%BD%20most%20-%20Jiho%C4%8Desk%C3%BD%20kraj%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Zv%C3%ADkov%20(Zv%C3%ADkovsk%C3%A9%20Podhrad%C3%AD)%203.JPG"}'::text[], '{"Vodní nádrž Orlík – hráz","Zámek Orlík nad Vltavou","Restaurace: U Cvrků (Orlík nad Vltavou)","Kostel Červená nad Vltavou","Podolský most","Hrad Zvíkov"}'::text[], '{"Česko"}'::text[], false, 80, 'approved');

  -- Husitské Táborsko a Chýnovská jeskyně  (090_taborsko.json)
  delete from public.routes where name = 'Husitské Táborsko a Chýnovská jeskyně' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Husitské Táborsko a Chýnovská jeskyně', 'Okružní jízda po malebných silnicích druhé třídy Táborskem, kompletně mimo dálnice a rychlostní komunikace. Z Mezné u Pelhřimova zamíříte přes klidné okresky do husitského Tábora, pokračujete k romantické zřícenině Kozího hrádku a dále zvlněnou krajinou na Chýnov k unikátní jeskyni. Zpáteční část vede přes Bechyni s proslulým mostem Duha a kolem rozhledny Hýlačka nad Táborem zpět na základnu. Trasa nabízí střídání táhlých zatáček v údolí Lužnice a lesních úseků, je vhodná na klidnou celodenní vyjížďku.', 'loop', 142, 215, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.4111, "lng": 14.6558, "label": "Tábor – Žižkovo náměstí a hrad Kotnov"}, {"lat": 49.39775, "lng": 14.72642, "label": "Kozí hrádek"}, {"lat": 49.42944, "lng": 14.83306, "label": "Chýnovská jeskyně"}, {"lat": 49.297, "lng": 14.469, "label": "Zámek Bechyně a most Duha"}, {"lat": 49.389, "lng": 14.643, "label": "Rozhledna Hýlačka"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.4111,14.6558%7C49.39775,14.72642%7C49.42944,14.83306%7C49.297,14.469%7C49.389,14.643', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A1bor%20-%20%C5%BDi%C5%BEkovo%20n%C3%A1m%C4%9Bst%C3%AD%20-%20okres%20T%C3%A1bor%20(04).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Koz%C3%AD%20Hr%C3%A1dek%20171.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%BDnovsk%C3%A1%20jeskyn%C4%9B(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20H%C3%BDla%C4%8Dka%202013.JPG"}'::text[], '{"Tábor – Žižkovo náměstí a hrad Kotnov","Restaurace: Goldie (Tábor)","Kozí hrádek","Chýnovská jeskyně","Zámek Bechyně a most Duha","Rozhledna Hýlačka"}'::text[], '{"Česko"}'::text[], false, 90, 'approved');

  -- Nejlepší zatáčky Javořické vrchoviny  (100_javoricka.json)
  delete from public.routes where name = 'Nejlepší zatáčky Javořické vrchoviny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nejlepší zatáčky Javořické vrchoviny', 'Náročný okruh po nejlepších serpentinách Javořické vrchoviny, který se drží výhradně okresek a lesních silnic a zcela se vyhýbá dálnicím. Od základny míříte přes Telč k nekonečně klikatým lesním úsekům pod nejvyšším vrcholem Vysočiny Javořicí (837 m), kde se vinou uzoučké asfaltky mezi smrčinami. Trasa protíná romantické okolí Velkého Pařezitého rybníka, žulové kraje Mrákotína a lesní hrad Roštejn, přičemž nabízí husté střídání zatáček, stoupání a klesání. Nejlepší je jaro až brzký podzim; v lesních stínech bývá i za sucha vlhko a listí či štěrk, pozor na zvěř, cyklisty a úzké krajnice bez svodidel. Ve vlhku a za šera jeďte defenzivně, povrch okresek je místy hrbolatý.', 'loop', 118, 195, 'hard',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Základna Mezná"}, {"lat": 49.184, "lng": 15.453, "label": "Telč – náměstí"}, {"lat": 49.157, "lng": 15.412, "label": "Mrákotín"}, {"lat": 49.153, "lng": 15.351, "label": "Javořice 837 m"}, {"lat": 49.17, "lng": 15.4, "label": "Velký Pařezitý rybník"}, {"lat": 49.272, "lng": 15.484, "label": "Hrad Roštejn"}, {"lat": 49.3464, "lng": 15.2119, "label": "Základna Mezná"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.184,15.453%7C49.157,15.412%7C49.153,15.351%7C49.17,15.4%7C49.272,15.484', 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mr%C3%A1kot%C3%ADn%20z%20Javo%C5%99ice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Javorice%202014-08%2012560.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%BD%20pa%C5%99ezit%C3%BD%20rybn%C3%ADk%202020-06-16.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn%20hrad%2003.JPG"}'::text[], '{"Zámek a náměstí Telč","Restaurace: Restaurant Zach (Telč)","Mrákotín – žulové lomy a pomník","Javořice","Velký Pařezitý rybník","Hrad Roštejn"}'::text[], '{"Česko"}'::text[], false, 100, 'approved');

  -- Slavonicko a Česká Kanada  (110_slavonicko.json)
  delete from public.routes where name = 'Slavonicko a Česká Kanada' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Slavonicko a Česká Kanada', 'Malebný okruh Českou Kanadou po klidných lesních silničkách bez dálnic a rychlostních komunikací. Trasa vede mezi rybníky, borovými lesy a žulovými balvany od renesančních Slavonic přes romantickou zříceninu Landštejna a Nové Bystřice s proslulou úzkokolejkou až k majestátnímu zámku v Jindřichově Hradci. Silnice jsou úzké, málo frekventované a plné plynulých zatáček, ideální pro pohodovou jízdu tempem, které si užijete. Doporučujeme počítat s častými zastávkami na focení a odpočinek u vody. Dálnicím a hlavním tahům se celá trasa záměrně vyhýbá.', 'poi', 118, 195, 'medium',
     '[{"lat": 48.999, "lng": 15.351, "label": "Slavonice - renesanční náměstí"}, {"lat": 48.995, "lng": 15.19, "label": "Staré Město pod Landštejnem"}, {"lat": 48.9878, "lng": 15.22902, "label": "Hrad Landštejn"}, {"lat": 49.02, "lng": 15.104, "label": "Nová Bystřice - úzkokolejka"}, {"lat": 49.142, "lng": 15.003, "label": "Zámek Jindřichův Hradec"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.999,15.351&destination=49.142,15.003&travelmode=driving&waypoints=48.995,15.19%7C48.9878,15.22902%7C49.02,15.104', 'https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20479.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slavonice,%20n%C3%A1m%C4%9Bst%C3%AD%20M%C3%ADru%20479.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Land%C5%A1tejn,%20Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Star%C3%A9%20M%C4%9Bsto%20pod%20Land%C5%A1tejnem,%20z%C3%A1mek%20Dobroho%C5%99%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Narrow%20gauge%20jindrichuv%20hradec.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Narrow%20gauge%20jindrichuv%20hradec.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Jind%C5%99ich%C5%AFv%20Hradec,%20Mal%C3%A9%20ark%C3%A1dy.JPG"}'::text[], '{"Slavonice – renesanční sgrafitové náměstí","Hrad Landštejn","Rybník Osika / Staré Město pod Landštejnem","Nová Bystřice – úzkokolejka","Restaurace: Pivovar Nová Bystřice (Nová Bystřice)","Zámek Jindřichův Hradec"}'::text[], '{"Česko"}'::text[], false, 110, 'approved');

  -- Za hradem Pernštejn a Novým Městem na Moravě  (120_pernstejn.json)
  delete from public.routes where name = 'Za hradem Pernštejn a Novým Městem na Moravě' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Za hradem Pernštejn a Novým Městem na Moravě', 'Okruh vede z Mezné u Pelhřimova přes východní Vysočinu po malebných silnicích II. a III. třídy, přičemž se zcela vyhýbá dálnicím – žádné úseky po D1 se nejedou. Trasa vás provede zvlněnou krajinou Žďárských vrchů se zatáčkovitými úseky, lesy a výhledy, ideálními pro pohodovou i svižnější jízdu. Cestou navštívíte skvěle zachovalý gotický hrad Pernštejn, poutní kostel na Zelené hoře, historické náměstí v Novém Městě na Moravě i rozhlednu Horní les. Silnice jsou převážně kvalitní, místy užší a klikaté v okolí říčních údolí Svratky, což z okruhu dělá zajímavý celodenní zážitek. Doporučujeme jet za suchého počasí, protože některé lesní úseky mohou být stinné a vlhké.', 'poi', 205, 300, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.58806, "lng": 15.94167, "label": "Zámek Žďár nad Sázavou / Zelená hora"}, {"lat": 49.56111, "lng": 16.07417, "label": "Nové Město na Moravě"}, {"lat": 49.5899, "lng": 16.34235, "label": "Rozhledna Horní les"}, {"lat": 49.55028, "lng": 16.31333, "label": "Hrad Pernštejn"}, {"lat": 49.524, "lng": 16.259, "label": "Bystřice nad Pernštejnem / Zubštejn"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.58806,15.94167%7C49.56111,16.07417%7C49.5899,16.34235%7C49.55028,16.31333%7C49.524,16.259', 'https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20kostel%20sv.%20Jana%20Nepomuck%C3%A9ho%20na%20Zelen%C3%A9%20ho%C5%99e.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20kostel%20sv.%20Jana%20Nepomuck%C3%A9ho%20na%20Zelen%C3%A9%20ho%C5%99e.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/NOV%C3%89%20M%C4%9ASTO%20na%20Morav%C4%9B%20-%20Star%C3%A1%20radnice%20-%20nyn%C3%AD%20Museum.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/NOV%C3%89%20M%C4%9ASTO%20na%20Morav%C4%9B%20-%20Star%C3%A1%20radnice%20-%20nyn%C3%AD%20Museum.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rove%C4%8Dn%C3%A9%20-%20rozhledna%20Horn%C3%AD%20les,%202024-10,%20obr01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Pern%C5%A1tejn%20(Pernstein)%20-%20by%20Pudelek%2003.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pivonice%20-%20hrad%20Zub%C5%A1tejn,%20obr01.jpg"}'::text[], '{"Zámek Žďár nad Sázavou a Zelená hora","Nové Město na Moravě – náměstí a Horácká galerie","Restaurace: Penzion U Martina (Nové Město na Moravě)","Rozhledna Horní les","Hrad Pernštejn","Bystřice nad Pernštejnem a hrad Zubštejn"}'::text[], '{"Česko"}'::text[], false, 120, 'approved');

  -- Passo dello Stelvio – král alpských průsmyků  (210_stelvio.json)
  delete from public.routes where name = 'Passo dello Stelvio – král alpských průsmyků' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Passo dello Stelvio – král alpských průsmyků', 'Legendární Passo dello Stelvio je se svými 2758 m druhým nejvyšším asfaltovým průsmykem Alp a nejvyšší silnicí italských Alp. Ze severní strany z Prata allo Stelvio čeká na motorkáře 48 očíslovaných serpentin (tornanti), které se v nekonečné kaskádě šplhají po úbočí Ortleru – jde o jednu z nejikoničtějších silnic na světě. Sjezd na jižní stranu do lázeňského Bormia je otevřenější a rychlejší, po cestě lze odbočit přes Passo Umbrail do Švýcarska. Ideální doba pro průjezd je červen až září, kdy je průsmyk spolehlivě otevřený; mimo sezonu bývá kvůli sněhu uzavřen. Počítejte s chladem a mlhou i v létě, hustým provozem cyklistů a aut o víkendech a nutností plné koncentrace v úzkých vlásenkách.', 'poi', 49, 110, 'hard',
     '[{"lat": 46.61841, "lng": 10.5914, "label": "Prato allo Stelvio (start)"}, {"lat": 46.55225, "lng": 10.51029, "label": "Trafoi"}, {"lat": 46.52861, "lng": 10.45278, "label": "Passo dello Stelvio – vrchol 2758 m"}, {"lat": 46.54306, "lng": 10.425, "label": "Passo Umbrail (odbočka do Švýcarska)"}, {"lat": 46.5, "lng": 10.41, "label": "Serpentiny jižní strany"}, {"lat": 46.46762, "lng": 10.37815, "label": "Bormio (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.61841,10.5914&destination=46.46762,10.37815&travelmode=driving&waypoints=46.55225,10.51029%7C46.52861,10.45278%7C46.54306,10.425%7C46.5,10.41', 'https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prato%20allo%20Stelvio-Prad%20am%20Stilfserjoch,%20Lorenz%20Kuntner''s%20Open-air%20exhibition%20002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20dello%20Stelvio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Umbrailpass.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Trafoi%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/BORMIO%20panoramica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Collegiata%20Kirche%20Bormio%202.jpg"}'::text[], '{"Prato allo Stelvio","Passo dello Stelvio – vrchol s 48 serpentinami (2758 m)","Passo Umbrail (odbočka do Švýcarska)","Trafoi","Bormio","Restaurace: La Rasiga (Bormio)"}'::text[], '{"Itálie","Švýcarsko"}'::text[], false, 210, 'approved');

  -- Grossglockner Hochalpenstraße – alpská legenda  (220_grossglockner.json)
  delete from public.routes where name = 'Grossglockner Hochalpenstraße – alpská legenda' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Grossglockner Hochalpenstraße – alpská legenda', 'Grossglockner Hochalpenstraße je jedna z nejslavnějších horských panoramatických silnic v Evropě a spojuje Bruck v Salcbursku s Heiligenblutem v Korutanech. Trasa se vine 36 serpentinami vzhůru až do nadmořské výšky 2504 m u tunelu Hochtor, s odbočkou na vyhlídku Edelweißspitze ve 2571 m. Jde o placenou vyhlídkovou silnici (mýto), nikoli o dálnici – dálnicím se zcela vyhýbá a nabízí čistě zážitkovou jízdu horami. Nejlepší období je od poloviny května do konce října, mimo tuto dobu bývá silnice kvůli sněhu uzavřená. I v létě zde počítej s výrazně nižšími teplotami, náhlými změnami počasí, mlhou a chladem ve výškách – vezmi si teplé a nepromokavé oblečení a jeď opatrně v serpentinách.', 'poi', 48, 120, 'hard',
     '[{"lat": 47.286, "lng": 12.826, "label": "Bruck an der Glocknerstraße"}, {"lat": 47.121, "lng": 12.831, "label": "Edelweißspitze"}, {"lat": 47.079, "lng": 12.845, "label": "Hochtor"}, {"lat": 47.075, "lng": 12.752, "label": "Kaiser-Franz-Josefs-Höhe"}, {"lat": 47.041, "lng": 12.842, "label": "Heiligenblut"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.286,12.826&destination=47.041,12.842&travelmode=driving&waypoints=47.121,12.831%7C47.079,12.845%7C47.075,12.752', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_an_der_Gro%C3%9Fglocknerstra%C3%9Fe_-_Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bruck_an_der_Gro%C3%9Fglocknerstra%C3%9Fe_-_Kirche.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Edelweissspitze.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hochtor_Tunnel,_Gro%C3%9Fglockner_Hochalpenstra%C3%9Fe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kaiser-Franz-Josefs-H%C3%B6he,_2014_(01).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Heiligenblut_am_Gro%C3%9Fglockner_-_Kirche.JPG"}'::text[], '{"Bruck an der Glocknerstraße","Edelweißspitze","Hochtor","Kaiser-Franz-Josefs-Höhe","Restaurace: Kärntnerhof Heiligenblut (Heiligenblut)","Heiligenblut"}'::text[], '{"Rakousko"}'::text[], false, 220, 'approved');

  -- Dolomity – Sella Ronda (čtyři průsmyky)  (230_dolomity.json)
  delete from public.routes where name = 'Dolomity – Sella Ronda (čtyři průsmyky)' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Dolomity – Sella Ronda (čtyři průsmyky)', 'Sella Ronda je legendární okruh kolem masivu Sella v italských Dolomitech, který spojuje čtyři vysokohorské průsmyky – Passo Pordoi, Passo Sella, Passo Gardena (Grödner Joch) a Passo Campolongo. Trasa se zcela vyhýbá dálnicím a rychlostním silnicím; jede se výhradně po klikatých horských silnicích plných serpentin a vlásenek s dechberoucími výhledy na dolomitské štíty. Nejlepší období pro jízdu je od června do září, kdy jsou průsmyky spolehlivě průjezdné a bez sněhu. Počítejte s hustým provozem cyklistů, karavanů i turistických busů, zejména v létě a o víkendech, proto jeďte defenzivně a v serpentinách předvídejte pomalá vozidla. Okruh lze projet oběma směry a je klidně zvládnutelný za jeden den s pauzami na jednotlivých sedlech.', 'loop', 52, 180, 'hard',
     '[{"lat": 46.476, "lng": 11.77, "label": "Canazei (start)"}, {"lat": 46.487, "lng": 11.812, "label": "Passo Pordoi"}, {"lat": 46.52, "lng": 11.878, "label": "Passo Campolongo"}, {"lat": 46.546, "lng": 11.81, "label": "Passo Gardena / Grödner Joch"}, {"lat": 46.557, "lng": 11.756, "label": "Selva di Val Gardena"}, {"lat": 46.508, "lng": 11.762, "label": "Passo Sella"}, {"lat": 46.476, "lng": 11.77, "label": "Canazei (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.476,11.77&destination=46.476,11.77&travelmode=driving&waypoints=46.487,11.812%7C46.52,11.878%7C46.546,11.81%7C46.557,11.756%7C46.508,11.762', 'https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20pordoi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20pordoi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20sella.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Groedner%20Joch%20-%20Passo%20Gardena%20(3D%20S%C3%BCdtirol).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Campolongo%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%ABlva%20Wolkenstein%20Selva%20di%20Val%20Gardena%20Sella.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Col%20Rodella%20Val%20di%20Fassa.jpg"}'::text[], '{"Passo Pordoi","Passo Sella","Passo Gardena / Grödner Joch","Passo Campolongo","Restaurace: Ristorante Cialdira Ladina (Corvara)","Canazei / Val di Fassa"}'::text[], '{"Itálie"}'::text[], false, 230, 'approved');

  -- Timmelsjoch – panoramatická horská cesta  (240_timmelsjoch.json)
  delete from public.routes where name = 'Timmelsjoch – panoramatická horská cesta' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Timmelsjoch – panoramatická horská cesta', 'Timmelsjoch (italsky Passo del Rombo) je jedna z nejvýše položených zpoplatněných horských silnic v Alpách, jejíž vrchol leží ve výšce 2 509 m n. m. na hranici Rakouska a Itálie. Trasa spojuje tyrolské Ötztal se severoitalským údolím Passeier a cíleně se vyhýbá dálnicím – jede se čistě po panoramatické horské cestě plné serpentin a přibližně 60 zatáček s ostrými vlásenkami a stoupáním až 12,7 %. Mýto se platí nad obcí Hochgurgl na rakouské straně a projet lze pouze přes den v letní sezóně. V zimě je silnice kvůli sněhu uzavřená, takže ideální doba pro jízdu je od června do září. Odměnou motorkářům jsou úchvatné výhledy na ledovce, moderní architektura muzeí Timmelsjoch Experience a jeden z nejlepších řidičských zážitků v Alpách.', 'poi', 35, 95, 'hard',
     '[{"lat": 46.9667, "lng": 11.0, "label": "Sölden – start v Ötztalu"}, {"lat": 46.9096, "lng": 11.0533, "label": "Hochgurgl – mýtná stanice"}, {"lat": 46.9028, "lng": 11.0967, "label": "Timmelsjoch / Passo del Rombo 2509 m"}, {"lat": 46.86, "lng": 11.12, "label": "Serpentiny italské strany"}, {"lat": 46.79436, "lng": 11.08807, "label": "Moso in Passiria / Moos in Passeier"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.9667,11.0&destination=46.79436,11.08807&travelmode=driving&waypoints=46.9096,11.0533%7C46.9028,11.0967%7C46.86,11.12', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio_(23).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinde_S%C3%B6lden,_Austria_-_panoramio_(23).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B6lden_Restaurant_Ice_Q_am_Gaislachkogel_2016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_-_Hochalpenstra%C3%9Fe_IMG_7446.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Timmelsjoch_view_south.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hochgurgl-Top_Mountain_Motorcycle_Museum-06NTD.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Moos-Moso.JPG"}'::text[], '{"Sölden","Restaurace: ice Q (Sölden)","Hochgurgl","Timmelsjoch / Passo del Rombo 2509 m","Top Mountain Motorcycle Museum (Passmuseum)","Moso in Passiria / Moos in Passeier"}'::text[], '{"Rakousko","Itálie"}'::text[], false, 240, 'approved');

  -- Okolo Lago di Garda  (250_garda.json)
  delete from public.routes where name = 'Okolo Lago di Garda' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Okolo Lago di Garda', 'Okruh kolem největšího italského jezera Lago di Garda patří k nejkrásnějším motorkářským zážitkům v Alpách. Západní břeh vede po slavné Gardesana Occidentale, sérii serpentin a tunelů vytesaných přímo do skal nad hladinou, s dechberoucími výhledy na tyrkysovou vodu a masiv Monte Baldo. Východní břeh (Gardesana Orientale) nabízí plynulejší jízdu podél malebných městeček jako Malcesine s hradem Scaligero a lanovkou na Monte Baldo. Pozor na hustý turistický provoz v hlavní sezoně, úzké tunely bez osvětlení a cyklisty; nejlepší období je konec jara (květen–červen) a začátek podzimu (září), kdy je počasí příjemné a doprava snesitelnější. Naplánujte si celý den – zastávky u jezera, kávu na promenádě a projížďku starou silnicí Ponale nad Rivou si nenechte ujít.', 'loop', 165, 330, 'medium',
     '[{"lat": 45.88577, "lng": 10.84117, "label": "Riva del Garda"}, {"lat": 45.85271, "lng": 10.8812, "label": "Torbole / Ponale"}, {"lat": 45.81468, "lng": 10.79322, "label": "Limone sul Garda"}, {"lat": 45.65, "lng": 10.635, "label": "Gargnano"}, {"lat": 45.5536, "lng": 10.5675, "label": "Salò"}, {"lat": 45.49744, "lng": 10.60507, "label": "Sirmione"}, {"lat": 45.5525, "lng": 10.7596, "label": "Bardolino"}, {"lat": 45.677, "lng": 10.7157, "label": "Torri del Benaco"}, {"lat": 45.76442, "lng": 10.81024, "label": "Malcesine"}, {"lat": 45.88577, "lng": 10.84117, "label": "Riva del Garda"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.88577,10.84117&destination=45.88577,10.84117&travelmode=driving&waypoints=45.85271,10.8812%7C45.81468,10.79322%7C45.65,10.635%7C45.5536,10.5675%7C45.49744,10.60507%7C45.5525,10.7596%7C45.677,10.7157%7C45.76442,10.81024', 'https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20garda%20from%20Torre%20Apponale.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Riva%20del%20garda%20from%20Torre%20Apponale.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Garda,%20old%20road%20to%20Pregasina%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Limone%20sul%20Garda,%20the%20town.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Scaligero%20Castle%20of%20Sirmione,%20town%20centre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sirmione%20castello%20scaligero.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Malcesine%20and%20the%20castle.JPG"}'::text[], '{"Riva del Garda","Torbole / Ponale","Limone sul Garda","Restaurace: QB Duepuntozero (Salò)","Sirmione","Restaurace: Ristorante Mignon (Malcesine)","Malcesine"}'::text[], '{"Itálie"}'::text[], false, 250, 'approved');

  -- Julské Alpy – průsmyk Vršič a údolí Soči  (260_vrsic.json)
  delete from public.routes where name = 'Julské Alpy – průsmyk Vršič a údolí Soči' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Julské Alpy – průsmyk Vršič a údolí Soči', 'Ikonická horská trasa Julskými Alpami, která se zcela vyhýbá dálnicím a vede jen po úzkých panoramatických silnicích. Z Kranjské Gory stoupá 50 očíslovanými serpentinami až na Vršič (1611 m) – nejvyšší silniční průsmyk ve Slovinsku, přičemž několik zatáček na východním svahu má stále původní dlažební kostky, které jsou za deště kluzké. Za sedlem trasa klesá do romantického údolí Trenta k prameni Soče a dále podél smaragdové řeky až do městečka Bovec. Nejlepší období je od června do září, kdy je průsmyk bez sněhu; brzy zjara a na podzim hrozí led a silnice se přes zimu uzavírá. Pozor na úzkou vozovku, cyklisty, turistické autobusy a náhlé změny počasí ve výškách.', 'poi', 50, 150, 'hard',
     '[{"lat": 46.485, "lng": 13.786, "label": "Kranjska Gora – start"}, {"lat": 46.469, "lng": 13.788, "label": "Jezero Jasna"}, {"lat": 46.433, "lng": 13.747, "label": "Průsmyk Vršič 1611 m"}, {"lat": 46.409, "lng": 13.719, "label": "Pramen Soči (Trenta)"}, {"lat": 46.357, "lng": 13.635, "label": "Údolí Soči"}, {"lat": 46.338, "lng": 13.552, "label": "Bovec – cíl"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.485,13.786&destination=46.338,13.552&travelmode=driving&waypoints=46.469,13.788%7C46.433,13.747%7C46.409,13.719%7C46.357,13.635', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kranjska_Gora_2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lake_Jasna_ibex_statue,_Kranjska_Gora,_Slovenia,_2013.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Julian_Alps_from_Vrsic_Pass_(16).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Izvir_So%C4%8De_Sept._2022.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velika_korita_So%C4%8De_So%C4%8Da_(Bovec)_01.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bovec_-_Hotel_Kanin.jpg"}'::text[], '{"Kranjska Gora","Jezero Jasna","Průsmyk Vršič (1611 m)","Pramen Soči (Izvir Soče)","Restaurace: Gostilna Metoja (Soča)","Bovec"}'::text[], '{"Slovinsko"}'::text[], false, 260, 'approved');

  -- Jadranská magistrála – chorvatské pobřeží  (270_jadran.json)
  delete from public.routes where name = 'Jadranská magistrála – chorvatské pobřeží' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Jadranská magistrála – chorvatské pobřeží', 'Jadranská magistrála (Jadranska magistrala, státní silnice D8) je legendární pobřežní trasa vedoucí těsně nad hladinou Jadranu – záměrně se vyhýbá vnitrozemské dálnici A1 a nabízí nekonečné výhledy na moře, skalnaté útesy a ostrovy. Silnice se vine v serpentinách podél mohutného pohoří Velebit, střídá stoupání a klesání a odměňuje motorkáře plynulými zatáčkami s panoramaty modré vody. Nejlepší období pro jízdu je pozdní jaro (květen–červen) a začátek podzimu (září), kdy je provoz slabší a teploty snesitelnější. Pozor na nárazový vítr bóru pod Velebitem, který dokáže i za slunečného dne prudce zesílit, a na letní vedra na nechráněných úsecích. Trasa začíná u Opatije a Rijeky a míří přes Senj, Karlobag a Paklenicu až do historického Zadaru.', 'poi', 230, 300, 'medium',
     '[{"lat": 45.339, "lng": 14.306, "label": "Opatija / Rijeka – start magistrály"}, {"lat": 44.99, "lng": 14.903, "label": "Senj – pevnost Nehaj"}, {"lat": 44.529, "lng": 15.078, "label": "Karlobag pod Velebitem"}, {"lat": 44.283, "lng": 15.463, "label": "NP Paklenica"}, {"lat": 44.116, "lng": 15.226, "label": "Zadar – staré město"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.339,14.306&destination=44.116,15.226&travelmode=driving&waypoints=44.99,14.903%7C44.529,15.078%7C44.283,15.463', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Kvarner%20Opatija.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Kvarner%20Opatija.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nehaj%20Senj%20Croatia%20West%20090728.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Paklenica%20-%20canyon%20Velika%20Paklenica.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20organ%20Zadar%201.jpg"}'::text[], '{"Opatija / Rijeka – začátek Jadranské magistrály","Senj – pevnost Nehaj","Karlobag pod Velebitem","Restaurace: Restaurant & Pizzeria OK Karlobag (Karlobag)","Národní park Paklenica","Zadar – staré město a mořské varhany"}'::text[], '{"Chorvatsko"}'::text[], false, 270, 'approved');

  -- Transfăgărășan – nejkrásnější silnice Karpat  (280_transfagarasan.json)
  delete from public.routes where name = 'Transfăgărășan – nejkrásnější silnice Karpat' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Transfăgărășan – nejkrásnější silnice Karpat', 'Transfăgărășan (silnice DN7C) je legendární horská cesta klikatící se přes rumunské Karpaty (pohoří Fagaraš) a rozhodně to není dálnice – celá trasa se vyhýbá rychlostním silnicím a nabízí nekonečné serpentiny stoupající až do výšky 2042 m. Cestou projedete tmavým 887 m dlouhým tunelem Bâlea těsně pod nejvyšším bodem a minete přehradu Vidraru, Drákulův hrad Poenari i ledovcové jezero Bâlea. Silnice je otevřená pouze od července do října; ve zbytku roku ji uzavírá sníh. Počítejte s proměnlivým horským počasím – i v létě zde bývá mlha, náhlé deště, chlad a mokrá vozovka, proto jeďte opatrně a s rezervou. Průměrná rychlost je kvůli zatáčkám kolem 40 km/h, na celý přejezd si vyhraďte klidně 5–6 hodin.', 'poi', 90, 360, 'hard',
     '[{"lat": 45.363, "lng": 24.634, "label": "Přehrada Vidraru"}, {"lat": 45.352, "lng": 24.635, "label": "Hrad Poenari"}, {"lat": 45.45, "lng": 24.6, "label": "Serpentiny jižní strany"}, {"lat": 45.596, "lng": 24.617, "label": "Tunel Bâlea (nejvyšší bod)"}, {"lat": 45.604, "lng": 24.617, "label": "Jezero Bâlea"}, {"lat": 45.618, "lng": 24.622, "label": "Vodopád Bâlea"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.363,24.634&destination=45.618,24.622&travelmode=driving&waypoints=45.352,24.635%7C45.45,24.6%7C45.596,24.617%7C45.604,24.617', 'https://commons.wikimedia.org/wiki/Special:FilePath/Curtea%20de%20Arges%20monastery.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Curtea%20de%20Arges%20monastery.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Dam%20in%20Romania.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Poenari%20-%20vedere%20principala.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan%20near%20Balea%20lake.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Balea.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Enchanted%20Balea%20falls.jpg"}'::text[], '{"Restaurace: Bistro Subcarpați (Curtea de Argeș)","Přehrada Vidraru (Lacul Vidraru)","Hrad Poenari (Drákulův hrad)","Tunel Bâlea","Jezero Bâlea (Bâlea Lac)","Vodopád Bâlea (Cascada Bâlea)"}'::text[], '{"Rumunsko"}'::text[], false, 280, 'approved');

  -- Švýcarská trojice – Furka, Grimsel, Susten  (290_furka.json)
  delete from public.routes where name = 'Švýcarská trojice – Furka, Grimsel, Susten' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švýcarská trojice – Furka, Grimsel, Susten', 'Legendární okruh přes tři vysoké alpské průsmyky – Furka (2429 m), Grimsel (2164 m) a Susten (2224 m) – patří k nejkrásnějším motorkářským trasám ve Švýcarsku a záměrně se vyhýbá dálnicím i tunelům, takže jedete výhradně po panoramatických horských silnicích. Ze sedla Furka je nádherný výhled na ledovec Rhône a slavný hotel Belvédère, u Grimselu vás ohromí tyrkysová přehradní jezera Grimselsee a Totensee. Serpentiny jsou úzké, s množstvím vlásenek a místy bez svodidel, proto vyžadují zkušenost a plnou koncentraci. Nejlepší období je červen až září, mimo tuto sezónu bývají průsmyky uzavřené kvůli sněhu. Pozor na chlad ve výškách, náhlé změny počasí, cyklisty, autobusy a vlhký asfalt ve stinných úsecích.', 'loop', 120, 180, 'hard',
     '[{"lat": 46.6353, "lng": 8.5941, "label": "Andermatt (start)"}, {"lat": 46.7267, "lng": 8.446, "label": "Sustenpass"}, {"lat": 46.561, "lng": 8.333, "label": "Grimselpass"}, {"lat": 46.573, "lng": 8.389, "label": "Ledovec Rhône / Belvédère"}, {"lat": 46.572, "lng": 8.415, "label": "Furkapass"}, {"lat": 46.6353, "lng": 8.5941, "label": "Andermatt (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.6353,8.5941&destination=46.6353,8.5941&travelmode=driving&waypoints=46.7267,8.446%7C46.561,8.333%7C46.573,8.389%7C46.572,8.415', 'https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rhonegletscher_Furkapass_15092011.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Grimselpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sustenpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Nosenhaus.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Rathaus.JPG"}'::text[], '{"Furkapass","Ledovec Rhône a Belvédère","Grimselpass","Sustenpass","Restaurace: Ochsen (Andermatt)","Andermatt"}'::text[], '{"Švýcarsko"}'::text[], false, 290, 'approved');

  -- Nockalmstraße a přehrada Kölnbreinsperre  (300_nockalm.json)
  delete from public.routes where name = 'Nockalmstraße a přehrada Kölnbreinsperre' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nockalmstraße a přehrada Kölnbreinsperre', 'Panoramatický okruh, který spojuje dva klenoty korutanských Alp a záměrně se vyhýbá dálnicím i rychlostním silnicím. Placená Nockalmstraße stoupá 52 vlásenkami mírnými zaoblenými horami Nockberge až na svůj nejvyšší bod Eisentalhöhe ve výšce 2042 m, odkud se otevírá dech beroucí výhled. Druhým vrcholem je jízda údolím Maltatal na masivní přehradu Kölnbreinsperre, nejvyšší přehradu Rakouska (200 m), s tyrkysovým jezerem a vyhlídkovou plošinou Airwalk. Ideální sezona je od začátku května do konce října, kdy jsou obě horské silnice sjízdné; mýto na Nockalmstraße činí přibližně 18,50 € pro motorky. Trasu doplňuje odpočinek u jezera Millstätter See, druhého největšího korutanského jezera, které je perfektním místem na kávu a zchlazení nohou.', 'loop', 175, 330, 'medium',
     '[{"lat": 46.8002, "lng": 13.583, "label": "Start – Millstätter See"}, {"lat": 46.965, "lng": 13.51, "label": "Údolí Maltatal"}, {"lat": 47.078, "lng": 13.352, "label": "Kölnbreinsperre – přehrada"}, {"lat": 46.929, "lng": 13.688, "label": "Innerkrems"}, {"lat": 46.885, "lng": 13.7, "label": "Nockalmstraße – panoramatická silnice"}, {"lat": 46.883, "lng": 13.7, "label": "Eisentalhöhe 2042 m"}, {"lat": 46.7903, "lng": 13.5745, "label": "Cíl – Millstätter See"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.8002,13.583&destination=46.7903,13.5745&travelmode=driving&waypoints=46.965,13.51%7C47.078,13.352%7C46.929,13.688%7C46.885,13.7%7C46.883,13.7', 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6lnbreinsperre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6lnbreinsperre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Innerkrems%20Krems%20in%20K%C3%A4rnten%2020070910a.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse-Karlbad.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse%20Eisentalhoehe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg"}'::text[], '{"Kölnbreinsperre – přehrada v údolí Maltatal","Innerkrems","Nockalmstraße – panoramatická silnice","Eisentalhöhe – nejvyšší bod 2042 m","Restaurace: Seerestaurant 1884 (Millstatt am See)","Millstätter See"}'::text[], '{"Rakousko"}'::text[], false, 300, 'approved');

  -- Schwarzwaldhochstraße B500 – Černý les  (310_schwarzwald.json)
  delete from public.routes where name = 'Schwarzwaldhochstraße B500 – Černý les' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Schwarzwaldhochstraße B500 – Černý les', 'Schwarzwaldhochstraße (silnice B500) je legendární horská hřebenová trasa Černým lesem, která se úplně vyhýbá dálnicím a vede lázeňským městem Baden-Baden až do Freudenstadtu. Čeká vás svižná jízda po plynulých táhlých zatáčkách s nádhernými výhledy do zalesněných údolí, kolem horského jezera Mummelsee a vrcholů Schliffkopf a Ruhestein. Cesta je vyhlášená mezi motorkáři a najdete tu řadu oblíbených motokaváren a horských hospod ideálních k zastávce. Nejlepší období je od května do října; mimo sezónu a po ránu se na exponovaných úsecích drží mlha a vlhko. Pozor na turistický provoz a autobusy o víkendech, na možný štěrk a listí v zatáčkách a v horských partiích na náhlé změny počasí a nižší teploty.', 'poi', 60, 110, 'medium',
     '[{"lat": 48.761, "lng": 8.241, "label": "Baden-Baden – start"}, {"lat": 48.593, "lng": 8.207, "label": "Mummelsee"}, {"lat": 48.56, "lng": 8.22, "label": "Ruhestein"}, {"lat": 48.535, "lng": 8.216, "label": "Schliffkopf"}, {"lat": 48.463, "lng": 8.411, "label": "Freudenstadt – cíl"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.761,8.241&destination=48.463,8.411&travelmode=driving&waypoints=48.593,8.207%7C48.56,8.22%7C48.535,8.216', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baden_Baden_-_Trinkhalle_-_View_SSE_I.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baden_Baden_-_Trinkhalle_-_View_SSE_I.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mummelsee%20und%20Hotel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ruhestein-Nationalparkzentrum-02-2022-gje.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sonnenuntergang%20am%20Schliffkopf%2C%20Nationalpark%20Schwarzwald.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Baiersbronn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Freudenstadt%20-%20Marktplatz%20Kirche.JPG"}'::text[], '{"Baden-Baden","Mummelsee","Ruhestein","Schliffkopf","Restaurace: Gasthof Rosengarten (Baiersbronn)","Freudenstadt"}'::text[], '{"Německo"}'::text[], false, 310, 'approved');

  -- Slovinský kras – Postojnská jeskyně a Škocjan  (320_postojna.json)
  delete from public.routes where name = 'Slovinský kras – Postojnská jeskyně a Škocjan' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Slovinský kras – Postojnská jeskyně a Škocjan', 'Okruh Slovinským krasem vede po klikatých silnicích krasové planiny a záměrně se vyhýbá dálnicím – jedete jen scénickými silnicemi mezi vápencovými poli, škrapy a dubovými lesy. Srdcem trasy je proslulá Postojnská jeskyně, do jejíhož nitra vás zaveze legendární podzemní vláček, a nedaleký hrad Predjama vestavěný přímo do ústí jeskyně ve skalní stěně. Dále pokračujete k UNESCEM chráněným Škocjanským jeskyním s obřím podzemním kaňonem řeky Reky a k hřebčínu lipicánů v Lipici. Cestou můžete stočit kola i k záhadnému mizejícímu Cerknickému jezeru. Jeskyně jsou přístupné a působivé po celý rok, takže tato trasa je vděčná v každém ročním období.', 'poi', 95, 180, 'medium',
     '[{"lat": 45.75028, "lng": 14.36389, "label": "Cerkniško jezero"}, {"lat": 45.78127, "lng": 14.20571, "label": "Postojnská jeskyně"}, {"lat": 45.8092, "lng": 14.1227, "label": "Hrad Predjama"}, {"lat": 45.66317, "lng": 13.98932, "label": "Škocjanské jeskyně"}, {"lat": 45.66737, "lng": 13.88005, "label": "Lipica"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.75028,14.36389&destination=45.66737,13.88005&travelmode=driving&waypoints=45.78127,14.20571%7C45.8092,14.1227%7C45.66317,13.98932', 'https://commons.wikimedia.org/wiki/Special:FilePath/Slovenia,%20Postojna%20Cave,%20Postojnska%20jama%20(15384050783).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slovenia,%20Postojna%20Cave,%20Postojnska%20jama%20(15384050783).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Postojna%20-%20Vojkova%20ulica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Predjama%20-%20Grad%20Predjama%203892.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/SkocjanCaves.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lipica%20horses%20(7198987762).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerkni%C5%A1ko%20jezero.jpg"}'::text[], '{"Postojnská jeskyně","Restaurace: Bistro Štorja (Postojna)","Hrad Predjama","Škocjanské jeskyně","Lipica","Cerknické jezero"}'::text[], '{"Slovinsko"}'::text[], false, 320, 'approved');

  -- Route des Grandes Alpes – francouzské průsmyky  (400_fr_grandesalpes.json)
  delete from public.routes where name = 'Route des Grandes Alpes – francouzské průsmyky' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Route des Grandes Alpes – francouzské průsmyky', 'Legendární alpská trasa vede od Ženevského jezera až ke Středozemnímu moři a záměrně se vyhýbá dálnicím – jezdíme výhradně po klikatých horských silnicích (D902, D925, D2202 a dalších), takže si užijete čisté serpentiny bez spěchu kamionů. Doporučujeme rozdělit tour na 3–4 dny. 1. den: od Ženevského jezera přes Col des Aravis a Cormet de Roselend do Val d''Isère. 2. den: nejvyšší asfaltový průsmyk Alp Col de l''Iseran, dále Col du Télégraphe a Col du Galibier směrem k Briançonu. 3. den: Col d''Izoard, Col de Vars a Barcelonnette. 4. den: nejvyšší silnice Francie Col de la Bonette, Col de la Cayolle, červené soutěsky Gorges de Daluis a sjezd k moři do Mentonu. Počítejte s vysokými nadmořskými výškami, chladem na vrcholech i za léta a s náročným řazením v tisících zatáček – jde o obtížnou, ale nezapomenutelnou jízdu.', 'poi', 720, 2400, 'hard',
     '[{"lat": 45.8702, "lng": 6.4588, "label": "Col des Aravis"}, {"lat": 45.69135, "lng": 6.69054, "label": "Cormet de Roselend"}, {"lat": 45.4168, "lng": 7.0252, "label": "Col de l''Iseran"}, {"lat": 45.1994, "lng": 6.4434, "label": "Col du Télégraphe"}, {"lat": 45.06427, "lng": 6.40794, "label": "Col du Galibier"}, {"lat": 44.8187, "lng": 6.7345, "label": "Col d''Izoard"}, {"lat": 44.5389, "lng": 6.7028, "label": "Col de Vars"}, {"lat": 44.3869, "lng": 6.6518, "label": "Barcelonnette"}, {"lat": 44.3216, "lng": 6.8069, "label": "Col de la Bonette"}, {"lat": 44.25914, "lng": 6.74397, "label": "Col de la Cayolle"}, {"lat": 44.05462, "lng": 6.84882, "label": "Gorges de Daluis"}, {"lat": 43.7765, "lng": 7.5044, "label": "Menton"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.8702,6.4588&destination=43.7765,7.5044&travelmode=driving&waypoints=45.69135,6.69054%7C45.4168,7.0252%7C45.1994,6.4434%7C45.06427,6.40794%7C44.8187,6.7345%7C44.5389,6.7028%7C44.3869,6.6518%7C44.3216,6.8069', 'https://commons.wikimedia.org/wiki/Special:FilePath/Col_des_aravis.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Col_des_aravis.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cormet_de_Roselend_(1_968_m).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Col_de_l''Iseran_2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Val_d''Isere_vue_aerienne.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fort_du_T%C3%A9l%C3%A9graphe_vu_de_la_vall%C3%A9e_de_la_Maurienne_(2019).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Galibier.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Izoard3.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vauban_briancon_enceinte.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Col_de_Vars.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Barcelonnette-Place_Manuel-DSCF8702.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bonette.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Col-de-la-Cayolle-1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gorges_du_Daluis_-_Rocher_de_la_T%C3%AAte_de_femme.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Menton_vieille_ville.JPG"}'::text[], '{"Col des Aravis","Cormet de Roselend","Col de l''Iseran","Restaurace: L''Avancher (Val d''Isère)","Col du Télégraphe","Col du Galibier","Col d''Izoard","Restaurace: Au Plaisir Ambré (Briançon)","Col de Vars","Barcelonnette","Col de la Bonette","Col de la Cayolle","Gorges de Daluis","Menton"}'::text[], '{"Francie"}'::text[], false, 400, 'approved');

  -- Gorges du Verdon – francouzský Grand Canyon  (410_fr_verdon.json)
  delete from public.routes where name = 'Gorges du Verdon – francouzský Grand Canyon' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Gorges du Verdon – francouzský Grand Canyon', 'Jednodenní okruh kolem nejhlubšího kaňonu Evropy patří mezi nejkrásnější motorkářské trasy Provence. Vede výhradně po klikatých horských silnicích – vyhýbáme se dálnicím i rychlostním silnicím, celý okruh jedeme po úzkých okreskách typu D952, D71 a D23. Trasa spojuje severní i jižní břeh kaňonu Verdonu přes vyhlídkovou Route des Crêtes, most Pont de l''Artuby a tyrkysové jezero Sainte-Croix. Silnice jsou technicky náročné, plné serpentin, tunelů a skalních převisů, s prudkými srázy hned za svodidly – vyžadují soustředění a pomalejší tempo. Ideální je vyrazit brzy ráno, protože v hlavní sezoně bývá provoz hustý a v úzkých úsecích se špatně předjíždí. Naplánujte si celý den včetně zastávek na fotky, kávu v malebných vesničkách a případné osvěžení u jezera.', 'loop', 118, 300, 'medium',
     '[{"lat": 43.837, "lng": 6.341, "label": "Rougon – start"}, {"lat": 43.79418, "lng": 6.39849, "label": "Point Sublime"}, {"lat": 43.779, "lng": 6.342, "label": "La Palud-sur-Verdon"}, {"lat": 43.758, "lng": 6.352, "label": "Route des Crêtes (D23)"}, {"lat": 43.7393, "lng": 6.38114, "label": "Balcons de la Mescla"}, {"lat": 43.76652, "lng": 6.4443, "label": "Pont de l''Artuby"}, {"lat": 43.77567, "lng": 6.24308, "label": "Aiguines"}, {"lat": 43.77154, "lng": 6.18983, "label": "Lac de Sainte-Croix"}, {"lat": 43.84639, "lng": 6.22111, "label": "Moustiers-Sainte-Marie"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.837,6.341&destination=43.84639,6.22111&travelmode=driving&waypoints=43.79418,6.39849%7C43.779,6.342%7C43.758,6.352%7C43.7393,6.38114%7C43.76652,6.4443%7C43.77567,6.24308%7C43.77154,6.18983', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20du%20Verdon%20-%20Rougon%20and%20rock%20-%20Point%20Sublime%20at%20D%20952%20road%20-%20Massif%20du%20Montdenier%20(cropped).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20du%20Verdon%20-%20Rougon%20and%20rock%20-%20Point%20Sublime%20at%20D%20952%20road%20-%20Massif%20du%20Montdenier%20(cropped).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Route%20des%20Cr%C3%AAtes-Gorges%20du%20Verdon%20West.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20du%20Verdon%20au%20balcon%20de%20la%20Mescla%20-1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20de%20l''Artuby%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aiguines-Verdon-Provence.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Sainte-Croix-1.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Moustiers%20Sainte%20Marie%20Village.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Moustiers-Sainte-Marie%20interieur%20du%20Village.jpg"}'::text[], '{"Point Sublime","Route des Crêtes (La Palud-sur-Verdon)","Balcons de la Mescla","Pont de l''Artuby","Aiguines","Lac de Sainte-Croix","Restaurace: La Bastide de Moustiers (Moustiers-Sainte-Marie)","Moustiers-Sainte-Marie"}'::text[], '{"Francie"}'::text[], false, 410, 'approved');

  -- Korsika – horské silnice ostrova krásy  (420_fr_corsica.json)
  delete from public.routes where name = 'Korsika – horské silnice ostrova krásy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Korsika – horské silnice ostrova krásy', 'Náročný čtyřdenní okruh po Korsice pro zkušené motorkáře, který cíleně vynechává dálnice a drží se úzkých horských a pobřežních silnic (D-silnice) plných serpentin, tunelů a vyhlídek. Den 1: z Bastie přes divoký poloostrov Cap Corse a jeho serpentiny podél moře až do Calvi. Den 2: z Calvi vnitrozemím přes nejvyšší korsický průsmyk Col de Vergio do Corte a k soutěskám Restonica. Den 3: z Corte přes červené skály Les Calanche de Piana a pobřeží do Ajaccia, dále na jih. Den 4: přes útesové město Bonifacio, Porto-Vecchio a legendární průsmyk Col de Bavella zpět na sever do Bastie. Počítejte s pomalým průměrem kvůli tisícům zatáček, kozám na silnici a úzkým úsekům – užijte si to a nespěchejte.', 'loop', 720, 1500, 'hard',
     '[{"lat": 42.69729, "lng": 9.45088, "label": "Bastia – start"}, {"lat": 42.964, "lng": 9.447, "label": "Cap Corse"}, {"lat": 42.566, "lng": 8.7571, "label": "Calvi"}, {"lat": 42.29032, "lng": 8.8784, "label": "Col de Vergio"}, {"lat": 42.30941, "lng": 9.14902, "label": "Corte"}, {"lat": 42.225, "lng": 9.05, "label": "Restonica"}, {"lat": 42.238, "lng": 8.6363, "label": "Les Calanche de Piana"}, {"lat": 41.9267, "lng": 8.7369, "label": "Ajaccio"}, {"lat": 41.3874, "lng": 9.15941, "label": "Bonifacio"}, {"lat": 41.59101, "lng": 9.27947, "label": "Porto-Vecchio"}, {"lat": 41.79602, "lng": 9.22477, "label": "Col de Bavella"}, {"lat": 42.69729, "lng": 9.45088, "label": "Bastia – cíl"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.69729,9.45088&destination=42.69729,9.45088&travelmode=driving&waypoints=42.964,9.447%7C42.566,8.7571%7C42.29032,8.8784%7C42.30941,9.14902%7C42.225,9.05%7C42.238,8.6363%7C41.9267,8.7369%7C41.3874,9.15941', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bastia%20vieux%20port.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bastia%20vieux%20port.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cap%20Corse%20-%20on%20the%20D80%20after%20Albo%20Punta%20di%20Canelle%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/0%20Calvi%20-%20Punta%20San%20Francesco%20-%20Quartiers%20de%20la%20Citadelle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bocca%20di%20Verghju.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/GR20%20DEPUIS%20CORTE%20(CORSE%20-%20FRANCE).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/GR20%20DEPUIS%20CORTE%20(CORSE%20-%20FRANCE).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gorge%20de%20Restonica01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/01%20Calanche%20Piana.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Port%20Ajaccio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bonifacio%20cliffs%20-Le%20Grain%20de%20Sable.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bonifacio%20cliffs%20-Le%20Grain%20de%20Sable.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20Palombaggia%20Beach,%20Corsica,%20France%20(52724214180).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aiguilles%20de%20Bavella,%20Corsica.JPG"}'::text[], '{"Bastia","Cap Corse","Calvi","Col de Vergio","Corte","Restaurace: A Casuccia (Corte)","Restonica","Les Calanche de Piana","Ajaccio","Bonifacio","Restaurace: Les Quatre Vents (Bonifacio)","Porto-Vecchio","Col de Bavella"}'::text[], '{"Francie"}'::text[], false, 420, 'approved');

  -- Picos de Europa – španělské vápencové velehory  (430_es_picos.json)
  delete from public.routes where name = 'Picos de Europa – španělské vápencové velehory' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Picos de Europa – španělské vápencové velehory', 'Okruh napříč nejdivočejším pohořím severního Španělska spojuje asturskou i kantaberskou stranu Picos de Europa a záměrně se vyhýbá dálnicím – jede se výhradně po klikatých horských silnicích, jako jsou N-625, CA-185 a LE-2703. Vápencové velehory tu spadají tisíce metrů do soutěsek řeky Sella a Deva, takže každá zatáčka nabídne jiný výhled na skalní stěny a smaragdové údolí. Trasa začíná v historickém Cangas de Onís, stoupá k jezerům Covadonga a přes divoké soutěsky pokračuje do útulného městečka Potes a přes průsmyk San Glorio. Počítejte s úzkými serpentinami, dobytkem na silnici a rychle se měnícím horským počasím, proto je ideální rozdělit okruh na dva dny s přenocováním v Potes nebo Cangas de Onís. Pro motorkáře je to jedna z nejvděčnějších tras Evropy – málo provozu, perfektní asfalt a nekonečná řada zatáček. Nádrž doplňte v údolích, protože v horách jsou pumpy vzácné.', 'poi', 210, 420, 'medium',
     '[{"lat": 43.3513, "lng": -5.1285, "label": "Cangas de Onís"}, {"lat": 43.30886, "lng": -5.05352, "label": "Covadonga"}, {"lat": 43.26992, "lng": -4.98615, "label": "Lagos de Covadonga"}, {"lat": 43.43907, "lng": -5.19347, "label": "Mirador del Fitu"}, {"lat": 43.3, "lng": -5.03, "label": "Desfiladero de los Beyos (N-625)"}, {"lat": 43.15368, "lng": -4.62343, "label": "Potes"}, {"lat": 43.1465, "lng": -4.81451, "label": "Fuente Dé"}, {"lat": 43.0271, "lng": -4.7956, "label": "Puerto de San Glorio"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.3513,-5.1285&destination=43.0271,-4.7956&travelmode=driving&waypoints=43.30886,-5.05352%7C43.26992,-4.98615%7C43.43907,-5.19347%7C43.3,-5.03%7C43.15368,-4.62343%7C43.1465,-4.81451', 'https://commons.wikimedia.org/wiki/Special:FilePath/Congas%20de%20Onis.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Congas%20de%20Onis.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Covadonga%20-%20Bas%C3%ADlica%20de%20Santa%20Mar%C3%ADa%20la%20Real%2009.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20Enol%20(Lagos%20de%20Covadonga,%20Picos%20de%20Europa,%20Asturias,%20Espa%C3%B1a).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/ES1200043-Sierra%20del%20Sueve%20desde%20el%20Mirador%20del%20Fito%20IGP0291.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Desfiladero%20de%20los%20Beyos%20o%20del%20Sella%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Potes,%20Cantabria%2016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Potes,%20Cantabria%2041.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Telef%C3%A9rico%20de%20Fuente%20D%C3%A9.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Monumento%20al%20oso%20pardo%20en%20el%20Collado%20de%20Llesba.jpg"}'::text[], '{"Cangas de Onís","Svatyně Covadonga","Lagos de Covadonga","Mirador del Fitu","Desfiladero de los Beyos","Potes","Restaurace: Casa Cayo (Potes)","Fuente Dé","Puerto de San Glorio"}'::text[], '{"Španělsko"}'::text[], false, 430, 'approved');

  -- Ronda a bílá města Andalusie  (440_es_ronda.json)
  delete from public.routes where name = 'Ronda a bílá města Andalusie' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Ronda a bílá města Andalusie', 'Tato dvoudenní vyjížďka propojuje ikonickou Rondu s okruhem bílých vesnic (pueblos blancos) v horách Sierra de Grazalema a vrcholí velehorskou silnicí na Pico Veleta nad Granadou. Trasa záměrně vede po klikatých horských silnicích a vyhlídkových okreskách (A-374, A-372, A-2302, A-397) a zcela se vyhýbá dálnicím (autovías/autopistas), takže si užijete zatáčky, serpentiny a výhledy místo nudné rovinky. První den zvládnete Rondu, Setenil de las Bodegas, Zaharu de la Sierra, Grazalemu a Júzcar v údolí Genal, kde přespíte v okolí Rondy. Druhý den zamiřte přes El Chorro a Caminito del Rey směrem ke Granadě, kde vás čeká Alhambra a výjezd na Pico Veleta, nejvýše položenou zpevněnou silnici Evropy. Počítejte s pomalejším tempem kvůli úzkým vozovkám, dobytku a turistickému provozu ve vesnicích.', 'poi', 295, 540, 'medium',
     '[{"lat": 36.74231, "lng": -5.16709, "label": "Ronda"}, {"lat": 36.8622, "lng": -5.1787, "label": "Setenil de las Bodegas"}, {"lat": 36.8406, "lng": -5.3905, "label": "Zahara de la Sierra"}, {"lat": 36.75836, "lng": -5.36607, "label": "Grazalema"}, {"lat": 36.62442, "lng": -5.16971, "label": "Júzcar"}, {"lat": 36.9068, "lng": -4.75923, "label": "El Chorro / Caminito del Rey"}, {"lat": 37.17604, "lng": -3.58828, "label": "Granada (Alhambra)"}, {"lat": 37.0558, "lng": -3.3658, "label": "Pico Veleta"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=36.74231,-5.16709&destination=37.0558,-3.3658&travelmode=driving&waypoints=36.8622,-5.1787%7C36.8406,-5.3905%7C36.75836,-5.36607%7C36.62442,-5.16971%7C36.9068,-4.75923%7C37.17604,-3.58828', 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Setenil%20de%20las%20Bodegas%202019-10-23%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Andaluc%C3%ADa%20Zahara%20de%20la%20Sierra1%20tango7174.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Grazalema%20(C%C3%A1diz).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%BAzcar%20M%C3%A1laga%20Andalusia%20Spain%20smurf%20town.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/El%20famoso%20Caminito%20del%20Rey.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20la%20Alhambra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/La%20Alhambra%20vista%20desde%20el%20Albaic%C3%ADn.%20Granada.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pico%20del%20Veleta%20Sierra%20Nevada.jpg"}'::text[], '{"Ronda (Puente Nuevo)","Restaurace: Tragatá (Ronda)","Setenil de las Bodegas","Zahara de la Sierra","Grazalema","Júzcar","El Chorro / Caminito del Rey","Granada (Alhambra)","Restaurace: Mirador de Morayma (Granada)","Pico Veleta (silnice)"}'::text[], '{"Španělsko"}'::text[], false, 440, 'approved');

  -- Andorra – pyrenejské průsmyky  (450_ad_andorra.json)
  delete from public.routes where name = 'Andorra – pyrenejské průsmyky' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Andorra – pyrenejské průsmyky', 'Jednodenní okruh celým Andorrským knížectvím po klikatých pyrenejských silnicích, který se záměrně vyhýbá dálnicím a rychlostním silnicím – v Andoře žádné dálnice ani tak nejsou, takže celý den strávíte na točitých horských cestách. Trasa začíná v hlavním městě Andorra la Vella a stoupá přes údolí k nejvýše položenému asfaltovému průsmyku Pyrenejí, Port d''Envalira ve výšce 2408 m. Odsud se vracíte přes malebné údolí Canillo se starobylým románským kostelem Sant Joan de Caselles a odbočíte k jezeru Estany d''Engolasters. Okruh doplňuje výjezd k horskému středisku Arcalís nad Ordinem a náročný, technický výšlap na Coll de la Gallina, oblíbený mezi cyklisty i motorkáři. Počítejte s vysokými nadmořskými výškami, chladnějším počasím na hřebenech a serpentinami, které vyžadují soustředění – ideální celodenní zážitek pro milovníky zatáček.', 'loop', 115, 240, 'medium',
     '[{"lat": 42.50779, "lng": 1.52109, "label": "Andorra la Vella (start)"}, {"lat": 42.51982, "lng": 1.56835, "label": "Estany d''Engolasters"}, {"lat": 42.571, "lng": 1.608, "label": "Sant Joan de Caselles"}, {"lat": 42.53534, "lng": 1.71765, "label": "Port d''Envalira"}, {"lat": 42.631731, "lng": 1.499821, "label": "Arcalís (Ordino)"}, {"lat": 42.44688, "lng": 1.47447, "label": "Coll de la Gallina"}, {"lat": 42.50779, "lng": 1.52109, "label": "Andorra la Vella (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.50779,1.52109&destination=42.50779,1.52109&travelmode=driving&waypoints=42.51982,1.56835%7C42.571,1.608%7C42.53534,1.71765%7C42.631731,1.499821%7C42.44688,1.47447', 'https://commons.wikimedia.org/wiki/Special:FilePath/Andorra%20la%20Vella%202025.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Andorra%20la%20Vella%202025.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Estany%20d''Engolasters%20-%20Encamp%20-%20Andorre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Esgl%C3%A8sia%20de%20Sant%20Joan%20de%20Caselles,Canillo,%20Andorra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Soldeu.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Port%20d''Envalira.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Entre%20Coll%20d''Ordino%20e%20Canillo.%20Andorra%2030.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Santuari%20de%20la%20Mare%20de%20D%C3%A9u%20de%20Can%C3%B2lic.JPG"}'::text[], '{"Andorra la Vella","Estany d''Engolasters","Sant Joan de Caselles","Restaurace: La Cort del Popaire (Soldeu)","Port d''Envalira","Arcalís (Ordino)","Coll de la Gallina"}'::text[], '{"Andorra"}'::text[], false, 450, 'approved');

  -- Portugalsko – údolí Douro a Serra da Estrela  (460_pt_douro.json)
  delete from public.routes where name = 'Portugalsko – údolí Douro a Serra da Estrela' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Portugalsko – údolí Douro a Serra da Estrela', 'Třídenní okruh severovýchodním Portugalskem, který spojuje vinařské terasy údolí Douro s nejvyššími horami pevninského Portugalska a záměrně se vyhýbá dálnicím (autoestradas) – jedeme výhradně po klikatých národních silnicích typu N222, N221, N338 a horských průsmycích, kde je zážitkem samotná jízda. První den startujeme v srdci Douro u Pinhão, projedeme legendární serpentiny N222 k Peso da Régua a přes vinice míříme na severovýchod do Miranda do Douro na španělské hranici. Druhý den sjíždíme na jih do hor Serra da Estrela, vystoupáme k vrcholu Torre (1993 m), nejvyššímu bodu pevninského Portugalska, a klesneme ledovcovým údolím Zêzere do městečka Manteigas. Třetí den navštívíme opevněné historické město Guarda, uděláme si zajížďku do divoké přírody NP Peneda-Gerês a okruh zakončíme v pohádkové středověké vesnici Sortelha. Počítejte s pomalým tempem – silnice jsou úzké a technické, ale odměnou jsou nekonečné výhledy, takže denní etapy plánujte kolem 4–6 hodin čisté jízdy.', 'poi', 720, 960, 'medium',
     '[{"lat": 41.1911, "lng": -7.5348, "label": "Pinhão – N222, údolí Douro"}, {"lat": 41.1625, "lng": -7.7879, "label": "Peso da Régua"}, {"lat": 41.4959, "lng": -6.2734, "label": "Miranda do Douro"}, {"lat": 40.5333, "lng": -7.2056, "label": "Guarda"}, {"lat": 40.322, "lng": -7.616, "label": "Torre – Serra da Estrela"}, {"lat": 40.4035, "lng": -7.5371, "label": "Manteigas – údolí Zêzere"}, {"lat": 41.7291, "lng": -8.1549, "label": "NP Peneda-Gerês"}, {"lat": 40.3276, "lng": -7.24, "label": "Sortelha"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=41.1911,-7.5348&destination=40.3276,-7.24&travelmode=driving&waypoints=41.1625,-7.7879%7C41.4959,-6.2734%7C40.5333,-7.2056%7C40.322,-7.616%7C40.4035,-7.5371%7C41.7291,-8.1549', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pinh%C3%A3o.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pinh%C3%A3o.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%A9gua%20-%20Museu%20do%20Douro%20na%20Regi%C3%A3o%20do%20Alto%20Douro.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pinh%C3%A3o.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Miranda%20do%20Douro%20-%20DSC%208090.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Torre-Serra%20da%20Estrela.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vale%20Glaciar%20do%20Z%C3%AAzere.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A9%20Catedral,%20Guarda,%20Portugal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A9%20Catedral%20da%20Guarda%20-%20Pra%C3%A7a%20Velha.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Miradouro%20da%20Pedra%20Bela%20-%20Parque%20Nacional%20Peneda-Ger%C3%AAs.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sortelha%20Castle.jpg"}'::text[], '{"Silnice N222 u Pinhão (údolí Douro)","Peso da Régua","Restaurace: Cozinha da Clara (Pinhão)","Miranda do Douro","Serra da Estrela – Torre","Manteigas (údolí Zêzere)","Guarda","Restaurace: Nobre Vinhos e Tal (Guarda)","NP Peneda-Gerês","Sortelha"}'::text[], '{"Portugalsko"}'::text[], false, 460, 'approved');

  -- Přehrada Vajont a Dolomiti Friulane  (470_it_vajont.json)
  delete from public.routes where name = 'Přehrada Vajont a Dolomiti Friulane' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Přehrada Vajont a Dolomiti Friulane', 'Jednodenní okruh po klikatých horských silnicích Dolomiti Friulane a Bellunských Dolomit, který spojuje jedno z nejtragičtějších míst italské historie s divokou přírodou Valcelliny. Trasa VĚDOMĚ vynechává dálnice (dálnici A27) a drží se scénických regionálních silnic SS251, SP422 a serpentin okolo přehrady Vajont — ideál pro motorkáře, kteří chtějí zatáčky, výhledy a klid. Ústředním bodem je přehrada Vajont, kde 9. října 1963 sesuv obřího skalního bloku z hory Monte Toc vyvolal 250 metrů vysokou vlnu, jež během několika minut smetla Longarone a okolní vesnice a zabila přibližně 2000 lidí. Trasa vede přes opuštěné vesnice Erto a Casso, přes klidné jezero Barcis až k horskému sedlu Passo Duran s úzkými, technicky náročnějšími serpentinami. Počítejte s chladnějším počasím ve výškách, místy hrubým povrchem a pietním charakterem některých zastávek. Je to spíš rozjímavá než rychlá jízda — vezměte si čas a respektujte místa spojená s obětmi katastrofy.', 'poi', 135, 300, 'medium',
     '[{"lat": 46.26361, "lng": 12.30028, "label": "Longarone"}, {"lat": 46.26722, "lng": 12.32833, "label": "Diga del Vajont"}, {"lat": 46.27083, "lng": 12.36389, "label": "Casso"}, {"lat": 46.26667, "lng": 12.37639, "label": "Erto"}, {"lat": 46.28972, "lng": 12.43417, "label": "Cimolais"}, {"lat": 46.18944, "lng": 12.55639, "label": "Barcis"}, {"lat": 46.32615, "lng": 12.09714, "label": "Passo Duran"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.26361,12.30028&destination=46.32615,12.09714&travelmode=driving&waypoints=46.26722,12.32833%7C46.27083,12.36389%7C46.26667,12.37639%7C46.28972,12.43417%7C46.18944,12.55639', 'https://commons.wikimedia.org/wiki/Special:FilePath/Diga%20del%20Vajont%20da%20Longarone%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Diga%20del%20Vajont%20da%20Longarone%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cimitero%20Vajont%20prima.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/V62%20Lago%20del%20Vajont.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Erto%20Centro.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Erto%20Centro.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Monte%20Duranno%20-%20Cimolais%20(PN).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20di%20Barcis%20(Barcis%20Lake).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Abendstimmung%20am%20Passo%20Duran.jpg"}'::text[], '{"Diga del Vajont","Longarone – památník obětem 1963","Casso","Erto","Restaurace: Vajont Ristora (Erto)","Cimolais","Barcis","Passo Duran"}'::text[], '{"Itálie"}'::text[], false, 470, 'approved');

  -- Amalfské pobřeží  (480_it_amalfi.json)
  delete from public.routes where name = 'Amalfské pobřeží' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Amalfské pobřeží', 'Legendární jednodenní okruh po pobřežní silnici SS163 (Statale Amalfitana), jedné z nejkrásnějších a nejnáročnějších motocyklových tras Evropy. Trasu VĚDOMĚ VEDEME MIMO DÁLNICE (žádná A3/autostrada) - jedeme výhradně po klikaté pobřežní SS163 a horských spojkách, abyste si užili moře, serpentiny a útesy. Vyjíždíme ze Sorrenta, projíždíme Positano, fjord Furore, Praiano, Amalfi, výletem nahoru do Ravella a zpět dolů do Vietri sul Mare, s návratem přes horský průsmyk Valico di Chiunzi. Počítejte s hustým provozem, úzkými zatáčkami, autobusy v protisměru a nutností trpělivosti - průměrná rychlost je nízká. Ideální je vyrazit brzy ráno mimo hlavní sezónu, přilbu s otevíratelnou bradou pro focení a plnou nádrž, protože čerpací stanice jsou vzácné.', 'poi', 95, 300, 'medium',
     '[{"lat": 40.62375, "lng": 14.38096, "label": "Sorrento (start)"}, {"lat": 40.62829, "lng": 14.48427, "label": "Positano"}, {"lat": 40.61436, "lng": 14.55453, "label": "Fiordo di Furore"}, {"lat": 40.6111, "lng": 14.5313, "label": "Praiano"}, {"lat": 40.634, "lng": 14.60268, "label": "Amalfi"}, {"lat": 40.64919, "lng": 14.61171, "label": "Ravello"}, {"lat": 40.66794, "lng": 14.72787, "label": "Vietri sul Mare"}, {"lat": 40.43083, "lng": 14.37083, "label": "Valico di Chiunzi (návrat)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=40.62375,14.38096&destination=40.43083,14.37083&travelmode=driving&waypoints=40.62829,14.48427%7C40.61436,14.55453%7C40.6111,14.5313%7C40.634,14.60268%7C40.64919,14.61171%7C40.66794,14.72787', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sorrento%20Sedile%20Dominova%20BW%202013-05-12%2014-10-51.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sorrento%20Sedile%20Dominova%20BW%202013-05-12%2014-10-51.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Positano%20panorama%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fiordo%20di%20Furore.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Praiano%20-%20The%20Amalfi%20Coast%20-%20Church%20of%20San%20Gennaro.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Amalfi%20-%20Duomo%20di%20Sant''Andrea.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Amalfi%20-%20Duomo%20di%20Sant''Andrea.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ravello%20Villa%20Rufolo.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vietri%20sul%20Mare.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Percorso%20dal%20valico%20di%20Chiunzi%20al%20Monte%20Finestra.jpg"}'::text[], '{"Sorrento","Positano","Fiordo di Furore","Praiano","Amalfi","Restaurace: Da Gemma (Amalfi)","Ravello","Vietri sul Mare","Valico di Chiunzi"}'::text[], '{"Itálie"}'::text[], false, 480, 'approved');

  -- Sicílie – sopka Etna  (490_it_etna.json)
  delete from public.routes where name = 'Sicílie – sopka Etna' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Sicílie – sopka Etna', 'Jednodenní okruh kolem nejvyšší činné sopky Evropy, který se úmyslně vyhýbá dálnicím a vede výhradně po malebných horských a venkovských silnicích kolem Etny. Vyjíždíte od Rifugio Sapienza na jižním svahu, sjíždíte přes Nicolosi a Zafferana Etnea a pokračujete panoramatickou silnicí SP92 a SS120 přes lávová pole k severnímu úpatí do Randazza. Odtud zamíříte k soutěskám Gole dell''Alcantara a přes klikatiny stoupáte k pobřeží do Taorminy a horské vísky Castelmola s dechberoucími výhledy na moře a kouřící vrchol. Silnice jsou úzké, plné serpentin a místy s hrubším povrchem po lávových proudech, proto počítejte s pomalejším tempem a opatrností. Celý okruh nabízí střídání sopečné krajiny, kaštanových lesů, vinic a středomořského pobřeží – ideální celodenní zážitek pro motorkáře, který se dálnicím zcela vyhýbá.', 'loop', 165, 330, 'medium',
     '[{"lat": 37.70054, "lng": 14.99839, "label": "Rifugio Sapienza (start)"}, {"lat": 37.61583, "lng": 15.02778, "label": "Nicolosi"}, {"lat": 37.679, "lng": 15.1043, "label": "Zafferana Etnea"}, {"lat": 37.87788, "lng": 14.95074, "label": "Randazzo"}, {"lat": 37.87911, "lng": 15.17525, "label": "Gole dell''Alcantara"}, {"lat": 37.8536, "lng": 15.2885, "label": "Taormina"}, {"lat": 37.85904, "lng": 15.27804, "label": "Castelmola"}, {"lat": 37.70054, "lng": 14.99839, "label": "Rifugio Sapienza (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=37.70054,14.99839&destination=37.70054,14.99839&travelmode=driving&waypoints=37.61583,15.02778%7C37.679,15.1043%7C37.87788,14.95074%7C37.87911,15.17525%7C37.8536,15.2885%7C37.85904,15.27804', 'https://commons.wikimedia.org/wiki/Special:FilePath/Etna%20-%20rifugio%20Sapienza.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Etna%20-%20rifugio%20Sapienza.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nicolosi%20at%20the%20Foot%20of%20Mount%20Etna%20(24409722454).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zafferana%20Etnea,%20Catania,%20Sicily,%20Italy%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Randazzo''s%20San%20Martino%20church.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Randazzo,%20Catania,%20Sicily,%20Italy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gole%20dell''Alcantara-pjt1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20del%20Teatro%20Greco%20di%20Taormina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castelmola%20-%20Panorama%20del%20borgo.jpg"}'::text[], '{"Etna – Rifugio Sapienza","Nicolosi","Zafferana Etnea","Randazzo","Restaurace: Ristorante Da Antonio (Randazzo)","Gole dell''Alcantara","Taormina","Castelmola"}'::text[], '{"Itálie"}'::text[], false, 490, 'approved');

  -- Trollstigen a Geirangerfjord  (500_no_trollstigen.json)
  delete from public.routes where name = 'Trollstigen a Geirangerfjord' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Trollstigen a Geirangerfjord', 'Ikonická norská trasa přes dva úseky Národních turistických cest (Geiranger–Trollstigen) vede záměrně po klikatých fjordových silnicích a horských serpentinách, dálnicím se cíleně vyhýbá – žádná dálnice zde stejně nevede a jezdec si tak užije čistý zážitek z úzkých vyhlídkových cest. Doporučujeme rozdělit na 2 dny: první den z Åndalsnesu přes Trollstigen a Gudbrandsjuvet do Valldalu, druhý den přes trajekt Linge–Eidsdal a Ørnevegen do Geirangeru s výletem na Dalsnibbu. Nezbytnou součástí je trajekt Eidsdal–Linge (Fv63), který jezdí každých cca 20–30 minut a šetří dlouhou objížďku kolem fjordu. Sezona je krátká: Trollstigen i horská cesta na Dalsnibbu bývají otevřené zhruba od konce května/června do října, mimo tuto dobu jsou uzavřené kvůli sněhu. Počítejte s pomalou jízdou v serpentinách, mokrým povrchem od vodopádů, hustým turistickým provozem a chladem ve výškách. Rezervu na trajekt, focení a časté zastávky si přidejte klidně několik hodin navíc.', 'poi', 210, 420, 'hard',
     '[{"lat": 62.56749, "lng": 7.68709, "label": "Åndalsnes – start"}, {"lat": 62.4858, "lng": 7.7236, "label": "Trollveggen"}, {"lat": 62.4564, "lng": 7.6576, "label": "Trollstigen"}, {"lat": 62.33076, "lng": 7.47113, "label": "Gudbrandsjuvet"}, {"lat": 62.3029, "lng": 7.2461, "label": "Valldal (trajekt Linge)"}, {"lat": 62.2887, "lng": 7.2754, "label": "Ørnesvingen"}, {"lat": 62.10145, "lng": 7.2062, "label": "Geiranger"}, {"lat": 62.0893, "lng": 7.2236, "label": "Flydalsjuvet"}, {"lat": 62.0563, "lng": 7.2818, "label": "Dalsnibba"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=62.56749,7.68709&destination=62.0563,7.2818&travelmode=driving&waypoints=62.4858,7.7236%7C62.4564,7.6576%7C62.33076,7.47113%7C62.3029,7.2461%7C62.2887,7.2754%7C62.10145,7.2062%7C62.0893,7.2236', 'https://commons.wikimedia.org/wiki/Special:FilePath/Trollstigen%20viewpoint.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trollstigen%20viewpoint.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2012-07%20Gudbrandsjuvet.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Strawberry%20field%20near%20Valldal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Geirangerfjorden%20from%20%C3%98rnesvingen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/GeirangerFjord.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/GeirangerFjord.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dalsnibba%3B%20Blick%20auf%20Geiranger%201%20Norwegen.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Romsdalsfjorden%20with%20%C3%85ndalsnes.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Trollveggen%202002%20June.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Flydalsjuvet%20Geiranger.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sylte%20kyrkje%20Valldal.JPG"}'::text[], '{"Trollstigen","Gudbrandsjuvet","Restaurace: Jordbærstova (Valldal)","Ørnevegen / Ørnesvingen","Geirangerfjord","Restaurace: Brasserie Posten (Geiranger)","Dalsnibba","Åndalsnes","Trollveggen","Flydalsjuvet","Valldal"}'::text[], '{"Norsko"}'::text[], false, 500, 'approved');

  -- Atlantická cesta – Atlanterhavsvegen  (510_no_atlantic.json)
  delete from public.routes where name = 'Atlantická cesta – Atlanterhavsvegen' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Atlantická cesta – Atlanterhavsvegen', 'Jednodenní pobřežní okruh po legendární norské Atlantické cestě (Atlanterhavsvegen, Fylkesveg 64) mezi Molde, Bud a Kristiansundem v kraji Møre og Romsdal. Trasa se záměrně vyhýbá dálnicím a rychlostním silnicím – vede výhradně po klikatých pobřežních a venkovských silnicích těsně u moře, což je přesně to, co dělá jízdu na motorce nezapomenutelnou. Vrcholem je úsek osmi mostů skákajících z ostrůvku na ostrůvek, korunovaný fotogenickým Storseisundetským mostem, který vypadá jako by mizel do prázdna. Počítej s ostrým slaným větrem, možnými přeháňkami a proměnlivým povrchem, proto jeď obezřetně a vyhraď si čas na zastávky u vyhlídek. Ideální je vyrazit z Molde přes rybářskou vesnici Bud, projet Atlantickou cestu na Averøy a den zakončit v přístavním Kristiansundu. Náročnost je nízká, ale odměnou je jedna z nejkrásnějších silnic světa.', 'poi', 95, 180, 'easy',
     '[{"lat": 62.73752, "lng": 7.15912, "label": "Start: Molde"}, {"lat": 62.90713, "lng": 6.91403, "label": "Bud"}, {"lat": 63.01372, "lng": 7.44487, "label": "Kårvåg"}, {"lat": 63.01693, "lng": 7.35515, "label": "Storseisundetský most"}, {"lat": 63.02937, "lng": 7.39362, "label": "Håholmen"}, {"lat": 63.11045, "lng": 7.72795, "label": "Cíl: Kristiansund"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=62.73752,7.15912&destination=63.11045,7.72795&travelmode=driving&waypoints=62.90713,6.91403%7C63.01372,7.44487%7C63.01693,7.35515%7C63.02937,7.39362', 'https://commons.wikimedia.org/wiki/Special:FilePath/MoldePana.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/MoldePana.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sj%C3%B8hus,%20Bud.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/BP%20K%C3%A5rv%C3%A5g%20-%20SAS2015-05-183.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/BP%20K%C3%A5rv%C3%A5g%20-%20SAS2015-05-183.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Storseisundbrua%20-%20Atlanterhavsveien.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A5holmen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Route%20de%20l''Atlantique%20en%20norv%C3%A8ge.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Storkaia%20Kristiansund.JPG"}'::text[], '{"Molde panorama","Bud","Kårvåg","Restaurace: Bjartmars Favorittkro (Kårvåg)","Storseisundetský most (Storseisundbrua)","Håholmen","Eldhusøya (vyhlídka)","Kristiansund"}'::text[], '{"Norsko"}'::text[], false, 510, 'approved');

  -- Švédsko – Divočinská cesta Vildmarksvägen  (520_se_vildmark.json)
  delete from public.routes where name = 'Švédsko – Divočinská cesta Vildmarksvägen' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švédsko – Divočinská cesta Vildmarksvägen', 'Vildmarksvägen (Divočinská cesta) je legendární okruh severním Jämtlandem, který vás provede skutečnou švédskou divočinou plnou jezer, vodopádů a holých náhorních plošin. Trasa se drží výhradně krajských a lesních silnic – žádné dálnice ani rychlostní silnice zde nenajdete, a přesně o to jde, protože každý kilometr chcete vychutnat pomalu. Vrcholem je průsmyk Stekenjokk, nejvýše položená veřejná silnice Švédska, kde motorkář jede otevřenou tundrou nad hranicí lesa a míjí stáda sobů. Okruh je ideální na jeden až dva dny s přespáním v Klimpfjäll nebo Stora Blåsjön a doporučuje se výhradně v létě, protože úsek přes Stekenjokk bývá kvůli sněhu uzavřen zhruba od října do začátku června. Silnice jsou úzké, místy se štěrkovým povrchem a bez svodidel, proto počítejte s klidným tempem a plnou nádrží – čerpací stanice jsou vzácné. Odměnou je jedna z nejkrásnějších a nejopuštěnějších motocyklových tras Skandinávie.', 'loop', 360, 540, 'medium',
     '[{"lat": 63.85167, "lng": 15.55824, "label": "Strömsund – start"}, {"lat": 64.34901, "lng": 14.38422, "label": "Hällingsåfallet"}, {"lat": 64.50279, "lng": 14.14614, "label": "Gäddede"}, {"lat": 64.9, "lng": 14.47, "label": "Ankarede"}, {"lat": 64.85, "lng": 14.28, "label": "Stora Blåsjön"}, {"lat": 65.06556, "lng": 14.46, "label": "Stekenjokk – nejvyšší bod"}, {"lat": 65.06, "lng": 14.8, "label": "Klimpfjäll"}, {"lat": 63.85167, "lng": 15.55824, "label": "Strömsund – cíl"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=63.85167,15.55824&destination=63.85167,15.55824&travelmode=driving&waypoints=64.34901,14.38422%7C64.50279,14.14614%7C64.9,14.47%7C64.85,14.28%7C65.06556,14.46%7C65.06,14.8', 'https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%B6msundsbron%202010.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%B6msundsbron%202010.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hallingsafall.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%A4ddede%20-%20KMB%20-%2016000300030126.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/16001000018084-Kultsj%C3%B6n-Riksantikvarie%C3%A4mbetet.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ankarede%20kapell.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ankarede,%20Stor-Bl%C3%A5sj%C3%B6n%20and%20Ankarvattnet.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vildmarksv%C3%A4gen%20Stekenjokk%20Klimpfj%C3%A4ll.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Klimpfj%C3%A4ll%20from%20Autjoklimpen.jpg"}'::text[], '{"Strömsund","Hällingsåfallet","Gäddede","Restaurace: Marsfjäll Mountain Lodge (Saxnäs / Klimpfjäll)","Ankarede","Stora Blåsjön","Stekenjokk – vyhlídka","Klimpfjäll"}'::text[], '{"Švédsko"}'::text[], false, 520, 'approved');

  -- Finské Laponsko  (530_fi_lapland.json)
  delete from public.routes where name = 'Finské Laponsko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Finské Laponsko', 'Velkolepá vícedenní pouť za polárním kruhem po klidných laponských silnicích, kde dálnice prakticky neexistují — jedeme výhradně po scénických tazích E75, E8 a silnicích 79 a 93, takže se dálnicím záměrně vyhýbáme a užíváme si liduprázdnou tundru, fjelly a nekonečné lesy. 1. den: start v Rovaniemi u polárního kruhu (Santa Claus Village), přes historickou Sodankylä nahoru do Saariselkä. 2. den: túra do divočiny národního parku Urho Kekkonen, poté k jezeru Inarijärvi a do muzea Siida v Inari. 3. den: dlouhý přejezd na dalekozápad k jezeru Kilpisjärvi pod fjellem Saana v nejsevernějším cípu Finska. 4. den: sjezd přes středisko Levi a národní park Pallas-Yllästunturi zpět k civilizaci. Počítejte s velkými vzdálenostmi mezi čerpacími stanicemi, chladem i v létě a soby na silnici — tankujte vždy, když můžete.', 'poi', 1180, 1140, 'medium',
     '[{"lat": 66.54366, "lng": 25.84762, "label": "Rovaniemi – polární kruh"}, {"lat": 67.41639, "lng": 26.58917, "label": "Sodankylä"}, {"lat": 68.4198, "lng": 27.4123, "label": "Saariselkä"}, {"lat": 68.29, "lng": 27.75, "label": "NP Urho Kekkonen"}, {"lat": 68.906, "lng": 27.0288, "label": "Inari / Inarijärvi"}, {"lat": 69.0167, "lng": 20.8167, "label": "Kilpisjärvi"}, {"lat": 67.80402, "lng": 24.80818, "label": "Levi"}, {"lat": 68.05, "lng": 24.06, "label": "NP Pallas-Yllästunturi"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=66.54366,25.84762&destination=68.05,24.06&travelmode=driving&waypoints=67.41639,26.58917%7C68.4198,27.4123%7C68.29,27.75%7C68.906,27.0288%7C69.0167,20.8167%7C67.80402,24.80818', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rovaniemi%20Santa%20Claus.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rovaniemi%20Santa%20Claus.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sodankyl%C3%A4%20vanha%20kirkko.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Saarisel%C3%A4n%20kyl%C3%A4.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Saarisel%C3%A4n%20kyl%C3%A4.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Parc-urho-kekkonen.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Inari%20lake.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sami%20Museum%20Siida.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Finnish%20national%20road%2021%20%26%20Saana%2C%20Ala-Kilpisj%C3%A4rvi.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Levi%20gondoli%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Levi%20gondoli%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pallas-Yll%C3%A4stunturi%20National%20Park%20(25719399914).jpg"}'::text[], '{"Rovaniemi – polární kruh a Santa Claus Village","Sodankylä","Saariselkä","Restaurace: Laanilan Kievari (Saariselkä)","Národní park Urho Kekkonen","Inari a jezero Inarijärvi","Muzeum Siida","Kilpisjärvi a fjell Saana","Restaurace: NiliPoro (Levi)","Levi","Národní park Pallas-Yllästunturi"}'::text[], '{"Finsko"}'::text[], false, 530, 'approved');

  -- Island – Zlatý okruh  (540_is_golden.json)
  delete from public.routes where name = 'Island – Zlatý okruh' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Island – Zlatý okruh', 'Klasický jednodenní okruh z Reykjavíku po nejslavnějších přírodních klenotech jihozápadního Islandu. Trasa vědomě vynechává jakékoli dálnice a vede po scénických silnicích č. 36, 365, 37 a 35, které nabízejí otevřené výhledy na lávová pole, jezera a sopečnou krajinu. Vyjedete z Reykjavíku k jezeru Þingvallavatn a národnímu parku Þingvellir, pokračujete přes gejzírové pole Geysir k mohutnému vodopádu Gullfoss a zpět kolem kráteru Kerið. Silnice jsou dobře udržované a poměrně nenáročné, přesto počítejte s náhlými změnami počasí a silným bočním větrem, který na motorce v otevřené krajině pořádně zabere. Ideální celodenní výlet s dostatkem času na zastávky, fotky a horké prameny.', 'loop', 248, 390, 'easy',
     '[{"lat": 64.1465, "lng": -21.942, "label": "Start – Reykjavík"}, {"lat": 64.25548, "lng": -21.12977, "label": "Þingvellir NP"}, {"lat": 64.18333, "lng": -21.15, "label": "Jezero Þingvallavatn"}, {"lat": 64.31039, "lng": -20.30232, "label": "Geysir / Strokkur"}, {"lat": 64.32707, "lng": -20.11995, "label": "Gullfoss"}, {"lat": 64.22547, "lng": -20.33725, "label": "Faxi vodopád"}, {"lat": 64.12532, "lng": -20.52414, "label": "Skálholt"}, {"lat": 64.04127, "lng": -20.88531, "label": "Kerið kráter"}, {"lat": 64.1465, "lng": -21.942, "label": "Cíl – Reykjavík"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=64.1465,-21.942&destination=64.1465,-21.942&travelmode=driving&waypoints=64.25548,-21.12977%7C64.18333,-21.15%7C64.31039,-20.30232%7C64.32707,-20.11995%7C64.22547,-20.33725%7C64.12532,-20.52414%7C64.04127,-20.88531', 'https://commons.wikimedia.org/wiki/Special:FilePath/Almannagj%C3%A1%20gorge,%20%C3%9Eingvellir%20National%20Park.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Almannagj%C3%A1%20gorge,%20%C3%9Eingvellir%20National%20Park.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C3%9Eingvallavatn.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Strokkur%20geyser%20eruption,%20close-up%20view.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gullfoss,%20an%20iconic%20waterfall%20of%20Iceland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Faxifoss%20waterfall,%20Iceland%202013.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20del%20lago%20%C3%9Eingvallavatn%20desde%20el%20observatorio%20Hakid,%20Su%C3%B0urland,%20Islandia,%202014-08-16,%20DD%20003.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hekla%20Volcano%20behind%20Skaholt%20Cathedral%20(30913419367).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Keri%C3%B0%20crater%20lake,%20Iceland%20-%20Eric%20Marchese.jpg"}'::text[], '{"Þingvellir NP","Þingvallavatn","Geysir (Strokkur)","Gullfoss","Faxi vodopád","Restaurace: Efstidalur II (Laugarvatn)","Skálholt","Kerið kráter"}'::text[], '{"Island"}'::text[], false, 540, 'approved');

  -- Dánsko – Skagen a jutské pobřeží  (550_dk_skagen.json)
  delete from public.routes where name = 'Dánsko – Skagen a jutské pobřeží' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Dánsko – Skagen a jutské pobřeží', 'Jednodenní pobřežní okruh severním Jutskem, který spojuje nejsevernější cíp Dánska s malebnými písečnými dunami, majáky a rybářskými vesnicemi podél Severního moře a Skagerraku. Trasu jsme záměrně vedli mimo dálnice (dálnici E39) – místo toho jedeme po klidných pobřežních a venkovských silnicích jako Kandestedvej, Gl. Skagen a silnicích podél západního pobřeží, kde je výhled na moře a duny. Začínáme na samotném hrotu Grenen, kde se setkávají dvě moře, pokračujeme přes zaváté duny a maják Rubjerg Knude až do přístavu Hirtshals a končíme v živém Aalborgu. Počítejte s otevřenou krajinou, silným pobřežním větrem a širokými panoramaty – ideální na klidnou vyjížďku bez spěchu. Celý okruh zvládnete pohodlně za jeden den včetně zastávek na fotky, kávu a procházky po plážích.', 'poi', 175, 300, 'easy',
     '[{"lat": 57.73977, "lng": 10.6418, "label": "Grenen (Skagen) – start, setkání dvou moří"}, {"lat": 57.71364, "lng": 10.55061, "label": "Den Tilsandede Kirke – zaváté kostel"}, {"lat": 57.6422, "lng": 10.4037, "label": "Råbjerg Mile – putující duna"}, {"lat": 57.443, "lng": 9.7718, "label": "Rubjerg Knude Fyr – maják na útesu"}, {"lat": 57.4684, "lng": 9.798, "label": "Lønstrup – rybářská vesnice"}, {"lat": 57.5881, "lng": 9.9592, "label": "Hirtshals – přístav a maják"}, {"lat": 57.048, "lng": 9.9187, "label": "Aalborg – cíl, nábřeží"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=57.73977,10.6418&destination=57.048,9.9187&travelmode=driving&waypoints=57.71364,10.55061%7C57.6422,10.4037%7C57.443,9.7718%7C57.4684,9.798%7C57.5881,9.9592', 'https://commons.wikimedia.org/wiki/Special:FilePath/Grenen,%20Skagen,%20Dinamarca,%202019-09-09,%20DD%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grenen,%20Skagen,%20Dinamarca,%202019-09-09,%20DD%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Den%20tilsandede%20kirke%2002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/190DK%20R%C3%A5bjerg%20Mile%20(14952866030).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rubjerg%20Knude%20Fyr,%20Hj%C3%B8rring,%20Denmark,%201807072231,%20ako.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%B8nstrup%20Coast%2020160529%20ubt.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skibe%20i%20Hirtshals%20havn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hirtshals%20Fyr%202015.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aalborg%20Havnefront%201.jpg"}'::text[], '{"Grenen (Skagen)","Den Tilsandede Kirke","Råbjerg Mile","Rubjerg Knude Fyr","Lønstrup","Restaurace: Abstrakt (Hirtshals)","Hirtshals","Aalborg"}'::text[], '{"Dánsko"}'::text[], false, 550, 'approved');

  -- Skotsko – North Coast 500  (560_uk_nc500.json)
  delete from public.routes where name = 'Skotsko – North Coast 500' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Skotsko – North Coast 500', 'North Coast 500 je legendární okruh po severním pobřeží Skotska, který startuje i končí v Inverness a měří kolem 830 km. Trasa vědomě vede po malebných pobřežních silnicích (A832, A835, A894, A838, A99) a zcela se vyhýbá dálnicím – žádnou dálnici na NC500 nepotkáte, což je součást jejího kouzla. POZOR: ve Skotsku se jezdí vlevo, a velká část trasy vede po úzkých jednoproudých silnicích (single-track roads) s výhybnami, takže je nutná trpělivost a ohleduplnost. Doporučujeme rozdělit okruh na 5–7 dní: 1. den Inverness → Applecross přes ikonický průsmyk Bealach na Bà, 2. den Applecross → Torridon → Ullapool, 3. den Ullapool → Lochinver → Kylesku, 4. den až Durness a mys Cape Wrath, 5. den severní pobřeží k John o'' Groats a Duncansby Head, 6.–7. den návrat přes Wick a Dunrobin Castle zpět do Inverness. Počítejte s pomalým průměrem, proměnlivým počasím a časovou rezervou na fotopauzy a trajekt k majáku Cape Wrath.', 'loop', 830, 4200, 'hard',
     '[{"lat": 57.47908, "lng": -4.22398, "label": "Inverness (start)"}, {"lat": 57.4263, "lng": -5.7515, "label": "Bealach na Bà"}, {"lat": 57.43241, "lng": -5.81686, "label": "Applecross"}, {"lat": 57.5462, "lng": -5.5048, "label": "Torridon"}, {"lat": 57.89588, "lng": -5.15887, "label": "Ullapool"}, {"lat": 58.14671, "lng": -5.24549, "label": "Lochinver"}, {"lat": 58.1668, "lng": -5.3076, "label": "Achmelvich"}, {"lat": 58.25675, "lng": -5.02124, "label": "Kylesku most"}, {"lat": 58.5677, "lng": -4.7456, "label": "Durness"}, {"lat": 58.5578, "lng": -4.7187, "label": "Smoo Cave"}, {"lat": 58.62766, "lng": -4.99958, "label": "Cape Wrath"}, {"lat": 58.6431, "lng": -3.0697, "label": "John o'' Groats"}, {"lat": 58.6433, "lng": -3.0229, "label": "Duncansby Head"}, {"lat": 57.98269, "lng": -3.9457, "label": "Dunrobin Castle"}, {"lat": 58.4388, "lng": -3.0937, "label": "Wick (cíl okruhu)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=57.47908,-4.22398&destination=58.4388,-3.0937&travelmode=driving&waypoints=57.4263,-5.7515%7C57.43241,-5.81686%7C57.5462,-5.5048%7C57.89588,-5.15887%7C58.14671,-5.24549%7C58.1668,-5.3076%7C58.25675,-5.02124%7C58.5677,-4.7456', 'https://commons.wikimedia.org/wiki/Special:FilePath/Inverness%20Castle,%20Scotland%20-%20Diliff.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Inverness%20Castle,%20Scotland%20-%20Diliff.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bealach%20na%20Ba%20Pano.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Applecross-Jetty.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Applecross%20Inn%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Scotland%20Torridon%20village.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ullapool%20harbour.%20-%20geograph.org.uk%20-%204649432.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ullapool%20harbour%20at%20low%20water%20-%20geograph.org.uk%20-%205989216.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Trawler%20at%20Lochinver%20Harbour%20-%20geograph.org.uk%20-%201018140.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sunset,%20Achmelvich%20Beach%20-%20geograph.org.uk%20-%20364193.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kylesku%20bridge%20surroundings.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sango%20Island%20-%20geograph.org.uk%20-%20341175.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Entrance%20to%20Smoo%20Cave.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Wrath%20lighthouse.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/John%20o''%20Groats.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Duncansby%20Head%20lighthouse.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/DunrobinCastle1.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wick%20Caithness%20Scottish%20Highlands.jpg"}'::text[], '{"Inverness","Bealach na Bà","Applecross","Restaurace: Applecross Inn (Applecross)","Torridon","Ullapool","Restaurace: The Seafood Shack (Ullapool)","Lochinver","Achmelvich","Kylesku most","Durness","Smoo Cave","Cape Wrath","John o'' Groats","Duncansby Head","Dunrobin Castle","Wick"}'::text[], '{"Skotsko","Spojené království"}'::text[], false, 560, 'approved');

  -- Wales – Snowdonia  (570_uk_snowdonia.json)
  delete from public.routes where name = 'Wales – Snowdonia' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Wales – Snowdonia', 'Jednodenní scénický okruh srdcem národního parku Eryri (Snowdonia) v severním Walesu, který se záměrně vyhýbá dálnicím i rychlým silnicím a drží se úzkých horských cest A4086, A498, A5 a A5086. POZOR: ve Walesu se jezdí VLEVO, silnice jsou úzké, klikaté a často bez krajnice, s ovcemi a kamennými zídkami u okraje – jeďte defenzivně a počítejte s protijedoucími auty za zatáčkami. Okruh začíná v Llanberis, stoupá dramatickým průsmykem Pen-y-Pass, klesá k jezerům Llyn Gwynant a Llyn Dinas do vesničky Beddgelert, poté se vrací přes Capel Curig, Betws-y-Coed a údolí Ogwen zpět. Nejlepší je jet brzy ráno, kdy je provoz turistů nižší a horské výhledy nejčistší; počasí se v horách mění rychle, vezměte si nepromokavé oblečení. Celý okruh se dá pohodlně projet za jeden den včetně zastávek na fotky, kávu a krátké procházky k vodopádům.', 'loop', 72, 150, 'medium',
     '[{"lat": 53.11667, "lng": -4.1275, "label": "Start – Llanberis"}, {"lat": 53.08064, "lng": -4.02048, "label": "Pen-y-Pass (Llanberis Pass)"}, {"lat": 53.0522, "lng": -4.0169, "label": "Llyn Gwynant"}, {"lat": 53.0071, "lng": -4.1015, "label": "Beddgelert"}, {"lat": 53.10615, "lng": -3.91236, "label": "Capel Curig"}, {"lat": 53.09382, "lng": -3.80668, "label": "Betws-y-Coed"}, {"lat": 53.0928, "lng": -3.823, "label": "Swallow Falls"}, {"lat": 53.12442, "lng": -4.00726, "label": "Llyn Ogwen"}, {"lat": 53.11667, "lng": -4.1275, "label": "Cíl – Llanberis"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=53.11667,-4.1275&destination=53.11667,-4.1275&travelmode=driving&waypoints=53.08064,-4.02048%7C53.0522,-4.0169%7C53.0071,-4.1015%7C53.10615,-3.91236%7C53.09382,-3.80668%7C53.0928,-3.823%7C53.12442,-4.00726', 'https://commons.wikimedia.org/wiki/Special:FilePath/Llanberis%20Pass%20-%20geograph.org.uk%20-%20748386.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Llanberis%20Pass%20-%20geograph.org.uk%20-%20748386.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bwlch%20Glas%20from%20the%20summit%20of%20Yr%20Wyddfa-Snowdon%20-%20geograph.org.uk%20-%20275057.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Llyn%20Gwynant.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/River%20Glaslyn,%20Beddgelert%20-%20geograph.org.uk%20-%20992059.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/River%20Glaslyn,%20Beddgelert%20-%20geograph.org.uk%20-%20992059.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Snowdon%20from%20Capel%20Curig.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Betws-y-coed,%20Pont-y-Pair%20Bridge%20-%20geograph.org.uk%20-%203606393.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Swallow%20Falls%20Betws-y-Coed%20-%20geograph.org.uk%20-%201015874.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Llyn%20Ogwen.JPG"}'::text[], '{"Pen-y-Pass (průsmyk Llanberis)","Snowdon / Yr Wyddfa","Llyn Gwynant","Beddgelert","Restaurace: Bistro Hebog (Beddgelert)","Capel Curig","Betws-y-Coed","Swallow Falls (Rhaeadr Ewynnol)","Llyn Ogwen"}'::text[], '{"Spojené království","Wales"}'::text[], false, 570, 'approved');

  -- Irsko – Ring of Kerry  (580_ie_kerry.json)
  delete from public.routes where name = 'Irsko – Ring of Kerry' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – Ring of Kerry', 'Ring of Kerry je proslulý okruh po poloostrově Iveragh v jihozápadním Irsku, který spojuje divoké pobřeží Atlantiku s horami MacGillycuddy''s Reeks. Trasa se drží pobřežních silnic (N70, N71) a menších okresních cest a záměrně se VYHÝBÁ dálnicím (motorway/dálnice) – žádná dálnice zde ani nevede, takže jedete jen malebnými serpentinami a vyhlídkovými úseky. POZOR: v Irsku se jezdí VLEVO, dbejte na to hlavně v úzkých zatáčkách a u kruhových objezdů. Doporučuje se jet okruh proti směru hodinových ručiček (z Killarney přes Killorglin), protože turistické autobusy jedou opačně a nebudete je potkávat čelně. Silnice bývají úzké, místy bez krajnice, s ovcemi na cestě a proměnlivým počasím, proto počítejte s pomalejším tempem a rezervou. Jednodenní okruh se startem i cílem v Killarney zvládnete pohodlně za jeden den včetně zastávek na vyhlídkách a v přístavních vesničkách.', 'loop', 179, 300, 'medium',
     '[{"lat": 52.05994, "lng": -9.50443, "label": "Killarney (start)"}, {"lat": 52.0244, "lng": -9.63665, "label": "Gap of Dunloe"}, {"lat": 51.94776, "lng": -10.2209, "label": "Cahersiveen"}, {"lat": 51.88543, "lng": -10.36194, "label": "Portmagee"}, {"lat": 51.8274, "lng": -10.172, "label": "Waterville"}, {"lat": 51.83824, "lng": -9.89953, "label": "Sneem"}, {"lat": 51.94056, "lng": -9.65333, "label": "Moll''s Gap"}, {"lat": 51.96739, "lng": -9.59284, "label": "Ladies View"}, {"lat": 52.02127, "lng": -9.50446, "label": "Muckross House"}, {"lat": 52.05994, "lng": -9.50443, "label": "Killarney (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=52.05994,-9.50443&destination=52.05994,-9.50443&travelmode=driving&waypoints=52.0244,-9.63665%7C51.94776,-10.2209%7C51.88543,-10.36194%7C51.8274,-10.172%7C51.83824,-9.89953%7C51.94056,-9.65333%7C51.96739,-9.59284%7C52.02127,-9.50446', 'https://commons.wikimedia.org/wiki/Special:FilePath/Muckross%20Lake,%20Killarney%20(NBY%20438657).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Muckross%20Lake,%20Killarney%20(NBY%20438657).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gap%20of%20Dunloe%20by%20Bob%20Demuyser.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Killarney%20National%20Park%20-%20Ladies%20View.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Road%20and%20Hillside%20before%20Molls%20Gap%20-%20geograph.org.uk%20-%2016041.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Colourful%20buildings%20in%20South%20Square%20Sneem%20-%20geograph.org.uk%20-%202724880.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sneem,%20Post%20Office%20and%20Sneem%20Tavern%20-%20geograph.org.uk%20-%205242043.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Waterville%20Est%C3%A1tua%20de%20Chaplin.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Portmagee%20Harbour.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kells%20Bay.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cahersiveen%20Barracks.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Muckross%20House-16-2017-gje.jpg"}'::text[], '{"Národní park Killarney","Gap of Dunloe","Ladies View","Moll''s Gap","Sneem","Restaurace: D O''Sheas Bar (Sneem)","Waterville","Portmagee (brána ke Skelligům)","Kells Bay","Cahersiveen","Muckross House"}'::text[], '{"Irsko"}'::text[], false, 580, 'approved');

  -- Nizozemsko – Afsluitdijk a Veluwe  (590_nl_veluwe.json)
  delete from public.routes where name = 'Nizozemsko – Afsluitdijk a Veluwe' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Nizozemsko – Afsluitdijk a Veluwe', 'Jednodenní scénický okruh napříč Nizozemskem, který záměrně vynechává dálnice (snareeg/A7 obcházíme po vedlejších silnicích) a vede vás po klidných hrázích, poldrech a mezi větrnými mlýny. Trasa začíná na legendární 32 km dlouhé hrázi Afsluitdijk, odkud se vydáte přes lesnaté vřesoviště Veluwe s národním parkem a muzeem Kröller-Müller. Pokračujete do pohádkového Giethoornu, přezdívaného benátky severu, a přes hanzovní městečko Elburg. Cesta uzavírá klasické nizozemské ikony – mlýny v Kinderdijku a skanzen Zaanse Schans u Amsterdamu. Počítejte s rovinatými, dobře udržovanými vedlejšími silnicemi, cyklisty a mnoha zastávkami na fotky, takže spěch se nekoná. Ideální pohodová jízda pro poznávání kultury i krajiny za jeden den.', 'poi', 295, 390, 'easy',
     '[{"lat": 53.06667, "lng": 5.34, "label": "Den Oever – začátek hráze Afsluitdijk"}, {"lat": 53.005, "lng": 5.1875, "label": "Afsluitdijk – střed hráze"}, {"lat": 52.7372, "lng": 6.0732, "label": "Giethoorn"}, {"lat": 52.44927, "lng": 5.83452, "label": "Elburg"}, {"lat": 52.09815, "lng": 5.82922, "label": "Nationaal Park De Hoge Veluwe"}, {"lat": 52.0908, "lng": 5.8168, "label": "Kröller-Müller Museum"}, {"lat": 51.8857, "lng": 4.62744, "label": "Kinderdijk"}, {"lat": 52.47346, "lng": 4.82028, "label": "Zaanse Schans"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=53.06667,5.34&destination=52.47346,4.82028&travelmode=driving&waypoints=53.005,5.1875%7C52.7372,6.0732%7C52.44927,5.83452%7C52.09815,5.82922%7C52.0908,5.8168%7C51.8857,4.62744', 'https://commons.wikimedia.org/wiki/Special:FilePath/De%20Afsluitdijk.%20ID510448.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/De%20Afsluitdijk.%20ID510448.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oude%20Dennenboom%20in%20Nationaal%20Park%20de%20Hooge%20Veluwe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Overzicht%20beeldentuin%20Kroller-Muller.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Netherlands,%20Giethoorn%20(02),%20tourism.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/20221-Vispoort.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/20221-Vispoort.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/The%20windmills%20of%20Kinderdijk.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zaanse%20Schans%20-%20Windmills%203.jpg"}'::text[], '{"Afsluitdijk","Nationaal Park De Hoge Veluwe","Kröller-Müller Museum","Giethoorn","Elburg","Restaurace: Achter de Poorte (Elburg)","Kinderdijk","Zaanse Schans"}'::text[], '{"Nizozemsko"}'::text[], false, 590, 'approved');

  -- Belgie – Ardeny  (600_be_ardeny.json)
  delete from public.routes where name = 'Belgie – Ardeny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Belgie – Ardeny', 'Jednodenní okruh srdcem belgických Arden, který se vědomě vyhýbá dálnicím a vede výhradně po klikatých lesních a údolních silnicích. Trasa spojuje hluboká údolí řek Ourthe, Amblève a Semois s hustými smrkovými lesy a vřesovišti kolem přehrad. Cesta začíná v malebném La Roche-en-Ardenne, míří přes legendární okruh Spa-Francorchamps a válečné Bastogne až k romantickému Bouillonu na jihu. Serpentiny jsou pro motorkáře odměnou, ale vyžadují soustředění, protože vozovka bývá po lese vlhká a místy pokrytá listím. Počítejte s tankováním v Bastogne nebo Vielsalm, protože mezi obcemi jsou delší úseky bez čerpacích stanic. Celý den je koncipován jako pohodová okružní jízda s dostatkem času na zastávky, kávu a fotografování.', 'loop', 215, 330, 'medium',
     '[{"lat": 50.1836, "lng": 5.5755, "label": "La Roche-en-Ardenne (hrad)"}, {"lat": 50.35306, "lng": 5.45604, "label": "Durbuy"}, {"lat": 50.58731, "lng": 5.97112, "label": "Barrage de la Gileppe"}, {"lat": 50.44474, "lng": 5.96837, "label": "Circuit de Spa-Francorchamps"}, {"lat": 50.39356, "lng": 5.87683, "label": "Coo (vodopád)"}, {"lat": 50.00972, "lng": 5.73889, "label": "Bastogne (Mardasson)"}, {"lat": 49.79274, "lng": 5.06543, "label": "Bouillon (hrad)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.1836,5.5755&destination=49.79274,5.06543&travelmode=driving&waypoints=50.35306,5.45604%7C50.58731,5.97112%7C50.44474,5.96837%7C50.39356,5.87683%7C50.00972,5.73889', 'https://commons.wikimedia.org/wiki/Special:FilePath/0%20La%20Roche-en-Ardenne%20050518%20(8).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/0%20La%20Roche-en-Ardenne%20050518%20(8).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Durbuy%20-%20Le%20ch%C3%A2teau%20vu%20du%20sommet%20de%20l''Anticlinal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lion%20de%20la%20Gileppe%20by%20Niederkasseler%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2021%206%20Hours%20of%20Spa-Francorchamps%20-%20Raidillon.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Coo%20waterfall.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Mardasson%20Memorial%20Bastogne.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/PLACE%20MCAULIFFE%20IN%20BASTOGNE%20BELGIUM.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/0%20Bouillon%20-%20Ch%C3%A2teau-fort%20et%20pont%20sur%20la%20Semois%20(1).JPG"}'::text[], '{"La Roche-en-Ardenne (hrad)","Durbuy","Barrage de la Gileppe","Circuit de Spa-Francorchamps","Coo (vodopád)","Bastogne (Mardasson)","Restaurace: Complètement Toqué (Bastogne)","Bouillon (hrad)"}'::text[], '{"Belgie"}'::text[], false, 600, 'approved');

  -- Lucembursko – Müllerthal a Vianden  (610_lu_mullerthal.json)
  delete from public.routes where name = 'Lucembursko – Müllerthal a Vianden' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Lucembursko – Müllerthal a Vianden', 'Pohodový jednodenní okruh napříč nejkrásnějšími kouty Lucemburska, který se záměrně vyhýbá dálnicím a vede pouze po klidných regionálních silnicích. Trasa spojuje pohádkový hrad Vianden nad údolím Our, romantické skalní soutěsky Müllerthalu zvaného Lucemburské Švýcarsko a nejstarší město země Echternach. Cestou se motorkář proplétá zvlněnou krajinou plnou zatáček, hlubokých lesů a údolí řek Sûre a Alzette. Silnice jsou úzké, ale kvalitní a dobře čitelné, takže okruh zvládne i méně zkušený jezdec. Ideální je vyrazit brzy ráno, aby zbyl čas na prohlídku hradů a zastávku u vodopádu. Celý okruh se dá pohodlně projet za jeden den včetně přestávek na kávu a fotografování.', 'loop', 135, 240, 'easy',
     '[{"lat": 49.61556, "lng": 6.13194, "label": "Start – Lucemburk, staré město"}, {"lat": 49.78561, "lng": 6.21724, "label": "Larochette"}, {"lat": 49.83583, "lng": 6.29167, "label": "Beaufort"}, {"lat": 49.78515, "lng": 6.29936, "label": "Müllerthal – Schiessentümpel"}, {"lat": 49.8125, "lng": 6.4225, "label": "Echternach"}, {"lat": 49.93488, "lng": 6.20283, "label": "Vianden"}, {"lat": 49.9167, "lng": 5.9333, "label": "Esch-sur-Sûre"}, {"lat": 49.61556, "lng": 6.13194, "label": "Cíl – Lucemburk"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.61556,6.13194&destination=49.61556,6.13194&travelmode=driving&waypoints=49.78561,6.21724%7C49.83583,6.29167%7C49.78515,6.29936%7C49.8125,6.4225%7C49.93488,6.20283%7C49.9167,5.9333', 'https://commons.wikimedia.org/wiki/Special:FilePath/Luxembourg%20(Old%20city%20panorama).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Luxembourg%20(Old%20city%20panorama).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Larochette,%20Luxembourg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/17th%20century%20castle%20Beaufort%20Luxembourg%202013-08%20--2.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schiessent%C3%BCmpel.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Echternach%20St%20Willibrord%20Basilika%20R03.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Echternach%20Dom.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Luxembourg,%20Vianden,%20Castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Esch-S%C3%BBre,%20um%20ale%20B%C3%ABsch%20(2).jpg"}'::text[], '{"Lucemburk – staré město","Larochette","Beaufort (hrad)","Müllerthal – Schiessentümpel","Echternach","Restaurace: GriMouGi (Echternach)","Vianden (hrad)","Esch-sur-Sûre"}'::text[], '{"Lucembursko"}'::text[], false, 610, 'approved');

  -- Lichtenštejnsko – Malbun a Rýnské údolí  (620_li_malbun.json)
  delete from public.routes where name = 'Lichtenštejnsko – Malbun a Rýnské údolí' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Lichtenštejnsko – Malbun a Rýnské údolí', 'Jednodenní vyhlídkový okruh malým alpským knížectvím, který začíná v hlavním městě Vaduz a stoupá serpentinami do horské obce Triesenberg s výhledy do Rýnského údolí. Trasa záměrně vede jen po klikatých horských a údolních silnicích – ŽÁDNÉ dálnice ani rychlostní silnice, čistě scénické okresky s množstvím zatáček. Z Triesenbergu pokračujeme přes náhorní plošinu Steg až do lyžařského střediska Malbun v nadmořské výšce kolem 1600 m, které je vrcholem celého výletu. Zpátky sjíždíme stejnými serpentinami do údolí a okruh uzavíráme na jihu u hradu Gutenberg v Balzers. Díky malým rozměrům státu se celý okruh pohodlně zvládne za jeden den včetně zastávek na focení a kávu.', 'loop', 48, 110, 'easy',
     '[{"lat": 47.13938, "lng": 9.52145, "label": "Vaduz – zámek"}, {"lat": 47.11856, "lng": 9.54344, "label": "Triesenberg"}, {"lat": 47.1077, "lng": 9.57771, "label": "Steg – Gänglesee"}, {"lat": 47.1012, "lng": 9.6048, "label": "Malbun"}, {"lat": 47.11856, "lng": 9.54344, "label": "Triesenberg (návrat)"}, {"lat": 47.06565, "lng": 9.50054, "label": "Balzers – hrad Gutenberg"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.13938,9.52145&destination=47.06565,9.50054&travelmode=driving&waypoints=47.11856,9.54344%7C47.1077,9.57771%7C47.1012,9.6048%7C47.11856,9.54344', 'https://commons.wikimedia.org/wiki/Special:FilePath/Liechtenstein%20asv2022-10%20img22%20Vaduz%20Schloss.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Liechtenstein%20asv2022-10%20img22%20Vaduz%20Schloss.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2018-10-05%20Liechtenstein,%20Triesenberg,%20Bergstrasse%20(KPFC)%2001%20(cropped).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Steg,%20Liechtenstein.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/LIE%20%E2%80%94%20Gemeinde%20Triesenberg%20Malbun%20%284er%20Sessellift%20Sareis%20%C2%B7%20Talstation%29%202023-05-29.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/9490%20Vaduz%2C%20Liechtenstein%20-%20panoramio%20%281%29.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Gutenberg%20in%20Balzers,%20Liechtenstein.jpg"}'::text[], '{"Vaduz – zámek Vaduz","Triesenberg","Steg – Gänglesee","Malbun","Restaurace: Torkel (Vaduz)","Balzers – hrad Gutenberg"}'::text[], '{"Lichtenštejnsko"}'::text[], false, 620, 'approved');

  -- Polsko – Bieszczady  (630_pl_bieszczady.json)
  delete from public.routes where name = 'Polsko – Bieszczady' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Polsko – Bieszczady', 'Okruh po nejkrásnějších horských silnicích polských Bieszczad, který ZÁMĚRNĚ vede mimo dálnice a rychlostní silnice – jede se výhradně po klikatých krajských a národních silnicích (droga wojewódzka 894, 895, 896, 897). Trasa kopíruje slavnou Wielkou Obwodnicu Bieszczadzku, legendární okružní silnici plnou serpentin, průsmyků a rozlehlých výhledů na poloniny. Startuje se v Lesku, projede se přehrada Solina, stoupá se do horských sedel Wyżna a Wyżniańska a klesá zpět přes Cisnu. Vozovka je většinou kvalitní, ale úzká a s množstvím zatáček, proto je ideální pro poklidnou, zážitkovou jízdu na jeden až dva dny. Doporučujeme přenocovat v Ustrzykach Górnych nebo ve Wetlině a druhý den si okruh dojet v klidu s zastávkami na poloniny.', 'loop', 185, 330, 'medium',
     '[{"lat": 49.46733, "lng": 22.33056, "label": "Lesko – start"}, {"lat": 49.3952, "lng": 22.4545, "label": "Zapora Solina"}, {"lat": 49.15139, "lng": 22.47333, "label": "Wetlina / Cisna"}, {"lat": 49.15716, "lng": 22.54965, "label": "Przełęcz Wyżna"}, {"lat": 49.1641, "lng": 22.5357, "label": "Połonina Wetlińska"}, {"lat": 49.10517, "lng": 22.64923, "label": "Ustrzyki Górne"}, {"lat": 49.46733, "lng": 22.33056, "label": "Lesko – cíl"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.46733,22.33056&destination=49.46733,22.33056&travelmode=driving&waypoints=49.3952,22.4545%7C49.15139,22.47333%7C49.15716,22.54965%7C49.1641,22.5357%7C49.10517,22.64923', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bieszczady.%20Serpentyny%20nad%20Berehami%20i%20Po%C5%82onina%20Cary%C5%84ska.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bieszczady.%20Serpentyny%20nad%20Berehami%20i%20Po%C5%82onina%20Cary%C5%84ska.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Solina%20Jezioro.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Po%C5%82onina%20Wetli%C5%84ska%20-%20Chatka%20Puchatka%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ustrzyki%20G%C3%B3rne%20ko%C5%9Bci%C3%B3%C5%82%20%C5%9Bw.%20Anny.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Majdan%20Cisna%20kolejka%20waskotorowa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gmina%20Cisna,%20Poland%20-%20panoramio%20(2).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bieszczady%20DK28.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Solina%20zapora%200001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lesko,%20zamek%20Kmit%C3%B3w%2001.JPG"}'::text[], '{"Wielka Obwodnica Bieszczadzka","Solina (přehrada)","Połonina Wetlińska","Ustrzyki Górne","Cisna","Restaurace: Polanka Kawiarnia & Bistro (Cisna)","Przełęcz Wyżna","Zapora Solina","Lesko"}'::text[], '{"Polsko"}'::text[], false, 630, 'approved');

  -- Polsko – Tatry a Morskie Oko  (640_pl_tatry.json)
  delete from public.routes where name = 'Polsko – Tatry a Morskie Oko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Polsko – Tatry a Morskie Oko', 'Jednodenní okruh polským podhůřím Tater, který záměrně vynechává dálnice a vede po malebných regionálních silnicích Podhala a Pienin. Vyrazíte přes Zakopane, tatranskou metropoli s dřevěnou architekturou, k parkovišti Palenica Białczańska pod Morskim Okem, nejkrásnějším tatranským jezerem. Cestou si užijete panoramata z Gubałówky, klidnou Dolinu Kościeliska a nad hladinou Czorsztyńského jezera se tyčící ruiny hradu Czorsztyn. Trasa se vine serpentinami, úzkými horskými úseky a lesními silnicemi, kde je potřeba počítat s turistickým provozem a přechody pro chodce. Vhodné pro zkušenější jezdce, kteří ocení kombinaci zatáček, výhledů a kulturních zastávek včetně dřevěného kostela v Dębně zapsaného na seznamu UNESCO. Doporučujeme brzký start, protože parkoviště pod Morskim Okem i centrum Zakopaného se rychle plní.', 'poi', 210, 330, 'medium',
     '[{"lat": 49.29903, "lng": 19.94905, "label": "Zakopane"}, {"lat": 49.305, "lng": 19.943, "label": "Gubałówka"}, {"lat": 49.275, "lng": 19.87, "label": "Dolina Kościeliska (Kiry)"}, {"lat": 49.19758, "lng": 20.0705, "label": "Morskie Oko (Palenica Białczańska)"}, {"lat": 49.46649, "lng": 20.21202, "label": "Dębno – dřevěný kostel"}, {"lat": 49.43511, "lng": 20.3132, "label": "Czorsztyn – hrad a jezero"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.29903,19.94905&destination=49.43511,20.3132&travelmode=driving&waypoints=49.305,19.943%7C49.275,19.87%7C49.19758,20.0705%7C49.46649,20.21202', 'https://commons.wikimedia.org/wiki/Special:FilePath/Zakopane%20ulica%20Krupowki%20zima%20noc-by%20Robert%20Parma.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zakopane%20ulica%20Krupowki%20zima%20noc-by%20Robert%20Parma.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zakopane%20ul.%20Krup%C3%B3wki.%20Willa%20Poraj%20(2).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20Morskie%20Oko%20in%20April.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Tatr%20z%20Guba%C5%82%C3%B3wki.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Organy.%20Dolina%20Ko%C5%9Bcieliska.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Debno%20kosciol%204.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Czorsztyn.%20Ruiny%20zamku,%20kon.XIII,%20XVI,%201680.%20128.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Niedzica%20Castle%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Niedzica%20Castle%201.jpg"}'::text[], '{"Zakopane","Restaurace: Bistro Kryjówka (Zakopane)","Morskie Oko","Gubałówka","Dolina Kościeliska","Dębno","Czorsztyn","Zamek Niedzica","Restaurace: Restauracja by Marco (Niedzica)"}'::text[], '{"Polsko"}'::text[], false, 640, 'approved');

  -- Slovensko – Vysoké Tatry a Slovenský ráj  (650_sk_tatry.json)
  delete from public.routes where name = 'Slovensko – Vysoké Tatry a Slovenský ráj' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Slovensko – Vysoké Tatry a Slovenský ráj', 'Dvoudenní scénická okružní jízda po nejkrásnějších silnicích východního Slovenska, která záměrně vynechává dálnice (D1) a vede výhradně po tečících horských cestách včetně slavné Cesty slobody vedoucí pod hřebeny Vysokých Tater. První den je věnovaný Vysokým Tatrám: start u Štrbského plesa, přejezd Cesty slobody přes Starý Smokovec a Tatranskou Lomnicu s odbočkou na Hrebienok, poté sjezd na východ k UNESCO památkám Spišský hrad a Levoča. Druhý den zamíří do Slovenského ráje – Dobšinská ľadová jaskyňa, kaňon Prielom Hornádu u Hrabušic, a návrat přes malebné Vernárske sedlo a úpatí Kráľovy hole s okouzlující serpentinou nad Telgártom. Trasa kombinuje plynulé stoupačky, mírné serpentiny a dlouhé rozhledové úseky, takže je ideální pro středně zkušené motorkáře. Kvůli horskému charakteru počítejte s chladnějším počasím ve výškách a proměnlivým povrchem po deštích.', 'poi', 320, 420, 'medium',
     '[{"lat": 49.1193, "lng": 20.06301, "label": "Štrbské Pleso – start"}, {"lat": 49.16472, "lng": 20.27833, "label": "Tatranská Lomnica"}, {"lat": 49.15667, "lng": 20.2225, "label": "Hrebienok / Starý Smokovec"}, {"lat": 49.0005, "lng": 20.76863, "label": "Spišský hrad"}, {"lat": 49.02528, "lng": 20.58944, "label": "Levoča"}, {"lat": 48.87222, "lng": 20.3, "label": "Dobšinská ľadová jaskyňa"}, {"lat": 48.99, "lng": 20.27, "label": "Prielom Hornádu / Hrabušice"}, {"lat": 48.9, "lng": 20.13, "label": "Vernárske sedlo / Vernár"}, {"lat": 48.8825, "lng": 20.14556, "label": "Kráľova hoľa – úpatí"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.1193,20.06301&destination=48.8825,20.14556&travelmode=driving&waypoints=49.16472,20.27833%7C49.15667,20.2225%7C49.0005,20.76863%7C49.02528,20.58944%7C48.87222,20.3%7C48.99,20.27%7C48.9,20.13', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20of%20Strbske%20pleso.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20of%20Strbske%20pleso.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grandhotel%20Praha%20Tatransk%C3%A1%20Lomnica%20(2).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrebienok,%20Vysok%C3%A9%20Tatry.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lanovka%20Star%C3%BD%20Smokovec%20-%20Hrebienok.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Spis%20Castle%20-%20Slovakia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Square%20Levo%C4%8Da16Slovakia18.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dob%C5%A1insk%C3%A1%20Ice%20Cave.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Slovensk%C3%BD%20r%C3%A1j,%20Prielom%20Horn%C3%A1du%20(17).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vern%C3%A1r%20-%20%C5%BEelezni%C4%8Dn%C3%A1%20zast%C3%A1vka%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/S%C5%82owacja%20-%20Kralova%20Hora.JPG"}'::text[], '{"Štrbské Pleso","Tatranská Lomnica","Hrebienok","Restaurace: Koliba Kamzík (Starý Smokovec)","Spišský hrad (UNESCO)","Levoča","Dobšinská ľadová jaskyňa","Slovenský ráj – Prielom Hornádu (Hrabušice)","Vernár","Kráľova hoľa"}'::text[], '{"Slovensko"}'::text[], false, 650, 'approved');

  -- Maďarsko – Balaton a Bakony  (660_hu_balaton.json)
  delete from public.routes where name = 'Maďarsko – Balaton a Bakony' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Maďarsko – Balaton a Bakony', 'Jednodenní scénický okruh kolem severního břehu Balatonu a přilehlého pohoří Bakony, vedený ZÁMĚRNĚ po vedlejších a krajinných silnicích – dálnici M7 se po celou dobu vyhýbáme. Trasa spojuje vinařské kopce, barokní města, středověké hrady a proslulou porcelánku a nabízí neustálé výhledy na jezero i sopečné kužely Tapolcké pánve. Začínáme na poloostrově Tihany, pokračujeme přes lázeňský Balatonfüred do historického Veszprému a Herendu, poté se stáčíme k hradům Sümeg a Szigliget, vinicím Badacsony a končíme u zámku Festetics v Keszthely. Silnice jsou převážně dobře udržované, s příjemnými zatáčkami v úseku Veszprém–Sümeg přes lesy Bakonského pohoří. Ideální celodenní vyjížďka s několika zastávkami na kávu, víno a fotky, tempo pohodové a technicky nenáročné.', 'loop', 175, 300, 'easy',
     '[{"lat": 46.91369, "lng": 17.88918, "label": "Tihany"}, {"lat": 46.95466, "lng": 17.89667, "label": "Balatonfüred"}, {"lat": 47.09327, "lng": 17.91149, "label": "Veszprém"}, {"lat": 47.13, "lng": 17.75, "label": "Herend"}, {"lat": 46.98216, "lng": 17.28254, "label": "Sümeg"}, {"lat": 46.80432, "lng": 17.43642, "label": "Szigliget"}, {"lat": 46.79, "lng": 17.5, "label": "Badacsony"}, {"lat": 46.77078, "lng": 17.24159, "label": "Keszthely"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.91369,17.88918&destination=46.77078,17.24159&travelmode=driving&waypoints=46.95466,17.89667%7C47.09327,17.91149%7C47.13,17.75%7C46.98216,17.28254%7C46.80432,17.43642%7C46.79,17.5', 'https://commons.wikimedia.org/wiki/Special:FilePath/Abtei%20Tihany.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Abtei%20Tihany.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tagore%20s%C3%A9t%C3%A1ny,%20Balatonf%C3%BCred%20-%202013.08.06%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Veszpr%C3%A9m%20Castle%20Area%20View%202010.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Budapest,%20Hungarian%20National%20Museum,%20Herend%20porcelain,%20plate%20and%20coffee%20set.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2016%20S%C3%BCmeg%20Castle%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szigliget%20castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szigliget%20castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Badacsonytomaj,%20Badacsony,%208261%20Hungary%20-%20panoramio%20(3).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Keszthely%20-%20Festetics%20Castle.jpg"}'::text[], '{"Tihany – benediktinské opatství","Balatonfüred – Tagoreho promenáda","Veszprém – hradní čtvrť","Herend – porcelánka","Sümeg – středověký hrad","Szigliget – hrad nad Balatonem","Restaurace: Villa Kabala (Szigliget)","Badacsony – sopečné vinice","Keszthely – zámek Festetics"}'::text[], '{"Maďarsko"}'::text[], false, 660, 'approved');

  -- Bulharsko – Shipka, Buzludža a Veliko Tarnovo  (670_bg_shipka.json)
  delete from public.routes where name = 'Bulharsko – Shipka, Buzludža a Veliko Tarnovo' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Bulharsko – Shipka, Buzludža a Veliko Tarnovo', 'Okruh centrálním Balkánem, který záměrně vynechává dálnice a vede výhradně po klikatých horských silnicích přes pohoří Stara planina. Trasu pojměte na dva dny: první den se točitými serpentinami vyšplhejte na průsmyk Shipka k Památníku svobody a odbočte na komunistický kolos Buzludža, poté sjeďte do Údolí růží ke Kazanlaku a přespěte v Gabrovu. Druhý den si užijte řemeslné městečko Etar, malebnou Tryavnu a přejezd hřebenem na sever do královského Velikého Tarnova s pevností Carevec. Silnice jsou technicky pestré – dlouhé stoupavé serpentiny na Shipce, uzké vesnické úseky u Tryavny a otevřené hřebenovky s výhledy. Počítejte s ostrými vlásenkami, místy zvlněným asfaltem a nižšími rychlostmi, o to větší zážitek z motorkaření. Nádrž doplňte v Kazanlaku i Gabrovu, mezi horskými úseky bývají čerpací stanice řídké.', 'poi', 215, 390, 'medium',
     '[{"lat": 42.753, "lng": 25.318, "label": "Průsmyk Shipka – Památník svobody"}, {"lat": 42.71619, "lng": 25.32896, "label": "Shipka – Chrám narození Kristova"}, {"lat": 42.7357, "lng": 25.3938, "label": "Pomník Buzludža"}, {"lat": 42.62597, "lng": 25.39919, "label": "Kazanlak – thrácká hrobka"}, {"lat": 42.80944, "lng": 25.34833, "label": "Etar – skanzen"}, {"lat": 42.87472, "lng": 25.33417, "label": "Gabrovo"}, {"lat": 42.86667, "lng": 25.5, "label": "Tryavna"}, {"lat": 43.07567, "lng": 25.61715, "label": "Veliko Tarnovo – Carevec"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.753,25.318&destination=43.07567,25.61715&travelmode=driving&waypoints=42.71619,25.32896%7C42.7357,25.3938%7C42.62597,25.39919%7C42.80944,25.34833%7C42.87472,25.33417%7C42.86667,25.5', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shipka%20pass%20(%D0%A8%D0%B8%D0%BF%D0%BA%D0%B0)%20-%20central%20Monument.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Shipka%20pass%20(%D0%A8%D0%B8%D0%BF%D0%BA%D0%B0)%20-%20central%20Monument.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Shipka%20Memorial%20Church%20(23343081802).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Buzludzha%20&%20Torch%20Monument.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20thracian%20tomb%20in%20Kazanlak%20from%20outside.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Etura%20Gabrovo%202.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Yantra%20River,%20Gabrovo,%20Bulgaria.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tryavna-imagesfrombulgaria.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Veliko%20Tarnovo%20(%D0%92%D0%B5%D0%BB%D0%B8%D0%BA%D0%BE%20%D0%A2%D1%8A%D1%80%D0%BD%D0%BE%D0%B2%D0%BE)%20-%20Tsarevets.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Fortress%20at%20Veliko%20Tarnovo.JPG"}'::text[], '{"Průsmyk Shipka – Památník svobody","Shipka – Chrám narození Kristova (Zlatý kostel)","Pomník Buzludža","Kazanlak – thrácká hrobka (Údolí růží)","Etar – skanzen","Gabrovo","Tryavna","Restaurace: Shtastliveca (Veliko Tarnovo)","Veliko Tarnovo – pevnost Carevec"}'::text[], '{"Bulharsko"}'::text[], false, 670, 'approved');

  -- Srbsko – Đerdap a Železná vrata  (680_rs_djerdap.json)
  delete from public.routes where name = 'Srbsko – Đerdap a Železná vrata' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Srbsko – Đerdap a Železná vrata', 'Malebná jednodenní trasa podél srbského břehu Dunaje soutěskou Đerdap (Železná vrata), jedním z nejdramatičtějších říčních kaňonů Evropy. Záměrně se vyhýbá dálnicím a rychlostním silnicím – celá jízda vede po klikaté regionální silnici Đerdapska magistrala (silnice 34/163), která kopíruje řeku a nabízí neustálý výhled na vodu a rumunské skály na druhém břehu. Trasa začíná u pevnosti Golubac a pokračuje proti proudu přes Národní park Đerdap, archeologické naleziště Lepenski Vir a městečko Donji Milanovac až k přehradě a Trajanově tabuli u Kladova. Silnice je úzká, s mnoha zatáčkami, tunely a prudkými srázy k řece, proto je vhodná pro zkušenější motorkáře a jízdu s rezervou. Naplánujte si celý den včetně přestávek na fotky, prohlídku muzea a jídlo v některé z rybářských hospůdek u vody.', 'poi', 135, 300, 'medium',
     '[{"lat": 44.66116, "lng": 21.67838, "label": "Pevnost Golubac – start"}, {"lat": 44.625, "lng": 21.85, "label": "Vstup do NP Đerdap"}, {"lat": 44.55, "lng": 22.0, "label": "Lepenski Vir"}, {"lat": 44.46593, "lng": 22.1517, "label": "Donji Milanovac"}, {"lat": 44.64112, "lng": 22.29123, "label": "Vyhlídka na sochu Decebala"}, {"lat": 44.65694, "lng": 22.31228, "label": "Tabula Traiana"}, {"lat": 44.6713, "lng": 22.52941, "label": "Přehrada Đerdap – cíl"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=44.66116,21.67838&destination=44.6713,22.52941&travelmode=driving&waypoints=44.625,21.85%7C44.55,22.0%7C44.46593,22.1517%7C44.64112,22.29123%7C44.65694,22.31228', 'https://commons.wikimedia.org/wiki/Special:FilePath/Golubac%20grad%202019%2002.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Golubac%20grad%202019%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Danube%20near%20Iron%20Gate%202006.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lepenski%20vir%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Donji%20Milanovac.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Donji%20Milanovac.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Frontal%20view%20of%20the%20Decebalus%20rock%20sculpture.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/RC174-Tabula%20Traiana.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wiki.%C4%90erdap%20II%20Iron%20Gate%20I%20hydroelectric%20power%20station%20707.jpg"}'::text[], '{"Pevnost Golubac","Národní park Đerdap","Lepenski Vir","Donji Milanovac","Restaurace: Lepenac (Donji Milanovac)","Socha Decebala","Tabula Traiana","Přehrada Đerdap"}'::text[], '{"Srbsko","Rumunsko"}'::text[], false, 680, 'approved');

  -- Bosna – pyramidy ve Visoku a Mostar  (690_ba_pyramids.json)
  delete from public.routes where name = 'Bosna – pyramidy ve Visoku a Mostar' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Bosna – pyramidy ve Visoku a Mostar', 'Malebná okružní trasa Bosnou a Hercegovinou, která záměrně vynechává dálnice a vede po klikatých horských silnicích a údolím řeky Neretvy s nádhernými výhledy. Trasa spojuje kontroverzní visocké pyramidy s osmanskými skvosty Sarajeva, Mostaru a Blagaje. Kolem takzvané Bosenské pyramidy Slunce panuje velká kontroverze – Semir Osmanagić tvrdí, že jde o umělou stavbu starou tisíce let, zatímco geologové a archeologové ji považují za přirozený útvar (tzv. flatiron) a celý projekt za pseudovědu. První den doporučujeme jet z Visoka přes pyramidy do Sarajeva a přenocovat v centru u Baščaršije. Druhý den pokračujte údolím Neretvy přes Jablanické jezero na jih do Mostaru, Blagaje, Počitelje a k vodopádům Kravice, které tvoří osvěžující finále. Počítejte s pomalejším tempem – užší silnice, tunely a zastávky na focení protáhnou čistý čas v sedle.', 'poi', 230, 420, 'medium',
     '[{"lat": 43.9888, "lng": 18.1702, "label": "Bosenská pyramida Slunce (Visočica)"}, {"lat": 43.98833, "lng": 18.17806, "label": "Visoko"}, {"lat": 43.8593, "lng": 18.4314, "label": "Sarajevo – Baščaršija"}, {"lat": 43.69222, "lng": 17.8275, "label": "Jablanické jezero"}, {"lat": 43.3356, "lng": 17.8153, "label": "Mostar – Stari Most"}, {"lat": 43.2572, "lng": 17.8864, "label": "Blagaj – Tekija"}, {"lat": 43.13458, "lng": 17.73196, "label": "Počitelj"}, {"lat": 43.15615, "lng": 17.60789, "label": "Vodopády Kravice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.9888,18.1702&destination=43.15615,17.60789&travelmode=driving&waypoints=43.98833,18.17806%7C43.8593,18.4314%7C43.69222,17.8275%7C43.3356,17.8153%7C43.2572,17.8864%7C43.13458,17.73196', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bosnian%20Pyramid.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bosnian%20Pyramid.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Old%20town%20Visoki.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sarajevo-bascarsija%20at%20night1.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jablani%C4%8Dko%20jezero%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stari%20most%20alte%20Br%C3%BCcke%202004%20Mostar%20Bosnien%20und%20Herzegowina%20Foto%20Wolfgang%20Pehlemann%20IMG%208136.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stari%20most%20alte%20Br%C3%BCcke%202004%20Mostar%20Bosnien%20und%20Herzegowina%20Foto%20Wolfgang%20Pehlemann%20IMG%208136.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dervish%20House,%20Blagaj%20(45259512482).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Po%C4%8Ditelj.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Waterfalls%20Kravica%206,%20Bosnia%20and%20Herzegovina.jpg"}'::text[], '{"Bosenská pyramida Slunce (Visoko)","Visoko (město)","Sarajevo (Baščaršija)","Jablanické jezero","Mostar (Stari Most)","Restaurace: Hindin Han (Mostar)","Blagaj (Tekija u pramene Buny)","Počitelj","Vodopády Kravice"}'::text[], '{"Bosna a Hercegovina"}'::text[], false, 690, 'approved');

  -- Černá Hora – Durmitor a kaňon Tary  (700_me_durmitor.json)
  delete from public.routes where name = 'Černá Hora – Durmitor a kaňon Tary' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Černá Hora – Durmitor a kaňon Tary', 'Náročný horský okruh napříč severní Černou Horou, který záměrně vynechává dálnice a vede výhradně po panoramatických horských silnicích. Z městečka Žabljak stoupáte národním parkem Durmitor kolem ledovcového Černého jezera, přejíždíte nejvyšší zpevněný průsmyk země Sedlo (silnice P14) a kocháte se hlubokým kaňonem řeky Tary s legendárním mostem Đurđevića. Trasa dále klesá k přehradnímu jezeru Piva s tyrkysovou vodou a nespočtem tunelů vytesaných do skály, míjí poutní klášter Ostrog přilepený ke svislé skále a vrací se přes Nikšić zpět do hor. Silnice jsou úzké, klikaté, místy s neosvětlenými tunely a strmými srázy bez svodidel, proto počítejte s pomalým tempem a doporučujeme okruh rozdělit na 1–2 dny. Odměnou je jedna z nejkrásnějších motorkářských cest Balkánu s minimem provozu a nekonečnými výhledy.', 'loop', 320, 600, 'hard',
     '[{"lat": 43.15417, "lng": 19.12278, "label": "Žabljak – start (NP Durmitor)"}, {"lat": 43.14556, "lng": 19.09889, "label": "Crno jezero (Černé jezero)"}, {"lat": 43.09846, "lng": 19.05033, "label": "Průsmyk Sedlo (P14)"}, {"lat": 43.1504, "lng": 19.29484, "label": "Most Đurđevića Tara / kaňon Tary"}, {"lat": 43.14667, "lng": 18.87556, "label": "Pivské jezero"}, {"lat": 43.1101, "lng": 18.81838, "label": "Klášter Piva"}, {"lat": 42.7731, "lng": 18.94446, "label": "Nikšić"}, {"lat": 42.6717, "lng": 19.0242, "label": "Klášter Ostrog"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.15417,19.12278&destination=42.6717,19.0242&travelmode=driving&waypoints=43.14556,19.09889%7C43.09846,19.05033%7C43.1504,19.29484%7C43.14667,18.87556%7C43.1101,18.81838%7C42.7731,18.94446', 'https://commons.wikimedia.org/wiki/Special:FilePath/Durmitor%20National%20Park%20in%20Montenegro%2006.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Durmitor%20National%20Park%20in%20Montenegro%2006.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Crno%20jezero%20(Durmitor).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tara%20River%20Canyon.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%90ur%C4%91evi%C4%87a%20Tara%20Bridge%20(by%20Pudelek).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Durmitor%20-%20Bobotov%20kuk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Piva%20Lake%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Manastir%20Piva%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Freedom%20Square%20in%20Niksic%20as%20seen%20from%20the%20south.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Freedom%20Square%20in%20Niksic%20as%20seen%20from%20the%20south.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Montenegro%20-%20view%20down%20from%20Ostrog%20monastery.JPG"}'::text[], '{"NP Durmitor (Žabljak)","Crno jezero (Černé jezero)","Kaňon řeky Tary","Most Đurđevića Tara","Průsmyk Sedlo (P14)","Pivské jezero","Klášter Piva","Nikšić","Restaurace: Konoba Portun (Nikšić)","Klášter Ostrog"}'::text[], '{"Černá Hora"}'::text[], false, 700, 'approved');

  -- Černá Hora – Boka Kotorská a Lovćen  (710_me_kotor.json)
  delete from public.routes where name = 'Černá Hora – Boka Kotorská a Lovćen' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Černá Hora – Boka Kotorská a Lovćen', 'Jednodenní okruh, který patří k tomu nejlepšímu, co Balkán nabízí motorkářům. Vyrážíme ze starého města Kotor a stoupáme po legendárních serpentinách s 25 vlásenkami, odkud se otevírá dechberoucí výhled na fjord Boka Kotorská. Trasa záměrně vede pouze po horských a pobřežních silnicích – žádné dálnice ani placené úseky – takže si užijete čistou jízdu v zatáčkách. Přes vesnici Njeguši pokračujeme do Národního parku Lovćen k Njegošovu mauzoleu, dále do historického Cetinje a zpět dolů k pobřeží přes Perast s ostrůvkem Gospa od Škrpjela až do rušné Budvy. Počítejte s úzkými silnicemi, kamením na krajnici, kozami a protijedoucími autobusy – proto obtížnost hard. Nádrž doplňte předem, na Lovćenu jsou benzinky vzácné.', 'loop', 95, 300, 'hard',
     '[{"lat": 42.42067, "lng": 18.76825, "label": "Kotor – staré město (start)"}, {"lat": 42.40905, "lng": 18.76932, "label": "Serpentiny Kotor–Njeguši, vyhlídka nad Bokou"}, {"lat": 42.4331, "lng": 18.8283, "label": "Njeguši"}, {"lat": 42.39972, "lng": 18.83763, "label": "Národní park Lovćen – Njegošovo mauzoleum"}, {"lat": 42.3931, "lng": 18.9116, "label": "Cetinje"}, {"lat": 42.28639, "lng": 18.84, "label": "Budva – staré město"}, {"lat": 42.4863, "lng": 18.6989, "label": "Perast"}, {"lat": 42.42067, "lng": 18.76825, "label": "Kotor – návrat (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.42067,18.76825&destination=42.42067,18.76825&travelmode=driving&waypoints=42.40905,18.76932%7C42.4331,18.8283%7C42.39972,18.83763%7C42.3931,18.9116%7C42.28639,18.84%7C42.4863,18.6989', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kotor%20Old%20Town.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kotor%20Old%20Town.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kotor%20and%20Boka%20kotorska%20-%20view%20from%20city%20wall.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/View%20over%20Njegusi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/View%20over%20Njegusi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Njego%C5%A1ev%20mauzolej.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cetinjski%20manastir.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Budva%20stari%20grad%20nocu%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/1%20perast%20aerial%202016.jpg"}'::text[], '{"Kotor – staré město a serpentiny (25 vlásenek)","Vyhlídka nad Boka Kotorskou","Njeguši","Restaurace: Konoba Batrićević (Njeguši)","Národní park Lovćen – Njegošovo mauzoleum","Cetinje","Budva – staré město","Perast a ostrov Gospa od Škrpjela"}'::text[], '{"Černá Hora"}'::text[], false, 710, 'approved');

  -- Severní Makedonie – Ochridské jezero a Mavrovo  (720_mk_ohrid.json)
  delete from public.routes where name = 'Severní Makedonie – Ochridské jezero a Mavrovo' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Severní Makedonie – Ochridské jezero a Mavrovo', 'Okruh napříč západní Severní Makedonií spojuje dvě nejkrásnější jezerní a horské oblasti země – Ochridské jezero a Národní park Mavrovo. Trasa se záměrně vyhýbá dálnicím a vede po klikatých panoramatických silnicích nad jezerem, přes horské průsmyky a lesnaté kaňony, kde si užijete opravdovou jízdu v zatáčkách. Z Ohridu stoupá silnice do Národního parku Galičica s výhledy na dvě jezera najednou, poté míří na jih ke klášteru Sveti Naum a na východ do historické Bitoly. Severní úsek vás zavede do hor Mavrova k horskému jezeru, majestátnímu klášteru Sveti Jovan Bigorski a vodopádu Duf. Počítejte s ostrými serpentinami, místy horším povrchem a dobytkem na silnici – ideální na dva dny s přespáním v Ohridu nebo Bitole. Doporučujeme plnou nádrž, protože pumpy jsou v horských úsecích řídké.', 'loop', 320, 600, 'medium',
     '[{"lat": 41.11445, "lng": 20.80122, "label": "Ohrid – Sveti Jovan Kaneo"}, {"lat": 41.1035, "lng": 20.8572, "label": "NP Galičica – vyhlídka nad jezerem"}, {"lat": 40.9139, "lng": 20.74047, "label": "Klášter Sveti Naum"}, {"lat": 41.03143, "lng": 21.33474, "label": "Bitola"}, {"lat": 41.6295, "lng": 20.748, "label": "Jezero Mavrovo"}, {"lat": 41.62194, "lng": 20.61167, "label": "Klášter Sveti Jovan Bigorski"}, {"lat": 41.60331, "lng": 20.59483, "label": "Vodopád Duf / Rostuše"}, {"lat": 41.11445, "lng": 20.80122, "label": "Návrat do Ohridu"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=41.11445,20.80122&destination=41.11445,20.80122&travelmode=driving&waypoints=41.1035,20.8572%7C40.9139,20.74047%7C41.03143,21.33474%7C41.6295,20.748%7C41.62194,20.61167%7C41.60331,20.59483', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sveti%20Jovan%20-%20Kaneo%20Ohrid%20oddaleku.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sveti%20Jovan%20-%20Kaneo%20Ohrid%20oddaleku.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20d''Ohrid%20panorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ohridsko%20krajbrezje%20pod%20Galicica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sveti%20Naum%20Ohridski.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sveti%20Jovan%20-%20Kaneo%20Ohrid%20oddaleku.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sirok%20Sokak,%20Bitola,%20Republic%20of%20Macedonia,%20summer%202011.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Clock%20tower%20in%20Bitola,%20Macedonia.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Submerged%20church%20of%20St.%20Nicholas%20(Mavrovo).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Monastery%20Sveti%20Jovan%20Bigorski%20Church.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Duf%20Waterfalls%20in%20Rostu%C5%A1e%201.JPG"}'::text[], '{"Ohrid – Sveti Jovan Kaneo","Ochridské jezero","NP Galičica – silnice nad jezerem","Sveti Naum (klášter)","Restaurace: Kaneo Restaurant (Ohrid)","Bitola","Restaurace: Gradska Kafeana (Bitola)","NP Mavrovo (jezero)","Klášter Sveti Jovan Bigorski","Vodopád Duf / Rostuše"}'::text[], '{"Severní Makedonie"}'::text[], false, 720, 'approved');

  -- Albánie – Albánské Alpy (Theth a Valbona)  (730_al_alps.json)
  delete from public.routes where name = 'Albánie – Albánské Alpy (Theth a Valbona)' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Albánie – Albánské Alpy (Theth a Valbona)', 'Vícedenní dobrodružství (cca 3 dny) srdcem Prokletije – Albánských Alp, záměrně bez jediného metru dálnice. Trasa vede úzkými horskými silnicemi, místy s nezpevněným štěrkovým povrchem, hlubokými výmoly a nechráněnými srázy, takže vyžaduje zkušeného jezdce a odolný stroj (ideálně enduro či adventure). 1. den: ze Shkodru přes hrad Rozafa stoupáme rozbitou horskou cestou do vysokohorské vesnice Theth, kde přenocujeme. 2. den: pěší výlet k vodopádu Grunas a k Modrému oku (Syri i Kaltër), poté náročný přejezd průsmyku Qafa e Thorës (cca 1680 m) do údolí Valbona – tento úsek je nejtěžší, hodně štěrku a serpentin. 3. den: sjezd do Fierzy, přeprava trajektem přes jezero Koman zpět a návrat do Shkodru; počítejte s pomalým tempem, rezervou na počasí a plnou nádrží, protože pumpy jsou v horách vzácné.', 'poi', 215, 900, 'hard',
     '[{"lat": 42.0468, "lng": 19.4983, "label": "Shkodër (start, hrad Rozafa)"}, {"lat": 42.38944, "lng": 19.78166, "label": "Theth (vesnice v horách)"}, {"lat": 42.3782, "lng": 19.775, "label": "Vodopád Grunas"}, {"lat": 42.35354, "lng": 19.77026, "label": "Modré oko Theth (Syri i Kaltër)"}, {"lat": 42.415, "lng": 19.805, "label": "Qafa e Thorës (horský průsmyk)"}, {"lat": 42.452, "lng": 19.886, "label": "Valbona (údolí, NP)"}, {"lat": 42.2569, "lng": 20.025, "label": "Fierza (trajekt)"}, {"lat": 42.10325, "lng": 19.82238, "label": "Koman (jezero / trajekt)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=42.0468,19.4983&destination=42.10325,19.82238&travelmode=driving&waypoints=42.38944,19.78166%7C42.3782,19.775%7C42.35354,19.77026%7C42.415,19.805%7C42.452,19.886%7C42.2569,20.025', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalaja%20e%20Rozafes,%20Shkoder%202.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kalaja%20e%20Rozafes,%20Shkoder%202.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rruga%20Kol%C3%AB%20Idromeno,%20Shkod%C3%ABr.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kisha%20e%20Thethit.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kisha%20e%20Thethit%20-%202018%20(2).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Waterfall%20of%20Grunas%20in%20Theth.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Syri%20kalter%20theth.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Buni%20i%20Thores.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Valbona%20Valley%20National%20Park,%20North%20Albania.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fierze-Dam-2018.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Komani1.jpg"}'::text[], '{"Shkodër – hrad Rozafa","Restaurace: Arti''Zanave (Shkodër)","Theth – kostel v horách","Restaurace: Thethi Paradise (Theth)","Vodopád Grunas (NP Theth)","Modré oko Theth (Syri i Kaltër)","Qafa e Thorës (horský průsmyk)","Valbona (údolí, národní park)","Fierza (trajekt přes jezero)","Koman – jezero a trajekt"}'::text[], '{"Albánie"}'::text[], false, 730, 'approved');

  -- Řecko – Meteora a Pindos  (740_gr_meteora.json)
  delete from public.routes where name = 'Řecko – Meteora a Pindos' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Řecko – Meteora a Pindos', 'Okruh napříč pohořím Pindos, jednou z nejúchvatnějších horských oblastí kontinentálního Řecka, vědomě vede pouze po klikatých horských silnicích a zcela se vyhýbá dálnicím (autostráda A2/Egnatia s tunely by celý zážitek připravila o kouzlo). Trasa začíná pod skalními věžemi Meteory u Kalambaky, stoupá přes legendární průsmyk Katara (cca 1705 m) do horského městečka Metsovo a pokračuje k jezeru Pamvotida v Ioannině. Odtud se noří do kamenných vesnic Zagori (Zagorochoria), k soutěsce Vikos a jejím obloukovým mostům. První den doporučujeme věnovat úseku Meteora – Katara – Metsovo – Ioannina s množstvím zatáček a serpentin. Druhý den projeďte klidnějším tempem Zagorochoria, vyhlídku Oxya nad soutěskou Vikos, kamenné mosty a závěrem odbočku k masivu Tzoumerka. Počítejte s úzkými cestami, kozami na silnici, prudkými výškovými rozdíly a chladnějším počasím ve výškách i v létě, proto volte střední tempo a rezervu na fotopauzy.', 'poi', 215, 420, 'medium',
     '[{"lat": 39.7044, "lng": 21.6269, "label": "Kalambaka – Meteora (start)"}, {"lat": 39.79, "lng": 21.26667, "label": "Průsmyk Katara"}, {"lat": 39.77025, "lng": 21.18286, "label": "Metsovo"}, {"lat": 39.6649, "lng": 20.8519, "label": "Ioannina – jezero Pamvotida"}, {"lat": 39.9066, "lng": 20.75166, "label": "Vyhlídka Oxya nad soutěskou Vikos"}, {"lat": 39.8756, "lng": 20.7947, "label": "Kamenné mosty Zagori (Kipi)"}, {"lat": 39.53, "lng": 21.1, "label": "Tzoumerka (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=39.7044,21.6269&destination=39.53,21.1&travelmode=driving&waypoints=39.79,21.26667%7C39.77025,21.18286%7C39.6649,20.8519%7C39.9066,20.75166%7C39.8756,20.7947', 'https://commons.wikimedia.org/wiki/Special:FilePath/Greece%20meteora%20monasteries.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Greece%20meteora%20monasteries.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Katara%20Pass%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Metsovo%20overview%20bgiu.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20main%20square%20in%20Metsovo,Hpeiros.Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ioannina,%20Lake%20Pamvotis%20and%20Fethiye%20Mosque.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ioannina,%20Lake%20Pamvotis%20and%20Fethiye%20Mosque.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kipoi%20Bagia%20Zagori%20village.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zagori%20Vikos%20gorge%20Oxia%20towards%20Vikos.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bridge%20of%20Kokkori%20or%20Noutsos.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tzoumerka.jpeg"}'::text[], '{"Meteora – kláštery nad Kalambakou","Průsmyk Katara","Metsovo","Restaurace: To Koutouki tou Nikola (Metsovo)","Ioannina – jezero Pamvotida","Restaurace: Presveía (Ioannina)","Zagori – Zagorochoria","Soutěska Vikos – vyhlídka Oxya","Kamenné mosty Zagori (Kokkori a Plakidas)","Tzoumerka"}'::text[], '{"Řecko"}'::text[], false, 740, 'approved');

  -- Rumunsko – Transalpina (DN67C)  (750_ro_transalpina.json)
  delete from public.routes where name = 'Rumunsko – Transalpina (DN67C)' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rumunsko – Transalpina (DN67C)', 'Transalpina (DN67C) je nejvýše položená silnice Rumunska a vede hřebeny Parângu v Jižních Karpatech z Novaci na jihu až k Sebeși na severu. Záměrně se vyhýbá dálnicím a rychlostním silnicím – celá trasa vede horskými serpentinami, přes vysokohorské pastviny a kolem přehradních jezer, takže si vychutnáš čistou jízdu bez kamionů. Vrcholem je průsmyk Pasul Urdele ve výšce 2145 m, nejvyšší bod celé silnice. Silnice je otevřená pouze v létě (zhruba od poloviny května do poloviny října) a jen za denního světla, v zimě je uzavřená kvůli sněhu. Počítej s celodenní jízdou (dlouhý den) – kvůli výškovému profilu, počasí a fotozastávkám jeď s rezervou a plnou nádrží. Nahoře bývá chladno a mlha i v létě, proto s sebou vem teplé a nepromokavé vrstvy.', 'poi', 148, 300, 'hard',
     '[{"lat": 45.18683, "lng": 23.66887, "label": "Novaci (jižní start)"}, {"lat": 45.29134, "lng": 23.68893, "label": "Rânca"}, {"lat": 45.3443, "lng": 23.65807, "label": "Pasul Urdele 2145 m"}, {"lat": 45.43516, "lng": 23.63025, "label": "Obârșia Lotrului"}, {"lat": 45.43317, "lng": 23.72193, "label": "Přehrada Vidra"}, {"lat": 45.56194, "lng": 23.61639, "label": "Lacul Oașa"}, {"lat": 45.76667, "lng": 23.63333, "label": "Sugag"}, {"lat": 45.7945, "lng": 23.8748, "label": "Săliște"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.18683,23.66887&destination=45.7945,23.8748&travelmode=driving&waypoints=45.29134,23.68893%7C45.3443,23.65807%7C45.43516,23.63025%7C45.43317,23.72193%7C45.56194,23.61639%7C45.76667,23.63333', 'https://commons.wikimedia.org/wiki/Special:FilePath/Novaci.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Novaci.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Winter%20Ski%20Resort%20Ranca%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ranca%20Ptuj%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pasul%20Urdele,%20Transalpina%20(2024-08-20%201).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lotru%20River%20in%20Ob%C3%A2r%C8%99ia%20Lotrului.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Vidra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Varfu%20lui%20patru.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/RO%20AB%20Sugag.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20%22Sfanta%20Treime%22%20sat%20VALE%20,oras%20Saliste,Jud%20Sibiu.JPG"}'::text[], '{"Novaci (jižní start)","Rânca (horské středisko)","Restaurace: Restaurant Tara (Rânca)","Průsmyk Urdele (Pasul Urdele, 2145 m)","Obârșia Lotrului","Přehrada Vidra (Lacul Vidra)","Jezero Oașa (Lacul Oașa)","Sugag","Săliște"}'::text[], '{"Rumunsko"}'::text[], false, 750, 'approved');

  -- Moldavsko – Orheiul Vechi a Cricova  (760_md_orhei.json)
  delete from public.routes where name = 'Moldavsko – Orheiul Vechi a Cricova' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Moldavsko – Orheiul Vechi a Cricova', 'Dvoudenní okruh Moldavskem po klidných venkovských silnicích, který záměrně vynechává dálnice a rychlostní tahy – jedeme regionálními cestami mezi vinicemi, kukuřičnými poli a údolím řeky Răut i Dněstru. Vyrážíme z Kišiněva ke skalnímu klášteru Orheiul Vechi, pokračujeme na sever přes klášter Curchi až k pevnosti v Soroce nad Dněstrem, poté sjíždíme k poutnímu místu Saharna s vodopády. Cestou zpět nechybí legendární vinné sklepy Cricova a největší vinný labyrint světa Mileștii Mici. Silnice jsou většinou úzké a místy s výtluky, proto počítejte s pomalejším tempem a defenzivní jízdou. Kombinace pravoslavných klášterů, skalních útvarů a vinařských podzemí dělá z této trasy ideální pohodový víkend pro dva na jeden až dva dny. Tankujte předem, čerpací stanice jsou na venkově řidší a otevírací doba klášterů bývá kratší.', 'poi', 410, 600, 'easy',
     '[{"lat": 47.02606, "lng": 28.83451, "label": "Kišiněv – katedrála Narození Páně"}, {"lat": 47.30583, "lng": 28.97694, "label": "Orheiul Vechi – skalní klášter"}, {"lat": 47.33389, "lng": 28.65389, "label": "Klášter Curchi"}, {"lat": 47.68361, "lng": 28.97028, "label": "Saharna – klášter a vodopády"}, {"lat": 48.15672, "lng": 28.30328, "label": "Soroca – pevnost"}, {"lat": 47.133, "lng": 28.85, "label": "Cricova – vinné sklepy"}, {"lat": 46.92092, "lng": 28.82055, "label": "Mileștii Mici – vinný labyrint"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.02606,28.83451&destination=46.92092,28.82055&travelmode=driving&waypoints=47.30583,28.97694%7C47.33389,28.65389%7C47.68361,28.97028%7C48.15672,28.30328%7C47.133,28.85', 'https://commons.wikimedia.org/wiki/Special:FilePath/Nativity%20Cathedral,%20Chi%C8%99in%C4%83u.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nativity%20Cathedral,%20Chi%C8%99in%C4%83u.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chisinau%20Center.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Crucea%20de%20piatra%20de%20la%20Orheiul%20Vechi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20m%C4%83n%C4%83stirii.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/M%C4%83n%C4%83stirea%20Sf.%20Treime%20din%20Saharna.%20M%C4%83n%C4%83stirea%20rupestr%C4%83--vedere%20paralel%C4%83%20cu%20st%C3%A2nca.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Soroca.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cricova%20Wine%20Cellar%20Collection.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Caves%20Milestii%20Mici%20Moldavie.jpg"}'::text[], '{"Chișinău – katedrála Narození Páně","Restaurace: La Plăcinte (Kišiněv)","Orheiul Vechi","Curchi","Saharna","Soroca","Cricova","Mileștii Mici"}'::text[], '{"Moldavsko"}'::text[], false, 760, 'approved');

  -- Litva – Kurská kosa  (770_lt_curonian.json)
  delete from public.routes where name = 'Litva – Kurská kosa' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Litva – Kurská kosa', 'Pohádkový výlet na 1–2 dny po litevském pobřeží Baltu a unikátní písečné Kurské kose, zapsané na seznamu UNESCO. Trasa začíná v přístavním Klaipėdě, odkud se na kosu dostanete jedině trajektem přes Kuronskou lagunu – motorku i s vámi převeze během několika minut. Záměrně se vyhýbáme dálnicím a jedeme klidnou pobřežní silničkou lemovanou borovými lesy, dunami a rybářskými vesničkami až do Nidy u ruské hranice. Zpět z kosy pokračujeme na sever přes lázeňskou Palangu s jantarovým muzeem a odbočíme k proslulé Hoře křížů u Šiauliai. Cesta je technicky nenáročná, ideální pro pohodovou jízdu s množstvím zastávek na fotky, jantar a čerstvé uzené ryby.', 'poi', 215, 420, 'easy',
     '[{"lat": 55.7033, "lng": 21.14428, "label": "Klaipėda – staré město"}, {"lat": 55.7176, "lng": 21.114, "label": "Trajekt Klaipėda – Smiltynė (Kurská kosa)"}, {"lat": 55.53761, "lng": 21.10918, "label": "Juodkrantė – Čarodějnický vrch"}, {"lat": 55.29496, "lng": 20.99064, "label": "Nida – Parnidžská duna"}, {"lat": 55.3408, "lng": 21.1894, "label": "Ventės Ragas – maják"}, {"lat": 55.9042, "lng": 21.0535, "label": "Palanga – jantarové muzeum"}, {"lat": 56.0092, "lng": 23.4167, "label": "Hora křížů u Šiauliai"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=55.7033,21.14428&destination=56.0092,23.4167&travelmode=driving&waypoints=55.7176,21.114%7C55.53761,21.10918%7C55.29496,20.99064%7C55.3408,21.1894%7C55.9042,21.0535', 'https://commons.wikimedia.org/wiki/Special:FilePath/Klaip%C3%A9da%20Theaterplatz%20Simon-Dach-Brunnen.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Klaip%C3%A9da%20Theaterplatz%20Simon-Dach-Brunnen.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Klaip%C3%A9da%20Theaterplatz%20Simon-Dach-Brunnen.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/F%C3%A4hre%20Smiltyn%C4%97%20Klaipeda.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hexenberg%20in%20Juodkrante.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Parnidis%20dune.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Parnidis%20dune.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ventes%20ragas.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ti%C5%A1kevi%C4%8Diai%20Palace%20at%20dusk%2C%20Palanga%2C%20Lithuania%20-%20Diliff.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hill%20of%20Crosses%2C%20Lithuania.JPG"}'::text[], '{"Klaipėda – staré město","Restaurace: Momo Grill (Klaipėda)","Trajekt na Kurskou kosu","Juodkrantė – Čarodějnický vrch (Raganų kalnas)","Nida – Parnidžská duna a sluneční hodiny","Restaurace: Tik Pas Joną (Nida)","Ventės Ragas – maják","Palanga – jantarové muzeum","Hora křížů u Šiauliai (Kryžių kalnas)"}'::text[], '{"Litva"}'::text[], false, 770, 'approved');

  -- Lotyšsko – Gauja a Sigulda  (780_lv_gauja.json)
  delete from public.routes where name = 'Lotyšsko – Gauja a Sigulda' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Lotyšsko – Gauja a Sigulda', 'Jednodenní pohodový okruh údolím řeky Gauja, přezdívaným lotyšské Švýcarsko, který záměrně vede jen po malebných venkovských a údolních silnicích a zcela se vyhýbá dálnicím i rychlostním tahům. Ze Siguldy vyrazíte přes řeku k hradu Turaida a jeskyni Gūtmaņala, poté klidnými lesními cestami Národního parku Gauja zamíříte do historického městečka Cēsis s působivými hradními zříceninami. Zpáteční trasa vede přes malebnou Līgatne s pískovcovými skalami a lanovkou přes údolí ke Krimuldě, odkud je nádherný výhled zpět na Siguldu. Silnice jsou většinou úzké, dobře udržované a lemované lesy, což z okruhu dělá ideální relaxační projížďku pro začátečníky i rodinné jezdce. Počítejte s častými zastávkami u hradů a vyhlídek, takže celý den strávíte v sedle bez spěchu a bez provozu velkých silnic.', 'loop', 95, 210, 'easy',
     '[{"lat": 57.16526, "lng": 24.85129, "label": "Sigulda – start"}, {"lat": 57.18222, "lng": 24.85028, "label": "Turaida"}, {"lat": 57.1762, "lng": 24.84236, "label": "Gūtmaņala"}, {"lat": 57.23, "lng": 25.05, "label": "NP Gauja"}, {"lat": 57.3138, "lng": 25.2688, "label": "Cēsis"}, {"lat": 57.2336, "lng": 25.0425, "label": "Līgatne"}, {"lat": 57.16667, "lng": 24.82667, "label": "Krimulda"}, {"lat": 57.16526, "lng": 24.85129, "label": "Sigulda – cíl"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=57.16526,24.85129&destination=57.16526,24.85129&travelmode=driving&waypoints=57.18222,24.85028%7C57.1762,24.84236%7C57.23,25.05%7C57.3138,25.2688%7C57.2336,25.0425%7C57.16667,24.82667', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sigulda%20New%20Castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sigulda%20New%20Castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Turaida%20Castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gutman%E2%80%99s%20cave.%20(2).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gauja%20river%202.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/C%C4%93su%20pils%20parks%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cesis%20Lettland%20Latvia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/L%C4%ABgatne,%20%C4%80nfabrikas%20klintis%202000-06-04.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Palace%20in%20Krimulda.JPG"}'::text[], '{"Sigulda – Nový zámek","Turaida (hrad a muzeum)","Gūtmaņova jeskyně (Gūtmaņala)","Národní park Gauja","Cēsis (hrad)","Restaurace: Vinetas un Allas Kārumlāde (Cēsis)","Līgatne","Krimulda"}'::text[], '{"Lotyšsko"}'::text[], false, 780, 'approved');

  -- Estonsko – Saaremaa a Lahemaa  (790_ee_saaremaa.json)
  delete from public.routes where name = 'Estonsko – Saaremaa a Lahemaa' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Estonsko – Saaremaa a Lahemaa', 'Pohodová dvoudenní jízda po estonských pobřežních a ostrovních silnicích, která záměrně vynechává dálnice a drží se malebných venkovských cest podél moře. První den vyrazíte z Tallinnu, projedete středověké staré město a zamíříte na východ do národního parku Lahemaa za panskými sídly Palmse a Sagadi. Druhý den se vydáte na západ k přístavu Virtsu, kde nasednete na trajekt Virtsu–Kuivastu přes úžinu Suur väin na ostrov Muhu a dále na Saaremaa (trajekt jede cca 25–30 minut, rezervaci doporučujeme v hlavní sezóně). Na Saaremaa objedete meteoritický kráter Kaali, útes Panga pank, větrné mlýny v Angle, biskupský hrad v Kuressaare a nejjižnější maják na Sõrve. Silnice jsou tu klidné, rovné až mírně zvlněné a ideální pro pomalé vychutnávání krajiny, takže počítejte spíš s fotopauzami než s kilometry v kuse.', 'poi', 460, 540, 'easy',
     '[{"lat": 59.4358, "lng": 24.7405, "label": "Tallinn – staré město (start)"}, {"lat": 59.51275, "lng": 25.95477, "label": "Palmse mõis (Lahemaa)"}, {"lat": 59.5167, "lng": 26.118, "label": "Sagadi mõis (Lahemaa)"}, {"lat": 58.575, "lng": 23.51, "label": "Přístav Virtsu – nástup na trajekt"}, {"lat": 58.5737, "lng": 23.39655, "label": "Přístav Kuivastu (Muhu) – výstup"}, {"lat": 58.37279, "lng": 22.6694, "label": "Kaali – meteoritický kráter"}, {"lat": 58.549, "lng": 22.632, "label": "Angla – větrné mlýny"}, {"lat": 58.56986, "lng": 22.29038, "label": "Panga pank – útes"}, {"lat": 58.25382, "lng": 22.49217, "label": "Kuressaare – biskupský hrad"}, {"lat": 57.90982, "lng": 22.05537, "label": "Sõrve – maják (cíl)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=59.4358,24.7405&destination=57.90982,22.05537&travelmode=driving&waypoints=59.51275,25.95477%7C59.5167,26.118%7C58.575,23.51%7C58.5737,23.39655%7C58.37279,22.6694%7C58.549,22.632%7C58.56986,22.29038%7C58.25382,22.49217', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tallinn%20Raekoja%20plats%20(4).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tallinn%20Raekoja%20plats%20(4).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Tallinna%20Raekoda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Palmse%20manor%20house%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sagadi%20manor%20house.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ferry%20Virtsu%20-%20Kuivastu,%20Estonia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kaali%20meteorite%20crater.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Saaremaa%20Angla%20Windmills%20Farm%20-%20Angla%20Tedre%20Talu%20Tuuleveski%2020896.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Panga%20pank.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare-linnus,%202010.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare%20linnus%20%C3%B5htuh%C3%A4maruses.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B5rve%20tuletorn%202013.jpg"}'::text[], '{"Tallinn – staré město (Raekoja plats)","Restaurace: Rataskaevu 16 (Tallinn)","Palmse mõis (Lahemaa)","Sagadi mõis (Lahemaa)","Trajekt Virtsu–Kuivastu","Kaali – meteoritický kráter","Angla – větrné mlýny","Panga pank – útes","Kuressaare – biskupský hrad","Restaurace: MO Restaurant (Kuressaare)","Sõrve – maják"}'::text[], '{"Estonsko"}'::text[], false, 790, 'approved');

  raise notice 'Seed tras hotov: 64 tras vloženo k pobočce %', v_branch;
