  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Kámen', 'Gotický hrad z 13. století malebně posazený na žulovém skalisku nad obcí Kámen u Pacova. Uvnitř najdete unikátní muzeum historických motocyklů značky ČZ a JAWA, což z něj dělá povinnou zastávku pro každého motorkáře. K hradu vede příjemná zatáčkovitá silnice a od hradeb je pěkný výhled do kraje.', 49.424, 15.015, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_K%C3%A1men.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_K%C3%A1men.jpg"}'::text[], 0),
    (v_route, 'Zámek Kamenice nad Lipou', 'Renesanční zámek přestavěný z původní gotické tvrze, obklopený rozlehlým anglickým parkem se slavnou památnou lípou. Sídlí zde expozice Uměleckoprůmyslového musea zaměřená na hračky a design. Ideální místo na klidnou pauzu a procházku parkem.', 49.30264, 15.0793, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kamenice_nad_Lipou,_z%C3%A1mek_a_l%C3%ADpa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kamenice_nad_Lipou,_z%C3%A1mek_a_l%C3%ADpa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kamenice_nad_Lipou,_z%C3%A1mek_(01).jpg"}'::text[], 1),
    (v_route, 'Zámek Žirovnice', 'Původně gotický hrad přestavěný na renesanční zámek, tyčící se na skalním ostrohu nad rybníkem uprostřed městečka proslulého výrobou knoflíků a perleti. Uvnitř se dochovaly vzácné pozdně gotické nástěnné malby. Součástí areálu je i muzeum perleti a špýchar.', 49.254, 15.185, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDirovnice%20z%C3%A1mek%20zdola.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDirovnice%20z%C3%A1mek%20zdola.jpg"}'::text[], 2),
    (v_route, 'Zámek Telč', 'Skvostný renesanční zámek na okraji památkového náměstí zapsaného na seznam UNESCO patří k nejkrásnějším v Česku. Prohlídka nabízí bohatě zdobené sály, arkádové nádvoří a zámeckou zahradu. Malebné náměstí s podloubím a barevnými domy je ideální na kávu i fotky.', 49.183, 15.455, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Zachari%C3%A1%C5%A1e%20z%20Hradce,%20Tel%C4%8D.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Tel%C4%8D_kaple_V%C5%A1ech_svat%C3%BDch.JPG"}'::text[], 3),
    (v_route, 'Hrad Roštejn', 'Romantický lovecký hrad ukrytý v hlubokých lesích Javořických vrchů severně od Telče, s charakteristickou sedmibokou věží. Okolní obora a klidné lesní silnice z něj dělají oblíbený cíl motorkářů hledajících klid a přírodu. Z věže je za dobrého počasí daleký rozhled po Vysočině.', 49.272, 15.484, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn_hrad_03.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%A1tejn_hrad_03.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Ro%C5%A1tejn_-_n%C3%A1dvo%C5%99%C3%AD.JPG"}'::text[], 4),
    (v_route, 'Restaurace: Gril u Osla / El Grill de Burro (Telč)', 'Oblíbená grilovací restaurace v historickém centru Telče specializující se na šťavnaté steaky z kvalitního masa, grilovanou zeleninu a těstoviny z čerstvých surovin od místních farmářů. Na Googlu má vynikající hodnocení kolem 4,9 hvězdy a patří k nejlépe hodnoceným podnikům ve městě. Ideální zastávka na vydatný oběd před nebo po prohlídce telčského zámku.', 49.1839, 15.4525, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zachari%C3%A1%C5%A1e%20z%20Hradce%20Square,%20Tel%C4%8D,%20Moravia,%20Czech%20Republic%20-%2020060930-04.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Rozhledna Pípalka na Křemešníku', 'Kamenná rozhledna Pípalka stojí ve výšce 765 m na vrcholu Křemešníku, jednoho z nejvýraznějších kopců Vysočiny asi 7 km od Pelhřimova. Z ochozu se otevírá kruhový výhled na širé lesy a pahorkatinu, za jasného počasí i do velké dálky. Poutní areál s kostelem Nejsvětější Trojice a studánkou v okolí je ideální zastávkou k protažení nohou i k občerstvení v přilehlém hotelu.', 49.4035, 15.32711, 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C5%99eme%C5%A1n%C3%ADk%20-%20rozhledna%20obr01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C5%99eme%C5%A1n%C3%ADk%20-%20rozhledna%20obr01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kremesnik.JPG"}'::text[], 0),
    (v_route, 'Pelhřimov – Masarykovo náměstí', 'Historické Masarykovo náměstí v Pelhřimově patří k největším a nejzachovalejším náměstím v Česku, lemované měšťanskými domy a radnicí s převážně barokní tváří. Pelhřimov je proslulý jako město rekordů a kuriozit, každoročně sem míří rekordmani na oblíbený festival. Ideální místo na kávu, oběd a procházku uprostřed okruhu, s dostatkem parkování pro motorky poblíž centra.', 49.431, 15.223, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pelh%C5%99imov%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pelh%C5%99imov%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pelh%C5%99imov%2C%20n%C3%A1m%C4%9Bst%C3%AD.jpg"}'::text[], 1),
    (v_route, 'Restaurace: PATRO (Pelhřimov)', 'Oblíbená pelhřimovská restaurace PATRO v Palackého ulici u historického centra láká na poctivou moderní českou kuchyni z čerstvých a domácích surovin, steaky, burgery i bezlepková jídla. Hosté ji hodnotí mimořádně vysoko (kolem 4,8 hvězdičky) a chválí kvalitu, velké porce i skvělý poměr cena/výkon. Skvělá zastávka na vydatný oběd uprostřed okruhu.', 49.4306, 15.2214, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pelh%C5%99imov%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pelh%C5%99imov%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD.JPG"}'::text[], 2),
    (v_route, 'Čeřínek – Přední skála', 'Vrch Čeřínek (761 m) v Přírodním parku Čeřínek leží mezi Jihlavou a Novým Rychnovem a láká na klidné lesní silničky a skalní vyhlídku Přední skála. Z jedenáct metrů vysokého skalního ochozu je pěkný rozhled na okolní kopce a osady, cestou míjíte mrazové sruby, kamenná moře a staré bukové porosty. V zimě je zde malý lyžařský areál, v teplejších měsících skvělé místo pro zastávku motorkáře.', 49.376, 15.435, 'https://commons.wikimedia.org/wiki/Special:FilePath/P%C5%99edn%C3%AD%20sk%C3%A1la%20(017).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/P%C5%99edn%C3%AD%20sk%C3%A1la%20(017).jpg"}'::text[], 3),
    (v_route, 'Strážiště u Pacova', 'Strážiště (745 m) je nejvyšší vrchol Pacovské pahorkatiny, který se zvedá asi 7 km severně od Pacova a dominuje krajině televizním vysílačem. Už v roce 1878 zde stála dřevěná rozhledna a pod vrcholem u léčivého pramene najdete barokní kapli sv. Jana Křtitele. Motorkáři sem pohodlně vyjedou po silnici z Pacova do Lukavce až téměř pod vrchol, odkud vede lesní cesta k výhledům na Pacovsko a Želivsko.', 49.53578, 15.00367, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaple%20svat%C3%A9ho%20Jana%20K%C5%99titele%20pod%20Str%C3%A1%C5%BEi%C5%A1t%C4%9Bm%20(Q67180794)%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaple%20svat%C3%A9ho%20Jana%20K%C5%99titele%20pod%20Str%C3%A1%C5%BEi%C5%A1t%C4%9Bm%20(Q67180794)%2001.jpg"}'::text[], 4),
    (v_route, 'Hrad Kámen', 'Gotický hrad Kámen vyrostl na výrazném žulovém skalisku v obci Kámen asi 5 km od Pacova a je vidět už z dálky nad okolní krajinou. Dominantou je obytná věž s vyhlídkou z nádvoří, odkud se rozhlédnete po Vysočině. Hrad dnes slouží jako pobočka Muzea Vysočiny Pelhřimov a je oblíbenou fotogenickou zastávkou; před návštěvou interiéru si ověřte aktuální otevírací dobu.', 49.42439, 15.01388, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20K%C3%A1men.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20K%C3%A1men.jpg"}'::text[], 5);
