  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Tábor – Žižkovo náměstí a hrad Kotnov', 'Historické jádro Tábora s malebným Žižkovým náměstím a věží Kotnov je srdcem husitského hnutí a městskou památkovou rezervací. Věž hradu Kotnov spolu s Bechyňskou branou tvoří dominantu města nad údolím Lužnice. Pro motorkáře je to ideální zastávka na kávu v dlážděných uličkách i vstup do slavného táborského podzemí.', 49.4111, 14.6558, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov1_10092005.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Tabor_Hrad_Kotnov2_10092005.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A1bor%20-%20%C5%BDi%C5%BEkovo%20n%C3%A1m%C4%9Bst%C3%AD%20-%20okres%20T%C3%A1bor%20(02).jpg"}'::text[], 0),
    (v_route, 'Restaurace: Goldie (Tábor)', 'Restaurace Goldie v boutique hotelu Nautilus přímo na Žižkově náměstí nabízí špičkovou českou i mezinárodní kuchyni z lokálních surovin. V roce 2026 získala prestižní ocenění Michelin Bib Gourmand za výjimečné jídlo za rozumnou cenu. Elegantní interiér s díly českých umělců a výhled na náměstí z ní dělají skvělou zastávku na oběd uprostřed trasy.', 49.4144, 14.658, 'https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A1bor%20-%20%C5%BDi%C5%BEkovo%20n%C3%A1m%C4%9Bst%C3%AD%20-%20okres%20T%C3%A1bor%20(04).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%A1bor%20-%20%C5%BDi%C5%BEkovo%20n%C3%A1m%C4%9Bst%C3%AD%20-%20okres%20T%C3%A1bor%20(04).jpg"}'::text[], 1),
    (v_route, 'Kozí hrádek', 'Romantická zřícenina gotického hrádku ukrytá v lese u Sezimova Ústí, kde v letech 1413–1414 pobýval a kázal mistr Jan Hus. Národní kulturní památka láká na klidnou procházku hlubokým lesem k dochovaným zdem a příkopům. Skvělé místo na krátký oddech mimo ruch silnic.', 49.39775, 14.72642, 'https://commons.wikimedia.org/wiki/Special:FilePath/Koz%C3%AD%20Hr%C3%A1dek%20171.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Koz%C3%AD%20Hr%C3%A1dek%20171.jpg"}'::text[], 2),
    (v_route, 'Chýnovská jeskyně', 'Nejstarší zpřístupněná jeskyně v Česku, otevřená veřejnosti už od roku 1868, s výraznou barevnou hrou bílého mramoru a tmavé amfibolitové horniny. Prohlídková trasa vede strmými schody podzemím se zajímavými geologickými útvary a je významným zimovištěm netopýrů. Příjemné osvěžení v horkém dni po jízdě zvlněnou krajinou.', 49.42944, 14.83306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%BDnovsk%C3%A1%20jeskyn%C4%9B(4).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%BDnovsk%C3%A1%20jeskyn%C4%9B(4).jpg"}'::text[], 3),
    (v_route, 'Zámek Bechyně a most Duha', 'Renesanční zámek Bechyně stojí na skalním ostrohu nad soutokem Smutné a Lužnice a spolu s klenutým železobetonovým mostem Duha z roku 1928 tvoří jeden z nejfotogeničtějších pohledů jižních Čech. Most se klene 50 metrů nad hladinou řeky a nabízí dech beroucí výhled do údolí. Zastávka spojující historii, techniku i krásnou přírodu.', 49.297, 14.469, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20z%C3%A1mek.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bechyn%C4%9B,%20most%20Duha,%20od%20z%C3%A1mku.jpg"}'::text[], 4),
    (v_route, 'Rozhledna Hýlačka', 'Dřevěná rozhledna na kopci Hýlačka v lokalitě Větrovy nad Táborem ve výšce přes 500 metrů nad mořem nabízí kruhový rozhled po Táborsku a za dobrého počasí až k šumavským hřebenům. Znovupostavená věž je oblíbeným výletním cílem s posezením v okolí. Ideální tečka výletu s výhledem, než se vydáte zpět na základnu.', 49.389, 14.643, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20H%C3%BDla%C4%8Dka%202013.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20H%C3%BDla%C4%8Dka%202013.JPG"}'::text[], 5);
