  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Opatija / Rijeka – začátek Jadranské magistrály', 'Lázeňská Opatija u Rijeky je tradičním startem chorvatské Jadranské magistrály. Elegantní promenáda Lungomare a výhledy na Kvarnerský záliv jsou ideálním místem na natankování před cestou na jih. Odtud se silnice D8 vydává podél pobřeží pryč od dálnice A1.', 45.339, 14.306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Kvarner%20Opatija.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hotel%20Kvarner%20Opatija.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Opatija%20Lungomare.jpg"}'::text[], 0),
    (v_route, 'Senj – pevnost Nehaj', 'Nad městem Senj se tyčí mohutná pevnost Nehaj z 16. století, symbol obávaných uskoků. Z jejích hradeb je nádherný rozhled na moře i na hřebeny Velebitu. Senj je zároveň známý jako největrnější místo pobřeží – právě zde často udeří bóra.', 44.99, 14.903, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nehaj%20Senj%20Croatia%20West%20090728.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nehaj%20Senj%20Croatia%20West%20090728.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Senj%20-%20twierdza%20%22Nehaj%22%20-%20castle%20called%20%22Nehaj%22%20-%20panoramio.jpg"}'::text[], 1),
    (v_route, 'Karlobag pod Velebitem', 'Malebné městečko Karlobag leží sevřené mezi mořem a strmými svahy Velebitu. Je to skvělá zastávka na kávu s výhledem na ostrov Pag přímo naproti přístavu. Úsek magistrály tudy vede v efektních zatáčkách nad útesy.', 44.529, 15.078, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG"}'::text[], 2),
    (v_route, 'Restaurace: Restaurant & Pizzeria OK Karlobag (Karlobag)', 'Rodinná restaurace OK sedí přímo na pobřeží Karlobagu s terasou nad mořem a výhledem na ostrov Pag. Nabízí čerstvé ryby, mořské plody i pizzu ve středomořském stylu a patří k nejlépe hodnoceným podnikům ve městě (kolem 4,8 hvězdičky z tisíců recenzí). Ideální zastávka na oběd přesně v polovině magistrály.', 44.529, 15.078, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karlobag%20(02).JPG"}'::text[], 3),
    (v_route, 'Národní park Paklenica', 'Národní park Paklenica ukrývá dramatické kaňony Velika a Mala Paklenica zaříznuté do jižního Velebitu. Vstup leží jen kousek od magistrály u obce Starigrad a láká na krátkou procházku do hlubokých skalních soutěsek. Je to oblíbený ráj horolezců i příjemný stín po horké jízdě.', 44.283, 15.463, 'https://commons.wikimedia.org/wiki/Special:FilePath/Paklenica%20-%20canyon%20Velika%20Paklenica.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Paklenica%20-%20canyon%20Velika%20Paklenica.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ani%C4%87a%20kuk%20-%20Paklenica.JPG"}'::text[], 4),
    (v_route, 'Zadar – staré město a mořské varhany', 'Historické jádro Zadaru na poloostrově nabízí římské fórum, úzké uličky a slavné mořské varhany (Morske orgulje), které hrají tóny poháněné vlnami. Vedle nich instalace Pozdrav Slunci vytváří po setmění světelnou show. Zadar je krásným cílem coastalní etapy Jadranské magistrály.', 44.116, 15.226, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20organ%20Zadar%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20organ%20Zadar%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zadar,%20Sunset%20-%20Pozdrav%20Suncu.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Roman%20Forum%20in%20Zadar,%20Croatia%20(48607823862).jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Restaurace: Bistro Subcarpați (Curtea de Argeș)', 'Oblíbené bistro v Curtea de Argeș u jižního začátku Transfăgărășanu, ideální na doplnění sil před náročným výjezdem. Nabízí poctivou rumunskou i mezinárodní kuchyni na krásné terase s přátelskou obsluhou. S hodnocením kolem 4,7 hvězdičky patří k nejlépe hodnoceným podnikům ve městě a je stálicí mezi motorkáři.', 45.1391, 24.6767, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curtea%20de%20Arges%20monastery.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Curtea%20de%20Arges%20monastery.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Manastirea%20Argesului,%20Curtea%20de%20Arges,%20AG.jpg"}'::text[], 0),
    (v_route, 'Přehrada Vidraru (Lacul Vidraru)', 'Mohutná obloukovitá přehrada z roku 1966 zadržuje jezero Vidraru sevřené v horách Fagaraš. Na hrázi vysoké přes 160 metrů stojí socha Prométhea a otevírá se odtud dech beroucí výhled na jižní část Transfăgărășanu. Ideální první zastávka na motorce, kde si dáte pauzu a vychutnáte panorama.', 45.363, 24.634, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Dam%20in%20Romania.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Dam%20in%20Romania.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Prometheus.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Vidraru.jpg"}'::text[], 1),
    (v_route, 'Hrad Poenari (Drákulův hrad)', 'Zřícenina pevnosti Poenari trůní vysoko na skalním ostrohu nad údolím řeky Arges a je spojována s vládcem Vladem Napichovačem, předobrazem hraběte Drákuly. K hradu vede přes 1400 schodů, odměnou je ale úchvatný výhled do kraje. Pro milovníky historie a legend nezapomenutelná odbočka hned na začátku trasy.', 45.352, 24.635, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Poenari%20-%20vedere%20principala.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Poenari%20-%20vedere%20principala.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Poenari%20Castle%20(Citadel).jpg"}'::text[], 2),
    (v_route, 'Tunel Bâlea', 'Tunel Bâlea dlouhý 887 metrů je nejvyšší silniční tunel v Rumunsku a označuje nejvyšší bod celé trasy pod hřebenem Fagaraše. Je nasvícený jen slabě, uvnitř bývá chladno a vlhko, proto dbejte zvýšené opatrnosti. Za jižním portálem vás čeká legendární výhled na kaskádu serpentin klesajících do údolí.', 45.596, 24.617, 'https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan%20near%20Balea%20lake.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan%20near%20Balea%20lake.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan-north.JPG"}'::text[], 3),
    (v_route, 'Jezero Bâlea (Bâlea Lac)', 'Ledovcové jezero Bâlea leží ve výšce 2034 metrů přímo v srdci nejvyšší části Transfăgărășanu. Kolem se rozkládají skalnaté štíty a horské louky, u břehu stojí chata i restaurace – dokonalé místo na zastávku a fotku motorky s alpskou kulisou. V zimě zde dokonce staví ledový hotel.', 45.604, 24.617, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Balea.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Balea.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Balea%20lake%20and%20chalet.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/RO%20B%20Transfagarasan%20view%20towards%20the%20north%20from%20Balea%20Lake%202.jpg"}'::text[], 4),
    (v_route, 'Vodopád Bâlea (Cascada Bâlea)', 'Nejvyšší vodopád v pohoří Fagaraš padá z výšky kolem 60 metrů po skalní stěně pod jezerem Bâlea. Nachází se na severní straně silnice a k jeho úpatí se dostanete krátkou procházkou nebo lanovkou. Skvělá zastávka na osvěžení uprostřed serpentin.', 45.618, 24.622, 'https://commons.wikimedia.org/wiki/Special:FilePath/Enchanted%20Balea%20falls.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Enchanted%20Balea%20falls.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Telecabina%20B%C3%A2lea%20Lac%20%E2%80%93%20B%C3%A2lea%20Cascad%C4%83.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Furkapass', 'Furka je s výškou 2429 m nejvyšší z trojice průsmyků a spojuje kantony Uri a Wallis. Silnice plná dramatických vlásenek se proslavila i díky honičce z bondovky Goldfinger. Z vrcholu se otevírají velkolepé výhledy do údolí Rhôny.', 46.572, 8.415, 'https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wallis_Furkapass_Blick_auf_den_Grimselpass_3.JPG"}'::text[], 0),
    (v_route, 'Ledovec Rhône a Belvédère', 'Přímo u serpentin na západní straně Furky leží ledovec Rhône, pramen řeky Rhôny, s legendární ledovou jeskyní vysekanou do jeho boku. Historický hotel Belvédère je ikonickým bodem trasy a ideálním místem na zastávku a fotky.', 46.573, 8.389, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhonegletscher_Furkapass_15092011.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rhonegletscher_Furkapass_15092011.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Furka-h%C3%A1g%C3%B3,_kil%C3%A1t%C3%A1s_a_Belvedere_Hotelt%C5%91l_a_Rh%C3%B4ne_v%C3%B6lgy%C3%A9re._Fortepan_17778.jpg"}'::text[], 1),
    (v_route, 'Grimselpass', 'Grimsel (2164 m) spojuje údolí Rhôny s Bernskou vysočinou a proslul soustavou přehradních jezer s tyrkysovou vodou. U vrcholu leží jezera Totensee a Grimselsee, obklopená holými žulovými skalami. Krajina působí drsně a měsíčně, což z průsmyku dělá nezapomenutelný zážitek.', 46.561, 8.333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grimselpass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grimselpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/C5.18_Totensee,_Hotel_Grimselpass.jpg"}'::text[], 2),
    (v_route, 'Sustenpass', 'Susten (2224 m) je považován za nejlépe stavěnou z trojice silnic – široké, plynulé zatáčky s dokonalým výhledem na ledovec Stein. Průsmyk spojuje kantony Uri a Bern a nabízí jednu z nejplynulejších jízd v celém okruhu. Krátký tunel pod vrcholem odděluje obě strany hor.', 46.7267, 8.446, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sustenpass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sustenpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/View_from_S%C3%BCstenpass.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Ochsen (Andermatt)', 'Tradiční švýcarská restaurace v centru Andermattu, ideální zastávka před náročným okruhem nebo po jeho dokončení. Podává poctivé alpské speciality jako fondue a rösti v útulném prostředí. S hodnocením kolem 4,6 patří k nejlépe hodnoceným podnikům ve městě.', 46.6355, 8.5945, 'https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Nosenhaus.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Nosenhaus.JPG"}'::text[], 4),
    (v_route, 'Andermatt', 'Andermatt je horské městečko v kantonu Uri, ideální výchozí i cílový bod celého okruhu. Leží na křižovatce alpských cest a nabízí ubytování, benzínky i restaurace před náročnou jízdou. Odtud se dá pokračovat i na další slavné průsmyky jako Oberalp či Gotthard.', 46.6353, 8.5941, 'https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Rathaus.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Rathaus.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Nosenhaus.JPG"}'::text[], 5);
  insert into public.routes
