  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kölnbreinsperre – přehrada v údolí Maltatal', 'Impozantní klenbová přehrada vysoká 200 m je nejvyšší přehradou Rakouska a leží na konci úchvatné Malta Hochalmstraße plné tunelů a serpentin. Za tyrkysovou hladinou vodní nádrže se tyčí ledovcové štíty národního parku Vysoké Taury. Na koruně přehrady čeká vyhlídková plošina Airwalk a horský hotel s panoramatickou restaurací.', 47.078, 13.352, 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6lnbreinsperre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6lnbreinsperre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Airwalk%20K%C3%B6lnbrein%20Staumauer,%20Maltatal,%20K%C3%A4rnten.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/1024%20Malta%20Hochalmstra%C3%9Fe,K%C3%B6lnbrein%20Stausee-3126.jpg"}'::text[], 0),
    (v_route, 'Innerkrems', 'Malebná horská osada ve výšce zhruba 1480 m tvoří severní vstupní bránu na Nockalmstraße. Je to ideální místo na natankování, kávu a poslední zastávku před výjezdem do serpentin. V okolí se rozkládá lyžařské a turistické středisko obklopené vrcholky Nockbergů.', 46.929, 13.688, 'https://commons.wikimedia.org/wiki/Special:FilePath/Innerkrems%20Krems%20in%20K%C3%A4rnten%2020070910a.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Innerkrems%20Krems%20in%20K%C3%A4rnten%2020070910a.jpg"}'::text[], 1),
    (v_route, 'Nockalmstraße – panoramatická silnice', 'Placená horská silnice dlouhá 34 km, která se klikatí 52 vlásenkami napříč jemně zaoblenými horami Nockberge. Pro motorkáře je to jeden z nejkrásnějších alpských zážitků – plynulé zatáčky, minimální provoz a nekonečné výhledy na travnaté kopce. Silnice je sjízdná od začátku května do konce října, mýto pro motorky je zhruba 18,50 €.', 46.885, 13.7, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse-Karlbad.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse-Karlbad.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%A4rnten%20Nockalmstra%C3%9Fe%2012.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse%20Windebensee%2026082007%2061.jpg"}'::text[], 2),
    (v_route, 'Eisentalhöhe – nejvyšší bod 2042 m', 'Nejvyšší bod celé Nockalmstraße ležící ve výšce 2042 m nad mořem. Z parkoviště se otevírá kruhový panoramatický výhled na hřebeny Nockbergů a v jasném počasí i na vzdálené vrcholy Vysokých Taur. Pro motorkáře je to povinná fotozastávka na střeše celé trasy.', 46.883, 13.7, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse%20Eisentalhoehe.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse%20Eisentalhoehe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nockberge%20Eisentalh%C3%B6he%20Panorama%2001.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Seerestaurant 1884 (Millstatt am See)', 'Michelinská restaurace v historické vile See-Villa přímo na břehu jezera Millstätter See s terasou sahající až k vodní hladině. Kuchyně staví na čerstvě ulovených rybách z jezera, zvěřině z vlastního revíru a vínech z vlastní vinice. Na TripAdvisoru má vynikající hodnocení 4,7 z 5 a je oceněna hvězdou průvodce Michelin – ideální odměna po náročné jízdě horami.', 46.8047, 13.5797, 'https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg"}'::text[], 4),
    (v_route, 'Millstätter See', 'Druhé největší korutanské jezero a nejobjemnější svého druhu s hloubkou až 142 m. Teplá tyrkysová voda a klidné pobřeží z něj dělají ideální místo na oddech, koupání a kávu před nebo po náročné jízdě horami. Okolní silnice kolem jezera nabízejí příjemnou vyjížďku bez dálnic.', 46.7903, 13.5745, 'https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Millst%C3%A4tter%20See%20Bootsverleih.JPG"}'::text[], 5);
