  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Baden-Baden', 'Elegantní lázeňské město na severním okraji Černého lesa a startovní bod Schwarzwaldhochstraße. Reprezentativní kolonáda Trinkhalle a Kurhaus dávají tušit dávnou noblesu evropské smetánky. Ideální místo na kávu a natankování před stoupáním do hor.', 48.761, 8.241, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baden_Baden_-_Trinkhalle_-_View_SSE_I.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baden_Baden_-_Trinkhalle_-_View_SSE_I.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Baden-Baden-Trinkhalle-aussen-Ost3-gje.JPG"}'::text[], 0),
    (v_route, 'Mummelsee', 'Malebné ledovcové horské jezero ve výšce přes 1000 m přímo u silnice B500 pod vrcholem Hornisgrinde. Opředené pověstí o vodních vílách, s horským hotelem a stánky – oblíbená motorkářská zastávka. Skvělé místo na fotku i krátký odpočinek s výhledem na hladinu jezera.', 48.593, 8.207, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mummelsee%20und%20Hotel.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mummelsee%20und%20Hotel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Seebach%20-%20Schwarzwaldhochstra%C3%9Fe%20-%20Mummelsee%20%2B%20Berghotel%20Mummelsee%2004%20ies.jpg"}'::text[], 1),
    (v_route, 'Ruhestein', 'Horské sedlo a vstupní brána do Národního parku Černý les s návštěvnickým centrem a hospodou Ruhestein-Schänke. Křižovatka turistických tras nad divokým jezerem Wildsee. Příjemná zastávka na občerstvení uprostřed hřebenové jízdy.', 48.56, 8.22, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ruhestein-Nationalparkzentrum-02-2022-gje.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ruhestein-Nationalparkzentrum-02-2022-gje.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nationalpark%20Schwarzwald.JPG"}'::text[], 2),
    (v_route, 'Schliffkopf', 'Jeden z nejvyšších bodů na trase (1055 m) s otevřenými vřesovišti a širokými výhledy do kraje. Vrchol leží v Národním parku Černý les a v okolí najdete horský hotel i vyhlídkové trasy. Za jasného počasí dohlédnete daleko přes zalesněné hřebeny.', 48.535, 8.216, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sonnenuntergang%20am%20Schliffkopf%2C%20Nationalpark%20Schwarzwald.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sonnenuntergang%20am%20Schliffkopf%2C%20Nationalpark%20Schwarzwald.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Gasthof Rosengarten (Baiersbronn)', 'Tradiční hotelová restaurace v obci Baiersbronn, která je proslulá největší koncentrací michelinských hvězd v Německu. Kuchyně staví na poctivé regionální a bádensko-švábské klasice a nabízí skvělý poměr ceny a kvality. Hosté ji hodnotí výborně (4,5/5) a chválí chutná jídla i příjemnou obsluhu.', 48.503, 8.371, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Baiersbronn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Baiersbronn.jpg"}'::text[], 4),
    (v_route, 'Freudenstadt', 'Cílové město trasy proslulé největším tržním náměstím v Německu, obklopeným podloubími a měšťanskými domy. Ideální místo na oběd a odpočinek po projetí hřebenovky. Odtud se dá pohodlně pokračovat dál do jižního Černého lesa.', 48.463, 8.411, 'https://commons.wikimedia.org/wiki/Special:FilePath/Freudenstadt%20-%20Marktplatz%20Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Freudenstadt%20-%20Marktplatz%20Kirche.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Freudenstadt.jpg"}'::text[], 5);
  insert into public.routes
