  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Postojnská jeskyně', 'Jedna z největších přístupných krasových jeskyní na světě, jejíž prohlídka začíná svezením podzemním elektrickým vláčkem. V rozlehlých síních uvidíte tisíce krápníků, stalagmitů a bílý sloup Brilliant. Skvělá zastávka za každého počasí – v jeskyni je stálých zhruba 10 °C.', 45.78127, 14.20571, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slovenia,%20Postojna%20Cave,%20Postojnska%20jama%20(15384050783).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slovenia,%20Postojna%20Cave,%20Postojnska%20jama%20(15384050783).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Postojnska%20Jama%20(Postojna%20Cave)%20-%20panoramio%20(55).jpg"}'::text[], 0),
    (v_route, 'Restaurace: Bistro Štorja (Postojna)', 'Oblíbené bistro a vinotéka v centru Postojny, jen kousek od Postojnské jeskyně. Kuchyně nabízí moderně pojaté notranjské speciality – marinovaného pstruha i vinné menu s pečlivým výběrem lahví. Restaurace patří k nejlépe hodnoceným v Postojně (4,6 na TripAdvisoru), ideální zastávka na oběd uprostřed okruhu.', 45.7745, 14.2137, 'https://commons.wikimedia.org/wiki/Special:FilePath/Postojna%20-%20Vojkova%20ulica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Postojna%20-%20Vojkova%20ulica.jpg"}'::text[], 1),
    (v_route, 'Hrad Predjama', 'Renesanční hrad zasazený přímo do ústí jeskyně ve svislé skalní stěně, jeden z nejmalebnějších hradů Evropy. Proslul legendou o loupeživém rytíři Erazimu Predjamském, který odsud dlouho odolával obléhání. Pod hradem se rozkládá rozsáhlý jeskynní systém přístupný v teplejších měsících.', 45.8092, 14.1227, 'https://commons.wikimedia.org/wiki/Special:FilePath/Predjama%20-%20Grad%20Predjama%203892.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Predjama%20-%20Grad%20Predjama%203892.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Predjamski%20grad.JPG"}'::text[], 2),
    (v_route, 'Škocjanské jeskyně', 'Součást seznamu UNESCO a jeden z nejvelkolepějších podzemních kaňonů na světě, vytesaný řekou Rekou. Trasa vede přes závratný most nad hlubokou soutěskou v obří Martelově síni. Návštěva je zážitkem po celý rok a doplní ji krásná krasová krajina kolem.', 45.66317, 13.98932, 'https://commons.wikimedia.org/wiki/Special:FilePath/SkocjanCaves.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/SkocjanCaves.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Skocjanske%20jame%20inside%204.JPG"}'::text[], 3),
    (v_route, 'Lipica', 'Nejstarší a největší hřebčín ušlechtilých bílých lipicánů na světě, založený už roku 1580. Můžete si prohlédnout stáje, pastviny s desítkami koní i ukázky drezúry. Areál leží uprostřed typické krasové krajiny blízko italských hranic.', 45.66737, 13.88005, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lipica%20horses%20(7198987762).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lipica%20horses%20(7198987762).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mare%20&%20Foal%203%20(7361664544).jpg"}'::text[], 4),
    (v_route, 'Cerknické jezero', 'Největší občasné (mizející) jezero v Evropě, které se přes rok plní a znovu vysychá skrze podzemní krasové kanály. Podle ročního období tu najdete rozlehlou vodní plochu s ptactvem, nebo suchou louku. Okolní silnice jsou ideální pro klidnou vyjížďku krasovou planinou.', 45.75028, 14.36389, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cerkni%C5%A1ko%20jezero.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cerkni%C5%A1ko%20jezero.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/SlikaCerkniskoJezeroPolno.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Col des Aravis', 'Malebný průsmyk (1486 m) mezi La Clusaz a Flumet s krásným výhledem na masiv Mont Blanc. Na vrcholu stojí kaplička Sainte-Anne a několik horských bister – ideální první zastávka na rozjezd. Silnice D909 je široká a plynulá, takže si užijete pohodové serpentiny.', 45.8702, 6.4588, 'https://commons.wikimedia.org/wiki/Special:FilePath/Col_des_aravis.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Col_des_aravis.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vue_sur_le_col_des_aravis_-_panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chapelle_des_Aravis_-_Col_des_Aravis_-_Haute-Savoie_-_France.jpg"}'::text[], 0),
    (v_route, 'Cormet de Roselend', 'Vysokohorský průsmyk (1968 m) nad tyrkysovým jezerem Lac de Roselend v masivu Beaufortain. Stoupání nabízí jedny z nejfotogeničtějších zatáček celé trasy s otevřenými výhledy na pastviny a hráz přehrady. Povrch je kvalitní, ale dávejte pozor na volně se pasoucí dobytek.', 45.69135, 6.69054, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cormet_de_Roselend_(1_968_m).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cormet_de_Roselend_(1_968_m).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/D_925_vers_Cormet_de_Roselend_(Savoie).JPG"}'::text[], 1),
    (v_route, 'Col de l''Iseran', 'Nejvyšší asfaltový průsmyk Alp (2764 m) mezi Val d''Isère a Bonneval-sur-Arc. Silnice D902 vede holým vysokohorským terénem, kde i v létě může být citelný chlad a sníh na okrajích. Vrchol je vrcholným zážitkem trasy – naberte teplé vrstvy a dejte si čas na aklimatizaci.', 45.4168, 7.0252, 'https://commons.wikimedia.org/wiki/Special:FilePath/Col_de_l''Iseran_2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Col_de_l''Iseran_2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Col_de_l%C2%B4Iseran_East_F.JPG"}'::text[], 2),
    (v_route, 'Restaurace: L''Avancher (Val d''Isère)', 'Oblíbená savojská restaurace v centru Val d''Isère, ideální zastávka na první přenocování po Col des Aravis a Cormet de Roselend. Šéfkuchař servíruje poctivé regionální klasiky – fondue, sýrovou raclette à l''ancienne i pečená masa z místních surovin. Podnik má výborné hodnocení návštěvníků a pověst skvělého poměru cena/výkon v horském letovisku.', 45.4489, 6.9797, 'https://commons.wikimedia.org/wiki/Special:FilePath/Val_d''Isere_vue_aerienne.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Val_d''Isere_vue_aerienne.jpg"}'::text[], 3),
    (v_route, 'Col du Télégraphe', 'Zalesněný průsmyk (1566 m) nad údolím Maurienne, který slouží jako předehra ke Galibieru. Nad silnicí se tyčí historický Fort du Télégraphe z opevňovacího systému Séré de Rivières. Nekonečné zatáčky ve stínu stromů jsou příjemné za horkých dní.', 45.1994, 6.4434, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fort_du_T%C3%A9l%C3%A9graphe_vu_de_la_vall%C3%A9e_de_la_Maurienne_(2019).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_du_T%C3%A9l%C3%A9graphe_vu_de_la_vall%C3%A9e_de_la_Maurienne_(2019).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Haute_vall%C3%A9e_de_la_Maurienne_(Savoie).JPG"}'::text[], 4),
    (v_route, 'Col du Galibier', 'Ikonický průsmyk (2642 m) a jeden z klenotů Route des Grandes Alpes s dechberoucími panoramaty vrcholů. Známý z Tour de France nabízí strmé, technické serpentiny a řídký vzduch ve výšce. Krátce pod vrcholem projíždíte tunelem, nebo můžete vyjet až na samotné sedlo.', 45.06427, 6.40794, 'https://commons.wikimedia.org/wiki/Special:FilePath/Galibier.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Galibier.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Col_du_Galibier_et_massif_du_Galibier.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Col_du_galibier.jpg"}'::text[], 5),
    (v_route, 'Col d''Izoard', 'Legendární průsmyk (2360 m) proslulý měsíční krajinou Casse Déserte s bizarními skalními věžemi. Silnice D902 mezi Briançonem a Guillestre patří k nejkrásnějším motorkářským úsekům Alp. Na vrcholu stojí pamětní stéla a malé muzeum – povinná zastávka na fotku.', 44.8187, 6.7345, 'https://commons.wikimedia.org/wiki/Special:FilePath/Izoard3.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Izoard3.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Col_d''Izoard_Monument.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Col_d''Izoard,_France_(7957089924).jpg"}'::text[], 6),
    (v_route, 'Restaurace: Au Plaisir Ambré (Briançon)', 'Vyhlášená francouzská restaurace v srdci opevněné Cité Vauban v Briançonu, skvělá zastávka mezi Galibierem a Col d''Izoard. Kuchyně je vynalézavá, s přesnými chutěmi a kvalitními surovinami – podnik nese michelinský Bib Gourmand a hodnocení kolem 4,5 hvězdy. Chválen je zejména výjimečný poměr ceny a kvality a příjemná obsluha.', 44.8938, 6.6455, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vauban_briancon_enceinte.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vauban_briancon_enceinte.JPG"}'::text[], 7),
    (v_route, 'Col de Vars', 'Průsmyk (2109 m) spojující údolí Guillestre a Ubaye s otevřenými loukami a lyžařskou obcí Vars. Stoupání je plynulé a méně přeplněné než sousední velikáni, takže si užijete klidnou jízdu. Za vrcholem vás čeká příjemný sjezd do Barcelonnette.', 44.5389, 6.7028, 'https://commons.wikimedia.org/wiki/Special:FilePath/Col_de_Vars.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Col_de_Vars.jpg"}'::text[], 8),
    (v_route, 'Barcelonnette', 'Sympatické městečko v údolí Ubaye s neobvyklou mexickou architekturou vil postavených navrátivšími se emigranty. Ideální místo na nocleh, doplnění paliva a odpočinek mezi náročnými etapami. Náměstí Place Manuel láká na kávu i lokální speciality.', 44.3869, 6.6518, 'https://commons.wikimedia.org/wiki/Special:FilePath/Barcelonnette-Place_Manuel-DSCF8702.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Barcelonnette-Place_Manuel-DSCF8702.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Barcelonnette-Villas_mexicaines-IMG_1240.JPG"}'::text[], 9),
    (v_route, 'Col de la Bonette', 'Vrcholová smyčka kolem Cime de la Bonette (2802 m) je nejvýše položenou asfaltovou silnicí ve Francii. Silnice vede přísně chráněným národním parkem Mercantour v holé vysokohorské krajině. Počítejte s prudkým chladem, řídkým vzduchem a naprosto výjimečnými výhledy.', 44.3216, 6.8069, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bonette.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bonette.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacets_Bonette_Cabane_noire.jpg"}'::text[], 10),
    (v_route, 'Col de la Cayolle', 'Divoký, úzký průsmyk (2326 m) mezi údolím Ubaye a Var vedoucí soutěskami a podél horské bystřiny. Silnice D902 je místy jen jeden a půl pruhu široká, takže vyžaduje soustředěnou a defenzivní jízdu. Odměnou je opuštěná, klidná a nádherná horská příroda.', 44.25914, 6.74397, 'https://commons.wikimedia.org/wiki/Special:FilePath/Col-de-la-Cayolle-1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Col-de-la-Cayolle-1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Route_entre_Barcelonnette_et_le_col_de_la_Cayolle_(D902)_-15.JPG"}'::text[], 11),
    (v_route, 'Gorges de Daluis', 'Nádherné červené soutěsky řeky Var, kterým se přezdívá ''Colorado Nice'' díky rezavě zbarveným pískovcům. Úzká silnice se prořezává skalními tunely a nad hlubokou roklí – jízda tu je pomalá a vizuálně strhující. Zastavte se na vyhlídce Rocher de la Tête de femme.', 44.05462, 6.84882, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gorges_du_Daluis_-_Rocher_de_la_T%C3%AAte_de_femme.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gorges_du_Daluis_-_Rocher_de_la_T%C3%AAte_de_femme.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Daluis_gorges_du_var_01.jpg"}'::text[], 12),
    (v_route, 'Menton', 'Cílové přímořské město na Azurovém pobřeží u italské hranice, symbolický konec trasy u Středozemního moře. Barevné domy staré čtvrti, palmy a citronové sady vytvářejí ostrý kontrast k chladným alpským vrcholům. Zasloužený závěr – smočte nohy v moři a oslavte dojezd.', 43.7765, 7.5044, 'https://commons.wikimedia.org/wiki/Special:FilePath/Menton_vieille_ville.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Menton_vieille_ville.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Menton_Old_Town_and_Harbour.jpg"}'::text[], 13);
