  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Point Sublime', 'Ikonická vyhlídka nad soutěskou Verdonu, odkud se otevírá pohled do hloubky přes 700 metrů. Z parkoviště je to jen pár minut pěšky k okraji srázu s výhledem na vesnici Rougon. Skvělé místo pro první zastávku a fotku motorky s kaňonem v pozadí. Ráno tu bývá klid, přes den se plní autobusy.', 43.79418, 6.39849, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20du%20Verdon%20-%20Rougon%20and%20rock%20-%20Point%20Sublime%20at%20D%20952%20road%20-%20Massif%20du%20Montdenier%20(cropped).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20du%20Verdon%20-%20Rougon%20and%20rock%20-%20Point%20Sublime%20at%20D%20952%20road%20-%20Massif%20du%20Montdenier%20(cropped).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20du%20Point%20Sublime.jpg"}'::text[], 0),
    (v_route, 'Route des Crêtes (La Palud-sur-Verdon)', 'Legendární okružní silnice D23 s asi patnácti vyhlídkovými balkony přímo nad propastí kaňonu. Úzká vozovka se řadou serpentin patří k tomu nejlepšímu, co lze na motorce v Provence zažít. Část trasy je jednosměrná, takže se jede v daném směru bez protijedoucích aut. Na skalách nad silnicí často uvidíte kroužit supy bělohlavé.', 43.758, 6.352, 'https://commons.wikimedia.org/wiki/Special:FilePath/Route%20des%20Cr%C3%AAtes-Gorges%20du%20Verdon%20West.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Route%20des%20Cr%C3%AAtes-Gorges%20du%20Verdon%20West.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Route%20des%20Cr%C3%AAtes-Gorges%20du%20Verdon%20Ost.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Belv%C3%A9d%C3%A8re%20du%20Tilleul-Route%20des%20Cr%C3%AAtes-Gorges%20du%20Verdon.JPG"}'::text[], 1),
    (v_route, 'Balcons de la Mescla', 'Vyhlídka na jižním břehu kaňonu v místě, kde se řeka Verdon stáčí do dramatické smyčky. Pohled dolů na soutok s Artuby je jeden z nejfotografovanějších v celém regionu. Malé parkoviště a kavárnička nabízejí příjemnou pauzu uprostřed dne. Odsud je to jen kousek k mostu Pont de l''Artuby.', 43.7393, 6.38114, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20du%20Verdon%20au%20balcon%20de%20la%20Mescla%20-1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20du%20Verdon%20au%20balcon%20de%20la%20Mescla%20-1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20du%20Verdon%20au%20balcon%20de%20la%20Mescla%20-2.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20du%20Verdon%20au%20balcon%20de%20la%20Mescla%20-3.JPG"}'::text[], 2),
    (v_route, 'Pont de l''Artuby', 'Jednoobloukový betonový most klenoucí se přes soutěsku Artuby ve výšce zhruba 180 metrů. Je proslulý jako jedno z nejvýše položených míst pro bungee jumping v Evropě. Pro motorkáře je to skvělá zastávka s výhledem do hluboké rokle přímo pod koly. Přejezd mostu na silnici D71 patří k adrenalinovým momentům trasy.', 43.76652, 6.4443, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20de%20l''Artuby%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20de%20l''Artuby%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20de%20l''Artuby%2C%20Gorges%20du%20Verdon%20-%20panoramio.jpg"}'::text[], 3),
    (v_route, 'Aiguines', 'Půvabná provensálská vesnička s renesančním zámkem, posazená na svahu nad jezerem Sainte-Croix. Z uliček i od kostela je nádherný výhled na tyrkysovou vodní hladinu. Skvělé místo na oběd nebo kávu před sjezdem k jezeru. Vesnice je proslulá tradiční výrobou dřevěných koulí na hru pétanque.', 43.77567, 6.24308, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aiguines-Verdon-Provence.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aiguines-Verdon-Provence.jpg"}'::text[], 4),
    (v_route, 'Lac de Sainte-Croix', 'Rozlehlé umělé jezero se sytě tyrkysovou vodou, které tvoří západní bránu do kaňonu Verdonu. U mostu Galetas si můžete půjčit loďku nebo šlapadlo a zajet k ústí soutěsky. Břehy lákají k osvěžení v horkém letním dni po náročné jízdě. Silnice kolem jezera nabízí spoustu příležitostí k zastávce a fotografování.', 43.77154, 6.18983, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Sainte-Croix-1.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Sainte-Croix-1.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20du%20Verdon%20from%20bridge%20over%20Lac%20de%20Sainte-Croix%2C%20Provence.jpg"}'::text[], 5),
    (v_route, 'Restaurace: La Bastide de Moustiers (Moustiers-Sainte-Marie)', 'Elegantní restaurace legendárního šéfkuchaře Alaina Ducasse ve staré provensálské usedlosti pod vesnicí Moustiers-Sainte-Marie. Kuchyně staví na sezonních surovinách z vlastní zahrady a klasické provensálské gastronomii povýšené do michelinské úrovně. Hosté ji milují za skvělou obsluhu i klidnou atmosféru mezi levandulí a bylinkami, hodnocení se drží kolem 4,6 hvězdy. Ideální zastávka na oběd zhruba v polovině okruhu.', 43.844, 6.216, 'https://commons.wikimedia.org/wiki/Special:FilePath/Moustiers%20Sainte%20Marie%20Village.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Moustiers%20Sainte%20Marie%20Village.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Moustiers-Sainte-Marie%20interieur%20du%20Village.jpg"}'::text[], 6),
    (v_route, 'Moustiers-Sainte-Marie', 'Jedna z nejkrásnějších vesnic Francie, vklíněná mezi dvě skalní stěny s pozlacenou hvězdou zavěšenou na řetězu nad údolím. Proslula výrobou jemné fajánsové keramiky, kterou najdete v desítkách obchůdků. Úzké kamenné uličky a kaple Notre-Dame de Beauvoir vysoko nad vesnicí stojí za procházku. Ideální závěrečná zastávka okruhu před návratem.', 43.84639, 6.22111, 'https://commons.wikimedia.org/wiki/Special:FilePath/Moustiers-Sainte-Marie%20interieur%20du%20Village.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Moustiers-Sainte-Marie%20interieur%20du%20Village.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Moustiers-Sainte-Marie%20(17).JPG"}'::text[], 7);
  insert into public.routes
