  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bastia', 'Přístavní metropole severní Korsiky a přirozený start i cíl okruhu. Zaparkuj u Vieux Port, dej si kávu a nasaj atmosféru starých uliček citadely. Odsud vyrážíš na severní smyčku kolem Cap Corse – natankuj do plna, dál na mysu jsou pumpy vzácné.', 42.69729, 9.45088, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bastia%20vieux%20port.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bastia%20vieux%20port.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bastia-le-vieux-port.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Corse-04518-bastia-vieux%20port.jpg"}'::text[], 0),
    (v_route, 'Cap Corse', 'Divoký severní poloostrov s úzkou pobřežní silnicí D80, která se lepí na útesy nad mořem. Nekonečné serpentiny, janovské věže a rybářské vesničky odměňují každou zatáčku výhledem. Silnice je místy jen na jedno auto, takže jeď defenzivně a užívej si jeden z nejkrásnějších pobřežních úseků ostrova.', 42.964, 9.447, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cap%20Corse%20-%20on%20the%20D80%20after%20Albo%20Punta%20di%20Canelle%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cap%20Corse%20-%20on%20the%20D80%20after%20Albo%20Punta%20di%20Canelle%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Corse-04642-marine%20de%20Giottani-%20cap%20Corse.jpg"}'::text[], 1),
    (v_route, 'Calvi', 'Přímořské město v Balagne s mohutnou janovskou citadelou nad tyrkysovým zálivem. Ideální zastávka na konci prvního dne – marina, pláž a spousta restaurací. Odsud druhý den zamíříš do hor přes klikaté silnice regionu Balagne.', 42.566, 8.7571, 'https://commons.wikimedia.org/wiki/Special:FilePath/0%20Calvi%20-%20Punta%20San%20Francesco%20-%20Quartiers%20de%20la%20Citadelle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/0%20Calvi%20-%20Punta%20San%20Francesco%20-%20Quartiers%20de%20la%20Citadelle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Citadel%20of%20Calvi,%20Corsica,%20France%20(52724224695).jpg"}'::text[], 2),
    (v_route, 'Col de Vergio', 'Nejvýše položený sjízdný průsmyk Korsiky (1478 m) na silnici D84 mezi Niolem a údolím Porto. Cesta nahoru vede borovicovými lesy Aïtone a plná serpentin nabízí famózní výhledy do hor. Nahoře je chladno i v létě, tak si přibal vrstvu navíc.', 42.29032, 8.8784, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bocca%20di%20Verghju.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bocca%20di%20Verghju.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Corsica,%20Col%20de%20Vergio,%20Jesus%20Christus.jpg"}'::text[], 3),
    (v_route, 'Corte', 'Historické srdce Korsiky s citadelou na skále, obklopené horami. Univerzitní město je skvělou základnou pro průzkum vnitrozemí a soutěsek. Zastav se na náměstí, dej si korsickou specialitu a naber sílu před cestou do Restonicy.', 42.30941, 9.14902, 'https://commons.wikimedia.org/wiki/Special:FilePath/GR20%20DEPUIS%20CORTE%20(CORSE%20-%20FRANCE).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/GR20%20DEPUIS%20CORTE%20(CORSE%20-%20FRANCE).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Parc%20Hte%20Corse-Bozio-Corte3.JPG"}'::text[], 4),
    (v_route, 'Restaurace: A Casuccia (Corte)', 'Rodinná restaurace v srdci Corte na terase pod historickým sídlem generála Gafforiho, ideální zastávka na konci druhého dne. Na jídelníčku najdeš pravé korsické speciality i vyhlášené pizzy z místních surovin. Skvělé hodnocení kolem 4,5 hvězdy chválí přátelskou obsluhu, výhled z terasy a poctivé porce za rozumnou cenu.', 42.3051, 9.1512, 'https://commons.wikimedia.org/wiki/Special:FilePath/GR20%20DEPUIS%20CORTE%20(CORSE%20-%20FRANCE).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/GR20%20DEPUIS%20CORTE%20(CORSE%20-%20FRANCE).jpg"}'::text[], 5),
    (v_route, 'Restonica', 'Dramatická horská soutěska nad Corte s křišťálovou řekou a žulovými stěnami. Úzká silnice D623 stoupá údolím k horským jezerům – jeď opatrně, je vyhrazená a v sezoně plná turistů. Odměnou je jedno z nejfotogeničtějších údolí ostrova.', 42.225, 9.05, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gorge%20de%20Restonica01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gorge%20de%20Restonica01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Korsika%20Corte%20Restonica%20Tal%202.jpg"}'::text[], 6),
    (v_route, 'Les Calanche de Piana', 'Bizarní červené žulové skály nad Portským zálivem, zapsané v UNESCO. Silnice D81 se proplétá přímo mezi rozeklanými skalními věžemi nad mořem – jeden z nejikoničtějších úseků na Korsice. Zastav na vyhlídce, ale pozor na úzkou vozovku a protijedoucí autobusy.', 42.238, 8.6363, 'https://commons.wikimedia.org/wiki/Special:FilePath/01%20Calanche%20Piana.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/01%20Calanche%20Piana.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/02%20Calanche%20Piana.jpg"}'::text[], 7),
    (v_route, 'Ajaccio', 'Hlavní město Korsiky a rodiště Napoleona, ležící v širokém zálivu. Živá marina, palmové promenády a spousta míst na přenocování z něj dělají příjemnou zastávku na konci třetího dne. Odsud vyrážíš na jižní cíp ostrova.', 41.9267, 8.7369, 'https://commons.wikimedia.org/wiki/Special:FilePath/Port%20Ajaccio.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Port%20Ajaccio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Citadelle%20d''Ajaccio.jpg"}'::text[], 8),
    (v_route, 'Bonifacio', 'Středověké město dramaticky posazené na bílých vápencových útesech nad mořem na nejjižnějším cípu ostrova. Přístup vede po klikaté pobřežní silnici s výhledy až na Sardinii. Nech motorku dole a projdi se úzkými uličkami horního města – zážitek k nezaplacení.', 41.3874, 9.15941, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bonifacio%20cliffs%20-Le%20Grain%20de%20Sable.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bonifacio%20cliffs%20-Le%20Grain%20de%20Sable.JPG"}'::text[], 9),
    (v_route, 'Restaurace: Les Quatre Vents (Bonifacio)', 'Elegantní restaurace na konci nábřeží bonifacké mariny s terasou přímo nad přístavem a výhledem na citadelu. Specializuje se na ryby a mořské plody – domácí bouillabaisse i lingvine s humrem, v zimě přechází na tradiční korsickou kuchyni. Vynikající hodnocení 4,6 hvězdy chválí čerstvé suroviny, kvalitu a nezapomenutelnou polohu u vody.', 41.3877, 9.1594, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bonifacio%20cliffs%20-Le%20Grain%20de%20Sable.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bonifacio%20cliffs%20-Le%20Grain%20de%20Sable.JPG"}'::text[], 10),
    (v_route, 'Porto-Vecchio', 'Elegantní přístavní město na jihovýchodě, obklopené proslulými plážemi Palombaggia a Santa Giulia. Skvělé místo na oběd u mariny před tím, než zamíříš do hor k průsmyku Bavella. Staré město na kopci nabízí příjemný stín a výhled na záliv.', 41.59101, 9.27947, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20Palombaggia%20Beach,%20Corsica,%20France%20(52724214180).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20Palombaggia%20Beach,%20Corsica,%20France%20(52724214180).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Plage%20marina%20fiori%20-%20panoramio.jpg"}'::text[], 11),
    (v_route, 'Col de Bavella', 'Legendární horský průsmyk (1218 m) s pilovitými skalními jehlami Aiguilles de Bavella, sen každého motorkáře. Silnice D268 k němu je jedna souvislá série dokonalých serpentin borovicovými lesy. Nahoře zastav u vyhlídky a vychutnej si panorama – tohle je vrchol celého okruhu.', 41.79602, 9.22477, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aiguilles%20de%20Bavella,%20Corsica.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aiguilles%20de%20Bavella,%20Corsica.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zonza%20-%20Aiguilles%20Bavella.jpg"}'::text[], 12);
