  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Cangas de Onís', 'Historické městečko, první hlavní město asturského království, je ideálním startem okruhu. Přes řeku Sella se klene fotogenický „římský" most s křížem Vítězství, symbol Asturie. Zaparkujte, dejte si kávu a načerpejte síly před stoupáním do hor. V okolí najdete i poslední benzinky před horskými úseky.', 43.3513, -5.1285, 'https://commons.wikimedia.org/wiki/Special:FilePath/Congas%20de%20Onis.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Congas%20de%20Onis.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Puente%20Romano.JPG"}'::text[], 0),
    (v_route, 'Svatyně Covadonga', 'Neorománská bazilika Santa María la Real se tyčí na skále nad údolím a je duchovním srdcem Asturie. Vedle stojí posvátná jeskyně Santa Cueva s Pannou Marií Covadonžskou. Cesta sem stoupá lesem v pěkných zatáčkách. Je to skvělé místo na zastávku před náročným výjezdem k jezerům.', 43.30886, -5.05352, 'https://commons.wikimedia.org/wiki/Special:FilePath/Covadonga%20-%20Bas%C3%ADlica%20de%20Santa%20Mar%C3%ADa%20la%20Real%2009.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Covadonga%20-%20Bas%C3%ADlica%20de%20Santa%20Mar%C3%ADa%20la%20Real%2009.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bas%C3%ADlica%20de%20Santa%20Mar%C3%ADa%20la%20Real%20de%20Covadonga,%20Asturias.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Santuario%20de%20Covadonga.%20Santa%20Cueva.jpg"}'::text[], 1),
    (v_route, 'Lagos de Covadonga', 'Dvě ledovcová jezera Enol a Ercina leží ve výšce přes 1000 metrů uprostřed pastvin a vápencových štítů. Silnice sem je úzká, prudká a plná serpentin – v sezoně bývá pro auta regulovaná, ale motorky mají obvykle volno. Nahoře na vás čeká jeden z nejkrásnějších horských výhledů Španělska. Pozor na krávy a mlhu, která přichází rychle.', 43.26992, -4.98615, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20Enol%20(Lagos%20de%20Covadonga,%20Picos%20de%20Europa,%20Asturias,%20Espa%C3%B1a).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20Enol%20(Lagos%20de%20Covadonga,%20Picos%20de%20Europa,%20Asturias,%20Espa%C3%B1a).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20Ercina%20(Lagos%20de%20Covadonga,%20Picos%20de%20Europa,%20Asturias,%20Espa%C3%B1a)%2004.JPG"}'::text[], 2),
    (v_route, 'Mirador del Fitu', 'Vyhlídka ve výšce 1100 metrů v pohoří Sueve nabízí panoramatický výhled na Picos de Europa i asturské pobřeží. Přístupová silnice je jedna dlouhá řada zatáček, kterou milují motorkáři i cyklisté. Za jasného dne odsud vidíte moře i zasněžené štíty najednou. Ideální místo na fotku motorky s horami v pozadí.', 43.43907, -5.19347, 'https://commons.wikimedia.org/wiki/Special:FilePath/ES1200043-Sierra%20del%20Sueve%20desde%20el%20Mirador%20del%20Fito%20IGP0291.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/ES1200043-Sierra%20del%20Sueve%20desde%20el%20Mirador%20del%20Fito%20IGP0291.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/ES1200043-Sierra%20del%20Suava%20desde%20el%20Mirador%20del%20Fito%20AGA9989.jpg"}'::text[], 3),
    (v_route, 'Desfiladero de los Beyos', 'Jedna z nejužších průjezdných soutěsek Evropy, vyhloubená řekou Sella podél silnice N-625. Skalní stěny se tu zvedají stovky metrů kolmo nad hlavou a silnice se vine těsně u řeky. Jízda soutěskou je nezapomenutelný zážitek, ale buďte opatrní – je tu stín, vlhko a místy kluzký asfalt. Rozhodně žádná dálnice, jen čistá horská romantika.', 43.3, -5.03, 'https://commons.wikimedia.org/wiki/Special:FilePath/Desfiladero%20de%20los%20Beyos%20o%20del%20Sella%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Desfiladero%20de%20los%20Beyos%20o%20del%20Sella%20-%20panoramio.jpg"}'::text[], 4),
    (v_route, 'Potes', 'Malebné kamenné městečko je srdcem údolí Liébana a přirozeným místem k přenocování při dvoudenním okruhu. Úzké uličky, středověké mosty přes řeku Quiviesa a věž Torre del Infantado tvoří kulisu jako z pohádky. Najdete tu spoustu restaurací s místní kuchyní a likérem orujo. Odsud vyrážejí trasy k lanovce Fuente Dé i přes průsmyk San Glorio.', 43.15368, -4.62343, 'https://commons.wikimedia.org/wiki/Special:FilePath/Potes,%20Cantabria%2016.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Potes,%20Cantabria%2016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Torre%20del%20Infantado%20(Potes)%20(2660853032)%20(2).jpg"}'::text[], 5),
    (v_route, 'Restaurace: Casa Cayo (Potes)', 'Tradiční rodinná restaurace v samém srdci Potes je legendou lebanské kuchyně a ideální zastávkou v půlce okruhu. Ochutnáte tu proslulý cocido lebaniego, jehněčí i místní sýry a k tomu domácí likér orujo. Hosté ji milují za skvělou kvalitu i vřelý přístup – hodnocení kolem 4,5 hvězdy na TripAdvisoru a 4,6 na Googlu z ní dělá jednu z nejoblíbenějších adres ve městě.', 43.1548, -4.6222, 'https://commons.wikimedia.org/wiki/Special:FilePath/Potes,%20Cantabria%2041.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Potes,%20Cantabria%2041.jpg"}'::text[], 6),
    (v_route, 'Fuente Dé', 'Slepé údolí končí kolmou vápencovou stěnou, kde lanovka vyveze návštěvníky o 750 metrů výš k vyhlídce Mirador del Cable ve výšce 1850 metrů. Silnice CA-185 sem z Potes vede krásným lebanským údolím plným zatáček. Nechte motorku dole a vyjeďte lanovkou za dechberoucím výhledem na Picos de Europa. Nahoře bývá výrazně chladněji, přibalte si vrstvu navíc.', 43.1465, -4.81451, 'https://commons.wikimedia.org/wiki/Special:FilePath/Telef%C3%A9rico%20de%20Fuente%20D%C3%A9.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Telef%C3%A9rico%20de%20Fuente%20D%C3%A9.jpg"}'::text[], 7),
    (v_route, 'Puerto de San Glorio', 'Vysoký horský průsmyk ve výšce 1604 metrů spojuje Kantabrii s provincií León a tvoří velkolepé finále okruhu. Silnice se vine dlouhými, přehlednými serpentinami s minimem provozu – motorkářský sen. Z vrcholu vede krátká odbočka k vyhlídce Mirador de Llesba se sochou medvěda a výhledem na celé pohoří. V zimě a brzy na jaře bývá průsmyk zasněžený, ověřte si sjízdnost.', 43.0271, -4.7956, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monumento%20al%20oso%20pardo%20en%20el%20Collado%20de%20Llesba.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monumento%20al%20oso%20pardo%20en%20el%20Collado%20de%20Llesba.jpg"}'::text[], 8);
