  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Ronda (Puente Nuevo)', 'Ronda se pyšní ohromujícím mostem Puente Nuevo, který se klene 120 metrů nad soutěskou El Tajo. Zaparkuj motorku poblíž centra a projdi se k vyhlídce nad kaňonem, výhled stojí za to. Ideální startovní bod pro celý okruh bílých měst.', 36.74117, -5.16667, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Puente%20Nuevo,%20Ronda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ronda%20Spain%20Puente-Nuevo-de-Ronda-01.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Tragatá (Ronda)', 'Tragatá je stylová tapasová restaurace šéfkuchaře Benita Gómeze, vedená v průvodci Michelin a proslulá kreativním pojetím andaluské kuchyně. Skvělé hodnocení kolem 4,4 hvězdičky potvrzuje tisíce spokojených hostů. Ideální zastávka na oběd v centru Rondy před vyjížďkou za bílými vesnicemi.', 36.7429, -5.1672, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg"}'::text[], 1),
    (v_route, 'Setenil de las Bodegas', 'Setenil je proslulé domy zapuštěnými přímo pod převislé skalní stěny, ulice tu doslova mizí pod kamenem. Silnice sem z Rondy nabízí příjemné táhlé zatáčky mezi olivovými háji. Nech motorku na okraji obce, uličky jsou úzké a plné turistů.', 36.8622, -5.1787, 'https://commons.wikimedia.org/wiki/Special:FilePath/Setenil%20de%20las%20Bodegas%202019-10-23%2003.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Setenil%20de%20las%20Bodegas%202019-10-23%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Setenil-DSC09997.JPG"}'::text[], 2),
    (v_route, 'Zahara de la Sierra', 'Bílá vesnice Zahara se choulí pod maurskou věží nad tyrkysovou nádrží Embalse de Zahara-El Gastor. Silnice A-2300 a serpentiny průsmyku Puerto de las Palomas patří k nejkrásnějším úsekům celé trasy. Zastav na vyhlídce nad přehradou a vychutnej si panorama.', 36.8406, -5.3905, 'https://commons.wikimedia.org/wiki/Special:FilePath/Andaluc%C3%ADa%20Zahara%20de%20la%20Sierra1%20tango7174.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Andaluc%C3%ADa%20Zahara%20de%20la%20Sierra1%20tango7174.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20pantano%20de%20Zahara%20de%20la%20Sierra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zahara%20de%20la%20Sierra,%20Spain.jpg"}'::text[], 3),
    (v_route, 'Grazalema', 'Grazalema leží v srdci stejnojmenného přírodního parku, jednoho z nejdeštivějších míst Španělska, díky čemuž je okolí nezvykle zelené. Klikaté horské silnice sem vedou hustými borovými lesy a nabízejí skvělou jízdu. Dobré místo na kávu a doplnění paliva před další etapou.', 36.75836, -5.36607, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Grazalema%20(C%C3%A1diz).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Grazalema%20(C%C3%A1diz).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Parque%20natural%20de%20la%20Sierra%20de%20Grazalema,%20Espa%C3%B1a,%20enero%20de%202011.JPG"}'::text[], 4),
    (v_route, 'Júzcar', 'Júzcar je celá modrá vesnice v údolí Genal, kterou natřeli kvůli premiéře filmu o Šmoulech a modrá už zůstala. Cesta sem z Rondy vede úzkou vyhlídkovou okreskou plnou kaštanů, technicky zábavná porce zatáček. Fotogenické zastavení mimo hlavní turistické trasy.', 36.62442, -5.16971, 'https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%BAzcar%20M%C3%A1laga%20Andalusia%20Spain%20smurf%20town.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%BAzcar%20M%C3%A1laga%20Andalusia%20Spain%20smurf%20town.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%BAzcar,%20Spain%20(%20The%20BLUE%20SMURF%20TOWN).JPG"}'::text[], 5),
    (v_route, 'El Chorro / Caminito del Rey', 'El Chorro ukrývá slavnou lávku Caminito del Rey přišpendlenou ke stěnám dramatické soutěsky nad řekou Guadalhorce. Silnice kolem přehrad sem nabízí úzké zatáčky a výhledy na tyrkysové nádrže. Pokud chceš projít stezku, rezervuj si vstupenku předem, kapacita je omezená.', 36.9068, -4.75923, 'https://commons.wikimedia.org/wiki/Special:FilePath/El%20famoso%20Caminito%20del%20Rey.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/El%20famoso%20Caminito%20del%20Rey.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Caminito%20del%20Rey%204.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Caminito%20del%20Rey%20Andalusia-13%20(25635110194).jpg"}'::text[], 6),
    (v_route, 'Granada (Alhambra)', 'Alhambra je maurský palácový komplex a klenot Granady, zapsaný na seznamu UNESCO. Přijeď brzy a zaparkuj na hlídaném parkovišti, centrum je pro motorky komplikované. Vstupenky si kup předem online, jinak se dovnitř nedostaneš.', 37.17604, -3.58828, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20la%20Alhambra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20la%20Alhambra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/La%20Alhambra%20vista%20desde%20el%20Albaic%C3%ADn.%20Granada.JPG"}'::text[], 7),
    (v_route, 'Restaurace: Mirador de Morayma (Granada)', 'Mirador de Morayma je půvabná restaurace v maurské čtvrti Albaicín s terasovou zahradou a úchvatným výhledem přímo na Alhambru. Podává povýšenou andaluskou kuchyni s mozárabskými motivy a těší se skvělému hodnocení kolem 4,4 hvězdičky. Rezervuj si stůl s výhledem předem, jde o zážitkovou tečku za druhým dnem trasy.', 37.1795, -3.5906, 'https://commons.wikimedia.org/wiki/Special:FilePath/La%20Alhambra%20vista%20desde%20el%20Albaic%C3%ADn.%20Granada.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/La%20Alhambra%20vista%20desde%20el%20Albaic%C3%ADn.%20Granada.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20la%20Alhambra.jpg"}'::text[], 8),
    (v_route, 'Pico Veleta (silnice)', 'Silnice na Pico Veleta je nejvýše položená zpevněná vozovka v Evropě, stoupá až přes 3300 metrů nad mořem. Horní úsek za lyžařským střediskem je pro běžnou dopravu uzavřený, ale výjezd k závoře je nezapomenutelný zážitek s řídkým vzduchem a výhledy. Ober se teple, i v létě tu bývá chladno a počasí se rychle mění.', 37.0558, -3.3658, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pico%20del%20Veleta%20Sierra%20Nevada.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pico%20del%20Veleta%20Sierra%20Nevada.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Veleta-pico.JPG"}'::text[], 9);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Andorra la Vella', 'Nejvýše položené hlavní město Evropy (1023 m) a přirozený start i cíl okruhu. Nabízí zázemí, čerpací stanice a bezcelní obchody, kde doplníte síly i palivo. Úzké uličky historického jádra kontrastují s moderním nákupním centrem. Odsud vyrážíte do hor a sem se také vracíte na konci dne.', 42.50779, 1.52109, 'https://commons.wikimedia.org/wiki/Special:FilePath/Andorra%20la%20Vella%202025.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Andorra%20la%20Vella%202025.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Andorra%20la%20Vella%203.JPG"}'::text[], 0),
    (v_route, 'Estany d''Engolasters', 'Klidné horské jezero ve výšce 1616 m nedaleko hlavního města, obklopené borovým lesem. K jezeru vede krátká, ale zábavná horská silnička plná zatáček, ideální na oddech uprostřed okruhu. Nad hladinou se tyčí historické vysílací antény bývalého Rádia Andorra. Je to oblíbené místo pro krátkou zastávku a fotografii.', 42.51982, 1.56835, 'https://commons.wikimedia.org/wiki/Special:FilePath/Estany%20d''Engolasters%20-%20Encamp%20-%20Andorre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Estany%20d''Engolasters%20-%20Encamp%20-%20Andorre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Radio%20Andorra%20broadcasting%20antennas%20-%20Llac%20d''Engolasters.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Estany%20d''Engolasters%20-%2019.jpg"}'::text[], 1),
    (v_route, 'Sant Joan de Caselles', 'Jeden z nejkrásnějších románských kostelů v Andoře z 11.–12. století, stojící u silnice v údolí Canillo. Jeho štíhlá zvonice a kamenná fasáda jsou skvělou fotozastávkou cestou k průsmyku Port d''Envalira. Kostel je zapsán v kulturním dědictví Andorry. Zastavte se tu na chvíli klidu, než se pustíte do stoupání do hor.', 42.571, 1.608, 'https://commons.wikimedia.org/wiki/Special:FilePath/Esgl%C3%A8sia%20de%20Sant%20Joan%20de%20Caselles,Canillo,%20Andorra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Esgl%C3%A8sia%20de%20Sant%20Joan%20de%20Caselles,Canillo,%20Andorra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Saint%20John%20church%20in%20Caselles%20(8).jpg"}'::text[], 2),
    (v_route, 'Restaurace: La Cort del Popaire (Soldeu)', 'Tradiční andorrská restaurace v centru horského střediska Soldeu, umístěná v citlivě zrekonstruované kamenné bordě přímo na trase k průsmyku Port d''Envalira. Specializuje se na maso grilované na otevřeném ohni a mistní pyrenejskou kuchyni. S hodnocením 4,6 na Googlu a 1. mistem v Soldeu na Tripadvisoru jde o skvělou zastávku na oběd před výjezdem do nejvyšších partií okruhu.', 42.577401, 1.66664, 'https://commons.wikimedia.org/wiki/Special:FilePath/Soldeu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Soldeu.jpg"}'::text[], 3),
    (v_route, 'Port d''Envalira', 'Nejvýše položený asfaltový průsmyk v celých Pyrenejích ve výšce 2408 m n. m. Silnice CG-2 sem stoupá dlouhými serpentinami a nabízí dechberoucí panoramata na okolní štíty. Pro motorkáře je to vrchol celé trasy – doslova i obrazně. I v létě zde bývá výrazně chladněji, proto s sebou vždy noste teplejší vrstvu.', 42.53534, 1.71765, 'https://commons.wikimedia.org/wiki/Special:FilePath/Port%20d''Envalira.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Port%20d''Envalira.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/CG-2%20Km23%20Tunel%20d''Envalira%20(14).JPG"}'::text[], 4),
    (v_route, 'Arcalís (Ordino)', 'Horské středisko na severu Andorry v parishi Ordino, nad nímž se tyčí Pic d''Arcalís (2777 m). Silnice sem vede zeleným údolím Ordino a končí ve vysokohorském terénu s drsnou přírodou. Je to skvělá slepá odbočka pro milovníky serpentin a rozlehlých alpských scenérií. Cesta zpět nabízí stejně krásné zatáčky jako výjezd.', 42.631731, 1.499821, 'https://commons.wikimedia.org/wiki/Special:FilePath/Entre%20Coll%20d''Ordino%20e%20Canillo.%20Andorra%2030.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Entre%20Coll%20d''Ordino%20e%20Canillo.%20Andorra%2030.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Entre%20Coll%20d''Ordino%20e%20Canillo.%20Andorra%2031.jpg"}'::text[], 5),
    (v_route, 'Coll de la Gallina', 'Technicky nejnáročnější průsmyk Andorry ve výšce okolo 1910 m, proslulý mezi cyklisty i motorkáři strmými, těsnými serpentinami. Stoupání vede z údolí Sant Julià de Lòria kolem svatyně Mare de Déu de Canòlic. Úzká vozovka a prudké zatáčky vyžadují plnou pozornost a přesnou stopu. Odměnou je klidná silnice bez provozu a nádherné výhledy do údolí.', 42.44688, 1.47447, 'https://commons.wikimedia.org/wiki/Special:FilePath/Santuari%20de%20la%20Mare%20de%20D%C3%A9u%20de%20Can%C3%B2lic.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Santuari%20de%20la%20Mare%20de%20D%C3%A9u%20de%20Can%C3%B2lic.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Our%20Lady%20church%20in%20Canolic%20(3).jpg"}'::text[], 6);
