  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Silnice N222 u Pinhão (údolí Douro)', 'Úsek N222 mezi Pinhão a Régua je opakovaně vyhlašován za jednu z nejkrásnějších silnic světa. Klikatí se nad řekou Douro kolem vinařských teras zapsaných na seznamu UNESCO a nabízí motorkáři plynulé zatáčky s dechberoucími výhledy. Zastavte na některém z vyhlídkových míst a vychutnejte si panorama portského vína.', 41.1911, -7.5348, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pinh%C3%A3o.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pinh%C3%A3o.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20Presidential%20Train,%20Douro%20Valley,%20Pinh%C3%A3o%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Way%20of%20Saint%20James%20in%20Pinh%C3%A3o,%20Douro%20Valley,%20Portugal.jpg"}'::text[], 0),
    (v_route, 'Peso da Régua', 'Régua je hlavním městem regionu portského vína a přirozenou branou do údolí Douro. U řeky stojí Museu do Douro a několik mostů, které nabízejí pěkné fotozastávky. Je to ideální místo na kávu a doplnění paliva před další jízdou po klikatých vinařských silnicích.', 41.1625, -7.7879, 'https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%A9gua%20-%20Museu%20do%20Douro%20na%20Regi%C3%A3o%20do%20Alto%20Douro.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%A9gua%20-%20Museu%20do%20Douro%20na%20Regi%C3%A3o%20do%20Alto%20Douro.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Douro%20Valley%20Regua.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Esta%C3%A7%C3%A3o%20da%20R%C3%A9gua,%202010.10.02.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Cozinha da Clara (Pinhão)', 'Moderní prosklená restaurace ve vinařství Quinta de la Rosa jen kousek od Pinhão nabízí poctivou místní kuchyni z lokálních surovin a vlastní zahrady. Z terasy se otevírá nádherný výhled na vinařské terasy a řeku Douro. Skvěle hodnocená (4,4/5 z více než 1200 recenzí) – ideální oběd na začátku prvního dne.', 41.207, -7.529, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pinh%C3%A3o.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pinh%C3%A3o.jpg"}'::text[], 2),
    (v_route, 'Miranda do Douro', 'Pohraniční město vysoko nad kaňonem řeky Douro na hranici se Španělskem, proslulé vlastním jazykem mirandštinou. Dominují mu zříceniny hradu a stará katedrála. Cesta sem vede opuštěnými silnicemi Mezinárodním přírodním parkem Douro, kde potkáte spíš supy než auta.', 41.4959, -6.2734, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Miranda%20do%20Douro%20-%20DSC%208090.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Miranda%20do%20Douro%20-%20DSC%208090.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Miranda%20do%20Douro%20-%20DSC%208096.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Igreja%20Matriz%20de%20Miranda%20do%20Douro.jpg"}'::text[], 3),
    (v_route, 'Serra da Estrela – Torre', 'Torre je s 1993 m nejvyšším bodem pevninského Portugalska a výstup k němu patří k nejlepším horským jízdám v zemi. Serpentiny stoupají nad hranici lesa mezi žulovými balvany a ledovcovými jezery. Počítejte s chladem, větrem a v zimě i se sněhem, ale výhledy do všech stran stojí za to.', 40.322, -7.616, 'https://commons.wikimedia.org/wiki/Special:FilePath/Torre-Serra%20da%20Estrela.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Torre-Serra%20da%20Estrela.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Serra%20a%20Estrela%20(Torre).JPG"}'::text[], 4),
    (v_route, 'Manteigas (údolí Zêzere)', 'Horské městečko na dně dokonalého ledovcového údolí ve tvaru U, kterým protéká řeka Zêzere. Silnice N338 sem klesá řadou vyhlídkových serpentin, jež jsou pro motorkáře čirou radostí. Zastavte u vyhlídky Poço do Inferno nebo se svlažte v místních horských potocích.', 40.4035, -7.5371, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vale%20Glaciar%20do%20Z%C3%AAzere.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vale%20Glaciar%20do%20Z%C3%AAzere.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Viveiro%20das%20Trutas%20Manteigas%20Serra%20da%20Estrela.jpg"}'::text[], 5),
    (v_route, 'Guarda', 'Nejvýše položené město Portugalska (1056 m) s mohutnou gotickou katedrálou Sé z 14. století na historickém náměstí Praça Velha. Kamenné uličky a zbytky hradeb připomínají obrannou minulost při španělské hranici. Díky poloze je Guarda skvělou základnou pro průzkum okolních hor.', 40.5333, -7.2056, 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A9%20Catedral,%20Guarda,%20Portugal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A9%20Catedral,%20Guarda,%20Portugal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A9%20Catedral%20da%20Guarda%20-%20Pra%C3%A7a%20Velha.jpg"}'::text[], 6),
    (v_route, 'Restaurace: Nobre Vinhos e Tal (Guarda)', 'Portugalská restaurace a vinný bar v historickém centru Guardy s balkonem a jedinečným výhledem na katedrálu Sé. Servírují regionální gastronomii z místních sýrů, uzenin a masa spolu s výběrem stovek portugalských vín. Vynikající hodnocení (4,7/5) – skvělé místo na oběd před další horskou etapou.', 40.5372, -7.268, 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A9%20Catedral%20da%20Guarda%20-%20Pra%C3%A7a%20Velha.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A9%20Catedral%20da%20Guarda%20-%20Pra%C3%A7a%20Velha.jpg"}'::text[], 7),
    (v_route, 'NP Peneda-Gerês', 'Jediný národní park Portugalska nabízí divokou žulovou krajinu, vodopády, přehrady a starobylé vesnice s tradičními sýpkami espigueiros. Vyhlídka Miradouro da Pedra Bela patří k nejfotografovanějším místům parku. Úzké horské silnice jsou technické a klikaté, ideální na pomalou zážitkovou jízdu bez spěchu.', 41.7291, -8.1549, 'https://commons.wikimedia.org/wiki/Special:FilePath/Miradouro%20da%20Pedra%20Bela%20-%20Parque%20Nacional%20Peneda-Ger%C3%AAs.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Miradouro%20da%20Pedra%20Bela%20-%20Parque%20Nacional%20Peneda-Ger%C3%AAs.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Miradouro%20da%20Pedra%20Bela%202-%20Parque%20Nacional%20Peneda-Ger%C3%AAs.jpg"}'::text[], 8),
    (v_route, 'Sortelha', 'Jedna z nejlépe dochovaných středověkých vesnic Portugalska, obehnaná kamennými hradbami a korunovaná hradem na skalním výběžku. Žulové domy působí, jako by čas zůstal stát ve 13. století. Je to ideální klidné místo na zakončení okruhu a procházku uličkami mezi obřími balvany.', 40.3276, -7.24, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sortelha%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sortelha%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castelo%20de%20Sortelha%20-%20Portugal%20(4112989372).jpg"}'::text[], 9);
