  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Diga del Vajont', 'Ikonická obloukovitá přehrada zaklíněná v úzké soutěsce pod horou Monte Toc. Právě zde 9. října 1963 sesuv půdy vyvolal ničivou vlnu, přehrada však jako stavba katastrofu přežila a stojí dodnes. Pro motorkáře nezapomenutelná zastávka — silnice se k ní vine sérií tunelů a serpentin s dechberoucími výhledy do hloubky. Zaparkujte, projděte se po koruně přehrady a vnímejte tíhu tohoto místa.', 46.26722, 12.32833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Diga%20del%20Vajont%20da%20Longarone%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Diga%20del%20Vajont%20da%20Longarone%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Diga%20del%20Vajont%20.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/V19%20Diga%20del%20Vajont.jpg"}'::text[], 0),
    (v_route, 'Longarone – památník obětem 1963', 'Město Longarone bylo v roce 1963 vlnou z Vajontu téměř srovnáno se zemí a přišlo o většinu svých obyvatel. Dnes zde stojí moderní kostel a hřbitov obětí ve Fortogně s tisíci hroby, který připomíná rozsah tragédie. Klidné místo vhodné k zastavení a poklonění se památce zemřelých. Odtud také vede silnice vzhůru k přehradě.', 46.26361, 12.30028, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cimitero%20Vajont%20prima.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cimitero%20Vajont%20prima.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cappella%20Votiva%20Vittime%20del%20Vajont.jpg"}'::text[], 1),
    (v_route, 'Casso', 'Horská vesnička přilepená ke svahu vysoko nad přehradou, která zázrakem přežila katastrofu, ačkoli ji vlna přehnaná přes hráz zasáhla. Úzké kamenné uličky a strmé domky nabízejí pohled na život v odlehlém friulském horském kraji. Přístupová silnice je úzká a strmá — pěkná technická vsuvka pro zkušenější motorkáře. Výhledy na jezero a údolí Vajontu jsou odsud jedny z nejlepších.', 46.27083, 12.36389, 'https://commons.wikimedia.org/wiki/Special:FilePath/V62%20Lago%20del%20Vajont.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/V62%20Lago%20del%20Vajont.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/V63%20Lago%20del%20Vajont.jpg"}'::text[], 2),
    (v_route, 'Erto', 'Staré jádro obce Erto zůstalo po katastrofě z velké části opuštěné a dnes tvoří působivé, tiché muzeum pod širým nebem. Zachovalé středověké domy, prázdné uličky a kostel sv. Bartoloměje vypovídají o osudu údolí. Vesnice leží na scénické silnici SS251 vedoucí k jezeru Barcis. Ideální místo na kávu a procházku před další etapou.', 46.26667, 12.37639, 'https://commons.wikimedia.org/wiki/Special:FilePath/Erto%20Centro.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Erto%20Centro.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chiesa%20di%20San%20Bartolomeo%20Apostolo%20(Erto,%20Erto%20e%20Casso)%2001.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Vajont Ristora (Erto)', 'Příjemná zastávka přímo na trase u silnice SS251 poblíž přehrady, s prostornou terasou a výhledem do údolí Vajontu. Kuchyně sází na místní friulské speciality — nářezy, sýry a proslulé frico s polentou. Na Googlu má skvělé hodnocení 4,6 hvězdy a hosté chválí vstřícnou obsluhu i pohodovou atmosféru. Ideální místo na oběd či kávu uprostřed okruhu.', 46.26805, 12.35361, 'https://commons.wikimedia.org/wiki/Special:FilePath/Erto%20Centro.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Erto%20Centro.jpg"}'::text[], 4),
    (v_route, 'Cimolais', 'Klidná horská obec na okraji přírodního parku Dolomiti Friulane, vstupní brána do divokých dolin Val Cimoliana. Okolní silnice jsou málo frekventované a lemované lesy a skalními štíty — pravá pastva pro milovníky zatáček. Skvělá zastávka na doplnění paliva a odpočinek uprostřed trasy. V okolí najdete i slavný přírodní útvar Campanile di Val Montanaia a masiv Monte Duranno.', 46.28972, 12.43417, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monte%20Duranno%20-%20Cimolais%20(PN).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monte%20Duranno%20-%20Cimolais%20(PN).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Forcella%20Savalons%20Bregolina%20Grande%20-%20Cimolais%20(PN).jpg"}'::text[], 5),
    (v_route, 'Barcis', 'Malebné městečko na břehu tyrkysově zeleného umělého jezera v srdci Valcelliny. Silnice podél jezera a soutěskou Forra del Cellina patří k nejkrásnějším úsekům celé trasy — vysoké skalní stěny, tunely a smaragdová voda. Ideální místo na oběd s výhledem na hladinu. Odtud pokračujte serpentinami dál do Dolomit.', 46.18944, 12.55639, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20di%20Barcis%20(Barcis%20Lake).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20di%20Barcis%20(Barcis%20Lake).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20di%20Barcis%20-%20Riserva%20Naturale%20Forra%20del%20Cellina.jpg"}'::text[], 6),
    (v_route, 'Passo Duran', 'Horské sedlo ve výšce 1601 m spojující údolí Cordevole a Zoldano, s úzkými technickými serpentinami a horskou útulnou u vrcholu. Provoz bývá minimální, povrch místy hrubý, ale odměnou jsou úchvatné výhledy na masiv Civetty a Moiazzy. Perfektní zakončení jízdy pro ty, kdo mají rádi klikaté horské pruhy. Ve výšce může být chladno, přibalte si teplejší vrstvu.', 46.32615, 12.09714, 'https://commons.wikimedia.org/wiki/Special:FilePath/Abendstimmung%20am%20Passo%20Duran.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Abendstimmung%20am%20Passo%20Duran.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Passo%20Duran.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Duranpas0.jpg"}'::text[], 7);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Sorrento', 'Sorrento je ideální startovní bod celé trasy a poslední místo s velkými parkovišti a benzínkami před úzkou SS163. Vychutnejte si výhled z útesů na Neapolský záliv a Vesuv, než nasednete na motorku. Zásobte se vodou a natankujte doplna, protože dál na pobřeží je zastávek málo.', 40.62375, 14.38096, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sorrento%20Sedile%20Dominova%20BW%202013-05-12%2014-10-51.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sorrento%20Sedile%20Dominova%20BW%202013-05-12%2014-10-51.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Marina%20Grande,%20Sorrento.jpg"}'::text[], 0),
    (v_route, 'Positano', 'Positano je fotogenické městečko nalepené na svahu, jehož barevné domky klesají až k moři. Jednosměrný okruh úzkými uličkami vás provede kolem kostela Santa Maria Assunta s barevnou kupolí. Motorka je tu obrovská výhoda - zaparkujete tam, kde auta nemají šanci.', 40.62829, 14.48427, 'https://commons.wikimedia.org/wiki/Special:FilePath/Positano%20panorama%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Positano%20panorama%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Positano-Amalfi%20Coast-Italy.jpg"}'::text[], 1),
    (v_route, 'Fiordo di Furore', 'Fjord Furore je dramatická soutěska, přes kterou se klene vysoký kamenný most - jeden z nejikoničtějších záběrů celé SS163. Pod vámi se skrývá malá pláž vklíněná mezi skalní stěny. Zastavte opatrně, prostor je stísněný a provoz na mostě hustý, ale výhled stojí za to.', 40.61436, 14.55453, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fiordo%20di%20Furore.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fiordo%20di%20Furore.JPG"}'::text[], 2),
    (v_route, 'Praiano', 'Praiano je klidnější a méně turistická alternativa k Positanu, oblíbená kvůli nádherným západům slunce. Kostel San Gennaro s majolikovou dlažbou a terasa s výhledem na pobřeží nabízí příjemnou pauzu. Provoz je tu o něco snesitelnější, dobré místo na oddech mezi serpentinami.', 40.6111, 14.5313, 'https://commons.wikimedia.org/wiki/Special:FilePath/Praiano%20-%20The%20Amalfi%20Coast%20-%20Church%20of%20San%20Gennaro.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Praiano%20-%20The%20Amalfi%20Coast%20-%20Church%20of%20San%20Gennaro.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/San%20Gennaro%2001.jpg"}'::text[], 3),
    (v_route, 'Amalfi', 'Amalfi je srdcem pobřeží, které dalo trase jméno, s velkolepou katedrálou svatého Ondřeje a strmým schodištěm na náměstí Piazza del Duomo. Je to dobré místo na oběd a kávu, ale počítejte s davy a obtížným parkováním. Motorku zaparkujte u přístavu a centrum projděte pěšky.', 40.634, 14.60268, 'https://commons.wikimedia.org/wiki/Special:FilePath/Amalfi%20-%20Duomo%20di%20Sant''Andrea.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Amalfi%20-%20Duomo%20di%20Sant''Andrea.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Amalfi%20-%20Duomo%20di%20Sant%27Andrea%203.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Da Gemma (Amalfi)', 'Da Gemma je legendární rodinná restaurace v srdci Amalfi, jen pár kroků od katedrály svatého Ondřeje, fungující nepřetržitě od roku 1872. Kuchyně staví na čerstvých mořských plodech a tradiční kampánské kuchyni - vyhlášené jsou paccheri s rybím ragú i pokrmy s místními citrony. Restaurace je hodnocena kolem 4,4 a doporučovaná průvodcem Michelin, což z ní dělá ideální zastávku na oběd zhruba v polovině trasy.', 40.63417, 14.60289, 'https://commons.wikimedia.org/wiki/Special:FilePath/Amalfi%20-%20Duomo%20di%20Sant''Andrea.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Amalfi%20-%20Duomo%20di%20Sant''Andrea.jpg"}'::text[], 5),
    (v_route, 'Ravello', 'Ravello leží vysoko nad Amalfi a odbočka nahoru je odměnou v podobě klidnější klikaté silnice s úchvatnými výhledy. Zahrady Villa Rufolo nabízejí jeden z nejslavnějších pohledů na pobřeží z výšky. Stoupání i klesání je náročné na brzdy, jeďte s rozvahou.', 40.64919, 14.61171, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ravello%20Villa%20Rufolo.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ravello%20Villa%20Rufolo.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Villa%20Rufolo%20Ravello%2018.JPG"}'::text[], 6),
    (v_route, 'Vietri sul Mare', 'Vietri sul Mare je východní brána Amalfského pobřeží, proslulá barevnou keramikou, kterou najdete v každém obchůdku. Odtud SS163 přechází do okolí Salerna, takže je to přirozený bod obratu. Doplňte palivo a připravte se na návrat přes hory.', 40.66794, 14.72787, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vietri%20sul%20Mare.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vietri%20sul%20Mare.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vietri%20sul%20mare%20(01).jpg"}'::text[], 7),
    (v_route, 'Valico di Chiunzi', 'Horský průsmyk Valico di Chiunzi je skvělou vnitrozemskou spojkou pro návrat bez použití dálnice - klikatá silnice stoupá nad údolí Tramonti. Z vrcholu se otevírá panoráma až k Vesuvu a Neapolskému zálivu na jedné straně a k pobřeží na druhé. Prázdné zatáčky tady bývají odměnou po hustém provozu dole u moře.', 40.43083, 14.37083, 'https://commons.wikimedia.org/wiki/Special:FilePath/Percorso%20dal%20valico%20di%20Chiunzi%20al%20Monte%20Finestra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Percorso%20dal%20valico%20di%20Chiunzi%20al%20Monte%20Finestra.jpg"}'::text[], 8);
  insert into public.routes
