  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Etna – Rifugio Sapienza', 'Horská chata ve výšce 1910 m n. m. na jižním svahu Etny je klasickým startem i cílem okruhu. Odtud vede lanovka a terénní vozy až k vrcholovým kráterům a kolem se rozkládají černá lávová pole z nedávných erupcí. Pro motorkáře je to skvělé místo na zahřátí, kávu a fotku s kouřícím vrcholem v pozadí. Silnice sem vede po klikatých serpentinách bez jediného metru dálnice.', 37.70054, 14.99839, 'https://commons.wikimedia.org/wiki/Special:FilePath/Etna%20-%20rifugio%20Sapienza.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Etna%20-%20rifugio%20Sapienza.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rifugio%20Sapienza-Etna.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Etna%20-%20Rifugio%20Sapienza.jpg"}'::text[], 0),
    (v_route, 'Nicolosi', 'Městečko zvané „brána Etny" leží na jižním úpatí sopky a je oblíbenou zastávkou před výjezdem nahoru. Najdete tu příjemné náměstí, řadu kaváren a nedaleké kužely Monti Rossi z historické erupce roku 1669. Ideální místo na doplnění paliva a lehké občerstvení. Okolní silnice nabízejí plynulé zatáčky lemované vinicemi a sadmi.', 37.61583, 15.02778, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nicolosi%20at%20the%20Foot%20of%20Mount%20Etna%20(24409722454).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nicolosi%20at%20the%20Foot%20of%20Mount%20Etna%20(24409722454).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cimitero%20di%20Nicolosi.JPG"}'::text[], 1),
    (v_route, 'Zafferana Etnea', 'Klidné horské město na východním svahu Etny proslulé medem a výhledy do údolí Valle del Bove. Kostel Santa Maria delle Grazie na hlavním náměstí stojí za krátkou zastávku. Cesta sem po SP92 patří k nejhezčím úsekům okruhu s pohledy na moře i na sopku. Dálnicím se zde motorkář zcela vyhne.', 37.679, 15.1043, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zafferana%20Etnea,%20Catania,%20Sicily,%20Italy%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zafferana%20Etnea,%20Catania,%20Sicily,%20Italy%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chiesa%20Santa%20Maria%20delle%20Grazie%20(Zafferana).jpg"}'::text[], 2),
    (v_route, 'Randazzo', 'Nejlépe dochované středověké město na severním úpatí Etny, postavené z tmavé sopečné lávy. Uličky s kostely San Martino a Santa Maria Assunta působí jako z jiného století. Leží nejblíže vrcholovým kráterům ze všech měst kolem sopky, přesto zůstalo erupcemi ušetřeno. Skvělá zastávka na oběd na půli cesty okruhu.', 37.87788, 14.95074, 'https://commons.wikimedia.org/wiki/Special:FilePath/Randazzo''s%20San%20Martino%20church.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Randazzo''s%20San%20Martino%20church.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Randazzo,%20Via%20degli%20Archi.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Randazzo,%20Catania,%20Sicily,%20Italy.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Ristorante Da Antonio (Randazzo)', 'Vyhlášená restaurace šéfkuchaře Antonia Fucileho na SS120 u Randazza, přesně na půli cesty okruhu, ideální na oběd. Kuchyně staví na sicilských tradicích s moderním pojetím – nechybí pistácie z Bronte, černé prasata z Nebrodi ani místní černý lanýž a stovka etnských vín. Na Tripadvisoru má skvělé hodnocení 4,8 z 5, rezervace je vřele doporučena.', 37.874, 14.98, 'https://commons.wikimedia.org/wiki/Special:FilePath/Randazzo,%20Catania,%20Sicily,%20Italy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Randazzo,%20Catania,%20Sicily,%20Italy.jpg"}'::text[], 4),
    (v_route, 'Gole dell''Alcantara', 'Úchvatná soutěska, kterou řeka Alcantara vyhloubila do sloupcovitých čedičových lávových stěn. Strmé černé kaňony s ledově studenou vodou vytvářejí jedno z nejfotogeničtějších přírodních míst na Sicílii. Pro motorkáře je to vítané osvěžení a protažení nohou uprostřed trasy. Přístupová silnice od Randazza vede malebným údolím podél řeky.', 37.87911, 15.17525, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gole%20dell''Alcantara-pjt1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gole%20dell''Alcantara-pjt1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gole%20Alcantara,%20Catania,%20Sicily.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Alcantara-Schlucht.jpg"}'::text[], 5),
    (v_route, 'Taormina', 'Slavné pobřežní město na útesu s antickým řecko-římským divadlem, odkud se otevírá pohled na moře i na Etnu v pozadí. Úzké uličky, elegantní obchody a panoramatické terasy patří k nejkrásnějším na ostrově. Příjezd po serpentinách od pobřeží je pro motorkáře zážitek sám o sobě. Doporučujeme zaparkovat pod městem a zbytek projít pěšky.', 37.8536, 15.2885, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20del%20Teatro%20Greco%20di%20Taormina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20del%20Teatro%20Greco%20di%20Taormina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mt%20Etna%20and%20Taormina%20as%20seen%20from%20the%20Ancient%20Theatre%20of%20Taormina%20(22290641726).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Taormina-Teatro%20Greco01.JPG"}'::text[], 6),
    (v_route, 'Castelmola', 'Maličká horská víska nad Taorminou ve výšce 436 m n. m., korunovaná zbytky hradu s nejkrásnějším panoramatem celého okruhu. Odtud shlédnete najednou Taorminu, pobřeží Jónského moře i kouřící vrchol Etny. Silnice nahoru je úzká a plná ostrých serpentin, jízda ale stojí za každou zatáčku. Ideální finální zastávka před návratem k Rifugio Sapienza.', 37.85904, 15.27804, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castelmola%20-%20Panorama%20del%20borgo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castelmola%20-%20Panorama%20del%20borgo.jpg"}'::text[], 7);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Trollstigen', 'Legendární horská silnice s jedenácti ostrými serpentinami stoupá strmě do výšky přes 850 metrů a patří k nejslavnějším motocyklovým cestám Norska. Úzké zatáčky, sklon až 10 % a vodopád Stigfossen padající přes silnici vyžadují plnou koncentraci a klidné plynulé řazení. Nahoře je vyhlídková plošina, kde stojí za to zastavit a nechat brzdy vychladnout. Cesta je průjezdná jen v letní sezoně, mimo ni bývá kvůli sněhu uzavřená.', 62.4564, 7.6576, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trollstigen%20viewpoint.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trollstigen%20viewpoint.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Trollstigen%20Norwegen.jpg"}'::text[], 0),
    (v_route, 'Gudbrandsjuvet', 'Úzká a hluboká rokle, kterou se v peřejích prořezává řeka Valldøla, leží přímo u silnice Fv63 mezi Trollstigenem a Valldalem. Moderní ocelové lávky a vyhlídkové plošiny umožňují pohled do soutěsky z bezpečné výšky. Pro motorkáře je to ideální krátká zastávka na protažení a focení. Parkoviště je hned u cesty, takže sesednutí zabere jen pár minut.', 62.33076, 7.47113, 'https://commons.wikimedia.org/wiki/Special:FilePath/2012-07%20Gudbrandsjuvet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2012-07%20Gudbrandsjuvet.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2012-07%20Gudbrandsjuvet2.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Jordbærstova (Valldal)', 'Tradiční norská restaurace u silnice Fv63 mezi Valldalem a Trollstigenem, proslulá dezerty z místních jahod z Valldalu. Nabízí domácí norskou kuchyni, jahodový dort a sezonní buffet s lososem i sobím masem. Podnik je na TripAdvisoru hodnocen jako nejlepší restaurace ve Valldalu a drží Certifikát excelence, takže je to ideální zastávka na oběd v půlce trasy.', 62.2841, 7.3286, 'https://commons.wikimedia.org/wiki/Special:FilePath/Strawberry%20field%20near%20Valldal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Strawberry%20field%20near%20Valldal.jpg"}'::text[], 2),
    (v_route, 'Ørnevegen / Ørnesvingen', 'Takzvaná Orlí cesta stoupá jedenácti serpentinami od hladiny Geirangerfjordu až do výšky přes 600 metrů. Z nejvyšší zatáčky se otevírá jeden z nejfotografovanějších pohledů na fjord a vodopád Sedm sester. Serpentiny jsou dobře zpevněné, ale v sezoně bývají plné aut a autobusů, proto jeďte předvídavě. Vyhlídka u horní zatáčky je povinná zastávka každého motocyklisty.', 62.2887, 7.2754, 'https://commons.wikimedia.org/wiki/Special:FilePath/Geirangerfjorden%20from%20%C3%98rnesvingen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Geirangerfjorden%20from%20%C3%98rnesvingen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C3%98rnevegen.JPG"}'::text[], 3),
    (v_route, 'Geirangerfjord', 'Geirangerfjord je zapsán na seznamu UNESCO a patří k nejúchvatnějším fjordům světa díky strmým stěnám a vodopádům padajícím přímo do vody. Vesnice Geiranger na jeho konci je přirozeným místem k přenocování a doplnění paliva. Odsud vedou dvě parádní vyhlídkové trasy – na Dalsnibbu a přes Ørnevegen. Pro motorkáře je to srdce celé cesty a ideální bod pro rozdělení trasy na dva dny.', 62.10145, 7.2062, 'https://commons.wikimedia.org/wiki/Special:FilePath/GeirangerFjord.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/GeirangerFjord.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Geirangerfjord%20(6-2007).jpg"}'::text[], 4),
    (v_route, 'Restaurace: Brasserie Posten (Geiranger)', 'Oblíbená restaurace v historické budově bývalé pošty přímo u břehu Geirangerfjordu. Skandinávská kuchyně staví na místních surovinách – rybí polévka, čerstvé mořské plody, sobí maso i místní sýry a piva. S hodnocením 4,5 z 5 na Google i TripAdvisoru patří k nejlépe hodnoceným podnikům v Geirangeru a je skvělou volbou na večeři na konci druhé etapy.', 62.101, 7.2058, 'https://commons.wikimedia.org/wiki/Special:FilePath/GeirangerFjord.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/GeirangerFjord.jpg"}'::text[], 5),
    (v_route, 'Dalsnibba', 'Placená horská cesta Nibbevegen vás vyveze až do výšky 1500 metrů, odkud je nejvyšší silniční výhled na fjord v Evropě. Vyhlídková plošina Geiranger Skywalk nabízí panorama fjordu, jezera Djupvatnet a okolních štítů. Cesta je úzká, bez svodidel a i v létě zde může ležet sníh, proto jeďte opatrně a teple oblečení. Otevřeno je pouze v letní sezoně, mimo ni je vjezd uzavřen.', 62.0563, 7.2818, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dalsnibba%3B%20Blick%20auf%20Geiranger%201%20Norwegen.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dalsnibba%3B%20Blick%20auf%20Geiranger%201%20Norwegen.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dalsnibba,%20Geiranger,%20Norway%2020170527%20181455.jpg"}'::text[], 6),
    (v_route, 'Åndalsnes', 'Åndalsnes na břehu Romsdalsfjordu je přirozenou vstupní branou k Trollstigenu a bývá výchozím bodem celé trasy. Ve městě natankujete, seženete nocleh i občerstvení před náročnou horskou jízdou. Okolní hory a údolí Romsdalen dělají z tohoto místa fotogenický start dobrodružství. Vede sem i železnice Raumabanen, takže je snadno dostupné.', 62.56749, 7.68709, 'https://commons.wikimedia.org/wiki/Special:FilePath/Romsdalsfjorden%20with%20%C3%85ndalsnes.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Romsdalsfjorden%20with%20%C3%85ndalsnes.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C3%85ndalsnes%20stasjon%20og%20hamn.jpg"}'::text[], 7),
    (v_route, 'Trollveggen', 'Trollská stěna je nejvyšší vertikální skalní stěna v Evropě s převýšením přes 1000 metrů a tyčí se nad údolím Romsdalen. Návštěvnické centrum u cesty E136 kousek od Åndalsnesu nabízí dechberoucí pohled vzhůru na hřebeny a věže. Pro motorkáře je to krátká zastávka cestou k Trollstigenu. Ve špatném počasí bývá vrchol schovaný v mracích, což dodává místu tajemnou atmosféru.', 62.4858, 7.7236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trollveggen%202002%20June.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trollveggen%202002%20June.jpg"}'::text[], 8),
    (v_route, 'Flydalsjuvet', 'Flydalsjuvet je slavná vyhlídka jen pár kilometrů nad Geirangerem směrem na Grotli. Odsud pochází ikonický záběr na fjord s výběžkem skály v popředí a vesnicí hluboko dole. Zastávka je snadno dostupná přímo u silnice a nabízí ideální místo na odpočinek a focení. Za dobré viditelnosti je výhled na Geirangerfjord naprosto nezapomenutelný.', 62.0893, 7.2236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Flydalsjuvet%20Geiranger.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Flydalsjuvet%20Geiranger.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/View%20to%20Geiranger%20from%20Flydalsjuvet,%202013%20June.jpg"}'::text[], 9),
    (v_route, 'Valldal', 'Valldal je klidná vesnice u fjordu Norddalsfjord, známá pěstováním jahod a jako místo, odkud vyplouvá trajekt Linge–Eidsdal. Je to přirozený bod k přenocování mezi Trollstigenem a Geirangerem. Z blízkého trajektového přístaviště pokračuje trasa dál po Fv63 k Ørnevegenu. Kolem cesty najdete občerstvení i palivo před další etapou fjordové jízdy.', 62.3029, 7.2461, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sylte%20kyrkje%20Valldal.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sylte%20kyrkje%20Valldal.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Strawberry%20field%20near%20Valldal.jpg"}'::text[], 10);
  insert into public.routes
