  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Molde panorama', '„Město růží“ s proslulým panoramatem 222 zasněžených vrcholů táhnoucích se za fjordem. Nejlepší výhled je z rekreační oblasti Moldemarka nad městem. Skvělé místo pro start nebo zakončení jízdy s velkolepým rozhledem na Romsdalské Alpy.', 62.73752, 7.15912, 'https://commons.wikimedia.org/wiki/Special:FilePath/MoldePana.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/MoldePana.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Romsdalsgata,%20Molde.jpg"}'::text[], 0),
    (v_route, 'Bud', 'Malebná rybářská vesnice na výběžku Romsdalu, obrácená k drsnému moři Hustadvika. Dřevěné přístavní domky a molo dýchají pravou atmosférou norského pobřeží. Ideální zastávka na kávu a procházku, než se vydáš dál po pobřežní silnici směrem k Atlantické cestě.', 62.90713, 6.91403, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sj%C3%B8hus,%20Bud.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sj%C3%B8hus,%20Bud.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bud-2-HH-08.JPG"}'::text[], 1),
    (v_route, 'Kårvåg', 'Malá vesnička na ostrově Averøy, kde Atlantická cesta začíná svůj nejúchvatnější úsek. Najdeš tu odpočívadlo, informace a možnost doplnit síly před přejezdem řetězu mostů. Klidné místo pro krátkou zastávku a první výhled na otevřené moře.', 63.01372, 7.44487, 'https://commons.wikimedia.org/wiki/Special:FilePath/BP%20K%C3%A5rv%C3%A5g%20-%20SAS2015-05-183.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/BP%20K%C3%A5rv%C3%A5g%20-%20SAS2015-05-183.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Bjartmars Favorittkro (Kårvåg)', 'Útulná mořská hospůdka přímo na Atlantické cestě u Kårvågu na ostrově Averøy, přesně v půli trasy mezi Molde a Kristiansundem. Kuchyně staví na místních rybách – proslulá je zdejší bacalao (klippfisk), která zde získala hned několik ocenění za nejlepší v kraji. S hodnocením kolem 4,5 hvězdy a terasou s výhledem na moře je to ideální zastávka na oběd uprostřed jízdy.', 63.0148, 7.4406, 'https://commons.wikimedia.org/wiki/Special:FilePath/BP%20K%C3%A5rv%C3%A5g%20-%20SAS2015-05-183.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/BP%20K%C3%A5rv%C3%A5g%20-%20SAS2015-05-183.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Atlanterhavsveien.jpg"}'::text[], 3),
    (v_route, 'Storseisundetský most (Storseisundbrua)', 'Nejdelší a nejslavnější z osmi mostů Atlantické cesty, 260 metrů dlouhá konzolová konstrukce s prudkým obloukem. Z určitého úhlu vypadá, jako by silnice končila ve vzduchu – proto se mu přezdívá „opilý most“. Pro motorkáře je to naprostý vrchol trasy, ale pozor na boční nárazy větru a mokrý povrch na vrcholu oblouku.', 63.01693, 7.35515, 'https://commons.wikimedia.org/wiki/Special:FilePath/Storseisundbrua%20-%20Atlanterhavsveien.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Storseisundbrua%20-%20Atlanterhavsveien.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Atlanterhavsveien,%20Storseisundet%20bru.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Storseisundbrua,%20West%20view%2020150604%201.jpg"}'::text[], 4),
    (v_route, 'Håholmen', 'Historický rybářský ostrůvek nedaleko Atlantické cesty, dnes chráněná osada s rustikálním ubytováním. V sezoně sem jezdí loďka z odpočívadla na ostrově Geitøya. Krásné místo na fotku a nadechnutí historie starého mořeplaveckého života.', 63.02937, 7.39362, 'https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A5holmen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A5holmen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A5holmen%20IW1.jpg"}'::text[], 5),
    (v_route, 'Eldhusøya (vyhlídka)', 'Odpočívadlo na ostrůvku obtočené 700 metrů dlouhou vznášející se lávkou s 360° výhledem na oceán. Moderní servisní budova s kavárnou splývá s krajinou. Ideální zastávka pro protažení nohou, kávu a fotky bouřlivého Atlantiku.', 63.0181, 7.3116, 'https://commons.wikimedia.org/wiki/Special:FilePath/Route%20de%20l''Atlantique%20en%20norv%C3%A8ge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Route%20de%20l''Atlantique%20en%20norv%C3%A8ge.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Atlantic%20Highway,%20Norway.jpg"}'::text[], 6),
    (v_route, 'Kristiansund', 'Živé přístavní město rozložené na několika ostrovech, tradiční centrum sušené tresky (klippfisk). Storkaia s nábřežím a rušným přístavem je příjemným cílem celodenní jízdy. Skvělé místo na jídlo, přenocování nebo jen posezení u vody po dni v sedle.', 63.11045, 7.72795, 'https://commons.wikimedia.org/wiki/Special:FilePath/Storkaia%20Kristiansund.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Storkaia%20Kristiansund.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jonas%20Eriksen%20brygga%20Kristiansund.JPG"}'::text[], 7);
