  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Strömsund', 'Klidné městečko na břehu jezerní soustavy Ströms Vattudal je přirozeným startem i cílem celého okruhu. Najdete tu poslední spolehlivé čerpací stanice, obchody i kavárny, takže je ideální doplnit nádrž a nakoupit zásoby před vjezdem do divočiny. Symbolem města je elegantní visutý most Strömsundsbron z roku 1956. Než vyrazíte, projeďte se pomalu podél vody a nasajte severskou atmosféru.', 63.85167, 15.55824, 'https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%B6msundsbron%202010.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%B6msundsbron%202010.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%B6msundsbron1.jpg"}'::text[], 0),
    (v_route, 'Hällingsåfallet', 'Dramatický vodopád padající do jednoho z nejdelších kaňonů severní Evropy je povinná zastávka hned v první části trasy. Od parkoviště vede krátká procházka k vyhlídkám nad soutěskou, kde voda burácí v hloubce pod vámi. Za slunečného dne se v tříšti často tvoří duha. Nechte motorku odpočinout a protáhněte si nohy – stojí to za to.', 64.34901, 14.38422, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hallingsafall.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hallingsafall.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Regnb%C3%A5gar%20i%20H%C3%A4llings%C3%A5fallet.jpg"}'::text[], 1),
    (v_route, 'Gäddede', 'Poslední větší vesnice před nejdivočejší částí okruhu leží jen pár kilometrů od norské hranice. Je to dobré místo na kávu, doplnění paliva a poslední signál mobilního operátora na hodně dlouho. Okolní krajina se tu začíná měnit v opravdovou horskou divočinu. Doporučujeme vyrazit odsud s plnou nádrží.', 64.50279, 14.14614, 'https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%A4ddede%20-%20KMB%20-%2016000300030126.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%A4ddede%20-%20KMB%20-%2016000300030126.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Marsfjäll Mountain Lodge (Saxnäs / Klimpfjäll)', 'Horský penzion a restaurace u břehu jezera Kultsjön kousek za Klimpfjäll je ideální zastávkou na jídlo v nejsevernější části okruhu. Kuchyně sází na místní severské suroviny – od tradiční domácí stravy přes rybí speciality (siven) až po oblíbený burger z masa horského skotu. Restaurace má vynikající hodnocení kolem 4,6 z 5 a hosté chválí přátelský personál i skvělé jídlo v srdci fjällské divočiny.', 65.0742, 15.3585, 'https://commons.wikimedia.org/wiki/Special:FilePath/16001000018084-Kultsj%C3%B6n-Riksantikvarie%C3%A4mbetet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/16001000018084-Kultsj%C3%B6n-Riksantikvarie%C3%A4mbetet.jpg"}'::text[], 3),
    (v_route, 'Ankarede', 'Historické sámské a osadnické místo se dřevěnou kaplí u soutoku řek je jedním z nejklidnějších zákoutí celé trasy. Odedávna sem sámské rodiny přicházely na církevní slavnosti a dodnes tu stojí tradiční kåty. Zastavte, ztište motor a vnímejte ticho hor a vody. Krátká procházka mezi chatkami vás vrátí o staletí zpět.', 64.9, 14.47, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ankarede%20kapell.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ankarede%20kapell.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ankarede%20kapell%20-%20KMB%20-%2016000300023972.jpg"}'::text[], 4),
    (v_route, 'Stora Blåsjön', 'Horská osada u tyrkysového jezera je oblíbené místo k přespání zhruba v polovině okruhu. Nabízí ubytování, kemp a výhledy na okolní vrcholy zrcadlící se v hladině. Odsud silnice začíná stoupat k náhorní plošině Stekenjokk. Skvělé místo, kde si dát pauzu a nabrat síly na nejnáročnější úsek.', 64.85, 14.28, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ankarede,%20Stor-Bl%C3%A5sj%C3%B6n%20and%20Ankarvattnet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ankarede,%20Stor-Bl%C3%A5sj%C3%B6n%20and%20Ankarvattnet.jpg"}'::text[], 5),
    (v_route, 'Stekenjokk – vyhlídka', 'Průsmyk Stekenjokk v nadmořské výšce kolem 876 metrů je nejvýše položená veřejná silnice ve Švédsku a absolutní vrchol celé cesty. Jedete tu otevřenou tundrou nad hranicí lesa, obklopeni holými kopci, jezírky a často i stády sobů. Silnice bývá kvůli sněhu otevřená jen přibližně od června do října, proto sem míří jen letní jezdci. Počasí se mění během minut, takže si vezměte vrstvu navíc a užijte si nekonečné výhledy.', 65.06556, 14.46, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vildmarksv%C3%A4gen%20Stekenjokk%20Klimpfj%C3%A4ll.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vildmarksv%C3%A4gen%20Stekenjokk%20Klimpfj%C3%A4ll.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vy%20fr%C3%A5n%20Stekenjokk%20gruvan%20fr%C3%A5n%20h%C3%B6ger%20sida%20av%20v%C3%A4gen.jpg"}'::text[], 6),
    (v_route, 'Klimpfjäll', 'Poslední horská vesnice na severním konci trasy, odkud se stáčíte zpět na jih k domovu. Leží pod horou Autjoklimpen a je oblíbeným výchozím bodem pro turisty i lyžaře. V létě tu najdete klid, čistý horský vzduch a poslední výhledy na vrcholky před sestupem do lesů. Doplňte palivo, pokud můžete – následuje dlouhá cesta zpět do Strömsundu.', 65.06, 14.8, 'https://commons.wikimedia.org/wiki/Special:FilePath/Klimpfj%C3%A4ll%20from%20Autjoklimpen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Klimpfj%C3%A4ll%20from%20Autjoklimpen.jpg"}'::text[], 7);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Rovaniemi – polární kruh a Santa Claus Village', 'Brána do Laponska a symbolický start celé cesty přímo na polárním kruhu. Vyfoťte motorku u vytyčené čáry v Santa Claus Village, doplňte palivo i zásoby — dál na sever už to bude řídké. Odsud vede silnice E75 na sever klidnou krajinou bez dálnic.', 66.54366, 25.84762, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rovaniemi%20Santa%20Claus.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rovaniemi%20Santa%20Claus.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rovaniemi%209.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rovaniemi%207.JPG"}'::text[], 0),
    (v_route, 'Sodankylä', 'Historické laponské městečko s dřevěným Starým kostelem z roku 1689, jedním z nejstarších ve finském Laponsku. Ideální zastávka na kávu a protažení nohou zhruba v polovině prvního dne. Silnice sem i dál je široká, plynulá a téměř prázdná.', 67.41639, 26.58917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sodankyl%C3%A4%20vanha%20kirkko.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sodankyl%C3%A4%20vanha%20kirkko.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sodankyl%C3%A4%20old%20church.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sodankyl%C3%A4n%20vanha%20kirkko.jpg"}'::text[], 1),
    (v_route, 'Saariselkä', 'Turistické středisko na okraji fjellů, výborná základna pro nocleh po prvním dni jízdy. Najdete tu ubytování, restaurace i čerpací stanici. Okolní kopcovitá tundra nabízí první opravdové laponské panoramata.', 68.4198, 27.4123, 'https://commons.wikimedia.org/wiki/Special:FilePath/Saarisel%C3%A4n%20kyl%C3%A4.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Saarisel%C3%A4n%20kyl%C3%A4.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Saariselk%C3%A4%20view.JPG"}'::text[], 2),
    (v_route, 'Restaurace: Laanilan Kievari (Saariselkä)', 'Rodinná zvěřinová restaurace v Laanile jen 2 km jižně od Saariselkä přímo u silnice E75 (Rovaniementie). S hodnocením 4,7 je dlouhodobě nejlépe hodnocenou restaurací v okolí — gurmánská kuchyně z místních surovin s lehkým francouzským nádechem v útulném srubu. Ideální zastávka na oběd či večeři na konci prvního dne cesty.', 68.399, 27.437, 'https://commons.wikimedia.org/wiki/Special:FilePath/Saarisel%C3%A4n%20kyl%C3%A4.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Saarisel%C3%A4n%20kyl%C3%A4.jpg"}'::text[], 3),
    (v_route, 'Národní park Urho Kekkonen', 'Jedna z největších divočin Evropy — holé fjelly, řeky a bezmezné pláně tundry. Motorku necháte na parkovišti a vyrazíte pěšky po značených stezkách za tichem a výhledy. Skvělý bod pro odpočinek od sedla a nadechnutí arktické přírody.', 68.29, 27.75, 'https://commons.wikimedia.org/wiki/Special:FilePath/Parc-urho-kekkonen.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Parc-urho-kekkonen.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lapland%20-%20Urho%20Kekkonen%20National%20Park%20-%2020180728171740.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/River%20Lutto%20in%20Urho%20Kekkonen%20National%20Park%2C%20Sodankyl%C3%A4%20(July%202018).jpg"}'::text[], 4),
    (v_route, 'Inari a jezero Inarijärvi', 'Třetí největší finské jezero s tisíci ostrůvky a posvátné místo sámské kultury. Klidná silnice E75 kopíruje břeh a nabízí jeden fotogenický výhled za druhým. Nocleh v Inari je ideální pro druhý den cesty.', 68.906, 27.0288, 'https://commons.wikimedia.org/wiki/Special:FilePath/Inari%20lake.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Inari%20lake.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Inari%2C%20Suomi%20-%20Finland%202013-03-10%20Inarij%C3%A4rvi%20snowmobile%20e.jpg"}'::text[], 5),
    (v_route, 'Muzeum Siida', 'Národní muzeum Sámů a středisko severolaponské přírody přímo v obci Inari. Skvělé místo, kde pochopíte kulturu původních obyvatel a arktickou přírodu, kterou celou cestu projíždíte. Ideální zastávka za deště nebo pro odpočinkové dopoledne.', 68.9023, 27.0294, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sami%20Museum%20Siida.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sami%20Museum%20Siida.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Siida%20museum%20facade%20Inari%20Finland%202009-10-01b.jpg"}'::text[], 6),
    (v_route, 'Kilpisjärvi a fjell Saana', 'Nejsevernější a nejzápadnější cíp Finska pod majestátním fjellem Saana, kde se stýkají hranice tří států. Cesta sem po silnici E8 patří k nejkrásnějším úsekům celé pouti — holé hory a jezera bez jediné dálnice. Počítejte s dlouhým, ale nezapomenutelným přejezdem.', 69.0167, 20.8167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Finnish%20national%20road%2021%20%26%20Saana%2C%20Ala-Kilpisj%C3%A4rvi.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Finnish%20national%20road%2021%20%26%20Saana%2C%20Ala-Kilpisj%C3%A4rvi.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/View%20from%20saana.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Aurora%20borealis%20over%20Saana%20fell.jpg"}'::text[], 7),
    (v_route, 'Restaurace: NiliPoro (Levi)', 'Nejlépe hodnocená restaurace v Levi (4,5, #1 z desítek podniků) přímo v centru střediska. Sámská rodinná pororavintola, kde majitel a chovatel sobů podává vše z vlastního stáda — pravé laponské sobí maso od guláše po kýtu. Skvělá zastávka na večeři po dlouhém přejezdu ze severozápadu na závěr cesty.', 67.80412, 24.80732, 'https://commons.wikimedia.org/wiki/Special:FilePath/Levi%20gondoli%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Levi%20gondoli%201.JPG"}'::text[], 8),
    (v_route, 'Levi', 'Největší lyžařské a rekreační středisko Finska pod fjellem Levitunturi, plné služeb, restaurací i ubytování. Vhodná zastávka na poslední noc před návratem. V létě tu ožívají cyklostezky a vyhlídky do širokého okolí.', 67.80402, 24.80818, 'https://commons.wikimedia.org/wiki/Special:FilePath/Levi%20gondoli%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Levi%20gondoli%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gondola%20in%20Levi%2C%20Finland.jpg"}'::text[], 9),
    (v_route, 'Národní park Pallas-Yllästunturi', 'Řetěz fjellů s údajně nejčistším vzduchem v Evropě a jeden z nejstarších finských národních parků. Silnice 79 a okolní tahy vedou fotogenickou krajinou tunturi, ideální na závěrečnou jízdu poutě. Zastavte se na vyhlídce Pallastunturi a rozlučte se s Laponskem.', 68.05, 24.06, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pallas-Yll%C3%A4stunturi%20National%20Park%20(25719399914).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pallas-Yll%C3%A4stunturi%20National%20Park%20(25719399914).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pallastunturi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Taivaskero%20%26%20Pyh%C3%A4kero%2C%20Pallastunturi.JPG"}'::text[], 10);
  insert into public.routes
