  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Þingvellir NP', 'Národní park zapsaný na seznamu UNESCO, kde se rozestupují severoamerická a euroasijská tektonická deska. Projížďka kaňonem Almannagjá je zážitek sama o sobě a parkoviště je jen kousek od nejzajímavějších skalních trhlin. Ideální první zastávka na okruhu s dostatkem místa pro motorky. Nechte si čas na krátkou procházku k vyhlídce nad údolím.', 64.25548, -21.12977, 'https://commons.wikimedia.org/wiki/Special:FilePath/Almannagj%C3%A1%20gorge,%20%C3%9Eingvellir%20National%20Park.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Almannagj%C3%A1%20gorge,%20%C3%9Eingvellir%20National%20Park.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Thingvellir%20Iceland%202005.JPG"}'::text[], 0),
    (v_route, 'Þingvallavatn', 'Největší přírodní jezero Islandu leží přímo v riftovém údolí u parku Þingvellir. Silnice č. 36 podél jeho břehů nabízí nádherné plynulé zatáčky s výhledem na hladinu a okolní sopky. Skvělé místo na krátkou zastávku a foto s motorkou u vody. Za jasného počasí se v jezeře zrcadlí okolní hory.', 64.18333, -21.15, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%9Eingvallavatn.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%9Eingvallavatn.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20del%20lago%20%C3%9Eingvallavatn%20desde%20el%20observatorio%20Hakid,%20Su%C3%B0urland,%20Islandia,%202014-08-16,%20DD%20003.JPG"}'::text[], 1),
    (v_route, 'Geysir (Strokkur)', 'Geotermální pole Haukadalur, kde gejzír Strokkur vystřeluje vodu do výšky až 20 metrů zhruba každých pár minut. U silnice je velké parkoviště i benzínka a kavárna, což se na motorce hodí na doplnění paliva i kávy. Nezapomeňte dodržovat značené cesty, pára a vroucí voda jsou opravdu horké. Perfektní zastávka v polovině okruhu.', 64.31039, -20.30232, 'https://commons.wikimedia.org/wiki/Special:FilePath/Strokkur%20geyser%20eruption,%20close-up%20view.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Strokkur%20geyser%20eruption,%20close-up%20view.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Strokkur,%20%C3%81rea%20geot%C3%A9rmica%20de%20Geysir,%20Su%C3%B0urland,%20Islandia,%202014-08-16,%20DD%20089.JPG"}'::text[], 2),
    (v_route, 'Gullfoss', 'Mohutný dvoustupňový vodopád „Zlaté vodopády“ padající do hluboké soutěsky řeky Hvítá je vrcholem celého okruhu. Od parkoviště je to k vyhlídkám jen pár kroků, počítejte ale s vodní tříští, takže si nechte helmu i bundu po ruce. Za slunečného dne se nad vodopádem často klene duha. Nejzazší bod trasy, odkud se stáčíte zpět k Reykjavíku.', 64.32707, -20.11995, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gullfoss,%20an%20iconic%20waterfall%20of%20Iceland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gullfoss,%20an%20iconic%20waterfall%20of%20Iceland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gullfoss,%20Su%C3%B0urland,%20Islandia,%202014-08-16,%20DD%20123.JPG"}'::text[], 3),
    (v_route, 'Faxi vodopád', 'Široký a klidný vodopád Faxi (Vatnsleysufoss) na řece Tungufljót leží stranou davů jen kousek od hlavní trasy. Je to příjemná a nenáročná zastávka s parkovištěm hned u silnice č. 35. Skvělé místo na svačinu a odpočinek mimo turistický ruch. V řece bývá vidět rybí přechod pro lososy.', 64.22547, -20.33725, 'https://commons.wikimedia.org/wiki/Special:FilePath/Faxifoss%20waterfall,%20Iceland%202013.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Faxifoss%20waterfall,%20Iceland%202013.JPG"}'::text[], 4),
    (v_route, 'Restaurace: Efstidalur II (Laugarvatn)', 'Rodinná farma a restaurace přímo na Zlatém okruhu u silnice č. 37, ideální na oběd zhruba v polovině trasy. Kuchyně staví na vlastních surovinách z farmy – proslulé jsou hovězí burgery a steaky i domácí zmrzlina a skyr z mléka zdejších krav. Podnik má skvělé hodnocení (Tripadvisor 4,6 z 5, #1 v Laugarvatni) a jídelnou lze koukat přímo do kravína.', 64.23306, -20.42472, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20del%20lago%20%C3%9Eingvallavatn%20desde%20el%20observatorio%20Hakid,%20Su%C3%B0urland,%20Islandia,%202014-08-16,%20DD%20003.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20del%20lago%20%C3%9Eingvallavatn%20desde%20el%20observatorio%20Hakid,%20Su%C3%B0urland,%20Islandia,%202014-08-16,%20DD%20003.JPG"}'::text[], 5),
    (v_route, 'Skálholt', 'Historické biskupské sídlo a jedno z nejvýznamnějších kulturních center Islandu s bílým kostelem uprostřed zvlněné krajiny. Odbočka ze silnice č. 35 je krátká a klidná, ideální na oddech od jízdy. Z místa je za dobrého počasí vidět sopka Hekla. Tichá a nenáročná zastávka s historií.', 64.12532, -20.52414, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hekla%20Volcano%20behind%20Skaholt%20Cathedral%20(30913419367).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hekla%20Volcano%20behind%20Skaholt%20Cathedral%20(30913419367).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2017-08-17%20Iceland,%20Golden%20Circle,%20Sk%C3%A1lholtskirkju,%20Exterior%20(01)%20(freddy2001).jpg"}'::text[], 6),
    (v_route, 'Kerið kráter', 'Sopečný kráter s výrazně tyrkysovým jezírkem a červenohnědými svahy je poslední velkou zastávkou před návratem do Reykjavíku. Parkoviště je přímo u silnice č. 35 a okruh kolem okraje kráteru zabere jen pár minut. Kontrast barev vody, mechu a lávy je fotograficky vděčný. Skvělé zakončení celého okruhu.', 64.04127, -20.88531, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keri%C3%B0%20crater%20lake,%20Iceland%20-%20Eric%20Marchese.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Keri%C3%B0%20crater%20lake,%20Iceland%20-%20Eric%20Marchese.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Keri%C3%B0,%20volcanic%20crater%20lake%20in%20Iceland%20(24078210408).jpg"}'::text[], 7);
