  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Grenen (Skagen)', 'Nejsevernější bod Dánska, kde se za bílého příboje setkávají Severní moře (Skagerrak) a Baltské moře (Kattegat). Zaparkuj u vstupu a projdi se po písečné kose až na samotný cíp – auta a motorky sem nesmí, jde se pěšky nebo lze svézt tzv. Sandormenem. Ideální místo na start okruhu za východu slunce, kdy je pobřeží klidné a světlo nejlepší.', 57.73977, 10.6418, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grenen,%20Skagen,%20Dinamarca,%202019-09-09,%20DD%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grenen,%20Skagen,%20Dinamarca,%202019-09-09,%20DD%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grenen%20from%20the%20air.jpg"}'::text[], 0),
    (v_route, 'Den Tilsandede Kirke', 'Zaváté kostel svatého Vavřince ze 14. století, z něhož nad písečnými dunami dnes ční už jen bílá věž. Loď kostela pohltil vátý písek a v 18. století musel být opuštěn. Vede sem krátká procházka borovým lesem od parkoviště – příjemná zastávka hned po odjezdu ze Skagenu.', 57.71364, 10.55061, 'https://commons.wikimedia.org/wiki/Special:FilePath/Den%20tilsandede%20kirke%2002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Den%20tilsandede%20kirke%2002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Skagen%20Versandete%20Kirche%2006.JPG"}'::text[], 1),
    (v_route, 'Råbjerg Mile', 'Největší putující duna severní Evropy, která se vlivem větru posouvá až o 15–18 metrů ročně. Z parkoviště se na její vrchol vystoupá pěšky a odměnou je panorama písečné pouště uprostřed Jutska. Vezmi si pevnou obuv – po měkkém písku se v moto botách chodí ztěžka, ale výhled stojí za to.', 57.6422, 10.4037, 'https://commons.wikimedia.org/wiki/Special:FilePath/190DK%20R%C3%A5bjerg%20Mile%20(14952866030).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/190DK%20R%C3%A5bjerg%20Mile%20(14952866030).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/191DK%20R%C3%A5bjerg%20Mile%20(14953358538).jpg"}'::text[], 2),
    (v_route, 'Rubjerg Knude Fyr', 'Slavný maják z roku 1900 stojící na vysokém útesu nad Severním mořem, který byl kvůli postupující erozi v roce 2019 přesunut o 70 metrů do vnitrozemí. Od parkoviště se jde přes duny asi 20–30 minut pěšky. Dramatické místo s obrovskými písečnými přesypy a nekonečným výhledem na moře – jedno z nejfotogeničtějších míst trasy.', 57.443, 9.7718, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rubjerg%20Knude%20Fyr,%20Hj%C3%B8rring,%20Denmark,%201807072231,%20ako.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rubjerg%20Knude%20Fyr,%20Hj%C3%B8rring,%20Denmark,%201807072231,%20ako.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rubjerg%20Knude%20Fyr,%20Hj%C3%B8rring,%20Denmark.jpg"}'::text[], 3),
    (v_route, 'Lønstrup', 'Idylická stará rybářská vesnice na pobřeží Skagerraku s malými galeriemi, kavárnami a dílnami. Úzké uličky a domky u pláže lákají na klidnou zastávku na oběd nebo kávu. Odsud je to jen kousek k pobřežnímu útesu Lønstrup Klint s výhledem na moře.', 57.4684, 9.798, 'https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%B8nstrup%20Coast%2020160529%20ubt.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%B8nstrup%20Coast%2020160529%20ubt.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%B8nstrup%20Klint%20Rubjerg%20Knude%202019.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Abstrakt (Hirtshals)', 'Oceňovaná restaurace v přístavu Hirtshals ve století staré bývalé dílně s výhledem na moře, kde vaří ze sezonních místních ryb a zeleniny v moderním severském duchu. Hosté ji milují za nápadité menu a mimořádnou obsluhu – na Googlu má skvělé hodnocení kolem 4,8 hvězdy. Ideální zastávka na oběd či časnou večeři zhruba v polovině okruhu před závěrečnou jízdou do Aalborgu.', 57.5945, 9.9578, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skibe%20i%20Hirtshals%20havn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skibe%20i%20Hirtshals%20havn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hafen%20Hirtshals,%20D%C3%A4nemark%20IMG%203215WI.jpg"}'::text[], 5),
    (v_route, 'Hirtshals', 'Rušný přístavní městečko s trajekty do Norska a na Island a s výrazným majákem Hirtshals Fyr z roku 1863. Najdeš tu i akvárium Nordsøen Oceanarium, jedno z největších v severní Evropě. Skvělé místo na pauzu s čerstvými rybami a pohledem na přístav před závěrečným úsekem do Aalborgu.', 57.5881, 9.9592, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hirtshals%20Fyr%202015.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hirtshals%20Fyr%202015.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hirtshals-fyr-%C3%B8st.JPG"}'::text[], 6),
    (v_route, 'Aalborg', 'Cíl okruhu – živé severojutské město na břehu Limfjordu s upraveným nábřežím, moderním Utzon Center a historickým centrem. Ideální na večerní procházku a jídlo po celém dni v sedle. Do Aalborgu dojedeš po pobřežních a venkovských silnicích, opět bez nutnosti použít dálnici.', 57.048, 9.9187, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aalborg%20Havnefront%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aalborg%20Havnefront%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aalborg%202010%20-%20125%20ubt.JPG"}'::text[], 7);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Inverness', 'Inverness je hlavní město Vysočiny a přirozený start i cíl celého okruhu NC500. Tady natankuješ, dokoupíš vybavení a naposledy si užiješ větší město před dny v divočině. Nezapomeň, že odtud už tě čeká jízda vlevo po stále užších silnicích.', 57.47908, -4.22398, 'https://commons.wikimedia.org/wiki/Special:FilePath/Inverness%20Castle,%20Scotland%20-%20Diliff.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Inverness%20Castle,%20Scotland%20-%20Diliff.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panoramic%20view%20of%20Inverness.jpg"}'::text[], 0),
    (v_route, 'Bealach na Bà', 'Bealach na Bà, tedy Průsmyk dobytka, je nejnáročnější horský přejezd celé Británie – z hladiny moře vystoupá na 626 metrů serpentinami s prudkými serpentinami. Pro motorkáře je to vrchol NC500, ale úzká single-track silnice a horské počasí vyžadují maximální soustředění. Jeď pomalu, respektuj výhybny a protijedoucí vozidla.', 57.4263, -5.7515, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bealach%20na%20Ba%20Pano.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bealach%20na%20Ba%20Pano.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bealach%20na%20Ba%20Viewpoint%20(32637651377).jpg"}'::text[], 1),
    (v_route, 'Applecross', 'Malebná osada Applecross leží hned za sjezdem z průsmyku a odměňuje unavené jezdce klidnou zátokou s výhledem na ostrov Skye. Místní hospoda Applecross Inn je legendární zastávkou na jídlo a přenocování. Ideální místo na první nocleh a nabrání sil.', 57.43241, -5.81686, 'https://commons.wikimedia.org/wiki/Special:FilePath/Applecross-Jetty.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Applecross-Jetty.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Applecross%20Inn%20-%20panoramio.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Applecross Inn (Applecross)', 'Applecross Inn je proslulá přímořská hospoda hned u zátoky, kterou milují motorkáři i gurmáni. Kuchyně staví na čerstvých mořských plodech z místních vod – langustinky, hřebenatky, ústřice i ryba s hranolky patří ke stálicím. Restaurace sbírá skvělá hodnocení a ocenění a je jednou z nejlepších rybích zastávek na celé NC500.', 57.43241, -5.81686, 'https://commons.wikimedia.org/wiki/Special:FilePath/Applecross%20Inn%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Applecross%20Inn%20-%20panoramio.jpg"}'::text[], 3),
    (v_route, 'Torridon', 'Torridon patří mezi nejdramatičtější horské scenérie Skotska – prastaré pískovcové hory se zvedají přímo nad mořský záliv Loch Torridon. Silnice podél jezera nabízí jednu zastávku na fotku za druhou. Skvělé místo protáhnout záda a nadechnout se čerstvého highlandského vzduchu.', 57.5462, -5.5048, 'https://commons.wikimedia.org/wiki/Special:FilePath/Scotland%20Torridon%20village.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Scotland%20Torridon%20village.jpg"}'::text[], 4),
    (v_route, 'Ullapool', 'Ullapool je živé přístavní městečko na břehu Loch Broom a největší sídlo na západní části trasy. Najdeš tu benzínu, restaurace i ubytování, takže je to ideální základna pro přenocování. Odsud vyplouvá i trajekt na Vnější Hebridy.', 57.89588, -5.15887, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ullapool%20harbour.%20-%20geograph.org.uk%20-%204649432.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ullapool%20harbour.%20-%20geograph.org.uk%20-%204649432.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ullapool%20harbour%20at%20low%20water%20-%20geograph.org.uk%20-%205989216.jpg"}'::text[], 5),
    (v_route, 'Restaurace: The Seafood Shack (Ullapool)', 'The Seafood Shack je oblíbený pouliční stánek s mořskými plody, který dvě místní ženy proměnily v jednu z nejlépe hodnocených restaurací celé Vysočiny. Menu se mění podle denního úlovku – ústřice, ručně sbírané hřebenatky, langusty i čerstvá ryba. Díky vynikajícím hodnocením a férovým cenám je to ideální zastávka na oběd v půli západního pobřeží.', 57.89588, -5.15887, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ullapool%20harbour%20at%20low%20water%20-%20geograph.org.uk%20-%205989216.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ullapool%20harbour%20at%20low%20water%20-%20geograph.org.uk%20-%205989216.jpg"}'::text[], 6),
    (v_route, 'Lochinver', 'Rybářská vesnička Lochinver leží pod výraznou horou Suilven a je proslulá svými masovými koláči (pies). Cesta sem po klikaté silnici B869 patří k nejzábavnějším úsekům pro motorkáře. Dej si pauzu, občerstvi se a užij si výhledy na zálivy.', 58.14671, -5.24549, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trawler%20at%20Lochinver%20Harbour%20-%20geograph.org.uk%20-%201018140.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trawler%20at%20Lochinver%20Harbour%20-%20geograph.org.uk%20-%201018140.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Culag%20Hotel%20in%20Lochinver%20-%20geograph.org.uk%20-%201022625.jpg"}'::text[], 7),
    (v_route, 'Achmelvich', 'Achmelvich ukrývá jednu z nejkrásnějších pláží Skotska s bílým pískem a tyrkysovou vodou, která vypadá spíš jako Karibik. Přístupová single-track silnička je úzká, ale odměna za odbočku stojí za to. Skvělé místo na krátkou procházku a fotky.', 58.1668, -5.3076, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sunset,%20Achmelvich%20Beach%20-%20geograph.org.uk%20-%20364193.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sunset,%20Achmelvich%20Beach%20-%20geograph.org.uk%20-%20364193.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vestey''s%20beach,%20Achmelvich.jpg"}'::text[], 8),
    (v_route, 'Kylesku most', 'Elegantní obloukový most Kylesku překlenuje záliv Loch a'' Chàirn Bhàin a patří k nejfotogeničtějším stavbám celé NC500. Zakřivená konstrukce vypadá skvěle na fotkách i při průjezdu na motorce. Zastav na parkovišti a vychutnej si výhled na okolní hory a moře.', 58.25675, -5.02124, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kylesku%20bridge%20surroundings.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kylesku%20bridge%20surroundings.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kylesku%20Bridge%20in%20the%20Summer%20-%20geograph.org.uk%20-%20521622.jpg"}'::text[], 9),
    (v_route, 'Durness', 'Durness je nejsevernější vesnice na západě trasy a brána k mysu Cape Wrath. Najdeš tu pláže, útesy i řemeslnou vesničku Balnakeil Craft Village. Dobré místo natankovat a přenocovat před nejodlehlejším úsekem okruhu.', 58.5677, -4.7456, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sango%20Island%20-%20geograph.org.uk%20-%20341175.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sango%20Island%20-%20geograph.org.uk%20-%20341175.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20entrance%20to%20Balnakeil%20Craft%20Village,%20Durness%20-%20geograph.org.uk%20-%202496901.jpg"}'::text[], 10),
    (v_route, 'Smoo Cave', 'Smoo Cave je impozantní mořská a sladkovodní jeskyně hned u silnice východně od Durness. Uvnitř se ukrývá vodopád, k němuž vede lávka, a vstup je zdarma. Rychlá a působivá zastávka přímo na trase NC500.', 58.5578, -4.7187, 'https://commons.wikimedia.org/wiki/Special:FilePath/Entrance%20to%20Smoo%20Cave.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Entrance%20to%20Smoo%20Cave.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Durness%20Smoo%20Youth%20Hostel.jpg"}'::text[], 11),
    (v_route, 'Cape Wrath', 'Cape Wrath je nejsevernější západní cíp Británie s osamělým majákem a divokým útesovým pobřežím. Na motorce sem přímo nedojedeš – nutný je minitrajekt přes ústí řeky a poté minibus, protože jde o vojenský prostor. Přesto je to nezapomenutelný výlet do skutečné divočiny.', 58.62766, -4.99958, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Wrath%20lighthouse.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Wrath%20lighthouse.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Wrath%20Lighthouse%20-%20geograph.org.uk%20-%20821653.jpg"}'::text[], 12),
    (v_route, 'John o'' Groats', 'John o'' Groats je symbolický nejsevernější cíp britské pevniny a slavné místo se směrovníkem, kam si musí každý motorkář udělat fotku. Odsud je to nejdál k Land''s End na jihu Anglie. Turistická, ale povinná zastávka celého okruhu.', 58.6431, -3.0697, 'https://commons.wikimedia.org/wiki/Special:FilePath/John%20o''%20Groats.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/John%20o''%20Groats.JPG"}'::text[], 13),
    (v_route, 'Duncansby Head', 'Duncansby Head je skutečný severovýchodní cíp pevniny s majákem a dramatickými skalními jehlami Duncansby Stacks. Krátká odbočka od John o'' Groats sem nabízí mnohem divočejší a autentičtější scenérii. Nech motorku u majáku a projdi se po útesech.', 58.6433, -3.0229, 'https://commons.wikimedia.org/wiki/Special:FilePath/Duncansby%20Head%20lighthouse.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duncansby%20Head%20lighthouse.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Duncansby-Stacks.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Duncansby%20Stacks%20from%20near%20Duncansby%20Head%20car%20park%20-%20geograph.org.uk%20-%202126053.jpg"}'::text[], 14),
    (v_route, 'Dunrobin Castle', 'Dunrobin Castle připomíná francouzský pohádkový zámek s věžičkami a rozlehlými zahradami nad mořem. Na zpáteční cestě podél východního pobřeží je to elegantní kontrast k divočině severu. Konají se tu i ukázky sokolnictví.', 57.98269, -3.9457, 'https://commons.wikimedia.org/wiki/Special:FilePath/DunrobinCastle1.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/DunrobinCastle1.JPG"}'::text[], 15),
    (v_route, 'Wick', 'Wick je historické přístavní město v Caithness, kdysi světové centrum lovu sleďů. Najdeš tu služby, ubytování i muzeum a nedaleké zříceniny Castle of Old Wick. Poslední větší zastávka před závěrečným úsekem zpět do Inverness.', 58.4388, -3.0937, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wick%20Caithness%20Scottish%20Highlands.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wick%20Caithness%20Scottish%20Highlands.jpg"}'::text[], 16);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Pen-y-Pass (průsmyk Llanberis)', 'Nejvyšší bod průsmyku Llanberis ve výšce 359 m, kde silnice A4086 stoupá mezi skalními stěnami hor Glyderau a masivu Snowdon. Pro motorkáře je to jeden z nejdramatičtějších úseků celého okruhu – klikaté serpentiny, výhledy do údolí a časté zastávky horolezců. Parkoviště bývá plné, přijeďte proto brzy. Nezapomeňte, že se jede vlevo a silnice je úzká.', 53.08064, -4.02048, 'https://commons.wikimedia.org/wiki/Special:FilePath/Llanberis%20Pass%20-%20geograph.org.uk%20-%20748386.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Llanberis%20Pass%20-%20geograph.org.uk%20-%20748386.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rock%20face%20in%20Llanberis%20Pass.jpg"}'::text[], 0),
    (v_route, 'Snowdon / Yr Wyddfa', 'Nejvyšší hora Walesu (1085 m) a dominanta celého národního parku Eryri. Z sedla je vidět její vrchol i historickou horskou železnici vedoucí až na summit. Motorkáři horu obkružují po silnicích a mají ji na dohled z většiny okruhu. Ideální místo pro zastávku a fotografii výhledu.', 53.06857, -4.07622, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bwlch%20Glas%20from%20the%20summit%20of%20Yr%20Wyddfa-Snowdon%20-%20geograph.org.uk%20-%20275057.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bwlch%20Glas%20from%20the%20summit%20of%20Yr%20Wyddfa-Snowdon%20-%20geograph.org.uk%20-%20275057.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Snowdon%20Summit%20View.jpg"}'::text[], 1),
    (v_route, 'Llyn Gwynant', 'Malebné horské jezero v údolí Nant Gwynant podél silnice A498, obklopené strmými svahy a loukami. Cesta kolem něj patří k nejfotogeničtějším částem okruhu, s plynulými zatáčkami a výhledy na vodní hladinu. Skvělé místo na krátkou zastávku a nadechnutí horského vzduchu. Pozor na úzkou vozovku a turisty u břehu.', 53.0522, -4.0169, 'https://commons.wikimedia.org/wiki/Special:FilePath/Llyn%20Gwynant.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Llyn%20Gwynant.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Llyn%20Gwynant%20-%20geograph.org.uk%20-%20464153.jpg"}'::text[], 2),
    (v_route, 'Beddgelert', 'Kouzelná kamenná vesnička na soutoku řek Glaslyn a Colwyn, často označovaná za nejhezčí ves Snowdonie. Najdete tu kavárny, hospůdky a legendu o věrném psu Gelertovi. Ideální zastávka na oběd nebo kávu uprostřed okruhu. Úzké uličky a mostek přes řeku dávají místu neopakovatelnou atmosféru.', 53.0071, -4.1015, 'https://commons.wikimedia.org/wiki/Special:FilePath/River%20Glaslyn,%20Beddgelert%20-%20geograph.org.uk%20-%20992059.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/River%20Glaslyn,%20Beddgelert%20-%20geograph.org.uk%20-%20992059.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Beddgelert%20Bridge,%20North%20Wales(112209).jpg"}'::text[], 3),
    (v_route, 'Restaurace: Bistro Hebog (Beddgelert)', 'Útulné bistro a kavárna přímo v centru Beddgelertu, ideální zastávka na oběd v půlce okruhu. Nabízí čerstvou lokální kuchyni – od domácích jídel po skvělou kávu a dezerty. Patří k nejlépe hodnoceným podnikům v okolí (na Tripadvisoru kolem 4,7 hvězdičky a #1 v Beddgelertu), v létě láká i venkovní posezení.', 53.0104, -4.1006, 'https://commons.wikimedia.org/wiki/Special:FilePath/River%20Glaslyn,%20Beddgelert%20-%20geograph.org.uk%20-%20992059.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/River%20Glaslyn,%20Beddgelert%20-%20geograph.org.uk%20-%20992059.jpg"}'::text[], 4),
    (v_route, 'Capel Curig', 'Horská vesnice na křižovatce silnic A5 a A4086, oblíbená mezi horolezci a turisty jako brána k Snowdonu. Z okolí se otevírá jeden z nejslavnějších výhledů na Yr Wyddfa zrcadlící se v jezírkách. Pro motorkáře příjemná zastávka s výhledem a možností občerstvení. Odsud pokračuje trasa po klasické silnici A5.', 53.10615, -3.91236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Snowdon%20from%20Capel%20Curig.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Snowdon%20from%20Capel%20Curig.jpg"}'::text[], 5),
    (v_route, 'Betws-y-Coed', 'Živé turistické městečko zvané brána Snowdonie, obklopené lesy a řekami s historickými mosty jako Pont-y-Pair. Nabízí spoustu kaváren, obchodů a nejvýchodnější bod okruhu. Skvělé místo na delší pauzu, doplnění paliva a procházku podél řeky Llugwy. Provoz zde bývá hustší, jeďte opatrně.', 53.09382, -3.80668, 'https://commons.wikimedia.org/wiki/Special:FilePath/Betws-y-coed,%20Pont-y-Pair%20Bridge%20-%20geograph.org.uk%20-%203606393.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Betws-y-coed,%20Pont-y-Pair%20Bridge%20-%20geograph.org.uk%20-%203606393.jpg"}'::text[], 6),
    (v_route, 'Swallow Falls (Rhaeadr Ewynnol)', 'Nejnavštěvovanější vodopád Walesu na řece Llugwy, jen kousek západně od Betws-y-Coed podél silnice A5. Kaskády se ženou mezi balvany a mechem porostlými skalami – zvlášť působivé po deštích. Přímo u silnice je placené parkoviště a krátká stezka k vyhlídce. Ideální rychlá zastávka mezi jízdou.', 53.0928, -3.823, 'https://commons.wikimedia.org/wiki/Special:FilePath/Swallow%20Falls%20Betws-y-Coed%20-%20geograph.org.uk%20-%201015874.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Swallow%20Falls%20Betws-y-Coed%20-%20geograph.org.uk%20-%201015874.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Swallow%20Falls,%20Betws-y-coed,%20North%20Wales%20-%20geograph.org.uk%20-%20881133.jpg"}'::text[], 7),
    (v_route, 'Llyn Ogwen', 'Mělké ledovcové jezero podél silnice A5 v údolí Ogwen, sevřené mezi pohořími Carneddau a Glyderau s dramatickou siluetou hory Tryfan. Jeden z nejfotogeničtějších úseků okruhu s dlouhými plynulými zatáčkami podél vody. Výborné místo na zastávku a fotku hor odrážejících se v hladině. Vozovka je úzká a v horách bývá vítr.', 53.12442, -4.00726, 'https://commons.wikimedia.org/wiki/Special:FilePath/Llyn%20Ogwen.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Llyn%20Ogwen.JPG"}'::text[], 8);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Národní park Killarney', 'Národní park Killarney je ideální startovní bod okruhu – rozlehlá jezera, dubové lesy a pohoří vytvářejí dechberoucí kulisu hned u města. Pro motorkáře je to skvělé místo na zahřátí, než se vydá na úzké pobřežní silnice. Pamatujte, že se v celém Irsku jezdí vlevo.', 52.02127, -9.50446, 'https://commons.wikimedia.org/wiki/Special:FilePath/Muckross%20Lake,%20Killarney%20(NBY%20438657).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Muckross%20Lake,%20Killarney%20(NBY%20438657).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lakes%20of%20killarney.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lush%20forest%20scenery%20in%20Killarney%20Park,%20Ireland.jpg"}'::text[], 0),
    (v_route, 'Gap of Dunloe', 'Gap of Dunloe je úzký horský průsmyk mezi masivy MacGillycuddy''s Reeks a Purple Mountain. Silnička je jednoproudá, klikatá a lemovaná jezírky a kamennými mostky, takže jezděte opatrně a počítejte s koňskými povozy i chodci. Odměnou je jedna z nejfotogeničtějších pasáží celého Kerry.', 52.0244, -9.63665, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gap%20of%20Dunloe%20by%20Bob%20Demuyser.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gap%20of%20Dunloe%20by%20Bob%20Demuyser.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gap%20of%20Dunloe%20Wishing%20Bridge.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kate%20Kearney''s%20Cottage%20-%20geograph.org.uk%20-%20781483.jpg"}'::text[], 1),
    (v_route, 'Ladies View', 'Ladies View je slavná vyhlídka na silnici N71 s panoramatem na Horní jezero a údolí národního parku. U vyhlídky je malé parkoviště i kavárna, kde si dáte pauzu a fotku. Zatáčky sem stoupají příjemně plynule a nabízejí skvělý výhled po celé cestě.', 51.96739, -9.59284, 'https://commons.wikimedia.org/wiki/Special:FilePath/Killarney%20National%20Park%20-%20Ladies%20View.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Killarney%20National%20Park%20-%20Ladies%20View.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Killarney-National-Park%20Ladies-View.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ladies%20View%20in%20summer,%20Ring%20of%20Kerry,%20Killarney%20National%20Park.jpg"}'::text[], 2),
    (v_route, 'Moll''s Gap', 'Moll''s Gap je horský průsmyk na silnici N71 mezi Kenmare a Killarney ve výšce zhruba 237 metrů. Serpentiny tu nabízejí nádherné výhledy na okolní hory a je zde oblíbená zastávka s obchůdkem a kavárnou. Pro motorkáře je to jedna z nejzábavnějších částí trasy s plynulými zatáčkami.', 51.94056, -9.65333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Road%20and%20Hillside%20before%20Molls%20Gap%20-%20geograph.org.uk%20-%2016041.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Road%20and%20Hillside%20before%20Molls%20Gap%20-%20geograph.org.uk%20-%2016041.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Avoca%20shop%20at%20Moll''s%20Gap%20-%20geograph.org.uk%20-%204669963.jpg"}'::text[], 3),
    (v_route, 'Sneem', 'Sneem je půvabná vesnička na poloostrově Iveragh, proslulá barevnými domky rozdělenými řekou do dvou náměstí. Je to skvělé místo na zastávku, kávu a protažení nohou uprostřed okruhu. Klidné okresní silnice sem vedou příjemně svižným tempem.', 51.83824, -9.89953, 'https://commons.wikimedia.org/wiki/Special:FilePath/Colourful%20buildings%20in%20South%20Square%20Sneem%20-%20geograph.org.uk%20-%202724880.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Colourful%20buildings%20in%20South%20Square%20Sneem%20-%20geograph.org.uk%20-%202724880.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sneem,%20Post%20Office%20and%20Sneem%20Tavern%20-%20geograph.org.uk%20-%205242043.jpg"}'::text[], 4),
    (v_route, 'Restaurace: D O''Sheas Bar (Sneem)', 'D O''Sheas Bar na North Square v Sneemu je tradiční irský pub s vynikající kuchyní – proslulý čerstvými mořskými plody a poctivými fish and chips. Na TripAdvisoru má skvělé hodnocení 4,5 hvězdičky a je označen jako nejlepší restaurace v Sneemu. Leží přesně v půli okruhu, takže je to ideální zastávka na vydatný oběd.', 51.8385, -9.8988, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sneem,%20Post%20Office%20and%20Sneem%20Tavern%20-%20geograph.org.uk%20-%205242043.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sneem,%20Post%20Office%20and%20Sneem%20Tavern%20-%20geograph.org.uk%20-%205242043.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Colourful%20buildings%20in%20South%20Square%20Sneem%20-%20geograph.org.uk%20-%202724880.jpg"}'::text[], 5),
    (v_route, 'Waterville', 'Waterville je pobřežní letovisko sevřené mezi Atlantikem a jezerem Lough Currane, kde kdysi trávil dovolenou Charlie Chaplin – jeho socha stojí na nábřeží. Silnice N70 tu vede přímo podél oceánu s výhledy na příboj. Ideální místo na oběd s výhledem na moře.', 51.8274, -10.172, 'https://commons.wikimedia.org/wiki/Special:FilePath/Waterville%20Est%C3%A1tua%20de%20Chaplin.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Waterville%20Est%C3%A1tua%20de%20Chaplin.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Statue%20de%20Charlie%20Chaplin%20%C3%A0%20Waterville.JPG"}'::text[], 6),
    (v_route, 'Portmagee (brána ke Skelligům)', 'Portmagee je malebná rybářská vesnička s řadou pestrobarevných domků podél přístavu a je hlavní branou k ostrovům Skellig. Odtud vyplouvají lodě k slavnému klášteru Skellig Michael, který znáte i z filmů Star Wars. Cesta sem vede přes most na ostrov Valentia a nabízí úžasné pobřežní výhledy.', 51.88543, -10.36194, 'https://commons.wikimedia.org/wiki/Special:FilePath/Portmagee%20Harbour.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Portmagee%20Harbour.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Portmagee%20harbour%2002.jpg"}'::text[], 7),
    (v_route, 'Kells Bay', 'Kells Bay House & Gardens ukrývá subtropickou zahradu s kapradinami a nejdelší lanový most v Irsku, to vše s výhledem na zátoku Dingle Bay. Silnice sem klesá úzkými zatáčkami k pobřeží, proto jeďte opatrně a vlevo. Je to klidnější zastávka mimo hlavní turistický proud.', 52.02281, -10.09971, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kells%20Bay.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kells%20Bay.jpg"}'::text[], 8),
    (v_route, 'Cahersiveen', 'Cahersiveen je hlavní městečko poloostrova Iveragh s výrazným kamenným kostelem a starou policejní kasárnou v podobě zámečku. Poblíž najdete i pravěké kamenné pevnosti Cahergall a Leacanabuaile. Dobré místo na doplnění paliva i občerstvení uprostřed západní části okruhu.', 51.94776, -10.2209, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cahersiveen%20Barracks.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cahersiveen%20Barracks.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Barracks%20Heritage%20Centre,%20Ring%20of%20Kerry,%20Cahersiveen%20(506514)%20(27865495445).jpg"}'::text[], 9),
    (v_route, 'Muckross House', 'Muckross House je viktoriánské sídlo s nádhernými zahradami na poloostrově mezi jezery Muckross a Lough Leane. Ke konci okruhu je to ideální klidná zastávka jen pár kilometrů od Killarney. Okolní cesty parkem jsou úzké a sdílené s koňskými povozy, proto jeďte pomalu.', 52.02127, -9.50446, 'https://commons.wikimedia.org/wiki/Special:FilePath/Muckross%20House-16-2017-gje.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Muckross%20House-16-2017-gje.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Killarney%20National%20Park%20-%20Muckross%20House.jpg"}'::text[], 10);
