  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Afsluitdijk', 'Monumentální 32 km dlouhá hráz z roku 1932 odděluje Waddenzee od jezera IJsselmeer a je bezkonkurenčním zážitkem pro motorkáře. Jedete po rovné lince mezi vodou po obou stranách a máte pocit, jako byste uháněli po moři. Zastavte se u pomníku inženýra Cornelise Lelyho a vyhlídkové věže s panoramatem. Vítr tu umí pořádně foukat, takže pevně držte řídítka.', 53.005, 5.1875, 'https://commons.wikimedia.org/wiki/Special:FilePath/De%20Afsluitdijk.%20ID510448.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/De%20Afsluitdijk.%20ID510448.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Afsluitdijk%20met%20standbeeld%20Lely.jpg"}'::text[], 0),
    (v_route, 'Nationaal Park De Hoge Veluwe', 'Rozlehlý národní park s vřesovišti, písečnými dunami a borovicovými lesy je oázou klidu uprostřed Nizozemska. Okolní vedlejší silnice nabízejí příjemné svezení stinnými lesy, kde často zahlédnete jeleny nebo divoká prasata. Uvnitř parku můžete přesednout na proslulá bílá kola zdarma. Skvělá zastávka na protažení a nadechnutí čerstvého lesního vzduchu.', 52.09815, 5.82922, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oude%20Dennenboom%20in%20Nationaal%20Park%20de%20Hooge%20Veluwe.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oude%20Dennenboom%20in%20Nationaal%20Park%20de%20Hooge%20Veluwe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sand%20Area%20Hoge%20Veluwe.jpg"}'::text[], 1),
    (v_route, 'Kröller-Müller Museum', 'Muzeum uvnitř parku Hoge Veluwe ukrývá druhou největší sbírku děl Vincenta van Gogha na světě. Největším lákadlem je ale rozlehlá socha park pod širým nebem, jeden z nejkrásnějších v Evropě. Motorku zaparkujete u vstupu a mezi sochami se pak toulkáte pěšky nebo na zapůjčeném kole. Ideální kulturní přestávka během jízdy krajinou Veluwe.', 52.0908, 5.8168, 'https://commons.wikimedia.org/wiki/Special:FilePath/Overzicht%20beeldentuin%20Kroller-Muller.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Overzicht%20beeldentuin%20Kroller-Muller.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Le%20grand%20K%20au%20KMM.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kroller%20muller%20museum.JPG"}'::text[], 2),
    (v_route, 'Giethoorn', 'Malebná vesnička zvaná benátky severu, kde místo silnic vedou úzké kanály a domky s doškovými střechami spojují dřevěné klenuté mostky. Auta ani motorky do centra nesmí, takže stroj necháte na parkovišti na okraji a dál pokračujete lodičkou nebo pěšky. Klidná atmosféra a odraz domků ve vodě jsou nezapomenutelné. Perfektní zastávka na oběd v přístavní restauraci.', 52.7372, 6.0732, 'https://commons.wikimedia.org/wiki/Special:FilePath/Netherlands,%20Giethoorn%20(02),%20tourism.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Netherlands,%20Giethoorn%20(02),%20tourism.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Giethoorn%20Netherlands%20Bovenwijde-01.jpg"}'::text[], 3),
    (v_route, 'Elburg', 'Dokonale zachované hanzovní opevněné městečko s pravoúhlým středověkým půdorysem ulic a hradbami s vodním příkopem. Dominantou je brána Vischpoort, bývalý maják u přístavu na jezeře Veluwemeer. Úzké uličky, staré cihlové domky a klidný přístav lákají k procházce. Skvělá klidná zastávka na kávu mimo turistický ruch větších měst.', 52.44927, 5.83452, 'https://commons.wikimedia.org/wiki/Special:FilePath/20221-Vispoort.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/20221-Vispoort.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Elburg%202014%20(74).JPG"}'::text[], 4),
    (v_route, 'Restaurace: Achter de Poorte (Elburg)', 'Elegantní restaurace ukrytá v historických hradbách Elburgu, kde šéfkuchař vaří jemnou francouzskou kuchyni výhradně z čerstvých denních surovin. Hosté chválí kreativní talíře, sladěná vína i vřelou obsluhu a na TripAdvisoru drží skvělé hodnocení 4,6 hvězdy. Ideální zastávka na oběd zhruba v polovině trasy, než vyrazíte dál na Veluwe.', 52.4489, 5.8342, 'https://commons.wikimedia.org/wiki/Special:FilePath/20221-Vispoort.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/20221-Vispoort.JPG"}'::text[], 5),
    (v_route, 'Kinderdijk', 'Skupina devatenácti historických větrných mlýnů z 18. století je zapsána na seznamu UNESCO a představuje nejikoničtější nizozemský obraz. Mlýny sloužily k odvodňování poldru Alblasserwaard a stojí seřazené podél kanálů. Podél hráze vede klidná vedlejší silnice a stezka, odkud máte mlýny jako na dlani. Nezapomenutelné místo na fotky vaší motorky s mlýny v pozadí.', 51.8857, 4.62744, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20windmills%20of%20Kinderdijk.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20windmills%20of%20Kinderdijk.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/KinderdijkMolens02.jpg"}'::text[], 6),
    (v_route, 'Zaanse Schans', 'Živý skanzen kousek od Amsterdamu s funkčními větrnými mlýny, zelenými dřevěnými domky a dílnami na výrobu sýra i dřeváků. Přiblížíte se po klidných silnicích podél řeky Zaan a stroj zaparkujete na hlídaném parkovišti u vstupu. Areál je volně přístupný a dýchá atmosférou 18. století. Vynikající tečka za celodenní poznávací jízdou před návratem.', 52.47346, 4.82028, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zaanse%20Schans%20-%20Windmills%203.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zaanse%20Schans%20-%20Windmills%203.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/3%20windmills.JPG"}'::text[], 7);
