  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'La Roche-en-Ardenne (hrad)', 'Feudální zřícenina z 11. století se tyčí na skalním ostrohu nad městečkem v zákrutu řeky Ourthe. Je to ideální start okruhu – z parkoviště pod hradem vyrazíte rovnou do údolních serpentin. Panorama města s věžemi hradu patří k nejfotografovanějším v Ardenách. Dejte si zde ranní kávu, než se vydáte po lesních silnicích na sever.', 50.1836, 5.5755, 'https://commons.wikimedia.org/wiki/Special:FilePath/0%20La%20Roche-en-Ardenne%20050518%20(8).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/0%20La%20Roche-en-Ardenne%20050518%20(8).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20La%20Roche-en-Ardenne%20050518%20(8).jpg"}'::text[], 0),
    (v_route, 'Durbuy', 'Durbuy bývá označováno za jedno z nejmenších měst na světě a jeho staré jádro z šedého kamene u řeky Ourthe je jako z pohádky. Úzké uličky, hrad a geologický anticlinal lákají k procházce i k zastávce na oběd. Silnice sem vede krásným zalesněným údolím bez jediného úseku dálnice. Parkování pro motorky najdete hned u vjezdu do historického centra.', 50.35306, 5.45604, 'https://commons.wikimedia.org/wiki/Special:FilePath/Durbuy%20-%20Le%20ch%C3%A2teau%20vu%20du%20sommet%20de%20l''Anticlinal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Durbuy%20-%20Le%20ch%C3%A2teau%20vu%20du%20sommet%20de%20l''Anticlinal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Durbuy%20met%20rivier%20L''%20Ourthe.jpg"}'::text[], 1),
    (v_route, 'Barrage de la Gileppe', 'Obloukovo-gravitační přehrada v Jalhay je proslulá obřím kamenným lvem, který stráží korunu hráze. Nabízí rozhlednu s výhledem na jezero obklopené smrkovými lesy a je vítanou zastávkou před příjezdem do Spa. Silnice kolem nádrže jsou svižné a málo frekventované. Ideální místo na protažení nohou a fotku motorky pod lvem.', 50.58731, 5.97112, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lion%20de%20la%20Gileppe%20by%20Niederkasseler%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lion%20de%20la%20Gileppe%20by%20Niederkasseler%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Soor%20-%20Barrage%20et%20tunnel%20vers%20la%20Gileppe%20(Baelen).jpg"}'::text[], 2),
    (v_route, 'Circuit de Spa-Francorchamps', 'Legendární závodní okruh v ardenských lesích je Mekkou každého motoristy díky ikonické stoupavé zatáčce Eau Rouge. I mimo závody stojí za to zastavit u vjezdu, nasát atmosféru a případně navštívit muzeum. Okolní veřejné silnice kopírují reliéf trati a nabízejí skvělé svahy a zatáčky. Pro motorkáře je to nezapomenutelný bod celého okruhu.', 50.44474, 5.96837, 'https://commons.wikimedia.org/wiki/Special:FilePath/2021%206%20Hours%20of%20Spa-Francorchamps%20-%20Raidillon.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2021%206%20Hours%20of%20Spa-Francorchamps%20-%20Raidillon.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Virage%20du%20Raidillon%20Spa%20Francorchamps.jpg"}'::text[], 3),
    (v_route, 'Coo (vodopád)', 'Vodopád Cascade de Coo na řece Amblève je nejvyšší přírodní vodopád Belgie a patří k nejnavštěvovanějším přírodním úkazům Arden. U vodopádu je zábavní park Plopsa a několik teras s občerstvením přímo nad padající vodou. Cesta sem vede úzkými údolními silnicemi lemovanými lesem. Skvělá zastávka na oběd nebo zmrzlinu uprostřed dne.', 50.39356, 5.87683, 'https://commons.wikimedia.org/wiki/Special:FilePath/Coo%20waterfall.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Coo%20waterfall.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Stavelot%20Cascade%20de%20Coo%2002.jpg"}'::text[], 4),
    (v_route, 'Bastogne (Mardasson)', 'Památník Mardasson připomíná 76 890 amerických vojáků padlých či raněných v bitvě v Ardenách během zimy 1944. Hvězdicovitý monument s výhledem do kraje je působivé místo k zamyšlení nad historií regionu. Samotné Bastogne je dobrým místem na tankování a pauzu. Přístupové silnice vedou otevřenou zvlněnou krajinou dál od hlavních tahů.', 50.00972, 5.73889, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mardasson%20Memorial%20Bastogne.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mardasson%20Memorial%20Bastogne.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bastogne%20M%C3%A9morial%20du%20Mardasson%20001.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Complètement Toqué (Bastogne)', 'Oblíbená francouzsko-belgická restaurace přímo na náměstí Place McAuliffe v centru Bastogne, ideální na oběd v polovině okruhu. Kuchyně staví na sezónních surovinách a poctivé regionální klasice servírované ve velkorysých porcích. Na TripAdvisoru drží skvělé hodnocení kolem 4,4 a patří k nejlépe hodnoceným podnikům ve městě.', 50.00323, 5.71778, 'https://commons.wikimedia.org/wiki/Special:FilePath/PLACE%20MCAULIFFE%20IN%20BASTOGNE%20BELGIUM.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/PLACE%20MCAULIFFE%20IN%20BASTOGNE%20BELGIUM.jpg"}'::text[], 6),
    (v_route, 'Bouillon (hrad)', 'Nejjižnější bod okruhu tvoří mohutný středověký hrad Godefroida z Bouillonu na skalním výběžku v ostrém meandru řeky Semois. Pohled na hrad ze břehu řeky patří k nejkrásnějším v celé Belgii. Klikaté silnice podél Semois jsou pastvou pro oči i pro motorku. Odsud se vydáte zpět na sever lesními cestami k La Roche a uzavřete okruh.', 49.79274, 5.06543, 'https://commons.wikimedia.org/wiki/Special:FilePath/0%20Bouillon%20-%20Ch%C3%A2teau-fort%20et%20pont%20sur%20la%20Semois%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/0%20Bouillon%20-%20Ch%C3%A2teau-fort%20et%20pont%20sur%20la%20Semois%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bouillon%20-%20Ch%C3%A2teau-fort%20et%20cit%C3%A9%20(1).jpg"}'::text[], 7);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lucemburk – staré město', 'Historické centrum Lucemburku zapsané na seznamu UNESCO je ideálním místem pro start i cíl okruhu. Z vyhlídek nad kasematami se otevírá pohled do hlubokého údolí čtvrti Grund. Motorku zaparkujete na okraji centra a užijete si kávu před vyjetím do kopců. Úzké dlážděné uličky a mohutná opevnění stojí za krátkou procházku.', 49.61556, 6.13194, 'https://commons.wikimedia.org/wiki/Special:FilePath/Luxembourg%20(Old%20city%20panorama).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Luxembourg%20(Old%20city%20panorama).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Luxembourg%20City%20Center.JPG"}'::text[], 0),
    (v_route, 'Larochette', 'Malebné městečko sevřené mezi zalesněnými skalami s ruinami středověkého hradu tyčícího se nad údolím Ernz. Příjezdové serpentiny nabízí příjemné zatáčky a stín okolních lesů. Hrad je krásně viditelný už z náměstí a nabízí skvělou fotozastávku. Klidné silnice v okolí jsou jako stvořené pro nenáročnou jízdu.', 49.78561, 6.21724, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Larochette,%20Luxembourg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Larochette,%20Luxembourg.jpg"}'::text[], 1),
    (v_route, 'Beaufort (hrad)', 'Dvojice hradů – středověká zřícenina a renesanční zámek ze 17. století – leží uprostřed lesů severního Müllerthalu. Cesta sem vede svěžími zvlněnými silnicemi bez provozu. Areál je proslulý i výrobou likéru Cassero z černého rybízu. Ideální zastávka na protažení a prohlídku před sjezdem k vodopádu.', 49.83583, 6.29167, 'https://commons.wikimedia.org/wiki/Special:FilePath/17th%20century%20castle%20Beaufort%20Luxembourg%202013-08%20--2.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/17th%20century%20castle%20Beaufort%20Luxembourg%202013-08%20--2.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Beaufort%20Castle%20Luxembourg%20R01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Beaufort%20Castle%202.jpg"}'::text[], 2),
    (v_route, 'Müllerthal – Schiessentümpel', 'Nejfotografovanější vodopád Lucemburska s trojitou kaskádou a starým kamenným mostkem uprostřed hlubokého lesa. Leží v srdci Lucemburského Švýcarska, kraje pískovcových skal a soutěsek. Krátká procházka od silnice vás dovede přímo k vodě. Chladné a stinné místo, kde se vyplatí sundat helmu a nadechnout se lesního vzduchu.', 49.78515, 6.29936, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schiessent%C3%BCmpel.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schiessent%C3%BCmpel.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Waldbillig%20(LU),%20Schiessent%C3%BCmpel%20--%202015%20--%206033%20--%203.jpg"}'::text[], 3),
    (v_route, 'Echternach', 'Nejstarší město Lucemburska na hranici s Německem s velkolepou bazilikou svatého Willibrorda. Ležérní historické náměstí láká na oběd nebo kávu uprostřed okruhu. Podél řeky Sûre vede příjemná silnice s výhledy na německý břeh. Skvělé místo pro doplnění energie před severní částí trasy.', 49.8125, 6.4225, 'https://commons.wikimedia.org/wiki/Special:FilePath/Echternach%20St%20Willibrord%20Basilika%20R03.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Echternach%20St%20Willibrord%20Basilika%20R03.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Echternach%20Dom.jpg"}'::text[], 4),
    (v_route, 'Restaurace: GriMouGi (Echternach)', 'Oblíbená středomořská restaurace přímo v historickém centru Echternachu s terasou u mostu na hranici s Německem. Nabízí lehkou středomořskou a evropskou kuchyni s výběrem masa, ryb i vegetariánských jídel a skvělými víny. Restaurace má výborné hodnocení 4,4 hvězdy na Googlu i TripAdvisoru a je ideální zastávkou k obědu v polovině okruhu.', 49.8125, 6.4228, 'https://commons.wikimedia.org/wiki/Special:FilePath/Echternach%20Dom.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Echternach%20Dom.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/St.%20Willibrord%20Basilika,%20Echternach-3711.jpg"}'::text[], 5),
    (v_route, 'Vianden (hrad)', 'Majestátní hrad Vianden se tyčí vysoko nad údolím řeky Our a patří k nejkrásnějším ve střední Evropě. Přístupová silnice se klikatí do kopce a nabízí nádherné zatáčky i výhledy. Nad hradem stojí sedačková lanovka a v okolí je hustá síť vyhlídek. Nezapomenutelný vrchol celého okruhu, kde stojí za to zaparkovat a projít si nádvoří.', 49.93488, 6.20283, 'https://commons.wikimedia.org/wiki/Special:FilePath/Luxembourg,%20Vianden,%20Castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Luxembourg,%20Vianden,%20Castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vianden%20castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sunset%20over%20the%20castle%20at%20Vianden%20,%20Luxemburg.jpg"}'::text[], 6),
    (v_route, 'Esch-sur-Sûre', 'Pohádková vesnička sevřená meandrem řeky Sûre a korunovaná zříceninou hradu na skalním ostrohu. Silnice sem vede podél přehradního jezera Haute-Sûre s krásnými výhledy. Klikaté úseky přírodním parkem jsou odměnou pro každého motorkáře. Ideální poslední zastávka před návratem klidnými silnicemi zpět do Lucemburku.', 49.9167, 5.9333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Esch-S%C3%BBre,%20um%20ale%20B%C3%ABsch%20(2).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Esch-S%C3%BBre,%20um%20ale%20B%C3%ABsch%20(2).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chateau%20esch%20sur%20sure%201.jpg"}'::text[], 7);
