  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vaduz – zámek Vaduz', 'Sídlo lichtenštejnského knížete se tyčí na skalním ostrohu přímo nad hlavním městem. Pro motorkáře je ideálním startem okruhu – zaparkujte v centru Vaduzu a projděte se k vyhlídce pod hradbami. Odtud se otevírá krásný pohled na celé Rýnské údolí a okolní Alpy. Samotný zámek je soukromý a nepřístupný, ale okolní silničky nabízejí skvělé fotky.', 47.13938, 9.52145, 'https://commons.wikimedia.org/wiki/Special:FilePath/Liechtenstein%20asv2022-10%20img22%20Vaduz%20Schloss.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Liechtenstein%20asv2022-10%20img22%20Vaduz%20Schloss.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vaduz%20Castle%2C%20Liechtenstein%2C%2020250502%201248%208573.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Liechtenstein-00188%20-%20Vaduz%20Castle%20%2819467376849%29.jpg"}'::text[], 0),
    (v_route, 'Triesenberg', 'Horská obec rozložená ve svazích nad Vaduzem, na kterou vede série pěkných serpentin. Je to největší lichtenštejnská obec a založili ji kdysi Walserové z kantonu Valais. Zastavte se u kostela sv. Josefa – z náměstí je nádherný výhled dolů do Rýnského údolí. Silnice sem je čistě horská, bez dálnic, a nabízí příjemné zatáčky.', 47.11856, 9.54344, 'https://commons.wikimedia.org/wiki/Special:FilePath/2018-10-05%20Liechtenstein,%20Triesenberg,%20Bergstrasse%20(KPFC)%2001%20(cropped).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2018-10-05%20Liechtenstein,%20Triesenberg,%20Bergstrasse%20(KPFC)%2001%20(cropped).jpg"}'::text[], 1),
    (v_route, 'Steg – Gänglesee', 'Malé horské jezírko na náhorní plošině Steg ve výšce okolo 1300 m, obklopené loukami a lesy. Je to klidné místo na krátkou zastávku, protažení a focení odrazu hor na hladině. Silnice přes Steg spojuje Triesenberg s Malbunem a patří k nejhezčím úsekům celého okruhu. V zimě tudy vede běžecká stopa, v létě je to oáza klidu.', 47.1077, 9.57771, 'https://commons.wikimedia.org/wiki/Special:FilePath/Steg,%20Liechtenstein.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Steg,%20Liechtenstein.jpg"}'::text[], 2),
    (v_route, 'Malbun', 'Nejvýše položené středisko Lichtenštejnska ve výšce kolem 1600 m a vrchol celého okruhu. Cesta sem vede posledními serpentinami a končí v kotli obklopeném horskými štíty. V zimě je to jediná lyžařská oblast v zemi, v létě výchozí bod pro túry a sedačkovou lanovku Sareis. Ideální místo na oběd a odpočinek před sjezdem zpět do údolí.', 47.1012, 9.6048, 'https://commons.wikimedia.org/wiki/Special:FilePath/LIE%20%E2%80%94%20Gemeinde%20Triesenberg%20Malbun%20%284er%20Sessellift%20Sareis%20%C2%B7%20Talstation%29%202023-05-29.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/LIE%20%E2%80%94%20Gemeinde%20Triesenberg%20Malbun%20%284er%20Sessellift%20Sareis%20%C2%B7%20Talstation%29%202023-05-29.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Torkel (Vaduz)', 'Michelinská restaurace Torkel leží v knížecí vinici Herawingert nad Vaduzem a nabízí moderní kuchyni z lokálních surovin farm-to-table. Na Google má vynikající hodnocení kolem 4,8 hvězdy a patří k nejlépe hodnoceným podnikům v celém knížectví. Dominantou sálu je starý dřevěný vinný lis (torkel) a z prosklené terasy je výhled na vinice a Rýnské údolí – ideální tečka za okruhem.', 47.1442279, 9.5195399, 'https://commons.wikimedia.org/wiki/Special:FilePath/9490%20Vaduz%2C%20Liechtenstein%20-%20panoramio%20%281%29.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/9490%20Vaduz%2C%20Liechtenstein%20-%20panoramio%20%281%29.jpg"}'::text[], 4),
    (v_route, 'Balzers – hrad Gutenberg', 'Dochovalý středověký hrad na skalním kopci nad nejjižnější obcí země, kterým se okruh uzavírá. Nádvoří a zahrady jsou v sezoně volně přístupné a nabízejí výhled na Rýnské údolí a okolní vinice. Silnice sem vede údolím, opět bez dálnic, po klidných okreskách. Skvělá tečka za celodenním výletem před návratem do Vaduzu.', 47.06565, 9.50054, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Gutenberg%20in%20Balzers,%20Liechtenstein.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Gutenberg%20in%20Balzers,%20Liechtenstein.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Gutenberg%20-%20Balzers-%20Liechtenstein.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gutenberg%20Castle%2C%20Balzers%2C%20Liechtenstein.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Wielka Obwodnica Bieszczadzka', 'Legendární okružní silnice Bieszczad, spojující nejkrásnější místa pohoří po klikatých horských cestách. Nabízí desítky serpentin, průsmyků a nekonečné výhledy na poloniny – bezva pastva pro každého motorkáře. Vede zásadně po krajských silnicích, dálnicím se tu vyhnete úplně. Ideální je jet klidně a nechat se vést zatáčkami.', 49.15716, 22.54965, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bieszczady.%20Serpentyny%20nad%20Berehami%20i%20Po%C5%82onina%20Cary%C5%84ska.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bieszczady.%20Serpentyny%20nad%20Berehami%20i%20Po%C5%82onina%20Cary%C5%84ska.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bieszczady%20DK28.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kruhly%20Wierch%20-%20Po%C5%82onina%20Cary%C5%84ska.JPG"}'::text[], 0),
    (v_route, 'Solina (přehrada)', 'Největší vodní nádrž v Polsku, obklopená zalesněnými kopci Bieszczad. Silnice kolem jezera se vine v mírných obloucích těsně nad hladinou a je jedním z nejfotogeničtějších úseků okruhu. Zastavte se u koruny hráze na kávu a rozhled po tyrkysové vodě. Okolí nabízí spoustu parkovišť pro motorky.', 49.3952, 22.4545, 'https://commons.wikimedia.org/wiki/Special:FilePath/Solina%20Jezioro.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Solina%20Jezioro.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pola%C5%84czyk%20(Zjawa),%20Solina%20lake.JPG"}'::text[], 1),
    (v_route, 'Połonina Wetlińska', 'Rozlehlá horská louka (polonina) s ikonickou útulnou Chatka Puchatka na hřebeni. Z parkoviště u silnice vyráží pěší stezka, takže si můžete motorku odložit a vyšlápnout k panoramatu. Výhledy do polsko-ukrajinského pohraničí jsou nezapomenutelné. Skvělé místo na delší zastávku a nadechnutí.', 49.1641, 22.5357, 'https://commons.wikimedia.org/wiki/Special:FilePath/Po%C5%82onina%20Wetli%C5%84ska%20-%20Chatka%20Puchatka%2003.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Po%C5%82onina%20Wetli%C5%84ska%20-%20Chatka%20Puchatka%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Po%C5%82onina%20Wetli%C5%84ska.jpg"}'::text[], 2),
    (v_route, 'Ustrzyki Górne', 'Horská osada v srdci Bieszczadského národního parku a klíčová křižovatka okruhu. Je to ideální místo na tankování, oběd nebo přenocování při dvoudenní variantě trasy. Odtud vede silnice krásnými zatáčkami dál k sedlům. Klid, hory a málo aut – přesně to, co motorkář hledá.', 49.10517, 22.64923, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ustrzyki%20G%C3%B3rne%20ko%C5%9Bci%C3%B3%C5%82%20%C5%9Bw.%20Anny.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ustrzyki%20G%C3%B3rne%20ko%C5%9Bci%C3%B3%C5%82%20%C5%9Bw.%20Anny.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bieszczady,%20rz.%20Wo%C5%82osatka%20w%20Ustrzykach%20G%C3%B3rnych.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ustrzyki%20G%C3%B3rne,%20Hotel%20G%C3%B3rski%20PTTK%20(HB2).jpg"}'::text[], 3),
    (v_route, 'Cisna', 'Malebná horská vesnice s historickou úzkokolejkou Bieszczadzka Kolejka Leśna. Leží na jižní části okruhu a je oblíbenou motorkářskou zastávkou s hospůdkami a bary. Silnice sem přijíždějí v pěkných obloucích lesnatými údolími. Dobré místo pro pauzu před stoupáním do sedel.', 49.15139, 22.47333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Majdan%20Cisna%20kolejka%20waskotorowa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Majdan%20Cisna%20kolejka%20waskotorowa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gmina%20Cisna,%20Poland%20-%20panoramio%20(2).jpg"}'::text[], 4),
    (v_route, 'Restaurace: Polanka Kawiarnia & Bistro (Cisna)', 'Útulná kavárna a bistro v centru Cisny, ideální zastávka zhruba v polovině okruhu. Podává skvělou kávu, domácí dorty, palačinky a poctivá polská jídla v přátelské atmosféře. Na TripAdvisoru má výborné hodnocení 4,7 z 5 a je dlouhodobě nejlépe hodnoceným podnikem ve městě.', 49.15139, 22.47333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gmina%20Cisna,%20Poland%20-%20panoramio%20(2).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gmina%20Cisna,%20Poland%20-%20panoramio%20(2).jpg"}'::text[], 5),
    (v_route, 'Przełęcz Wyżna', 'Horské sedlo ve výšce 872 m mezi Brzegami Górnymi a Wetlinou, nejnavštěvovanější vyhlídka parku. Silnice sem stoupá pěknými serpentinami a nabízí výhled na Połoninu Caryńskou a Tarnicu. Je tu parkoviště a stánky, takže se dá zastavit a pokochat. Za jasného večera je to i skvělé místo na pozorování hvězd.', 49.15716, 22.54965, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bieszczady%20DK28.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bieszczady%20DK28.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kruhly%20Wierch%20-%20Po%C5%82onina%20Cary%C5%84ska.JPG"}'::text[], 6),
    (v_route, 'Zapora Solina', 'Mohutná betonová hráz nádrže Solina na řece San, vysoká přes 80 metrů. Po koruně hráze se dá projít pěšky a shora je impozantní pohled na jezero i elektrárnu. Silnice k hrázi patří k nejhezčím úsekům okruhu. Oblíbené turistické místo s občerstvením a parkováním.', 49.3952, 22.4545, 'https://commons.wikimedia.org/wiki/Special:FilePath/Solina%20zapora%200001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Solina%20zapora%200001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Solina%20zapora%200002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Solina%20zapora%200003.JPG"}'::text[], 7),
    (v_route, 'Lesko', 'Historické městečko na řece San, brána do Bieszczad a výchozí bod celého okruhu. Najdete tu renesanční zámek Kmitů, starou synagogu a příjemné náměstí. Je to ideální místo na start i cíl, doplnění paliva a zásob. Odtud silnice míří přímo do hor plných zatáček.', 49.46733, 22.33056, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lesko,%20zamek%20Kmit%C3%B3w%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lesko,%20zamek%20Kmit%C3%B3w%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lesko%20synagoga.jpg"}'::text[], 8);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zakopane', 'Zakopane je hlavní zimní i letní středisko pod Tatrami a ideální výchozí bod okruhu. Projeďte se okolo proslulé promenády Krupówki s dřevěnými vilami v goralském stylu a doplňte palivo i síly. Parkování v centru je omezené, proto zvažte odstavení na okraji a procházku pěšky.', 49.29903, 19.94905, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zakopane%20ulica%20Krupowki%20zima%20noc-by%20Robert%20Parma.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zakopane%20ulica%20Krupowki%20zima%20noc-by%20Robert%20Parma.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zakopane%20ul.%20Krup%C3%B3wki.%20Willa%20Poraj%20(2).jpg"}'::text[], 0),
    (v_route, 'Restaurace: Bistro Kryjówka (Zakopane)', 'Bistro Kryjówka v samém srdci Zakopaného spojuje goralskou tradici s moderním pojetím a servíruje regionální, italská i evropská jídla. Restaurace má vynikající hodnocení kolem 4,8 hvězdičky z tisíců recenzí a chválí se štědré porce i příjemná dřevem obložená atmosféra. Je to skvělá zastávka na začátku okruhu, kde doplníte síly před cestou k Morskiemu Oku.', 49.30193, 19.95113, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zakopane%20ul.%20Krup%C3%B3wki.%20Willa%20Poraj%20(2).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zakopane%20ul.%20Krup%C3%B3wki.%20Willa%20Poraj%20(2).jpg"}'::text[], 1),
    (v_route, 'Morskie Oko', 'Morskie Oko je největší a jedno z nejkrásnějších jezer v polských Tatrách, obklopené štíty Mięguszowieckých vrcholů. Motorku odstavíte na placeném parkovišti Palenica Białczańska, odkud k jezeru vede pouze pěší (nebo bryčkou) asi 9 km dlouhá asfaltka. Vyplatí se rezervovat na výlet dostatek času a vyrazit brzy ráno.', 49.19758, 20.0705, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Morskie%20Oko%20in%20April.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Morskie%20Oko%20in%20April.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama-Morskiego-Oka.jpg"}'::text[], 2),
    (v_route, 'Gubałówka', 'Gubałówka je zalesněný hřbet nad Zakopaným s dechberoucím panoramatem celého tatranského hřebene. Na vrchol vás vyveze historická pozemní lanovka, zatímco motorku necháte dole u dolní stanice. Nahoře najdete stánky s goralskými dobrotami a jednu z nejlepších vyhlídek v okolí.', 49.305, 19.943, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Tatr%20z%20Guba%C5%82%C3%B3wki.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Tatr%20z%20Guba%C5%82%C3%B3wki.jpg"}'::text[], 3),
    (v_route, 'Dolina Kościeliska', 'Dolina Kościeliska je jedno z nejmalebnějších údolí Západních Tater, přístupné od obce Kiry asi 8 km od Zakopaného. Motorku zaparkujete u vstupu do údolí, dál se pokračuje pěšky nebo bryčkou mezi vápencovými skalami jako jsou Organy. Cesta k údolí vede příjemnou úzkou silnicí lemovanou lesy a potokem.', 49.275, 19.87, 'https://commons.wikimedia.org/wiki/Special:FilePath/Organy.%20Dolina%20Ko%C5%9Bcieliska.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Organy.%20Dolina%20Ko%C5%9Bcieliska.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dolina%20Ko%C5%9Bcieliska%20a20.JPG"}'::text[], 4),
    (v_route, 'Dębno', 'Dřevěný kostel svatého Michaela Archanděla v Dębně je klenot gotické tesařské architektury z konce 15. století, zapsaný na seznamu UNESCO. Postavený z modřínového a jedlového dřeva bez jediného hřebíku ukrývá unikátní středověké polychromie. Leží přímo u silnice mezi Nowým Targem a Czorsztynem, takže je snadno dostupný na motorce.', 49.46649, 20.21202, 'https://commons.wikimedia.org/wiki/Special:FilePath/Debno%20kosciol%204.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Debno%20kosciol%204.jpg"}'::text[], 5),
    (v_route, 'Czorsztyn', 'Ruiny gotického hradu Czorsztyn se tyčí na kopci nad hladinou Czorsztyńského jezera na řece Dunajec. Z hradeb se otevírá nádherný výhled na přehradu a naproti stojící zámek Niedzica. Silnice sem vede malebným krajem Pienin a je vděčnou zastávkou pro fotografy i milovníky historie.', 49.43511, 20.3132, 'https://commons.wikimedia.org/wiki/Special:FilePath/Czorsztyn.%20Ruiny%20zamku,%20kon.XIII,%20XVI,%201680.%20128.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Czorsztyn.%20Ruiny%20zamku,%20kon.XIII,%20XVI,%201680.%20128.jpg"}'::text[], 6),
    (v_route, 'Zamek Niedzica', 'Zámek Niedzica (Dunajec) se romanticky tyčí na skalním ostrohu nad Czorsztyńským jezerem naproti ruinám Czorsztyna. Tato dobře zachovalá středověká pevnost patří k nejfotogeničtějším hradům Pienin a nabízí nádherné výhledy na hladinu jezera i řeku Dunajec. Leží přímo na trase okruhu a je vděčnou kulturní zastávkou v cíli cesty. Nahrazuje původní zastávku Przełęcz Glinne, která leží daleko mimo trasu v Beskidu Żywieckim.', 49.43082, 20.30718, 'https://commons.wikimedia.org/wiki/Special:FilePath/Niedzica%20Castle%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Niedzica%20Castle%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/20170305%20Niedzica%20zamek%205195.jpg"}'::text[], 7),
    (v_route, 'Restaurace: Restauracja by Marco (Niedzica)', 'Restauracja by Marco v Niedzici je oblíbeným místem pod zámkem s hodnocením kolem 4,6 hvězdičky. Menu nabízí širokou škálu jídel inspirovaných mezinárodní kuchyní s italskými akcenty a hosté chválí kvalitu pokrmů i přátelskou atmosféru. Je to ideální zastávka na odpočinek po prohlídce hradů a jezera v závěru okruhu.', 49.43056, 20.30833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Niedzica%20Castle%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Niedzica%20Castle%201.jpg"}'::text[], 8);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Štrbské Pleso', 'Ledovcové pleso ve výšce 1346 m je ideálním startem výletu a nabízí dechberoucí panorama tatranských štítů odrážejících se ve vodní hladině. Zaparkovat můžete přímo u jezera a protáhnout se před dlouhou jízdou. Ráno tu bývá klid a čerstvý horský vzduch, který motorku i jezdce naladí na cestu.', 49.1193, 20.06301, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20of%20Strbske%20pleso.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20of%20Strbske%20pleso.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vysok%C3%A9%20Tatry,%20%C5%A0trbsk%C3%A9%20pleso%20za%20v%C3%BDchodu%20slunce.JPG"}'::text[], 0),
    (v_route, 'Tatranská Lomnica', 'Elegantní tatranské středisko na Cestě slobody s historickými vilami a lanovkou na Lomnický štít. Silnice sem vede plynulými zatáčkami pod hřebeny Vysokých Tater a nabízí skvělé rozhledy. Zastávka na kávu v Grandhotelu Praha je příjemným zpestřením trasy.', 49.16472, 20.27833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grandhotel%20Praha%20Tatransk%C3%A1%20Lomnica%20(2).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grandhotel%20Praha%20Tatransk%C3%A1%20Lomnica%20(2).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vila%20Sz%C3%A9ch%C3%A9nyi%20(Tatransk%C3%A1%20Lomnica)%20Slovakia5.JPG"}'::text[], 1),
    (v_route, 'Hrebienok', 'Turistické centrum nad Starým Smokovcem, kam se z podhůří dostanete pozemní lanovkou. Motorku necháte dole a nahoře si vychutnáte výhled na Slavkovský štít a nedaleké vodopády Studeného potoka. Krátká zastávka, která rozbije jízdu příjemným horským zážitkem.', 49.15667, 20.2225, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrebienok,%20Vysok%C3%A9%20Tatry.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrebienok,%20Vysok%C3%A9%20Tatry.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lanovka%20Star%C3%BD%20Smokovec%20-%20Hrebienok.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Koliba Kamzík (Starý Smokovec)', 'Stylová koliba v srdci Starého Smokovca patří dlouhodobě k nejlepším restauracím Vysokých Tater a láká na poctivou slovenskou kuchyni – halušky, grilované speciality i zvěřinu. Hosté ji milují pro dřevěný horský interiér a přátelskou obsluhu, což potvrzuje skvělé hodnocení kolem 4,8 hvězdičky z tisíců recenzí. Ideální místo na vydatný oběd po výjezdu z Hrebienku, než se vydáte dál na Spiš.', 49.1385, 20.218, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lanovka%20Star%C3%BD%20Smokovec%20-%20Hrebienok.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lanovka%20Star%C3%BD%20Smokovec%20-%20Hrebienok.jpg"}'::text[], 3),
    (v_route, 'Spišský hrad (UNESCO)', 'Jedna z největších hradních zřícenin ve střední Evropě, zapsaná na seznamu UNESCO, se tyčí na vápencovém vrchu nad krajinou Spiše. Silueta hradu je vidět už z dálky a při příjezdu po vedlejších cestách působí monumentálně. Ideální fotostop a možnost prohlídky rozsáhlých nádvoří.', 49.0005, 20.76863, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spis%20Castle%20-%20Slovakia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spis%20Castle%20-%20Slovakia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Spis%20Castle%2001.JPG"}'::text[], 4),
    (v_route, 'Levoča', 'Historické spišské město za dochovanými hradbami, rovněž součást UNESCO. Náměstí Majstra Pavla s radnicí a chrámem sv. Jakuba je dokonalým místem na oběd i procházku. Dlážděné uličky a renesanční domy dýchají středověkou atmosférou.', 49.02528, 20.58944, 'https://commons.wikimedia.org/wiki/Special:FilePath/Square%20Levo%C4%8Da16Slovakia18.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Square%20Levo%C4%8Da16Slovakia18.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Square%20Levo%C4%8Da16Slovakia47.JPG"}'::text[], 5),
    (v_route, 'Dobšinská ľadová jaskyňa', 'Světoznámá ledová jeskyně zapsaná v UNESCO, kde i v létě zůstávají mohutné ledové stěny a sloupy. Přístup vede krátkým výšlapem od parkoviště lesem. Chladná prohlídka je vítaným osvěžením uprostřed letního dne na motorce.', 48.87222, 20.3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dob%C5%A1insk%C3%A1%20Ice%20Cave.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dob%C5%A1insk%C3%A1%20Ice%20Cave.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dob%C5%A1insk%C3%A1%20Ice%20Cave%201.jpg"}'::text[], 6),
    (v_route, 'Slovenský ráj – Prielom Hornádu (Hrabušice)', 'Divoký kaňon řeky Hornád v Národním parku Slovenský ráj s lávkami, žebříky a stupačkami nad vodou. Motorku zaparkujete u Podlesku poblíž Hrabušic a vydáte se pěšky do soutěsky. Zelené rokliny a šumící peřeje jsou odměnou pro každého, kdo si chce protáhnout nohy.', 48.99, 20.27, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slovensk%C3%BD%20r%C3%A1j,%20Prielom%20Horn%C3%A1du%20(17).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slovensk%C3%BD%20r%C3%A1j,%20Prielom%20Horn%C3%A1du%20(17).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Slovensk%C3%BD%20r%C3%A1j,%20Prielom%20Horn%C3%A1du%20(14).JPG"}'::text[], 7),
    (v_route, 'Vernár', 'Malebná horská obec na okraji Slovenského ráje, k níž vede jedna z nejkrásnějších tras přes Vernárske sedlo. Klikaté stoupání a rozhledy do údolí patří k vrcholům celého výletu. Ideální místo na krátkou zastávku a vychutnání ticha podhorské krajiny.', 48.9, 20.13, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vern%C3%A1r%20-%20%C5%BEelezni%C4%8Dn%C3%A1%20zast%C3%A1vka%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vern%C3%A1r%20-%20%C5%BEelezni%C4%8Dn%C3%A1%20zast%C3%A1vka%20-%20panoramio.jpg"}'::text[], 8),
    (v_route, 'Kráľova hoľa', 'Majestátní vrchol Nízkých Tater (1946 m) a jeden z pramenů slovenských řek, opředený legendami o kráľi Matúšovi. Silnice v jeho úpatí u Telgártu nabízí slavnou serpentinu a tunel, které milují všichni motorkáři. Rozhledy na hřebeny jsou působivým finále dvoudenní jízdy.', 48.8825, 20.14556, 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C5%82owacja%20-%20Kralova%20Hora.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/S%C5%82owacja%20-%20Kralova%20Hora.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kr%C3%A1%C4%BEova%20ho%C4%BEa%20-%20asfalt.cesta%20k%20vysiela%C4%8Du%20-%20panoramio.jpg"}'::text[], 9);
