  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Tihany – benediktinské opatství', 'Poloostrov Tihany se dvěma věžemi barokního opatství je nejfotogeničtějším místem celého Balatonu. Silnička na poloostrov se vine kolem levandulových polí a vnitrozemského jezírka, ideální na pomalou vyjížďku. Od opatství je nádherný výhled na hladinu jezera – skvělé místo pro první zastávku a fotku motorky.', 46.91369, 17.88918, 'https://commons.wikimedia.org/wiki/Special:FilePath/Abtei%20Tihany.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Abtei%20Tihany.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tihany%20Abbey%20and%20Port%20of%20Tihany%20with%20Lelle%20(ship,%201978).JPG"}'::text[], 0),
    (v_route, 'Balatonfüred – Tagoreho promenáda', 'Nejstarší lázeňské město u Balatonu láká elegantní nábřežní promenádou lemovanou platany. Zaparkuj u přístavu a projdi se kolem kaváren a jachet s výhledem na Tihany. Klidné tempo a rovné pobřežní silnice sem lákají na relaxační kávovou pauzu.', 46.95466, 17.89667, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tagore%20s%C3%A9t%C3%A1ny,%20Balatonf%C3%BCred%20-%202013.08.06%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tagore%20s%C3%A9t%C3%A1ny,%20Balatonf%C3%BCred%20-%202013.08.06%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Fountain.%20-%20Tagore%20Promenade,%20Balatonf%C3%BCred.JPG"}'::text[], 1),
    (v_route, 'Veszprém – hradní čtvrť', 'Historické „město královen“ se pyšní hradním kopcem s katedrálou a barokními paláci nad údolím. Klikaté uličky staré čtvrti stojí za procházku, zatímco příjezdové silnice od Balatonu nabízejí příjemné stoupání. Odtud pokračuje trasa do lesů Bakonského pohoří.', 47.09327, 17.91149, 'https://commons.wikimedia.org/wiki/Special:FilePath/Veszpr%C3%A9m%20Castle%20Area%20View%202010.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Veszpr%C3%A9m%20Castle%20Area%20View%202010.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Veszpr%C3%A9m%20-%20V%C3%A1r%20utca%2023.%20-%201346.JPG"}'::text[], 2),
    (v_route, 'Herend – porcelánka', 'Světoznámá manufaktura na ruční malovaný porcelán, dodavatel evropských panovnických dvorů, sídlí v malebné vesnici v Bakonském pohoří. Návštěvnické centrum a muzeum nabízejí pohled do řemesla i mini-manufakturu. Cesta sem vede zvlněnou lesní krajinou po tiché okresní silnici.', 47.13, 17.75, 'https://commons.wikimedia.org/wiki/Special:FilePath/Budapest,%20Hungarian%20National%20Museum,%20Herend%20porcelain,%20plate%20and%20coffee%20set.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Budapest,%20Hungarian%20National%20Museum,%20Herend%20porcelain,%20plate%20and%20coffee%20set.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Herend%20marking.JPG"}'::text[], 3),
    (v_route, 'Sümeg – středověký hrad', 'Mohutný kamenný hrad trůní na osamělém vápencovém kopci a je jedním z nejzachovalejších v Maďarsku. Za jasného dne odtud dohlédneš daleko do kraje a na okolní pahorky. Silnice přes Bakony k Sümegu patří k nejzábavnějším úsekům celé trasy s hezkými zatáčkami.', 46.98216, 17.28254, 'https://commons.wikimedia.org/wiki/Special:FilePath/2016%20S%C3%BCmeg%20Castle%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2016%20S%C3%BCmeg%20Castle%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hungary,%20S%C3%BCmeg%20Castle.jpg"}'::text[], 4),
    (v_route, 'Szigliget – hrad nad Balatonem', 'Zřícenina hradu Szigliget se tyčí nad malebnou vesnicí a vinicemi na severním břehu Balatonu. Krátký výstup nabízí jeden z nejlepších panoramatických výhledů na jezero a Tapolckou pánev. Serpentiny k parkovišti pod hradem si motorkáři užijí.', 46.80432, 17.43642, 'https://commons.wikimedia.org/wiki/Special:FilePath/Szigliget%20castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szigliget%20castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szigliget%20castle%20(4).jpg"}'::text[], 5),
    (v_route, 'Restaurace: Villa Kabala (Szigliget)', 'Vyhlášená restaurace v secesní vile na svahu nad Szigligetem s dechberoucím výhledem na Balaton, uvedená v průvodci MICHELIN a držitelka zelené hvězdy za udržitelnou gastronomii. Kuchyně sází na sezónní lokální suroviny, vlastní sýry a párovaná vína z okolních vinic. Hosté ji na Googlu hodnotí kolem 4,9 hvězdy, což z ní dělá ideální zastávku na oběd v polovině okruhu.', 46.79139, 17.43389, 'https://commons.wikimedia.org/wiki/Special:FilePath/Szigliget%20castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szigliget%20castle.jpg"}'::text[], 6),
    (v_route, 'Badacsony – sopečné vinice', 'Charakteristická placatá sopka Badacsony je obklopena strmými vinicemi na čedičové půdě, proslulými minerálním bílým vínem. Silnice mezi révou nabízí výhledy na jezero a řadu vinařství s posezením (pozor na řidiče – ochutnávku nech pro spolujezdce). Ideální zastávka na oběd s výhledem.', 46.79, 17.5, 'https://commons.wikimedia.org/wiki/Special:FilePath/Badacsonytomaj,%20Badacsony,%208261%20Hungary%20-%20panoramio%20(3).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Badacsonytomaj,%20Badacsony,%208261%20Hungary%20-%20panoramio%20(3).jpg"}'::text[], 7),
    (v_route, 'Keszthely – zámek Festetics', 'Rozlehlý barokní zámek Festetics s honosnou knihovnou a upravenými zahradami uzavírá okruh na západním cípu Balatonu. Zámek patří k nejkrásnějším v Maďarsku a stojí za prohlídku interiérů i parku. Odtud vede pohodová pobřežní silnice zpět podél jezera.', 46.77078, 17.24159, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keszthely%20-%20Festetics%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Keszthely%20-%20Festetics%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/13%20Festetics%20Kast%C3%A9ly%20Keszthely.JPG"}'::text[], 8);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Průsmyk Shipka – Památník svobody', 'Slavný horský průsmyk ve výšce 1150 m, kam vede jedna z nejkrásnějších serpentinových silnic v Bulharsku. Kamenná věž Památníku svobody připomíná bitvy z rusko-turecké války a nabízí dechberoucí rozhled do obou údolí. Pro motorkáře je výjezd nahoru čirá radost – dlouhé táhlé vlásenky a kvalitní asfalt. Nahoře je parkoviště i občerstvení, ideální zastávka na fotku.', 42.753, 25.318, 'https://commons.wikimedia.org/wiki/Special:FilePath/Shipka%20pass%20(%D0%A8%D0%B8%D0%BF%D0%BA%D0%B0)%20-%20central%20Monument.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Shipka%20pass%20(%D0%A8%D0%B8%D0%BF%D0%BA%D0%B0)%20-%20central%20Monument.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/BASA-746K-1-84-14%20Shipka%20Pass%20Liberty%20Monument%20aerial%20photo,%20Bulgaria%201930s.JPG"}'::text[], 0),
    (v_route, 'Shipka – Chrám narození Kristova (Zlatý kostel)', 'Pravoslavný pamětní chrám s pěti zlatými kupolemi, který se třpytí na úpatí hor u městečka Shipka. Byl postaven na počest padlých vojáků za osvobození Bulharska a jeho ruský styl působí jako z pohádky. Kolem vede klidná silnice, takže je snadné zastavit a projít se areálem. Skvělá zastávka při sjezdu z průsmyku do Údolí růží.', 42.71619, 25.32896, 'https://commons.wikimedia.org/wiki/Special:FilePath/Shipka%20Memorial%20Church%20(23343081802).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Shipka%20Memorial%20Church%20(23343081802).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Shipka-memorial-church-outside.JPG"}'::text[], 1),
    (v_route, 'Pomník Buzludža', 'Monumentální betonový talíř bývalého komunistického památníku na vrcholu Buzludža v 1441 m n. m. Přístupová silnice je úzká a klikatá, ale odměnou je surová atmosféra opuštěné stavby s výhledem do celého kraje. Motorkáři sem jezdí pro jedinečné foto i pocit z výjezdu na vrchol. Interiér bývá uzavřen, ale exteriér a panorama stojí za každou serpentinu.', 42.7357, 25.3938, 'https://commons.wikimedia.org/wiki/Special:FilePath/Buzludzha%20&%20Torch%20Monument.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Buzludzha%20&%20Torch%20Monument.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/20140622%20Buzludzha%20070.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Buzludzha-03.JPG"}'::text[], 2),
    (v_route, 'Kazanlak – thrácká hrobka (Údolí růží)', 'UNESCO památka ze 4. století př. n. l. s unikátními thráckými freskami, ležící v srdci proslulého Údolí růží. Kolem Kazanlaku se rozkládají růžová pole, ze kterých se destiluje světoznámý olej. Návštěvníci vidí věrnou repliku hrobky, originál je chráněný. Ideální zastávka na doplnění paliva i klidný oběd před další horskou etapou.', 42.62597, 25.39919, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20thracian%20tomb%20in%20Kazanlak%20from%20outside.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20thracian%20tomb%20in%20Kazanlak%20from%20outside.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kazanlak-tomb-fresco-1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Thracian%20Tomb%20of%20Kazanlak.jpg"}'::text[], 3),
    (v_route, 'Etar – skanzen', 'Architektonicko-etnografický skanzen jižně od Gabrova, kde ožívají tradiční bulharská řemesla a vodní mlýny na břehu říčky. Projdete si dlážděnou uličku s dílnami a ochutnáte místní speciality. Příjezd vede příjemnou údolní silnicí lemovanou lesy. Skvělé místo na protažení nohou a nasátí atmosféry bulharského obrození.', 42.80944, 25.34833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Etura%20Gabrovo%202.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Etura%20Gabrovo%202.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Etura%20Gabrovo%2010.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Etura%20Gabrovo%208.JPG"}'::text[], 4),
    (v_route, 'Gabrovo', 'Město na řece Jantře, brána do centrálního Balkánu a známé bulharské hlavní město humoru. Nabízí příjemné nábřeží, mosty a dostatek benzínek i kaváren pro doplnění sil. Odsud vedou horské silnice na sever přes hřeben Staré planiny. Praktická základna pro nocleh mezi prvním a druhým dnem trasy.', 42.87472, 25.33417, 'https://commons.wikimedia.org/wiki/Special:FilePath/Yantra%20River,%20Gabrovo,%20Bulgaria.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Yantra%20River,%20Gabrovo,%20Bulgaria.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bulgaria%20Bulgaria-0894%20-%20Yantra%20River%20(7433405358).jpg"}'::text[], 5),
    (v_route, 'Tryavna', 'Kouzelné městečko národního obrození s kamennou hodinovou věží z roku 1814 a dřevěným mostem přes říčku. Historické jádro s dlážděným náměstím láká k procházce mezi řemeslnými domky. Cesta sem vede úzkými, ale malebnými horskými silničkami. Klidná zastávka plná autentické architektury a řezbářské tradice.', 42.86667, 25.5, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tryavna-imagesfrombulgaria.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tryavna-imagesfrombulgaria.JPG"}'::text[], 6),
    (v_route, 'Restaurace: Shtastliveca (Veliko Tarnovo)', 'Ikonická restaurace řetězce Shtastliveca v historické části Velikého Tarnova na ulici Stefan Stambolov, kousek od pevnosti Carevec. Podává moderně pojatou bulharskou a balkánskou kuchyni v elegantním interiéru ve stylu 30. let. Patří k nejlépe hodnoceným podnikům ve městě (kolem 4,8 hvězdy) a je ideálním místem k zakončení dvoudenního okruhu.', 43.08106, 25.65576, 'https://commons.wikimedia.org/wiki/Special:FilePath/Veliko%20Tarnovo%20(%D0%92%D0%B5%D0%BB%D0%B8%D0%BA%D0%BE%20%D0%A2%D1%8A%D1%80%D0%BD%D0%BE%D0%B2%D0%BE)%20-%20Tsarevets.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Veliko%20Tarnovo%20(%D0%92%D0%B5%D0%BB%D0%B8%D0%BA%D0%BE%20%D0%A2%D1%8A%D1%80%D0%BD%D0%BE%D0%B2%D0%BE)%20-%20Tsarevets.JPG"}'::text[], 7),
    (v_route, 'Veliko Tarnovo – pevnost Carevec', 'Středověká pevnost na kopci Carevec nad meandrem řeky Jantry, symbol druhého bulharského carství. Mohutné hradby, brány a Patriarší chrám tvoří monumentální cíl celé trasy. Přístupové silnice do Velikého Tarnova jsou svižné a nabízejí nádherné výhledy na město stoupající po svazích. Ideální zakončení dvoudenního horského okruhu.', 43.07567, 25.61715, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fortress%20at%20Veliko%20Tarnovo.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fortress%20at%20Veliko%20Tarnovo.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Veliko%20Tarnovo%20(%D0%92%D0%B5%D0%BB%D0%B8%D0%BA%D0%BE%20%D0%A2%D1%8A%D1%80%D0%BD%D0%BE%D0%B2%D0%BE)%20-%20Tsarevets.JPG"}'::text[], 8);
  insert into public.routes
