  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Pevnost Golubac', 'Středověká pevnost z 14. století stojí přímo na břehu Dunaje tam, kde se řeka zužuje do soutěsky Železných vrat. Devět mohutných věží se tyčí nad vodou a pevnost je ideálním startem celé trasy. Zaparkujte motorku, projděte si zrekonstruované hradby a užijte si výhled na vstup do kaňonu. Silnice zde prochází přímo pod hradem tunelem.', 44.66116, 21.67838, 'https://commons.wikimedia.org/wiki/Special:FilePath/Golubac%20grad%202019%2002.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Golubac%20grad%202019%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Goluba%C4%8Dki%20grad,%20Golubac%2007.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Golubac%20Fortress%202025.jpg"}'::text[], 0),
    (v_route, 'Národní park Đerdap', 'Největší národní park Srbska chrání dramatickou dunajskou soutěsku i okolní lesnaté hory. Silnice Đerdapska magistrala vede celým parkem a nabízí jedny z nejkrásnějších říčních výhledů v Evropě. Počítejte s množstvím zatáček, tunelů a vyhlídkových míst, kde stojí za to zastavit. Jízda parkem je klidná, ale vyžaduje pozornost kvůli úzké vozovce.', 44.625, 21.85, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danube%20near%20Iron%20Gate%202006.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Danube%20near%20Iron%20Gate%202006.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Danube%20near%20Iron%20Gate%202006%203.JPG"}'::text[], 1),
    (v_route, 'Lepenski Vir', 'Archeologické naleziště jedné z nejstarších organizovaných osad Evropy staré přes 8000 let. Moderní zastřešené muzeum ukrývá originální kamenné sochy s rybími rysy a půdorysy pravěkých obydlí. Je to skvělá zastávka pro protažení nohou a nahlédnutí do mezolitu. Od hlavní silnice sem vede krátká odbočka dolů k řece.', 44.55, 22.0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lepenski%20vir%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lepenski%20vir%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lepenski%20Vir,%20muzej%2019.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lepenski%20Vir%20Head.JPG"}'::text[], 2),
    (v_route, 'Donji Milanovac', 'Klidné městečko na pravém břehu dunajského jezera je přirozeným místem pro polední přestávku. Najdete tu benzínku, kavárny i rybí restaurace s výhledem na vodu. Doplňte palivo, protože další úsek k přehradě je delší. Nábřeží je příjemné místo k odpočinku uprostřed trasy.', 44.46593, 22.1517, 'https://commons.wikimedia.org/wiki/Special:FilePath/Donji%20Milanovac.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Donji%20Milanovac.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wiki.%C4%90erdap%20III%20Donji%20Milanovac%20485.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Lepenac (Donji Milanovac)', 'Rodinná restaurace s prenocováním leží přímo u Đerdapske magistrály nedaleko Donjeho Milanovace, v srdci národního parku s nádherným výhledem na Dunaj. Specializuje se na čerstvé dunajské ryby, rybí čorbu a grilovaný sýr s domácím teplým chlebem. Restaurace je na Tripadvisoru hodnocena 4,4 a je zde vedena jako nejlepší podnik ve městě – ideální zastávka na oběd uprostřed trasy.', 44.4735, 22.145, 'https://commons.wikimedia.org/wiki/Special:FilePath/Donji%20Milanovac.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Donji%20Milanovac.JPG"}'::text[], 4),
    (v_route, 'Socha Decebala', 'Kolosální skalní reliéf tváře dáckého krále Decebala je s 55 metry nejvyšší skalní sochou v Evropě. Nachází se na rumunské straně Dunaje, ale nejlepší výhled je právě ze srbského břehu a z vody. Zastavte na vyhlídce naproti a vyfotografujte si tuto působivou tvář vytesanou do skály. Přímo naproti přes řeku stojí i Trajanova tabule.', 44.64112, 22.29123, 'https://commons.wikimedia.org/wiki/Special:FilePath/Frontal%20view%20of%20the%20Decebalus%20rock%20sculpture.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Frontal%20view%20of%20the%20Decebalus%20rock%20sculpture.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rock%20Sculpture%20of%20Decebalus%20(26845769043).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Statuia%20lui%20Decebal.jpg"}'::text[], 5),
    (v_route, 'Tabula Traiana', 'Římská pamětní deska vytesaná do skály nad Dunajem připomíná dokončení Trajanovy vojenské cesty soutěskou. Původní nápis byl při stavbě přehrady v roce 1972 vyzvednut výše nad hladinu. Z parkoviště u silnice vede krátká lávka k vyhlídce na tuto téměř dva tisíce let starou památku. Naproti přes řeku uvidíte sochu Decebala.', 44.65694, 22.31228, 'https://commons.wikimedia.org/wiki/Special:FilePath/RC174-Tabula%20Traiana.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/RC174-Tabula%20Traiana.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Traian''s%20Table%20(Tabula%20Traiana).jpg"}'::text[], 6),
    (v_route, 'Přehrada Đerdap', 'Mohutná vodní elektrárna Železná vrata I je největší přehradou na Dunaji a tvoří státní hranici mezi Srbskem a Rumunskem. Její stavba v 70. letech zvedla hladinu řeky a proměnila celou soutěsku. Přehrada je vhodným cílem trasy nedaleko města Kladovo. Fotit samotné těleso elektrárny je kvůli hraničnímu režimu možné jen z dálky.', 44.6713, 22.52941, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wiki.%C4%90erdap%20II%20Iron%20Gate%20I%20hydroelectric%20power%20station%20707.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wiki.%C4%90erdap%20II%20Iron%20Gate%20I%20hydroelectric%20power%20station%20707.jpg"}'::text[], 7);
  insert into public.routes
