  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bosenská pyramida Slunce (Visoko)', 'Zalesněný kopec Visočica, který má nápadně pyramidový tvar a bývá označován za největší pyramidu světa. Vědci ho ale považují za přirozený geologický útvar a Osmanagićovy pyramidy za pseudovědeckou legendu. Ať už mu věříte, nebo ne, výjezd nad Visoko odměňuje motorkáře skvělým rozhledem po údolí. Vezměte si pevnou obuv, chcete-li vyšlapat až nahoru.', 43.9888, 18.1702, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bosnian%20Pyramid.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bosnian%20Pyramid.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Viso%C4%8Dica,%20bosnianska%20pyram%C3%ADda.jpg"}'::text[], 0),
    (v_route, 'Visoko (město)', 'Staré městečko nad řekou Bosnou, historicky centrum středověké bosenské državy a středisko koželužství. Uličky, mešity a tržnice tvoří příjemnou zastávku před nebo po výletu k pyramidám. Dobré místo na kávu a doplnění paliva před cestou do Sarajeva.', 43.98833, 18.17806, 'https://commons.wikimedia.org/wiki/Special:FilePath/Old%20town%20Visoki.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Old%20town%20Visoki.jpg"}'::text[], 1),
    (v_route, 'Sarajevo (Baščaršija)', 'Historické osmanské jádro Sarajeva s dřevěnou kašnou Sebilj, měditepeckou uličkou a vůní ćevapi ve vzduchu. Ideální místo pro nocleh na první den – motorku zaparkujte na okraji staré čtvrti, protože dlážděné uličky jsou pro pěší. Východ i západ slunce nad městem sevřeným v kotlině stojí za to.', 43.8593, 18.4314, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sarajevo-bascarsija%20at%20night1.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sarajevo-bascarsija%20at%20night1.JPG"}'::text[], 2),
    (v_route, 'Jablanické jezero', 'Rozlehlá přehradní nádrž na Neretvě pod městem Konjic, obklopená horami a lákavá tyrkysovou barvou vody. Silnice podél břehu nabízí nekonečné zatáčky a výhledy – ráj pro motorkáře. Cestou najdete stánky s pstruhem a domácím medem. Skvělá zastávka na cestě mezi Sarajevem a Mostarem.', 43.69222, 17.8275, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jablani%C4%8Dko%20jezero%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jablani%C4%8Dko%20jezero%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jablani%C4%8Dko%20Jezero2.jpg"}'::text[], 3),
    (v_route, 'Mostar (Stari Most)', 'Slavný osmanský kamenný most z 16. století, který se klene nad tyrkysovou Neretvou a je zapsán na seznamu UNESCO. Původní most byl za války v roce 1993 zničen a později věrně obnoven. Odvážlivci odsud skáčou do řeky z výšky přes dvacet metrů. Klikatá silnice do Mostaru údolím Neretvy patří k nejhezčím úsekům celé trasy.', 43.3356, 17.8153, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stari%20most%20alte%20Br%C3%BCcke%202004%20Mostar%20Bosnien%20und%20Herzegowina%20Foto%20Wolfgang%20Pehlemann%20IMG%208136.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stari%20most%20alte%20Br%C3%BCcke%202004%20Mostar%20Bosnien%20und%20Herzegowina%20Foto%20Wolfgang%20Pehlemann%20IMG%208136.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/1964-9-22%20Mostar%20-%20Stari%20Most,%20Oude%20brug%20over%20de%20Neretva%20dia%202.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Hindin Han (Mostar)', 'Tradiční hercegovská restaurace v historickém hanu přímo ve staré čtvrti Mostaru, jen pár kroků od Starého mostu, s terasou nad říčkou Radobolja. Servírují bosenské klasiky jako ćevapi, sarmu, plněnou papriku a čerstvého pstruha z Neretvy. Skvělé hodnocení kolem 4,5 hvězdičky a velké porce z ní dělají ideální zastávku na oběd v Mostaru.', 43.3373, 17.8149, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stari%20most%20alte%20Br%C3%BCcke%202004%20Mostar%20Bosnien%20und%20Herzegowina%20Foto%20Wolfgang%20Pehlemann%20IMG%208136.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stari%20most%20alte%20Br%C3%BCcke%202004%20Mostar%20Bosnien%20und%20Herzegowina%20Foto%20Wolfgang%20Pehlemann%20IMG%208136.jpg"}'::text[], 5),
    (v_route, 'Blagaj (Tekija u pramene Buny)', 'Dervišský klášter (tekija) z 16. století, přilepený k obří skalní stěně přímo u vývěru krasové řeky Buny. Jedno z nejfotogeničtějších míst Hercegoviny, kde z jeskyně vyvěrá ledově studená a průzračná voda. Krátká odbočka z hlavní silnice se rozhodně vyplatí, nabízí stín i osvěžení.', 43.2572, 17.8864, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dervish%20House,%20Blagaj%20(45259512482).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dervish%20House,%20Blagaj%20(45259512482).jpg"}'::text[], 6),
    (v_route, 'Počitelj', 'Opevněné osmanské městečko vytesané do svahu nad Neretvou, s věží Kula, mešitou a dlážděnými schodišti. Národní památka a otevřené muzeum, které vypadá jako zastavené v čase. Vyšlápněte k pevnosti pro nádherný výhled na údolí a řeku. Leží přímo u silnice Mostar–Čapljina, takže se snadno zařadí do trasy.', 43.13458, 17.73196, 'https://commons.wikimedia.org/wiki/Special:FilePath/Po%C4%8Ditelj.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Po%C4%8Ditelj.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pocitelj%20Castle.JPG"}'::text[], 7),
    (v_route, 'Vodopády Kravice', 'Mohutný půlkruhový vodopád na řece Trebižat, vysoký kolem 25 metrů, s jezírkem vhodným ke koupání. V létě ideální osvěžující zastávka po horkém dni v sedle. Od Počitelje či Ljubuški sem vede klidná venkovská silnice mimo hlavní tahy. Parkoviště je nad vodopády, dolů se sestupuje pěšky.', 43.15615, 17.60789, 'https://commons.wikimedia.org/wiki/Special:FilePath/Waterfalls%20Kravica%206,%20Bosnia%20and%20Herzegovina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Waterfalls%20Kravica%206,%20Bosnia%20and%20Herzegovina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Slapovi%20Kravice.jpg"}'::text[], 8);
