  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'NP Durmitor (Žabljak)', 'Horské městečko Žabljak je nejvýše položené sídlo na Balkáně a slouží jako brána do národního parku Durmitor zapsaného na seznamu UNESCO. Odsud vyrážíte na okruh a najdete tu poslední spolehlivé čerpací stanice a servis před náročnými horskými úseky. Ideální výchozí bod pro přenocování a rozdělení trasy na dva dny.', 43.15417, 19.12278, 'https://commons.wikimedia.org/wiki/Special:FilePath/Durmitor%20National%20Park%20in%20Montenegro%2006.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Durmitor%20National%20Park%20in%20Montenegro%2006.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Durmitor%20national%20park%20montenegro.jpg"}'::text[], 0),
    (v_route, 'Crno jezero (Černé jezero)', 'Ledovcové Černé jezero leží ve výšce 1416 m jen pár kilometrů od Žabljaku a je symbolem celého Durmitoru. Zrcadlí se v něm okolní vápencové štíty a je to skvělé místo na krátkou zastávku a odpočinek hned na začátku okruhu. K jezeru vede odbočka z hlavní silnice, poslední úsek se dojíždí pěšky.', 43.14556, 19.09889, 'https://commons.wikimedia.org/wiki/Special:FilePath/Crno%20jezero%20(Durmitor).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Crno%20jezero%20(Durmitor).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Durmitor%20-%20Crno%20jezero.jpg"}'::text[], 1),
    (v_route, 'Kaňon řeky Tary', 'Kaňon Tary je nejhlubší kaňon Evropy s hloubkou až 1300 metrů a druhý nejhlubší na světě. Silnice se vine po jeho okraji a nabízí závratné pohledy do hlubiny se smaragdovou řekou. Pro motorkáře jde o jeden z nejúchvatnějších úseků celé trasy, jeďte opatrně kvůli srázům bez svodidel.', 43.1504, 19.29484, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tara%20River%20Canyon.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tara%20River%20Canyon.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kanjon%20reke%20Tare.jpg"}'::text[], 2),
    (v_route, 'Most Đurđevića Tara', 'Betonový obloukový most z roku 1940 překlenuje kaňon Tary ve výšce 172 metrů nad hladinou řeky. Je to jedna z nejfotografovanějších staveb Černé Hory a povinná zastávka na okruhu. U mostu najdete parkoviště, občerstvení i možnost zipline přes kaňon.', 43.1504, 19.29484, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%90ur%C4%91evi%C4%87a%20Tara%20Bridge%20(by%20Pudelek).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%90ur%C4%91evi%C4%87a%20Tara%20Bridge%20(by%20Pudelek).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Montenegro%20%C4%90ur%C4%91evi%C4%87a%20Tara%20Bridge%2004.jpg"}'::text[], 3),
    (v_route, 'Průsmyk Sedlo (P14)', 'Sedlo je s výškou přes 1900 m nejvýše položená zpevněná silnice v Černé Hoře a vrchol panoramatické trasy P14 mezi Žabljakem a Plužine. Serpentiny vedou pod velehorskými štíty Durmitoru včetně nejvyššího vrcholu Bobotov kuk a nabízejí ničím nerušené výhledy. Silnice je úzká a místy jen pro jedno vozidlo, počítejte s pomalou a soustředěnou jízdou.', 43.09846, 19.05033, 'https://commons.wikimedia.org/wiki/Special:FilePath/Durmitor%20-%20Bobotov%20kuk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Durmitor%20-%20Bobotov%20kuk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Durmitor%20National%20Park%20in%20Montenegro%2006.jpg"}'::text[], 4),
    (v_route, 'Pivské jezero', 'Přehradní Pivské jezero má sytě tyrkysovou barvu a silnice kolem něj prochází desítkami tunelů vytesaných přímo do skalní stěny. Jde o jeden z nejefektnějších úseků okruhu, kde se cesta vine vysoko nad hladinou. Buďte opatrní v neosvětlených tunelech a úzkých galeriích.', 43.14667, 18.87556, 'https://commons.wikimedia.org/wiki/Special:FilePath/Piva%20Lake%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Piva%20Lake%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/PivskoJezero%20South.JPG"}'::text[], 5),
    (v_route, 'Klášter Piva', 'Klášter Piva je unikátní tím, že byl při stavbě přehrady kámen po kameni přemístěn na nové místo u vesnice Goransko. Uvnitř se dochovaly cenné fresky ze 16. století. Klidná zastávka stranou hlavní trasy, kde si můžete odpočinout od náročných serpentin.', 43.1101, 18.81838, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manastir%20Piva%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Manastir%20Piva%202.jpg"}'::text[], 6),
    (v_route, 'Nikšić', 'Nikšić je druhé největší město Černé Hory a přirozená křižovatka na jižní straně okruhu. Najdete tu čerpací stanice, motoservisy, restaurace i známý pivovar Trebjesa. Ideální místo na doplnění paliva a oběd před závěrečným návratem horskými silnicemi zpět do Durmitoru.', 42.7731, 18.94446, 'https://commons.wikimedia.org/wiki/Special:FilePath/Freedom%20Square%20in%20Niksic%20as%20seen%20from%20the%20south.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Freedom%20Square%20in%20Niksic%20as%20seen%20from%20the%20south.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Krupac%20Lake%20(Nik%C5%A1i%C4%87%2C%20Montenegro)%2002.jpg"}'::text[], 7),
    (v_route, 'Restaurace: Konoba Portun (Nikšić)', 'Konoba Portun v centru Nikšiće (ulice Njegoševa) patří k nejlépe hodnoceným restauracím města a nabízí poctivou domácí černohorskou a balkánskou kuchyni za příznivé ceny. Na Tripadvisoru má skvělé hodnocení kolem 4,9 z 5 a je opakovaně řazena mezi nejlepší podniky ve městě. Ideální zastávka na oběd před závěrečnou horskou etapou zpět do Durmitoru.', 42.7736, 18.9483, 'https://commons.wikimedia.org/wiki/Special:FilePath/Freedom%20Square%20in%20Niksic%20as%20seen%20from%20the%20south.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Freedom%20Square%20in%20Niksic%20as%20seen%20from%20the%20south.jpg"}'::text[], 8),
    (v_route, 'Klášter Ostrog', 'Pravoslavný klášter Ostrog je doslova vtesaný do svislé skalní stěny ve výšce téměř 900 metrů a patří k nejvýznamnějším poutním místům Balkánu. Přístupová silnice je řada strmých serpentin s omezeným provozem, výhled do údolí Bjelopavliči je ale ohromující. Vhodná zastávka na jižní části okruhu před návratem do hor.', 42.6717, 19.0242, 'https://commons.wikimedia.org/wiki/Special:FilePath/Montenegro%20-%20view%20down%20from%20Ostrog%20monastery.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Montenegro%20-%20view%20down%20from%20Ostrog%20monastery.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ostrog%20gornji%20manastir%202007.jpg"}'::text[], 9);
