  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kotor – staré město a serpentiny (25 vlásenek)', 'Startovní bod okruhu v opevněném starém městě zapsaném na seznamu UNESCO. Hned za městem začíná slavná stará silnice do Njeguši s 25 vlásenkami vytesanými do skály. Každá zatáčka nabízí nový výhled na fjord, ale silnice je úzká a bez svodidel – jeďte opatrně a počítejte s protijedoucími vozidly. Ranní start vám zajistí prázdnější serpentiny a chladnější asfalt.', 42.42067, 18.76825, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kotor%20Old%20Town.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kotor%20Old%20Town.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Architecture%20in%20Old%20Town%20-%20Kotor%20-%20Montenegro%20-%2001.jpg"}'::text[], 0),
    (v_route, 'Vyhlídka nad Boka Kotorskou', 'Zhruba po dvacáté vlásence se dostanete více než 900 metrů nad hladinu a otevře se ikonický panoramatický pohled na celý záliv Boka Kotorská s Kotorem hluboko dole. Ideální místo na zastávku, fotku a odpočinek motoru. Je tu často vítr, dejte pozor na parkování na úzké krajnici.', 42.40905, 18.76932, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kotor%20and%20Boka%20kotorska%20-%20view%20from%20city%20wall.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kotor%20and%20Boka%20kotorska%20-%20view%20from%20city%20wall.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Boka%20kotorska%20-%20view%20from%20Kotor%20city%20wall.jpg"}'::text[], 1),
    (v_route, 'Njeguši', 'Horská vesnice ve výšce kolem 850 m, rodiště dynastie Petrovićů a domov proslulého uzeného pršutu Njeguški pršut a domácího sýra. Ideální zastávka na svačinu uprostřed okruhu, než se pustíte do Národního parku Lovćen. Silnice sem je klidnější a plná plynulých zatáček.', 42.4331, 18.8283, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20over%20Njegusi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/View%20over%20Njegusi.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Konoba Batrićević (Njeguši)', 'Rodinná uzenářská konoba přímo v Njeguši s bílou budovou a verandou s výhledem do kraje. Servírují domácí Njeguški pršut, domácí sýr a medovinu z fermentovaného medu – ideální zastávka v polovině okruhu. Na Tripadvisoru drží skvělé hodnocení 5,0 z 5, takže o kvalitě není pochyb.', 42.4331, 18.8283, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20over%20Njegusi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/View%20over%20Njegusi.jpg"}'::text[], 3),
    (v_route, 'Národní park Lovćen – Njegošovo mauzoleum', 'Mauzoleum vládce a básníka Petara II. Petroviće-Njegoše stojí na vrcholu Jezerski vrh ve výšce 1 657 m. K mauzoleu vede 461 schodů a odměnou je kruhový výhled na hory i moře, za jasného dne prý až do Itálie. Cesta parkem je klikatá a chladnější – vezměte si vrstvu navíc.', 42.39972, 18.83763, 'https://commons.wikimedia.org/wiki/Special:FilePath/Njego%C5%A1ev%20mauzolej.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Njego%C5%A1ev%20mauzolej.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Jezerski%20vrh%20na%20Lovcenu%20-%20Njegosev%20mauzolej%2010.jpg"}'::text[], 4),
    (v_route, 'Cetinje', 'Stará královská metropole Černé Hory s klášterem, muzei a bývalými vyslanectvími z časů knížectví. Klidné historické město je vhodné na oběd a protažení nohou v polovině trasy. Odtud se stáčíte zpět směrem k pobřeží po plynulých horských silnicích.', 42.3931, 18.9116, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cetinjski%20manastir.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cetinjski%20manastir.jpg"}'::text[], 5),
    (v_route, 'Budva – staré město', 'Rušné pobřežní letovisko s hradbami obklopeným středověkým Starým Městem a živou riviérou. Nejjižnější bod okruhu, kde se dá vychutnat moře a kavárny před návratem do zálivu. Pozor na hustý provoz a nedostatek parkování v hlavní sezóně.', 42.28639, 18.84, 'https://commons.wikimedia.org/wiki/Special:FilePath/Budva%20stari%20grad%20nocu%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Budva%20stari%20grad%20nocu%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Budva,%20view%20from%20Gospostina.jpg"}'::text[], 6),
    (v_route, 'Perast a ostrov Gospa od Škrpjela', 'Půvabné barokní městečko u vody s dvěma ostrůvky – umělým Gospa od Škrpjela s kostelem Panny Marie na útesu a přírodním Sveti Đorđe. Na ostrov se dostanete lodičkou z nábřeží, motorku necháte u silnice. Cesta podél zálivu do Perastu patří k nejmalebnějším úsekům celého okruhu.', 42.4863, 18.6989, 'https://commons.wikimedia.org/wiki/Special:FilePath/1%20perast%20aerial%202016.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/1%20perast%20aerial%202016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gospa%20od%20Skrpjela%20otocic%20sveti%20Dorde%20Perast%20Kotor.jpg"}'::text[], 7);
