  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Ohrid – Sveti Jovan Kaneo', 'Ikonický kostelík svatého Jana na útesu nad Ochridským jezerem je nejfotogeničtějším místem celého regionu a skvělým startem okruhu. Zaparkujte moto ve staré části Ohridu a projděte se dlážděnými uličkami k útesu. Za rozbřesku i při západu slunce nabízí nezapomenutelné výhledy na jezero.', 41.11445, 20.80122, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sveti%20Jovan%20-%20Kaneo%20Ohrid%20oddaleku.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sveti%20Jovan%20-%20Kaneo%20Ohrid%20oddaleku.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sv%20Jovan%20Bogoslov%20Kaneo,%20Ohrid,%20Macedonia.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Iglesia%20San%20Juan%20Kaneo,%20Ohrid,%20Macedonia,%202014-04-17,%20DD%2025.JPG"}'::text[], 0),
    (v_route, 'Ochridské jezero', 'Jedno z nejstarších a nejhlubších jezer Evropy, zapsané na seznamu UNESCO, lemuje značná část trasy. Silnice podél břehu jsou klidné a plné výhledů na tyrkysovou hladinu s horami v pozadí. Ideální na zastávku u vody a osvěžení během horkého dne.', 41.06, 20.71, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20d''Ohrid%20panorama.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20d''Ohrid%20panorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Ohrid%20Macedonia%20(3940275284).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Ohrid%20I%20(73198761).jpeg"}'::text[], 1),
    (v_route, 'NP Galičica – silnice nad jezerem', 'Horská silnice P504 stoupá serpentinami do Národního parku Galičica mezi Ochridským a Prespanským jezerem. Z hřebene uvidíte obě jezera najednou – jde o jeden z nejlepších motorkářských zážitků v zemi. Povrch je místy hrbolatý a bez svodidel, jeďte proto opatrně a vychutnejte si každou zatáčku.', 41.1035, 20.8572, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ohridsko%20krajbrezje%20pod%20Galicica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ohridsko%20krajbrezje%20pod%20Galicica.jpg"}'::text[], 2),
    (v_route, 'Sveti Naum (klášter)', 'Klášter z 10. století stojí na skále na jižním cípu jezera těsně u albánských hranic. Kolem tryskají krasové prameny, které napájejí jezero, a po areálu se procházejí pávi. Je to klidná zastávka na oběd s výhledem na vodu a horské pozadí.', 40.9139, 20.74047, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sveti%20Naum%20Ohridski.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sveti%20Naum%20Ohridski.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%B2%20%D0%9D%D0%B0%D1%83%D0%BC.JPG"}'::text[], 3),
    (v_route, 'Restaurace: Kaneo Restaurant (Ohrid)', 'Rybí restaurace přímo na břehu jezera pod kostelíkem Sveti Jovan Kaneo, proslulá čerstvým ochridským pstruhem a jedinečným výhledem na hladinu. Hosté ji dlouhodobě řadí mezi nejlépe hodnocené podniky v Ohridu (kolem 4,5 hvězdy) díky kvalitní kuchyni a poloze u vody. Ideální zastávka na oběd na začátku i konci okruhu.', 41.1141, 20.8018, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sveti%20Jovan%20-%20Kaneo%20Ohrid%20oddaleku.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sveti%20Jovan%20-%20Kaneo%20Ohrid%20oddaleku.JPG"}'::text[], 4),
    (v_route, 'Bitola', 'Druhé největší město Makedonie proslulé pěší třídou Široko Sokak a rakousko-uherskou architekturou konzulů. Po horských úsecích je to příjemné město na kávu, jídlo a přenocování. Nedaleko leží antické město Heraclea Lyncestis s mozaikami, které stojí za odbočku.', 41.03143, 21.33474, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sirok%20Sokak,%20Bitola,%20Republic%20of%20Macedonia,%20summer%202011.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sirok%20Sokak,%20Bitola,%20Republic%20of%20Macedonia,%20summer%202011.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bitola-Sirok%20sokak.JPG"}'::text[], 5),
    (v_route, 'Restaurace: Gradska Kafeana (Bitola)', 'Tradiční makedonská kavárna a restaurace na třídě Široko Sokak, v Bitole legendární a dlouhodobě vysoce hodnocená (kolem 4,5 hvězdy). Nabízí domácí balkánskou kuchyni, čerstvé speciality z grilu a příjemnou atmosféru přímo v centru města. Skvělá volba na jídlo a oddech ve zhruba polovině okruhu.', 41.0316, 21.3347, 'https://commons.wikimedia.org/wiki/Special:FilePath/Clock%20tower%20in%20Bitola,%20Macedonia.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Clock%20tower%20in%20Bitola,%20Macedonia.JPG"}'::text[], 6),
    (v_route, 'NP Mavrovo (jezero)', 'Horské jezero ve výšce přes 1200 m je srdcem Národního parku Mavrovo a v létě láká na svěží horský vzduch. Z hladiny vyčnívá napůl potopený kostel svatého Mikuláše – jedinečný motiv na fotku z moto výletu. Okolní silnice vedou hlubokými lesy a jsou v létě příjemně chladné.', 41.6295, 20.748, 'https://commons.wikimedia.org/wiki/Special:FilePath/Submerged%20church%20of%20St.%20Nicholas%20(Mavrovo).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Submerged%20church%20of%20St.%20Nicholas%20(Mavrovo).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mavrovo%20lake%20church%20summer%20(cropp).jpg"}'::text[], 7),
    (v_route, 'Klášter Sveti Jovan Bigorski', 'Působivý klášter zavěšený na svahu nad údolím řeky Radiky je proslulý ručně vyřezávaným dřevěným ikonostasem, jedním z nejkrásnějších na Balkáně. Leží přímo u silnice Debar–Gostivar, takže se dá snadno zastavit. Klidné prostředí a výhled do kaňonu z něj dělají povinnou zastávku.', 41.62194, 20.61167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monastery%20Sveti%20Jovan%20Bigorski%20Church.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monastery%20Sveti%20Jovan%20Bigorski%20Church.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Monastery%20Sveti%20Jovan%20Bigorski,%20Macedonia%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Monastery%20Sveti%20Jovan%20Bigorski,%20Macedonia%20(5).JPG"}'::text[], 8),
    (v_route, 'Vodopád Duf / Rostuše', 'Vodopád Duf padá do skalnatého kaňonu nad vesnicí Rostuše na úpatí hory Dešat. Moto nechte ve vsi a dojděte pěší stezkou podél potoka až k padající vodě. Je to osvěžující finále horské části okruhu, než se vydáte zpět k Ohridu.', 41.60331, 20.59483, 'https://commons.wikimedia.org/wiki/Special:FilePath/Duf%20Waterfalls%20in%20Rostu%C5%A1e%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duf%20Waterfalls%20in%20Rostu%C5%A1e%201.JPG"}'::text[], 9);
