  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Shkodër – hrad Rozafa', 'Startovní bod trasy nad městem Shkodër, kde se nad soutokem řek Buna a Drin tyčí na skalnatém kopci ilyrský hrad Rozafa. Od hradeb je nádherný rozhled na Skadarské jezero i na siluetu Albánských Alp, kam se vydáte. Zaparkujte motorku dole a vystoupejte pěšky – je to ideální rozehřátí před náročnými horskými cestami.', 42.0468, 19.4983, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalaja%20e%20Rozafes,%20Shkoder%202.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kalaja%20e%20Rozafes,%20Shkoder%202.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rozafa%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozafat%20-%20Shkoder,%20Albania.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Arti''Zanave (Shkodër)', 'Útulná restaurace v centru Shkodru v uličce u pěší zóny, kde ochutnáte tradiční albánskou kuchyni z místních surovin. Na Tripadvisoru má skvělé hodnocení 4,7 a patří k nejlépe hodnoceným podnikům ve městě. Výtěžek navíc podporuje ženy v nouzi, takže dobrý oběd před cestou do hor tady dává i smysl.', 42.0685, 19.5127, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rruga%20Kol%C3%AB%20Idromeno,%20Shkod%C3%ABr.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rruga%20Kol%C3%AB%20Idromeno,%20Shkod%C3%ABr.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pedonalja%20Shkod%C3%ABr.jpg"}'::text[], 1),
    (v_route, 'Theth – kostel v horách', 'Bílý kamenný kostel Kisha e Thethit je symbolem odlehlé vysokohorské vesnice Theth uprostřed Prokletije. Cesta sem ze Shkodru je dlouhá a rozbitá, místy štěrková, ale odměnou je jedinečná horská atmosféra a ideální místo na první nocleh. Ve vesnici najdete guesthousy s domácí kuchyní a klidem bez davů.', 42.38944, 19.78166, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kisha%20e%20Thethit.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kisha%20e%20Thethit.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kisha%20e%20Thethit%203.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kisha%20e%20Thethit,%202023.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Thethi Paradise (Theth)', 'Rodinná horská restaurace přímo v Thethu s výhledem na okolní štíty Albánských Alp a domácí albánskou kuchyní z čerstvých místních surovin. Na Tripadvisoru boduje s výborným hodnocením 4,9 a patří k nejlépe hodnoceným místům ve vesnici. Ideální zastávka na vydatnou večeři po náročném prvním dni v sedle.', 42.393, 19.771, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kisha%20e%20Thethit%20-%202018%20(2).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kisha%20e%20Thethit%20-%202018%20(2).jpg"}'::text[], 3),
    (v_route, 'Vodopád Grunas (NP Theth)', 'Zhruba 30 metrů vysoký vodopád Grunas je nejznámější přírodní scenérií Národního parku Theth. Motorku necháte ve vesnici a k vodopádu vede pěší stezka kaňonem, která je odměnou za náročnou jízdu do hor. Chladná tříšť a šum vody jsou ideální pauzou po prašných cestách.', 42.3782, 19.775, 'https://commons.wikimedia.org/wiki/Special:FilePath/Waterfall%20of%20Grunas%20in%20Theth.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Waterfall%20of%20Grunas%20in%20Theth.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Theth,%20Grunas%20%E2%80%93%20Grunas%20Waterfall%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grunas%20Wasserfall%20Theth.jpg"}'::text[], 4),
    (v_route, 'Modré oko Theth (Syri i Kaltër)', 'Křišťálově čistý pramen s ledově modrou vodou ukrytý v horách jižně od Thethu, nedaleko vesničky Kaprre. Přístupová cesta je hrbolatá a poslední úsek se jde pěšky, takže se sem hodí pevná obuv. Voda má i v létě jen pár stupňů, ale barva stojí za každý kilometr rozbité cesty.', 42.35354, 19.77026, 'https://commons.wikimedia.org/wiki/Special:FilePath/Syri%20kalter%20theth.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Syri%20kalter%20theth.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Syri%20i%20Kalter%20Theth.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Syri%20i%20Kalt%C3%ABr,%20Theth%20(3).jpg"}'::text[], 5),
    (v_route, 'Qafa e Thorës (horský průsmyk)', 'Vysokohorský průsmyk ve výšce kolem 1680 m spojuje údolí Theth a Valbona a je nejnáročnějším úsekem celé trasy. Cesta je úzká, plná serpentin, štěrku a míst bez svodidel nad prudkými srázy – vyžaduje soustředění a pomalé tempo. Z vrcholu se otevírá dechberoucí panorama štítů Albánských Alp, které patří k vrcholům celé cesty.', 42.415, 19.805, 'https://commons.wikimedia.org/wiki/Special:FilePath/Buni%20i%20Thores.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Buni%20i%20Thores.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20road%20to%20Theth.jpg"}'::text[], 6),
    (v_route, 'Valbona (údolí, národní park)', 'Ledovcové údolí řeky Valbona v srdci stejnojmenného národního parku uchvátí širokým bílým korytem a strmými vápencovými štíty. Po přejezdu průsmyku je to ideální místo na oddech a druhý nocleh v některém z horských penzionů. Prašné cesty údolím lákají k pomalé jízdě s častým zastavením na fotky.', 42.452, 19.886, 'https://commons.wikimedia.org/wiki/Special:FilePath/Valbona%20Valley%20National%20Park,%20North%20Albania.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Valbona%20Valley%20National%20Park,%20North%20Albania.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Valbona%20Valley,%20Tropoj%C3%AB,%20Albania%202018%2005.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Valbona%20Valley,%20Tropoj%C3%AB,%20Albania%202018%2013.jpg"}'::text[], 7),
    (v_route, 'Fierza (trajekt přes jezero)', 'Malá osada Fierza u přehradní nádrže na řece Drin je nástupním bodem pro slavný trajekt přes jezero Koman. Motorku najedete přímo na palubu lodi, což je jediný rozumný způsob, jak se vyhnout dlouhé objížďce. Sem se dostanete od Valbony po klikaté horské silnici, počítejte s časovou rezervou před odplutím.', 42.2569, 20.025, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fierze-Dam-2018.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fierze-Dam-2018.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fierza.jpg"}'::text[], 8),
    (v_route, 'Koman – jezero a trajekt', 'Jezero Koman je umělá nádrž sevřená strmými kaňonovými stěnami, přezdívaná albánské fjordy. Přeprava trajektem z Fierzy sem trvá zhruba tři hodiny a nabízí jedny z nejkrásnějších výhledů celé cesty. Od přístaviště u přehrady pak pokračujete zpět do Shkodru po horské silnici – závěr celého okruhu.', 42.10325, 19.82238, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Komani1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Komani1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Komani%20lake.jpg"}'::text[], 9);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Meteora – kláštery nad Kalambakou', 'Kláštery zavěšené na vrcholcích obřích pískovcových věží patří k nejfotografovanějším místům Řecka a jsou ideálním startem okruhu. Silnice mezi kláštery je úzká, plná zatáček a vyhlídek, kde se motorka doslova prodírá skalním městem. Zaparkujte pod věžemi v Kalambace a nechte si čas na procházku alespoň k jednomu z klášterů.', 39.72173, 21.63047, 'https://commons.wikimedia.org/wiki/Special:FilePath/Greece%20meteora%20monasteries.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Greece%20meteora%20monasteries.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Meteora%20-%20Kalambaka%20-%20Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Meteora%20Main%20Monastery.jpg"}'::text[], 0),
    (v_route, 'Průsmyk Katara', 'Historický průsmyk ve výšce kolem 1705 m je jedním z nejvýše položených silničních přejezdů Řecka a spojuje Thesálii s Epirem. Stará silnice přes Kataru nabízí serpentiny, horské panorama a chladný vzduch i uprostřed léta – vyhnete se tak dálničnímu tunelu Egnatia. Jeďte opatrně, povrch bývá místy hrbolatý a mlha přichází rychle.', 39.79, 21.26667, 'https://commons.wikimedia.org/wiki/Special:FilePath/Katara%20Pass%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Katara%20Pass%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Katara%20Pass%203.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Katara%20Pass%205.JPG"}'::text[], 1),
    (v_route, 'Metsovo', 'Kamenné horské městečko roztroušené po svazích Pindosu je proslulé svou architekturou, sýrem a vřelou pohostinností. Náměstí s kavárnami je ideální zastávkou na kávu a odpočinek po přejezdu Katary. Uzoučké dlážděné uličky a výhledy do údolí dělají z Metsova jedno z nejmalebnějších míst celé trasy.', 39.77025, 21.18286, 'https://commons.wikimedia.org/wiki/Special:FilePath/Metsovo%20overview%20bgiu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Metsovo%20overview%20bgiu.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Metsovo%20Frourion%20Square.jpg"}'::text[], 2),
    (v_route, 'Restaurace: To Koutouki tou Nikola (Metsovo)', 'Oblíbená tradiční taverna přímo v Metsovu je ideální zastávkou na oběd po přejezdu průsmyku Katara. Vaří poctivou epirskou kuchyni – místní sýry, grilované maso a domácí pitu – a hosté ji na TripAdvisoru hodnotí skvělou známkou kolem 4,5. Vřelá pohostinnost a horské speciality z ní dělají jeden z nejlépe hodnocených podniků na celé trase.', 39.7702, 21.1826, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20main%20square%20in%20Metsovo,Hpeiros.Greece.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20main%20square%20in%20Metsovo,Hpeiros.Greece.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Metsovo%20overview%20bgiu.jpg"}'::text[], 3),
    (v_route, 'Ioannina – jezero Pamvotida', 'Hlavní město Epiru leží na břehu klidného jezera Pamvotida s malým ostrůvkem uprostřed. Osmanská pevnost, mešita a promenáda kolem vody nabízejí příjemnou pauzu a dobré jídlo. Silnice podél jezera je rovinatější, takže poslouží jako oddech mezi horskými úseky.', 39.6649, 20.8519, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ioannina,%20Lake%20Pamvotis%20and%20Fethiye%20Mosque.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ioannina,%20Lake%20Pamvotis%20and%20Fethiye%20Mosque.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ali%20Pasha%27s%20tomb,%20Fethiye%20Mosque,%20Ioannina,%20September%202022.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Presveía (Ioannina)', 'Restaurace Presveía leží u jezera Pamvotida v Ioannině a nabízí přímý výhled na vodní hladinu. Servíruje středomořskou a řeckou kuchyni s pestrým výběrem a hosté ji na TripAdvisoru chválí skvělým hodnocením kolem 4,6. Klidná poloha u břehu jezera z ní dělá příjemnou zastávku na jídlo v polovině okruhu.', 39.6669, 20.8514, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ioannina,%20Lake%20Pamvotis%20and%20Fethiye%20Mosque.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ioannina,%20Lake%20Pamvotis%20and%20Fethiye%20Mosque.JPG"}'::text[], 5),
    (v_route, 'Zagori – Zagorochoria', 'Zagorochoria je síť sedmačtyřiceti tradičních kamenných vesnic propojených úzkými horskými cestami, které jsou přímo stvořené pro motorku. Kamenné domy, klenuté brány a lesnaté svahy vytvářejí kulisu jako z jiného století. Jezděte pomalu – cesty jsou úzké, klikaté a často jimi procházejí stáda ovcí a koz.', 39.8756, 20.78, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kipoi%20Bagia%20Zagori%20village.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kipoi%20Bagia%20Zagori%20village.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/GR-zagoria-dorf.jpg"}'::text[], 6),
    (v_route, 'Soutěska Vikos – vyhlídka Oxya', 'Vikos je jednou z nejhlubších soutěsek na světě a vyhlídka Oxya nabízí závratný pohled do její propasti až 900 metrů hluboké. Krátká odbočka od Monodendri končí u kamenné zídky na okraji srázu, odkud je výhled nezapomenutelný. Zaparkujte motorku a posledních pár metrů dojděte pěšky až na skalní ostroh.', 39.9066, 20.75166, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zagori%20Vikos%20gorge%20Oxia%20towards%20Vikos.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zagori%20Vikos%20gorge%20Oxia%20towards%20Vikos.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vikos-Schlucht,%20Oxia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vikos%20Gorge.jpg"}'::text[], 7),
    (v_route, 'Kamenné mosty Zagori (Kokkori a Plakidas)', 'Obloukové kamenné mosty z 18. a 19. století jako Kokkori (Noutsos) a trojobloukový Plakidas (Kalogeriko) patří k symbolům Zagori. Dokonale zapadají do divoké krajiny a klenou se nad bystřinami poblíž vesnice Kipi. Jsou skvělým místem na zastávku a fotku motorky na pozadí historického mostu.', 39.8756, 20.7947, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bridge%20of%20Kokkori%20or%20Noutsos.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bridge%20of%20Kokkori%20or%20Noutsos.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Old%20Bridge%20Kalogeriko.jpg"}'::text[], 8),
    (v_route, 'Tzoumerka', 'Masiv Tzoumerka (Athamanika) na jihu Pindosu láká na divoké vrcholy, vodopády a soutěsku řeky Arachthos. Horské silnice sem vedou přes odlehlé kamenné vesnice a nabízejí prázdné serpentiny s minimem provozu. Je to důstojné zakončení okruhu pro ty, kdo chtějí ještě porci pravého horského ježdění mimo turistické trasy.', 39.53, 21.1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tzoumerka.jpeg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tzoumerka.jpeg","https://commons.wikimedia.org/wiki/Special:FilePath/Athamanika.jpg"}'::text[], 9);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Novaci (jižní start)', 'Městečko Novaci v župě Gorj je jižní branou Transalpiny a ideálním místem k natankování a poslednímu kávovému zastavení před stoupáním. Odsud silnice DN67C okamžitě začíná šplhat do Parângu. Zkontroluj počasí i stav nádrže – dál nahoře už čerpací stanice nejsou. Užij si klidný rozjezd, než přijdou první serpentiny.', 45.18683, 23.66887, 'https://commons.wikimedia.org/wiki/Special:FilePath/Novaci.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Novaci.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/RO%20GJ%20Novaci-Romani%20church%208.jpg"}'::text[], 0),
    (v_route, 'Rânca (horské středisko)', 'Horské středisko Rânca leží ve výšce kolem 1600 m a je oblíbenou zastávkou motorkářů. Odsud začíná nejkrásnější a nejtechničtější část stoupání s množstvím zatáček a výhledů do údolí. V sezóně tu najdeš penziony i občerstvení. Dej si pauzu, protáhni se a nasaď teplejší vrstvu – nahoře bude chladněji.', 45.29134, 23.68893, 'https://commons.wikimedia.org/wiki/Special:FilePath/Winter%20Ski%20Resort%20Ranca%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Winter%20Ski%20Resort%20Ranca%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ranca%20Ptuj%2001.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Restaurant Tara (Rânca)', 'Restaurant Tara stojí přímo u Transalpiny nad Rânkou a je jednou z nejlépe hodnocených zastávek na celé trase – na Tripadvisoru drží skvělé hodnocení 4,9 z 5. Kuchyně je rumunská i mezinárodní, ochutnej tradiční sarmale nebo mămăligu na prostorné terase s výhledem na hory Parâng. Je to ideální místo na oběd zhruba v polovině stoupání, než vyrazíš k průsmyku Urdele.', 45.299662, 23.680778, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ranca%20Ptuj%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ranca%20Ptuj%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Winter%20Ski%20Resort%20Ranca%20-%20panoramio.jpg"}'::text[], 2),
    (v_route, 'Průsmyk Urdele (Pasul Urdele, 2145 m)', 'Pasul Urdele ve výšce 2145 m je nejvyšší bod Transalpiny i celé rumunské silniční sítě. Serpentiny nad hranicí lesa nabízejí dechberoucí panoramata Parângu. Vozovka je úzká a počasí se mění během minut, proto jeď opatrně a počítej s mlhou i větrem. Je to vrcholný zážitek celé trasy – zastav se na fotku.', 45.3443, 23.65807, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pasul%20Urdele,%20Transalpina%20(2024-08-20%201).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pasul%20Urdele,%20Transalpina%20(2024-08-20%201).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pasul%20Urdele,%20Transalpina%20(2024-08-20%202).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/RO%20GJ%20DN67C%20Transalpina%207.jpg"}'::text[], 3),
    (v_route, 'Obârșia Lotrului', 'Obârșia Lotrului je horská křižovatka ve výšce zhruba 1400 m, kde se setkává několik pohoří a řeka Lotru. Najdeš tu penziony a možnost odpočinku po náročném sjezdu z průsmyku. Je to dobré místo na doplnění energie a krátkou pauzu. Odsud pokračuje trasa dál severním směrem k jezerům.', 45.43516, 23.63025, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lotru%20River%20in%20Ob%C3%A2r%C8%99ia%20Lotrului.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lotru%20River%20in%20Ob%C3%A2r%C8%99ia%20Lotrului.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Obarsia%20Lotrului%202016%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Obarsia%20Lotrului%202016%20(2).jpg"}'::text[], 4),
    (v_route, 'Přehrada Vidra (Lacul Vidra)', 'Přehradní jezero Vidra na řece Lotru leží ve výšce okolo 1265 m a nabízí nádherné výhledy na klidnou vodní hladinu obklopenou horami. Silnice tu vede podél břehu a je to ideální místo na fotozastávku. V okolí je středisko Voineasa. Vychutnej si klidnější tempo mezi zatáčkami.', 45.43317, 23.72193, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Vidra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Vidra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Vidra%20-%20panoramio%20(2).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Vidra%20-%20panoramio%20(3).jpg"}'::text[], 5),
    (v_route, 'Jezero Oașa (Lacul Oașa)', 'Jezero Oașa je přehradní nádrž na řece Sebeș ve výšce zhruba 1255 m na pomezí žup Alba a Sibiu. Silnice DN67C vede přes hráz a obtáčí jezero v pohoří Șureanu. Křišťálová voda mezi jehličnany a masiv Vârful lui Pătru v pozadí patří k nejfotogeničtějším místům severní části trasy. Krátká pauza tu opravdu stojí za to.', 45.56194, 23.61639, 'https://commons.wikimedia.org/wiki/Special:FilePath/Varfu%20lui%20patru.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Varfu%20lui%20patru.jpg"}'::text[], 6),
    (v_route, 'Sugag', 'Obec Sugag v župě Alba leží v údolí řeky Sebeș a značí, že už sjíždíš z hor do civilizace. Zatáčky se zde zklidňují a krajina přechází v mírnější kopce a lesy. Je to vhodné místo na doplnění paliva a občerstvení. Odsud pokračuje trasa k Săliște a Sebeși.', 45.76667, 23.63333, 'https://commons.wikimedia.org/wiki/Special:FilePath/RO%20AB%20Sugag.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/RO%20AB%20Sugag.jpg"}'::text[], 7),
    (v_route, 'Săliște', 'Malebné městečko Săliște v regionu Mărginimea Sibiului je tradičním severním zakončením zážitku z Transalpiny poblíž Sebeși. Po dni v horách si tu můžeš odpočinout, projít historické centrum a ochutnat místní kuchyni. Silnice tu už je pohodová a klidná. Skvělé místo na tečku za celodenní jízdou.', 45.7945, 23.8748, 'https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20%22Sfanta%20Treime%22%20sat%20VALE%20,oras%20Saliste,Jud%20Sibiu.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20%22Sfanta%20Treime%22%20sat%20VALE%20,oras%20Saliste,Jud%20Sibiu.JPG"}'::text[], 8);
