  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Chișinău – katedrála Narození Páně', 'Klasicistní pravoslavná katedrála se samostatnou zvonicí stojí v srdci hlavního města a je přirozeným startem trasy. Kolem katedrály se dá pohodlně zaparkovat a nabrat občerstvení před cestou na venkov. Bílá stavba s modrými kopulemi je příjemným kontrastem k venkovským klášterům dále na trase.', 47.02606, 28.83451, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nativity%20Cathedral,%20Chi%C8%99in%C4%83u.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nativity%20Cathedral,%20Chi%C8%99in%C4%83u.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Moldova%20Chisineu%20Cathedral%20Nasterea%20Domnului.jpg"}'::text[], 0),
    (v_route, 'Restaurace: La Plăcinte (Kišiněv)', 'Oblíbená síť tradičních moldavských restaurací La Plăcinte v centru Kišiněva je ideální zastávkou na začátku okruhu. Servírují domácí plăcinte, sarmale i mămăligu z čerstvých surovin a těší se skvělému hodnocení kolem 4,7–4,8 hvězdičky. Přátelská obsluha a rozumné ceny z ní dělají spolehlivý start dvoudenní cesty.', 47.02342, 28.83227, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chisinau%20Center.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chisinau%20Center.jpg"}'::text[], 1),
    (v_route, 'Orheiul Vechi', 'Skalní klášter vytesaný do vápencového srázu nad meandrem řeky Răut je nejfotogeničtějším místem Moldavska. Zaparkujte motorku dole a vystoupejte pěšky k pravoslavné kapli s výhledem na zákruty řeky. Okolní venkovské silnice bez provozu jsou samy o sobě zážitkem a ideálně navazují na klidné tempo výletu.', 47.30583, 28.97694, 'https://commons.wikimedia.org/wiki/Special:FilePath/Crucea%20de%20piatra%20de%20la%20Orheiul%20Vechi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Crucea%20de%20piatra%20de%20la%20Orheiul%20Vechi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Orheiul%20Vechi%20panorama.jpg"}'::text[], 2),
    (v_route, 'Curchi', 'Klášterní komplex Curchi s nápadnou žlutobílou katedrálou patří k architektonickým skvostům země a leží uprostřed lesů Orheiského regionu. Přístupová cesta vede klidnou zvlněnou krajinou ideální pro motorkáře. Ohrada kláštera nabízí stín a klid k odpočinku v polovině trasy.', 47.33389, 28.65389, 'https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20m%C4%83n%C4%83stirii.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20m%C4%83n%C4%83stirii.JPG"}'::text[], 3),
    (v_route, 'Saharna', 'Poutní klášter Nejsvětější Trojice je zasazen do skalnaté rokle s řadou vodopádů a peřejí podél říčky Saharna. Krátká pěší túra vede k nejznámějšímu kaskádu a k legendární stopě v kameni. Jedno z nejvýznamnějších poutních míst Moldavska a osvěžující přírodní zastávka blízko Dněstru.', 47.68361, 28.97028, 'https://commons.wikimedia.org/wiki/Special:FilePath/M%C4%83n%C4%83stirea%20Sf.%20Treime%20din%20Saharna.%20M%C4%83n%C4%83stirea%20rupestr%C4%83--vedere%20paralel%C4%83%20cu%20st%C3%A2nca.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/M%C4%83n%C4%83stirea%20Sf.%20Treime%20din%20Saharna.%20M%C4%83n%C4%83stirea%20rupestr%C4%83--vedere%20paralel%C4%83%20cu%20st%C3%A2nca.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Saharna,%20cascada.jpg"}'::text[], 4),
    (v_route, 'Soroca', 'Dokonale zachovalá kruhová pevnost z počátku 16. století stojí přímo na břehu Dněstru u ukrajinské hranice. Je nejsevernějším bodem trasy a odměnou za dlouhou jízdu venkovskými silnicemi. Z hradeb je hezký výhled na řeku a okolní kopce, kde se tyčí i známý Svíčka vděčnosti.', 48.15672, 28.30328, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Soroca.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Soroca.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Inside%20the%20Soroca%20fortress.jpg"}'::text[], 5),
    (v_route, 'Cricova', 'Podzemní vinné město Cricova ukrývá desítky kilometrů chodeb, jimiž se dá projet i autem. Prohlídku absolvujte bez motorky, na povrchu je hlídané parkoviště. Jde o jedny z nejznámějších sklepů světa a příjemnou zastávku před závěrem okruhu – ochutnávku ale nechte na řidiče až po dojezdu.', 47.133, 28.85, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cricova%20Wine%20Cellar%20Collection.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cricova%20Wine%20Cellar%20Collection.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Combinatul%20de%20Vinuri%20%E2%80%9DCricova%E2%80%9D%20S.A..jpg"}'::text[], 6),
    (v_route, 'Mileștii Mici', 'Největší vinný sklep světa zapsaný v Guinnessově knize rekordů skrývá přes 200 kilometrů galerií a téměř dva miliony lahví. Motorku odstavte u vstupu a podzemím vás provezou autem. Konstantní teplota kolem 12 stupňů je příjemným ochlazením po dni v sedle. Skvělá tečka za dvoudenní jízdou Moldavskem.', 46.92092, 28.82055, 'https://commons.wikimedia.org/wiki/Special:FilePath/Caves%20Milestii%20Mici%20Moldavie.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Caves%20Milestii%20Mici%20Moldavie.jpg"}'::text[], 7);
