  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Klaipėda – staré město', 'Bývalý německý Memel vás uvítá dlážděnými uličkami, hrázděnými domy a přístavní atmosférou u řeky Dané. Zaparkujte motorku a projděte se k Divadelnímu náměstí s fontánou Simona Dacha a sochou Ännchen von Tharau. Je to ideální startovní bod před cestou na kosu – dají se tu doplnit síly i najít mnoho útulných kaváren.', 55.7033, 21.14428, 'https://commons.wikimedia.org/wiki/Special:FilePath/Klaip%C3%A9da%20Theaterplatz%20Simon-Dach-Brunnen.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Klaip%C3%A9da%20Theaterplatz%20Simon-Dach-Brunnen.JPG"}'::text[], 0),
    (v_route, 'Restaurace: Momo Grill (Klaipėda)', 'Malý, ale vyhlášený grill restaurant v centru Klaipėdy, kde mistrně připravují maso i ryby přímo z grilu. Hodnocení 4,7 z 5 na Tripadvisoru i Googlu ho řadí mezi úplnou špičku ve městě. Ideální místo, kde se před cestou na kosu pořádně najíst v příjemné, elegantní atmosféře.', 55.7089, 21.1352, 'https://commons.wikimedia.org/wiki/Special:FilePath/Klaip%C3%A9da%20Theaterplatz%20Simon-Dach-Brunnen.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Klaip%C3%A9da%20Theaterplatz%20Simon-Dach-Brunnen.JPG"}'::text[], 1),
    (v_route, 'Trajekt na Kurskou kosu', 'Na Kurskou kosu se autem ani motorkou jinak než trajektem nedostanete – přeprava přes Kuronskou lagunu ze Smiltynė je zážitek sama o sobě. Automobilový trajekt vyjíždí z Naujoji perkėla a přeprava motorky trvá jen pár minut. Postavte se s mašinou k zábradlí a užijte si výhled na klaipėdský přístav i písečnou kosu na obzoru.', 55.7176, 21.1894, 'https://commons.wikimedia.org/wiki/Special:FilePath/F%C3%A4hre%20Smiltyn%C4%97%20Klaipeda.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/F%C3%A4hre%20Smiltyn%C4%97%20Klaipeda.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ferry%20pedestrian%20Smiltyne%20Klaipeda.JPG"}'::text[], 2),
    (v_route, 'Juodkrantė – Čarodějnický vrch (Raganų kalnas)', 'V borovém lese nad rybářskou vesničkou Juodkrantė se ukrývá kouzelná galerie zhruba 80 dřevěných soch čarodějnic, čertů a postav z litevských pověstí. Okruh po lesních stezkách zvládnete pěšky za necelou hodinu a je to skvělé protažení po jízdě. Motorku bezpečně odstavíte na parkovišti u vstupu přímo u pobřežní silnice.', 55.53761, 21.10918, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hexenberg%20in%20Juodkrante.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hexenberg%20in%20Juodkrante.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rimas%20Zinkevi%C4%8Dius%20%E2%80%9ERagana%20ir%20velnias%E2%80%9C.jpg"}'::text[], 3),
    (v_route, 'Nida – Parnidžská duna a sluneční hodiny', 'Vrchol trasy na kose – mohutná pohyblivá duna se tyčí přes 50 metrů nad lagunou a z jejího hřebene je výhled až k ruské hranici. Na vrcholu stojí kamenné sluneční hodiny s vysokým žulovým obeliskem. Nidu doporučujeme jako místo na nocleh, pokud výlet rozdělíte na dva dny, a nezapomeňte ochutnat místní uzené ryby.', 55.29496, 20.99064, 'https://commons.wikimedia.org/wiki/Special:FilePath/Parnidis%20dune.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Parnidis%20dune.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Tik Pas Joną (Nida)', 'Rodinná rybí hospůdka v přístavu v Nidě, kde podávají čerstvě uzené ryby přímo z vlastní udírny a vyhlášenou rybí polévku. S hodnocením 4,7 na Googlu a 4,8 na Restaurant Guru patří k tomu nejlepšímu, co na kose ochutnáte. Čerstvě uzené ryby se rychle vyprodají, ale i s frontou stojí tahle klasika kosy za to.', 55.3072, 21.0067, 'https://commons.wikimedia.org/wiki/Special:FilePath/Parnidis%20dune.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Parnidis%20dune.jpg"}'::text[], 5),
    (v_route, 'Ventės Ragas – maják', 'Po návratu trajektem odbočte na klidný mys Ventės Ragas na východním břehu laguny, kde stojí kamenný maják a jedna z nejstarších ornitologických stanic v Evropě. Za tahu ptáků se tu chytají a kroužkují tisíce ptáků do obřích sítí. Cesta sem vede tichou venkovskou silničkou daleko od jakékoli dálnice a odměnou je nádherný západ slunce nad vodou.', 55.3408, 21.1894, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ventes%20ragas.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ventes%20ragas.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vent%C4%97s%20Ragas%20a%20z%C3%A1pad%20slunce%20na%20Kur%C5%A1sk%C3%A9%20kose.jpg"}'::text[], 6),
    (v_route, 'Palanga – jantarové muzeum', 'Nejznámější litevské přímořské letovisko láká na dlouhou pláž, molo a rušnou promenádu Basanavičiaus. Neorenesanční palác Tiškevičiů uprostřed botanického parku ukrývá proslulé Jantarové muzeum s tisíci kusy baltského „zlata“ včetně vzácných inkluzí hmyzu. Palanga je příjemná zastávka na kávu i procházku parkem před poslední etapou na východ.', 55.9042, 21.0535, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ti%C5%A1kevi%C4%8Diai%20Palace%20at%20dusk%2C%20Palanga%2C%20Lithuania%20-%20Diliff.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ti%C5%A1kevi%C4%8Diai%20Palace%20at%20dusk%2C%20Palanga%2C%20Lithuania%20-%20Diliff.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Palanga%20Palac%20Tyszkiewiczow.JPG"}'::text[], 7),
    (v_route, 'Hora křížů u Šiauliai (Kryžių kalnas)', 'Působivé a dojemné poutní místo, kde na nevelkém pahorku stojí přes sto tisíc křížů, růženců a soch, které sem po generace nosí poutníci z celého světa. Za sovětské éry ho úřady opakovaně srovnaly se zemí, ale lidé kříže vždy znovu vztyčili. Vydejte se sem tichými venkovskými silnicemi a vyhněte se dálnici A1 – atmosféra místa stojí za malou zajížďku a je důstojným zakončením výletu.', 56.0092, 23.4167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hill%20of%20Crosses%2C%20Lithuania.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hill%20of%20Crosses%2C%20Lithuania.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Siauliai%20Hill%20of%20Crosses.JPG"}'::text[], 8);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Sigulda – Nový zámek', 'Novogotický Nový siguldský zámek z roku 1878 je ideálním startem i cílem okruhu a nabízí pohodlné parkování pro motorky. Odsud vyrazíte údolím Gauji po klidných silnicích bez provozu dálnic. Před odjezdem se vyplatí projít zámecký park s výhledy do údolí.', 57.16526, 24.85129, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sigulda%20New%20Castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sigulda%20New%20Castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/The%20new%20Sigulda%20castle%20(2).JPG"}'::text[], 0),
    (v_route, 'Turaida (hrad a muzeum)', 'Cihlově červený hrad Turaida z roku 1214 se tyčí nad údolím Gauji a je součástí rozsáhlého muzejního rezervátu. Z věže je jeden z nejkrásnějších výhledů na celé údolí a na Siguldu. Cesta sem vede příjemnou serpentinou z údolí řeky, ideální pro klidné svezení.', 57.18222, 24.85028, 'https://commons.wikimedia.org/wiki/Special:FilePath/Turaida%20Castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Turaida%20Castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Turaida%20Castle%20from%20Sigulda.JPG"}'::text[], 1),
    (v_route, 'Gūtmaņova jeskyně (Gūtmaņala)', 'Největší a nejvyšší jeskyně v Pobaltí leží přímo u silnice v pískovcovém údolí Gauji jen kousek od Turaidy. Stěny zdobí nápisy staré stovky let a váže se k ní pověst o Turaidské růži. Zastávka je krátká a snadno dostupná přímo od parkoviště.', 57.1762, 24.84236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gutman%E2%80%99s%20cave.%20(2).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gutman%E2%80%99s%20cave.%20(2).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gutmanis%20Cave%20in%202016.jpg"}'::text[], 2),
    (v_route, 'Národní park Gauja', 'Nejstarší a největší národní park Lotyšska láká na hluboké lesy, pískovcové útesy a meandrující řeku Gauja. Silnice parkem jsou úzké, tiché a lemované stromy, takže projížďka je čirý požitek bez ruchu hlavních tahů. Cestou najdete množství vyhlídek a odpočívadel u řeky.', 57.23, 25.05, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gauja%20river%202.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gauja%20river%202.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gauja%20National%20Park,%20Latvia.jpg"}'::text[], 3),
    (v_route, 'Cēsis (hrad)', 'Působivé zříceniny livonského hradu Cēsis z 13. století patří k nejlépe dochovaným v Pobaltí a tvoří nejsevernější bod okruhu. Historické centro města zve na kávu a protažení nohou po delší jízdě. Do hradních sklepení se sestupuje se svíčkovou lucernou, což je zážitek sám o sobě.', 57.3138, 25.2688, 'https://commons.wikimedia.org/wiki/Special:FilePath/C%C4%93su%20pils%20parks%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/C%C4%93su%20pils%20parks%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cesis%20Lettland%20Latvia.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Vinetas un Allas Kārumlāde (Cēsis)', 'Útulná cukrárna-kavárna v historickém srdci Cēsis na adrese Rīgas iela 12 je ideální zastávkou v polovině okruhu. Nabízí domácí zákusky, dorty i teplé i studené saláty a je oblíbená u místních i turistů. Skvělé hodnocení (4,7 na Googlu a 4,5 na TripAdvisoru) potvrzuje pověst jednoho z nejlepších míst na sladkou pauzu ve městě.', 57.312, 25.2725, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cesis%20Lettland%20Latvia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cesis%20Lettland%20Latvia.jpg"}'::text[], 5),
    (v_route, 'Līgatne', 'Malebné městečko Līgatne s historickou papírnou, dřevěnými domky a pískovcovými skalami v údolí Gauji je klidnou zastávkou na zpáteční cestě. Přes řeku zde jezdí tradiční přívoz a v okolí najdete strmé pískovcové útesy Ānfabrikas klintis. Silnice sem vedou lesem daleko od jakékoli dálnice.', 57.2336, 25.0425, 'https://commons.wikimedia.org/wiki/Special:FilePath/L%C4%ABgatne,%20%C4%80nfabrikas%20klintis%202000-06-04.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/L%C4%ABgatne,%20%C4%80nfabrikas%20klintis%202000-06-04.jpg"}'::text[], 6),
    (v_route, 'Krimulda', 'Klasicistní panství Krimulda leží na protějším břehu Gauji než Sigulda a nabízí nádherný výhled do údolí. Spojení zpět k Siguldě zajišťuje historická lanovka přes údolí, nebo klidná silnice kolem řeky. Je to poslední zastávka okruhu před návratem do výchozího bodu.', 57.16667, 24.82667, 'https://commons.wikimedia.org/wiki/Special:FilePath/Palace%20in%20Krimulda.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Palace%20in%20Krimulda.JPG"}'::text[], 7);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Tallinn – staré město (Raekoja plats)', 'Středověké staré město Tallinnu zapsané na seznamu UNESCO je ideálním startem trasy. Radniční náměstí (Raekoja plats) lemují barevné hanzovní domy a gotická radnice. Motorku nechte za hradbami na parkovišti a jádro si projděte pěšky po dlažebních kostkách, které nejsou pro jízdu příjemné.', 59.4358, 24.7405, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tallinn%20Raekoja%20plats%20(4).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tallinn%20Raekoja%20plats%20(4).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Tallinn%20Raekoja%20plats%20(1).JPG"}'::text[], 0),
    (v_route, 'Restaurace: Rataskaevu 16 (Tallinn)', 'Rataskaevu 16 patří k nejoblíbenějším restauracím v tallinnském Starém Městě a je skvělým místem na oběd hned na startu trasy. Kuchyně staví na moderním pojetí estonské a severské klasiky s lokálními surovinami jako losí maso a černý chléb. S hodnocením kolem 4,8 hvězdy na Googlu i TripAdvisoru jde o jednu z nejlépe hodnocených restaurací ve městě, takže si stůl raději rezervujte předem.', 59.4372, 24.7423, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tallinna%20Raekoda.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tallinna%20Raekoda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tallinn%20Raekoja%20plats%20(1).JPG"}'::text[], 1),
    (v_route, 'Palmse mõis (Lahemaa)', 'Barokní panské sídlo Palmse je srdcem národního parku Lahemaa a sídlí zde jeho návštěvnické centrum. Kolem zámečku najdete upravený park, rybníky a hospodářské budovy k procházce. Cesta sem vede klidnými lesními silnicemi mimo hlavní tahy, které si motorkář užije.', 59.51275, 25.95477, 'https://commons.wikimedia.org/wiki/Special:FilePath/Palmse%20manor%20house%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Palmse%20manor%20house%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/PalmseManorPark.jpg"}'::text[], 2),
    (v_route, 'Sagadi mõis (Lahemaa)', 'Růžové panské sídlo Sagadi s lesnickým muzeem leží kousek od Palmse a doplňuje prohlídku Lahemaa. Areál obklopuje symetrická zahrada a starý park se vzrostlými stromy. Mezi oběma sídly se dá krásně projet po úzkých venkovských cestách bez provozu.', 59.5167, 26.118, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sagadi%20manor%20house.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sagadi%20manor%20house.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sagadi%20manor,%20Parque%20Nacional%20Lahemaa,%20Estonia,%202012-08-12,%20DD%2017.JPG"}'::text[], 3),
    (v_route, 'Trajekt Virtsu–Kuivastu', 'Z přístavu Virtsu na pevnině přeplouvá trajekt úžinu Suur väin do Kuivastu na ostrově Muhu, odkud se po hrázi pokračuje na Saaremaa. Přeprava trvá zhruba 25–30 minut a motorky se nakládají mezi prvními. V hlavní sezóně si jízdenku raději rezervujte předem, ať nečekáte na další spoj.', 58.575, 23.51, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ferry%20Virtsu%20-%20Kuivastu,%20Estonia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ferry%20Virtsu%20-%20Kuivastu,%20Estonia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Virtsu-Kuivastu%20(Suur%20v%C3%A4in).jpg"}'::text[], 4),
    (v_route, 'Kaali – meteoritický kráter', 'Kaali je skupina meteoritických kráterů, jejichž hlavní jámu dnes vyplňuje kruhové jezírko obklopené valem. Vznikl dopadem meteoritu před tisíci lety a je jedním z nejznámějších přírodních úkazů Estonska. U kráteru je parkoviště i malé návštěvnické centrum, takže je to příjemná zastávka na svačinu.', 58.37279, 22.6694, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaali%20meteorite%20crater.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaali%20meteorite%20crater.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kaali%20Meteorite%20Crater,%20Kaali,%20Saaremaa,%20Estonia%2003.jpg"}'::text[], 5),
    (v_route, 'Angla – větrné mlýny', 'Na kopečku u silnice mezi Upa a Leisi stojí pětice historických větrných mlýnů, symbol venkovského Saaremaa. Čtyři jsou typické ostrovní kozlíkové mlýny, jeden je holandského typu z roku 1927. U areálu je muzeum lidové kultury a kavárna, ideální fotostop přímo u trasy.', 58.549, 22.632, 'https://commons.wikimedia.org/wiki/Special:FilePath/Saaremaa%20Angla%20Windmills%20Farm%20-%20Angla%20Tedre%20Talu%20Tuuleveski%2020896.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Saaremaa%20Angla%20Windmills%20Farm%20-%20Angla%20Tedre%20Talu%20Tuuleveski%2020896.JPG"}'::text[], 6),
    (v_route, 'Panga pank – útes', 'Panga pank je nejvyšší pobřežní útes ostrovů Saaremaa a Muhu, tyčící se až 20 metrů nad moře. Vápencová stěna se táhne podél severního pobřeží a nabízí výhledy na moře i klidnou rekreační zónu. K okraji se dá dojet po klidné cestě, pozor ale na strmý sráz při procházce.', 58.56986, 22.29038, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panga%20pank.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panga%20pank.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panga%20pank%20-%20cliff%20in%20Saaremaa%20-%20panoramio.jpg"}'::text[], 7),
    (v_route, 'Kuressaare – biskupský hrad', 'Kuressaare v hlavním městě Saaremaa je jedním z nejlépe dochovaných středověkých hradů v Pobaltí, obklopený vodním příkopem a bastiony. Kamenná pevnost dnes ukrývá muzeum a je dominantou celého města. Kolem hradu je rozlehlý park a klidné centrum vhodné na přenocování mezi oběma dny.', 58.25382, 22.49217, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare-linnus,%202010.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare-linnus,%202010.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare%20linnus%20%C3%B5hust.jpg"}'::text[], 8),
    (v_route, 'Restaurace: MO Restaurant (Kuressaare)', 'MO Restaurant je fine-dining restaurace u klubovny Saare Golf kousek od Kuressaare, ideální zastávka v polovině trasy před přenocováním. Kuchyně kombinuje starou evropskou klasiku s prvotřídními místními surovinami a k jídlu se pojí krásný výhled z prosklené jídelny i terasy. S hodnocením kolem 4,5 hvězdy patří k nejlépe hodnoceným podnikům na ostrově Saaremaa.', 58.2589, 22.5119, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare%20linnus%20%C3%B5htuh%C3%A4maruses.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare%20linnus%20%C3%B5htuh%C3%A4maruses.JPG"}'::text[], 9),
    (v_route, 'Sõrve – maják', 'Maják Sõrve stojí na samém jižním cípu poloostrova Sõrve a je nejjižnějším bodem Saaremaa. Cesta k němu po úzké kose mezi mořem po obou stranách patří k nejhezčím úsekům celé trasy. Za jasného počasí odsud dohlédnete až k lotyšskému pobřeží a je to symbolický cíl výletu.', 57.90982, 22.05537, 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B5rve%20tuletorn%202013.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B5rve%20tuletorn%202013.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B5rve%20lighthouse%20on%20Saaremaa%20island.jpg"}'::text[], 10);
